import type { Enemy, Objective, Projectile, Vector2 } from './types'

const distanceSquared = (a: Vector2, b: Vector2): number => {
  const dx = a.x - b.x
  const dy = a.y - b.y
  return dx * dx + dy * dy
}

export const projectileHitsEnemy = (projectile: Projectile, enemy: Enemy): boolean => {
  const radius = projectile.radius + enemy.radius
  return distanceSquared(projectile.position, enemy.position) <= radius * radius
}

export const enemyHitsPlayer = (
  enemy: Enemy,
  playerPosition: Vector2,
  playerRadius: number,
): boolean => {
  const radius = enemy.radius + playerRadius
  return distanceSquared(enemy.position, playerPosition) <= radius * radius
}

export const enemyEscapedWithObjective = (enemy: Enemy): boolean =>
  enemy.carryingObjectiveId !== null && enemy.position.y < -40

export const releaseObjectiveAtGround = (objective: Objective): Objective => ({
  ...objective,
  status: 'safe',
  carrierEnemyId: null,
})

import {
  ENEMY_RADIUS,
  GROUND_Y,
  OBJECTIVE_CAPTURE_RADIUS,
  OBJECTIVE_RADIUS,
  WORLD_WIDTH,
} from './constants'
import type { Enemy, EnemyKind, Objective, Vector2 } from './types'

const LCG_MODULUS = 2 ** 31
const LCG_MULTIPLIER = 1_103_515_245
const LCG_INCREMENT = 12_345

export const advanceSeed = (seed: number): number =>
  (LCG_MULTIPLIER * seed + LCG_INCREMENT) % LCG_MODULUS

export const seededUnit = (seed: number): { value: number; seed: number } => {
  const nextSeed = advanceSeed(seed)
  return { value: nextSeed / LCG_MODULUS, seed: nextSeed }
}

export const seededRange = (
  seed: number,
  min: number,
  max: number,
): { value: number; seed: number } => {
  const next = seededUnit(seed)
  return { value: min + (max - min) * next.value, seed: next.seed }
}

const wrapX = (x: number): number => {
  if (x < 0) {
    return x + WORLD_WIDTH
  }
  if (x >= WORLD_WIDTH) {
    return x - WORLD_WIDTH
  }
  return x
}

const unitDirection = (from: Vector2, to: Vector2): Vector2 => {
  const deltaX = to.x - from.x
  const deltaY = to.y - from.y
  const length = Math.hypot(deltaX, deltaY)
  if (length <= 0.0001) {
    return { x: 0, y: 0 }
  }
  return { x: deltaX / length, y: deltaY / length }
}

const nearestSafeObjective = (enemy: Enemy, objectives: Objective[]): Objective | null => {
  let nearest: Objective | null = null
  let nearestDistance = Number.POSITIVE_INFINITY

  for (const objective of objectives) {
    if (objective.status !== 'safe') {
      continue
    }
    const distance = Math.hypot(
      objective.position.x - enemy.position.x,
      objective.position.y - enemy.position.y,
    )
    if (distance < nearestDistance) {
      nearestDistance = distance
      nearest = objective
    }
  }

  return nearest
}

const chooseEnemyKind = (seed: number, wave: number): { kind: EnemyKind; seed: number } => {
  const roll = seededUnit(seed)
  const waveBias = Math.min(0.25, wave * 0.015)
  if (roll.value < 0.36 - waveBias) {
    return { kind: 'skimmer', seed: roll.seed }
  }
  if (roll.value < 0.76) {
    return { kind: 'floater', seed: roll.seed }
  }
  return { kind: 'abductor', seed: roll.seed }
}

const spawnSide = (
  seed: number,
  cameraX: number,
): { x: number; direction: number; seed: number } => {
  const side = seededUnit(seed)
  const direction = side.value < 0.5 ? 1 : -1
  const x = wrapX(cameraX + (direction > 0 ? WORLD_WIDTH * 0.65 : WORLD_WIDTH * 0.35))
  return { x, direction, seed: side.seed }
}

export const spawnEnemy = (
  seed: number,
  wave: number,
  nextEnemyId: number,
  cameraX: number,
): { enemy: Enemy; seed: number; nextEnemyId: number } => {
  const kindPick = chooseEnemyKind(seed, wave)
  const side = spawnSide(kindPick.seed, cameraX)
  const speedScale = seededRange(side.seed, 1 + wave * 0.03, 1.85 + wave * 0.05)
  const drift = seededRange(speedScale.seed, 0, Math.PI * 2)
  const altitude = seededRange(drift.seed, 90, 360)

  const kind = kindPick.kind
  const horizontal = side.direction * speedScale.value
  const enemy: Enemy = {
    id: nextEnemyId,
    kind,
    radius: ENEMY_RADIUS[kind],
    driftPhase: drift.value,
    carryingObjectiveId: null,
    position: {
      x: side.x,
      y: kind === 'skimmer' ? GROUND_Y - 42 : altitude.value,
    },
    velocity: {
      x: kind === 'abductor' ? horizontal * 0.6 : horizontal,
      y: kind === 'skimmer' ? 0 : kind === 'floater' ? 0.15 : 0,
    },
  }

  return { enemy, seed: altitude.seed, nextEnemyId: nextEnemyId + 1 }
}

export const updateEnemy = (enemy: Enemy, tick: number, objectives: Objective[]): Enemy => {
  if (enemy.kind === 'floater') {
    const sway = Math.sin((tick + enemy.driftPhase) * 0.045) * 0.85
    return {
      ...enemy,
      position: {
        x: wrapX(enemy.position.x + enemy.velocity.x),
        y: Math.max(80, Math.min(GROUND_Y - 150, enemy.position.y + enemy.velocity.y + sway)),
      },
    }
  }

  if (enemy.kind === 'skimmer') {
    const sway = Math.sin((tick + enemy.driftPhase) * 0.09) * 5.8
    return {
      ...enemy,
      position: {
        x: wrapX(enemy.position.x + enemy.velocity.x),
        y: GROUND_Y - 36 + sway,
      },
    }
  }

  if (enemy.carryingObjectiveId !== null) {
    return {
      ...enemy,
      position: {
        x: wrapX(enemy.position.x + enemy.velocity.x * 0.55),
        y: enemy.position.y - 1.9,
      },
    }
  }

  const target = nearestSafeObjective(enemy, objectives)
  if (!target) {
    return {
      ...enemy,
      position: {
        x: wrapX(enemy.position.x + enemy.velocity.x),
        y: Math.max(90, enemy.position.y - 0.2),
      },
    }
  }

  const direction = unitDirection(enemy.position, target.position)
  const speed = Math.max(1.45, Math.abs(enemy.velocity.x))
  return {
    ...enemy,
    position: {
      x: wrapX(enemy.position.x + direction.x * speed),
      y: enemy.position.y + direction.y * speed,
    },
  }
}

export const canCaptureObjective = (enemy: Enemy, objective: Objective): boolean => {
  if (
    enemy.kind !== 'abductor' ||
    enemy.carryingObjectiveId !== null ||
    objective.status !== 'safe'
  ) {
    return false
  }
  const captureDistance = enemy.radius + OBJECTIVE_RADIUS + OBJECTIVE_CAPTURE_RADIUS
  return (
    Math.hypot(objective.position.x - enemy.position.x, objective.position.y - enemy.position.y) <=
    captureDistance
  )
}

import {
  enemyEscapedWithObjective,
  enemyHitsPlayer,
  projectileHitsEnemy,
  releaseObjectiveAtGround,
} from './collisions'
import {
  AIM_ANGLE_STEP,
  AIM_DEFAULT_ANGLE,
  AIM_DEFAULT_FORCE,
  AIM_FORCE_STEP,
  ARENA_HEIGHT,
  ENEMY_SCORE,
  FIRE_COOLDOWN_TICKS,
  GROUND_Y,
  INITIAL_STATE,
  OBJECTIVE_COUNT,
  OBJECTIVE_LOST_LIFE_PENALTY,
  OBJECTIVE_RADIUS,
  PLAYER_HIT_LIFE_PENALTY,
  PLAYER_HIT_RADIUS,
  PLAYER_X,
  PLAYER_Y,
  PROJECTILE_RADIUS,
  PROJECTILE_TTL,
  RESCUE_BONUS,
  SALVO_COOLDOWN_TICKS,
  SALVO_SPREAD,
  SURVIVAL_SCORE_PER_TICK,
  TARGET_PROGRESS,
  WAVE_BONUS,
  WORLD_WIDTH,
} from './constants'
import { canCaptureObjective, spawnEnemy, updateEnemy } from './enemies'
import { clampAimAngle, clampAimForce, createLaunchVelocity, projectStep } from './trajectory'
import type { ControlState, Enemy, GameState, Objective, Projectile, Vector2 } from './types'
import { computeWave, nextCameraX, shouldSpawnEnemy, waveAdvanced } from './waves'

export type GameAction = 'primary' | 'secondary' | 'tertiary' | 'reset'

const EMPTY_CONTROLS: ControlState = {
  aimUp: false,
  aimDown: false,
  forceUp: false,
  forceDown: false,
  fire: false,
  reaim: false,
  salvo: false,
}

const clamp = (value: number, min: number, max: number): number => {
  if (value < min) {
    return min
  }
  if (value > max) {
    return max
  }
  return value
}

const wrapX = (x: number): number => {
  if (x < 0) {
    return x + WORLD_WIDTH
  }
  if (x >= WORLD_WIDTH) {
    return x - WORLD_WIDTH
  }
  return x
}

const groundObjectives = (): Objective[] =>
  Array.from({ length: OBJECTIVE_COUNT }, (_, index) => ({
    id: index + 1,
    position: {
      x: 520 + index * 260,
      y: GROUND_Y - OBJECTIVE_RADIUS,
    },
    status: 'safe',
    carrierEnemyId: null,
  }))

const decrementCooldown = (ticks: number): number => (ticks > 0 ? ticks - 1 : 0)

const withDerivedMeters = (state: GameState): GameState => {
  const safeObjectives = state.objectives.filter((objective) => objective.status === 'safe').length
  const capturedObjectives = state.objectives.filter(
    (objective) => objective.status === 'captured',
  ).length
  const dangerBudget = state.enemies.length + capturedObjectives * 5 + state.wave * 4
  const intensity = clamp(Math.round(8 + dangerBudget), 0, 100)
  const aimPenalty = Math.abs(state.aim.angle - AIM_DEFAULT_ANGLE) * 20
  const cooldownPenalty = state.fireCooldownTicks * 1.5 + state.salvoCooldownTicks * 0.3
  const focus = clamp(Math.round(100 - aimPenalty - cooldownPenalty), 0, 100)
  const progress = clamp(
    Math.round((state.tick / (TARGET_PROGRESS * 60)) * 100 + safeObjectives * 3),
    0,
    TARGET_PROGRESS,
  )

  return {
    ...state,
    intensity,
    focus,
    progress,
  }
}

const launchProjectile = (
  state: GameState,
  angleOffset = 0,
): { projectile: Projectile; nextProjectileId: number } => {
  const launchPosition = {
    x: PLAYER_X + Math.cos(state.aim.angle + angleOffset) * 24,
    y: PLAYER_Y + Math.sin(state.aim.angle + angleOffset) * 24,
  }
  return {
    projectile: {
      id: state.nextProjectileId,
      position: launchPosition,
      velocity: createLaunchVelocity(state.aim.angle + angleOffset, state.aim.force),
      ttl: PROJECTILE_TTL,
      radius: PROJECTILE_RADIUS,
    },
    nextProjectileId: state.nextProjectileId + 1,
  }
}

const applyAimControls = (state: GameState, controls: ControlState): GameState => {
  const angleDelta =
    (controls.aimUp ? -AIM_ANGLE_STEP : 0) + (controls.aimDown ? AIM_ANGLE_STEP : 0)
  const forceDelta =
    (controls.forceUp ? AIM_FORCE_STEP : 0) + (controls.forceDown ? -AIM_FORCE_STEP : 0)

  const aim = {
    angle: clampAimAngle(state.aim.angle + angleDelta),
    force: clampAimForce(state.aim.force + forceDelta),
  }

  if (controls.reaim) {
    return {
      ...state,
      aim: { angle: AIM_DEFAULT_ANGLE, force: AIM_DEFAULT_FORCE },
      status: 'Re-aim locked neutral artillery profile',
    }
  }

  return { ...state, aim }
}

const applyWeaponActions = (state: GameState, controls: ControlState): GameState => {
  const withCooldowns = {
    ...state,
    fireCooldownTicks: decrementCooldown(state.fireCooldownTicks),
    salvoCooldownTicks: decrementCooldown(state.salvoCooldownTicks),
  }

  if (controls.salvo && withCooldowns.salvoCooldownTicks === 0) {
    const first = launchProjectile(withCooldowns, -SALVO_SPREAD)
    const second = launchProjectile(
      { ...withCooldowns, nextProjectileId: first.nextProjectileId },
      0,
    )
    const third = launchProjectile(
      { ...withCooldowns, nextProjectileId: second.nextProjectileId },
      SALVO_SPREAD,
    )
    return {
      ...withCooldowns,
      projectiles: [
        ...withCooldowns.projectiles,
        first.projectile,
        second.projectile,
        third.projectile,
      ],
      nextProjectileId: third.nextProjectileId,
      fireCooldownTicks: FIRE_COOLDOWN_TICKS,
      salvoCooldownTicks: SALVO_COOLDOWN_TICKS,
      status: 'Full Salvo deployed: three-arc burst',
    }
  }

  if (controls.fire && withCooldowns.fireCooldownTicks === 0) {
    const fired = launchProjectile(withCooldowns)
    return {
      ...withCooldowns,
      projectiles: [...withCooldowns.projectiles, fired.projectile],
      nextProjectileId: fired.nextProjectileId,
      fireCooldownTicks: FIRE_COOLDOWN_TICKS,
      status: 'Standard Shot committed to trajectory',
    }
  }

  return withCooldowns
}

const stepProjectiles = (projectiles: Projectile[]): Projectile[] =>
  projectiles
    .map((projectile) => {
      const stepped = projectStep(projectile.position, projectile.velocity)
      return {
        ...projectile,
        position: {
          x: wrapX(stepped.position.x),
          y: stepped.position.y,
        },
        velocity: stepped.velocity,
        ttl: projectile.ttl - 1,
      }
    })
    .filter(
      (projectile) =>
        projectile.ttl > 0 &&
        projectile.position.y >= -80 &&
        projectile.position.y <= ARENA_HEIGHT + 120,
    )

const stepEnemiesAndObjectives = (
  state: GameState,
): { enemies: Enemy[]; objectives: Objective[]; livesLost: number } => {
  const updatedEnemies = state.enemies.map((enemy) =>
    updateEnemy(enemy, state.tick, state.objectives),
  )
  const objectives = state.objectives.map((objective) => ({ ...objective }))
  let livesLost = 0

  for (const enemy of updatedEnemies) {
    if (enemy.kind !== 'abductor') {
      continue
    }

    if (enemy.carryingObjectiveId === null) {
      const candidate = objectives.find((objective) => canCaptureObjective(enemy, objective))
      if (!candidate) {
        continue
      }
      candidate.status = 'captured'
      candidate.carrierEnemyId = enemy.id
      enemy.carryingObjectiveId = candidate.id
      continue
    }

    const carried = objectives.find((objective) => objective.id === enemy.carryingObjectiveId)
    if (!carried) {
      enemy.carryingObjectiveId = null
      continue
    }
    carried.position = { ...enemy.position }
    carried.carrierEnemyId = enemy.id

    if (enemyEscapedWithObjective(enemy)) {
      carried.status = 'lost'
      carried.carrierEnemyId = null
      enemy.carryingObjectiveId = null
      livesLost += OBJECTIVE_LOST_LIFE_PENALTY
    }
  }

  return { enemies: updatedEnemies, objectives, livesLost }
}

const resolveProjectileEnemyCollisions = (
  state: GameState,
): { enemies: Enemy[]; objectives: Objective[]; projectiles: Projectile[]; scoreDelta: number } => {
  const remainingProjectiles = [...state.projectiles]
  const remainingEnemies: Enemy[] = []
  const objectives = state.objectives.map((objective) => ({ ...objective }))
  let scoreDelta = 0

  for (const enemy of state.enemies) {
    let projectileIndex = -1
    for (let index = 0; index < remainingProjectiles.length; index += 1) {
      if (projectileHitsEnemy(remainingProjectiles[index], enemy)) {
        projectileIndex = index
        break
      }
    }

    if (projectileIndex < 0) {
      remainingEnemies.push(enemy)
      continue
    }

    remainingProjectiles.splice(projectileIndex, 1)
    scoreDelta += ENEMY_SCORE[enemy.kind]

    if (enemy.carryingObjectiveId !== null) {
      const rescued = objectives.find((objective) => objective.id === enemy.carryingObjectiveId)
      if (rescued) {
        rescued.position = {
          x: rescued.position.x,
          y: GROUND_Y - OBJECTIVE_RADIUS,
        }
        const released = releaseObjectiveAtGround(rescued)
        Object.assign(rescued, released)
      }
      scoreDelta += RESCUE_BONUS
    }
  }

  return { enemies: remainingEnemies, objectives, projectiles: remainingProjectiles, scoreDelta }
}

const resolvePlayerHits = (state: GameState): { enemies: Enemy[]; livesLost: number } => {
  const playerPosition: Vector2 = { x: PLAYER_X, y: PLAYER_Y }
  const survivors: Enemy[] = []
  let hits = 0

  for (const enemy of state.enemies) {
    if (enemyHitsPlayer(enemy, playerPosition, PLAYER_HIT_RADIUS)) {
      hits += 1
      continue
    }
    survivors.push(enemy)
  }

  return { enemies: survivors, livesLost: hits * PLAYER_HIT_LIFE_PENALTY }
}

const evaluateWin = (state: GameState): boolean =>
  state.progress >= TARGET_PROGRESS &&
  state.wave >= 8 &&
  state.objectives.some((objective) => objective.status === 'safe')

const evaluateLose = (state: GameState): boolean =>
  state.lives <= 0 || state.objectives.every((objective) => objective.status === 'lost')

const evaluateStatus = (state: GameState, prevWave: number): string => {
  if (state.phase === 'gameOver') {
    return state.status
  }
  if (waveAdvanced(state.tick, prevWave)) {
    return `Wave ${state.wave} escalation: incoming vectors intensifying`
  }
  if (state.objectives.some((objective) => objective.status === 'captured')) {
    return 'Objective under abduction: prioritize arc interception'
  }
  return state.status
}

const spawnPressureEnemy = (state: GameState): GameState => {
  if (!shouldSpawnEnemy(state.tick, state.wave)) {
    return state
  }

  const spawned = spawnEnemy(state.rngSeed, state.wave, state.nextEnemyId, state.cameraX)
  return {
    ...state,
    enemies: [...state.enemies, spawned.enemy],
    rngSeed: spawned.seed,
    nextEnemyId: spawned.nextEnemyId,
  }
}

export const createInitialState = (seed = INITIAL_STATE.rngSeed): GameState => ({
  ...INITIAL_STATE,
  rngSeed: seed,
  objectives: groundObjectives(),
})

export const stepGameState = (state: GameState, controls: ControlState): GameState => {
  if (state.phase === 'gameOver') {
    return state
  }

  const previousWave = state.wave
  let next = {
    ...state,
    tick: state.tick + 1,
    wave: computeWave(state.tick + 1),
    cameraX: nextCameraX(state.cameraX, state.wave),
    score: state.score + SURVIVAL_SCORE_PER_TICK,
  }

  next = applyAimControls(next, controls)
  next = applyWeaponActions(next, controls)
  next = spawnPressureEnemy(next)

  next = {
    ...next,
    projectiles: stepProjectiles(next.projectiles),
  }

  const enemyStep = stepEnemiesAndObjectives(next)
  next = {
    ...next,
    enemies: enemyStep.enemies,
    objectives: enemyStep.objectives,
    lives: next.lives - enemyStep.livesLost,
  }

  const collisions = resolveProjectileEnemyCollisions(next)
  next = {
    ...next,
    enemies: collisions.enemies,
    objectives: collisions.objectives,
    projectiles: collisions.projectiles,
    score: next.score + collisions.scoreDelta,
  }

  const playerHits = resolvePlayerHits(next)
  next = {
    ...next,
    enemies: playerHits.enemies,
    lives: next.lives - playerHits.livesLost,
  }

  if (waveAdvanced(next.tick, previousWave)) {
    next = {
      ...next,
      score: next.score + WAVE_BONUS,
    }
  }

  next = withDerivedMeters(next)
  next = {
    ...next,
    status: evaluateStatus(next, previousWave),
  }

  if (evaluateLose(next)) {
    return {
      ...next,
      phase: 'gameOver',
      status: 'Defensive line collapsed: reset to restart',
    }
  }

  if (evaluateWin(next)) {
    return {
      ...next,
      phase: 'gameOver',
      score: next.score + 250,
      status: 'Angle War survived: ballistic command achieved',
    }
  }

  return next
}

const controlForAction = (action: GameAction): ControlState => {
  if (action === 'primary') {
    return { ...EMPTY_CONTROLS, fire: true }
  }
  if (action === 'secondary') {
    return { ...EMPTY_CONTROLS, reaim: true }
  }
  if (action === 'tertiary') {
    return { ...EMPTY_CONTROLS, salvo: true }
  }
  return EMPTY_CONTROLS
}

export const reduceGameState = (state: GameState, action: GameAction): GameState => {
  if (action === 'reset') {
    return createInitialState()
  }
  if (state.phase === 'gameOver') {
    return state
  }
  return stepGameState(state, controlForAction(action))
}

import {
  AIM_MAX_ANGLE,
  AIM_MAX_FORCE,
  AIM_MIN_ANGLE,
  AIM_MIN_FORCE,
  GRAVITY_PER_TICK,
  PROJECTILE_TTL,
} from './constants'
import type { Vector2 } from './types'

const clamp = (value: number, min: number, max: number): number => {
  if (value < min) {
    return min
  }
  if (value > max) {
    return max
  }
  return value
}

export const clampAimAngle = (angle: number): number => clamp(angle, AIM_MIN_ANGLE, AIM_MAX_ANGLE)

export const clampAimForce = (force: number): number => clamp(force, AIM_MIN_FORCE, AIM_MAX_FORCE)

export const createLaunchVelocity = (angle: number, force: number): Vector2 => ({
  x: Math.cos(clampAimAngle(angle)) * clampAimForce(force),
  y: Math.sin(clampAimAngle(angle)) * clampAimForce(force),
})

export const projectStep = (
  position: Vector2,
  velocity: Vector2,
): { position: Vector2; velocity: Vector2 } => {
  const nextVelocity = {
    x: velocity.x,
    y: velocity.y + GRAVITY_PER_TICK,
  }
  return {
    position: {
      x: position.x + nextVelocity.x,
      y: position.y + nextVelocity.y,
    },
    velocity: nextVelocity,
  }
}

export const sampleTrajectory = (
  origin: Vector2,
  angle: number,
  force: number,
  maxSteps = 54,
): Vector2[] => {
  const points: Vector2[] = []
  let position = { ...origin }
  let velocity = createLaunchVelocity(angle, force)
  const steps = Math.min(maxSteps, PROJECTILE_TTL)

  for (let index = 0; index < steps; index += 1) {
    const next = projectStep(position, velocity)
    position = next.position
    velocity = next.velocity
    points.push(position)
  }

  return points
}

import {
  CAMERA_SCROLL_BASE,
  CAMERA_SCROLL_WAVE_STEP,
  SPAWN_INTERVAL_MIN,
  SPAWN_INTERVAL_START,
  SPAWN_INTERVAL_STEP,
  WAVE_TICKS,
  WORLD_WIDTH,
} from './constants'

const clamp = (value: number, min: number, max: number): number => {
  if (value < min) {
    return min
  }
  if (value > max) {
    return max
  }
  return value
}

const wrapX = (x: number): number => {
  if (x < 0) {
    return x + WORLD_WIDTH
  }
  if (x >= WORLD_WIDTH) {
    return x - WORLD_WIDTH
  }
  return x
}

export const computeWave = (tick: number): number => Math.floor(tick / WAVE_TICKS) + 1

export const nextCameraX = (cameraX: number, wave: number): number =>
  wrapX(cameraX + CAMERA_SCROLL_BASE + (wave - 1) * CAMERA_SCROLL_WAVE_STEP)

export const spawnIntervalForWave = (wave: number): number =>
  clamp(
    SPAWN_INTERVAL_START - (wave - 1) * SPAWN_INTERVAL_STEP,
    SPAWN_INTERVAL_MIN,
    SPAWN_INTERVAL_START,
  )

export const shouldSpawnEnemy = (tick: number, wave: number): boolean =>
  tick % spawnIntervalForWave(wave) === 0

export const waveAdvanced = (tick: number, previousWave: number): boolean =>
  computeWave(tick) > previousWave

import { INITIAL_STATE, PROGRESS_TARGET } from './constants'
import type { GameState } from './types'

export type GameAction = 'primary' | 'secondary' | 'tertiary' | 'tick' | 'reset'

const clamp = (value: number, min: number, max: number): number => {
  if (value < min) {
    return min
  }
  if (value > max) {
    return max
  }
  return value
}

const withGameOverCheck = (state: GameState): GameState => {
  if (state.lives <= 0) {
    return { ...state, phase: 'gameOver', status: 'System collapse: retry run' }
  }

  if (state.progress >= PROGRESS_TARGET) {
    return {
      ...state,
      phase: 'gameOver',
      status: 'Prototype objective reached',
      score: state.score + 25,
    }
  }

  return state
}

export const reduceGameState = (state: GameState, action: GameAction): GameState => {
  if (action === 'reset') {
    return INITIAL_STATE
  }
  if (state.phase === 'gameOver') {
    return state
  }

  if (action === 'tick') {
    const next = {
      ...state,
      tick: state.tick + 1,
      intensity: clamp(state.intensity + 2, 0, 100),
      focus: clamp(state.focus - 1, 0, 100),
      lives: state.intensity > 92 ? state.lives - 1 : state.lives,
      status: 'Paddle / Rotary pressure rising',
    }
    return withGameOverCheck(next)
  }

  if (action === 'primary') {
    const next = {
      ...state,
      score: state.score + 10,
      progress: state.progress + 4,
      focus: clamp(state.focus + 2, 0, 100),
      status: 'Deflect executed',
    }
    return withGameOverCheck(next)
  }

  if (action === 'secondary') {
    const next = {
      ...state,
      focus: clamp(state.focus + 8, 0, 100),
      intensity: clamp(state.intensity + -4, 0, 100),
      score: state.score + 2,
      status: 'Re-center recovered control',
    }
    return withGameOverCheck(next)
  }

  const next = {
    ...state,
    score: state.score + 16,
    progress: state.progress + 6,
    intensity: clamp(state.intensity + 8, 0, 100),
    focus: clamp(state.focus - 6, 0, 100),
    status: 'Power Spin high-risk burst',
  }
  return withGameOverCheck(next)
}

