import { useCallback, useState } from 'react'

import { nextLossStats, nextWinStats, type StatsShape } from '@games/stats-utils'

import type { GameStats } from '@/domain'
import { DEFAULT_STATS } from '@/domain'

import { load, save } from '../storageService'

const STORAGE_KEY = 'battleship-stats'

export interface UseStatsResult {
  stats: GameStats
  recordWin: () => void
  recordLoss: () => void
  resetStats: () => void
}

export const useStats = (): UseStatsResult => {
  const [stats, setStats] = useState<GameStats>(() => load<GameStats>(STORAGE_KEY, DEFAULT_STATS) ?? DEFAULT_STATS)

  const recordWin = useCallback(() => {
    setStats((previous) => {
      const next = nextWinStats(previous as StatsShape) as GameStats
      save(STORAGE_KEY, next)
      return next
    })
  }, [])

  const recordLoss = useCallback(() => {
    setStats((previous) => {
      const next = nextLossStats(previous as StatsShape) as GameStats
      save(STORAGE_KEY, next)
      return next
    })
  }, [])

  const resetStats = useCallback(() => {
    save(STORAGE_KEY, DEFAULT_STATS)
    setStats(DEFAULT_STATS)
  }, [])

  return { stats, recordWin, recordLoss, resetStats }
}

/**
 * AI move selection — CPU player logic.
 * Pure functions: given a board state, return the best move.
 */

import { DIFFICULTY_PRESETS } from './constants'
import type { Board, CellState, Coord, Difficulty } from './types'

/** Check if a cell contains a CPU ship */
function isCpuShip(board: Board, coord: Coord): boolean {
  return board.ships.some(
    (ship) =>
      ship.owner === 'cpu' && ship.cells.some((c) => c.row === coord.row && c.col === coord.col),
  )
}

/** Get all cells that haven't been shot yet and don't contain CPU ships */
function getUntriedCells(board: Board): Coord[] {
  const cells: Coord[] = []
  for (let row = 0; row < board.size; row++) {
    for (let col = 0; col < board.size; col++) {
      const cell = board.grid[row][col]
      const coord = { row, col }
      // Include empty cells and player ships, but exclude CPU ships
      if ((cell === 'empty' || cell === 'ship') && !isCpuShip(board, coord)) {
        cells.push(coord)
      }
    }
  }
  return cells
}

/** Get adjacent untried cells around a coordinate, excluding CPU ships */
function getAdjacentUntried(board: Board, coord: Coord): Coord[] {
  const dirs: Coord[] = [
    { row: -1, col: 0 },
    { row: 1, col: 0 },
    { row: 0, col: -1 },
    { row: 0, col: 1 },
  ]
  return dirs
    .map((d) => ({ row: coord.row + d.row, col: coord.col + d.col }))
    .filter(
      (c) =>
        c.row >= 0 &&
        c.row < board.size &&
        c.col >= 0 &&
        c.col < board.size &&
        (board.grid[c.row][c.col] === 'empty' || board.grid[c.row][c.col] === 'ship') &&
        !isCpuShip(board, c),
    )
}

/** Check if a cell is a hit (made by either player or CPU) */
function isHit(state: CellState): boolean {
  return state === 'playerHit' || state === 'cpuHit'
}

/** Find all unsunk hit cells (hits that belong to ships not yet fully sunk) */
function getUnsunkHits(board: Board): Coord[] {
  const sunkCells = new Set<string>()
  for (const ship of board.ships) {
    if (ship.cells.every((c) => isHit(board.grid[c.row][c.col]))) {
      for (const c of ship.cells) {
        sunkCells.add(`${c.row},${c.col}`)
      }
    }
  }

  const unsunkHits: Coord[] = []
  for (let row = 0; row < board.size; row++) {
    for (let col = 0; col < board.size; col++) {
      if (isHit(board.grid[row][col]) && !sunkCells.has(`${row},${col}`)) {
        unsunkHits.push({ row, col })
      }
    }
  }
  return unsunkHits
}

/**
 * CPU move selection — hunt/target strategy with difficulty modulation.
 *
 * Randomization: Lower difficulties make more random, suboptimal moves.
 * SmartTargeting: Lower difficulties ignore unsunk hits and only hunt.
 * Target mode: if smartTargeting enabled and unsunk hits exist, target them.
 * Hunt mode: pick a random untried cell with checkerboard parity.
 */
export function getCpuMove(board: Board, difficulty: Difficulty): Coord {
  const preset = DIFFICULTY_PRESETS[difficulty]

  // Randomization: at lower difficulties, make more random moves (ignore strategy)
  if (Math.random() < preset.randomization) {
    const untried = getUntriedCells(board)
    return untried[Math.floor(Math.random() * untried.length)]
  }

  // SmartTargeting mode: focus around existing unsunk hits
  if (preset.smartTargeting) {
    const unsunkHits = getUnsunkHits(board)
    if (unsunkHits.length > 0) {
      // Try cells adjacent to unsunk hits
      for (const hit of unsunkHits) {
        const adjacent = getAdjacentUntried(board, hit)
        if (adjacent.length > 0) {
          return adjacent[Math.floor(Math.random() * adjacent.length)]
        }
      }
    }
  }

  // Hunt mode — checkerboard pattern for efficiency
  const untried = getUntriedCells(board)
  const checkerboard = untried.filter((c) => (c.row + c.col) % 2 === 0)
  const pool = checkerboard.length > 0 ? checkerboard : untried
  return pool[Math.floor(Math.random() * pool.length)]
}

/**
 * Board operations — pure functions for creating and manipulating game state.
 * No React, no DOM — purely functional transformations.
 */

import { GRID_SIZE, SHIP_DEFS } from './constants'
import type { Board, CellState, Coord, FireResult, Orientation, Ship, ShipDef } from './types'

/** Create an empty board */
export function createBoard(size: number = GRID_SIZE): Board {
  const grid: CellState[][] = Array.from({ length: size }, () =>
    Array.from<CellState>({ length: size }).fill('empty'),
  )
  return { size, grid, ships: [] }
}

/** Get cells a ship would occupy given origin + orientation */
export function getShipCells(origin: Coord, orientation: Orientation, length: number): Coord[] {
  const cells: Coord[] = []
  for (let i = 0; i < length; i++) {
    cells.push({
      row: origin.row + (orientation === 'vertical' ? i : 0),
      col: origin.col + (orientation === 'horizontal' ? i : 0),
    })
  }
  return cells
}

/** Check if a ship placement is valid (in bounds, no overlaps with ANY ship) */
export function canPlaceShip(
  board: Board,
  origin: Coord,
  orientation: Orientation,
  length: number,
): boolean {
  const cells = getShipCells(origin, orientation, length)
  return cells.every((c) => {
    if (c.row < 0 || c.row >= board.size || c.col < 0 || c.col >= board.size) {
      return false
    }
    // Can only place where there's no other ship (owned by either player)
    const shipAtCell = board.ships.find((ship) =>
      ship.cells.some((shipCell) => shipCell.row === c.row && shipCell.col === c.col),
    )
    return !shipAtCell
  })
}

/** Place a ship on the board — returns new board or null if invalid */
export function placeShip(
  board: Board,
  def: ShipDef,
  origin: Coord,
  orientation: Orientation,
  owner: 'player' | 'cpu',
): Board | null {
  if (!canPlaceShip(board, origin, orientation, def.length)) {
    return null
  }

  const cells = getShipCells(origin, orientation, def.length)
  const newGrid = board.grid.map((row) => [...row])
  // Mark all ships on the grid (both player and CPU)
  for (const c of cells) {
    newGrid[c.row][c.col] = 'ship'
  }

  const ship: Ship = { def, origin, orientation, cells, owner }
  return { ...board, grid: newGrid, ships: [...board.ships, ship] }
}

/** Fire at a cell — returns updated board and result */
export function fireAt(
  board: Board,
  coord: Coord,
  shooter: 'player' | 'cpu' = 'player',
): { board: Board; result: FireResult } {
  const cell = board.grid[coord.row][coord.col]

  // Check if already shot at this location (any type of shot)
  if (cell === 'playerHit' || cell === 'playerMiss' || cell === 'cpuHit' || cell === 'cpuMiss') {
    return { board, result: { result: 'already', sunkShip: null } }
  }

  // Hard guard: never allow a side to fire on its own ships.
  const ownShipAtTarget = board.ships.some(
    (ship) =>
      ship.owner === shooter && ship.cells.some((c) => c.row === coord.row && c.col === coord.col),
  )

  if (ownShipAtTarget) {
    return { board, result: { result: 'already', sunkShip: null } }
  }

  // Determine opponent (who we're shooting at)
  const opponent: 'player' | 'cpu' = shooter === 'player' ? 'cpu' : 'player'

  // Check if there's an opponent ship at this location
  const opponentShipAtTarget = board.ships.some(
    (ship) =>
      ship.owner === opponent && ship.cells.some((c) => c.row === coord.row && c.col === coord.col),
  )

  const newGrid = board.grid.map((row) => [...row])
  const isHit = cell === 'ship' && opponentShipAtTarget
  newGrid[coord.row][coord.col] = isHit
    ? shooter === 'player'
      ? 'playerHit'
      : 'cpuHit'
    : shooter === 'player'
      ? 'playerMiss'
      : 'cpuMiss'
  const newBoard: Board = { ...board, grid: newGrid }

  let sunkShip: Ship | null = null
  if (isHit) {
    sunkShip =
      board.ships.find(
        (ship) =>
          ship.owner === opponent &&
          ship.cells.some((c) => c.row === coord.row && c.col === coord.col) &&
          ship.cells.every((c) => {
            if (c.row === coord.row && c.col === coord.col) {
              return true
            }
            const cellState = newGrid[c.row][c.col]
            return cellState === 'playerHit' || cellState === 'cpuHit'
          }),
      ) ?? null
  }

  return {
    board: newBoard,
    result: { result: isHit ? 'hit' : 'miss', sunkShip },
  }
}

/** Place ships randomly on a board for a specific owner */
export function placeShipsRandomly(board: Board, owner: 'player' | 'cpu' = 'cpu'): Board {
  let current = board
  for (const def of SHIP_DEFS) {
    let placed = false
    while (!placed) {
      const orientation: Orientation = Math.random() < 0.5 ? 'horizontal' : 'vertical'
      const origin: Coord = {
        row: Math.floor(Math.random() * GRID_SIZE),
        col: Math.floor(Math.random() * GRID_SIZE),
      }
      const result = placeShip(current, def, origin, orientation, owner)
      if (result) {
        current = result
        placed = true
      }
    }
  }
  return current
}

