// Bingo Blackout hooks barrel
export { useGame } from './useGame'

export type { BlackoutBingoGameState } from '@/domain'

import { GRID_SIZE } from './constants'
import type { BingoCard, BingoCell, BingoColumn, WinningPattern } from './types'
import { COLUMNS, COLUMN_RANGES } from './types'

function createCell(number: number | null, marked = false): BingoCell {
  return {
    number,
    marked,
    isFreeSpace: number === null,
  }
}

function pickUniqueInRange(min: number, max: number, count: number): number[] {
  const available = Array.from({ length: max - min + 1 }, (_, i) => i + min)
  const selected: number[] = []

  while (selected.length < count && available.length > 0) {
    const index = Math.floor(Math.random() * available.length)
    const [value] = available.splice(index, 1)
    selected.push(value)
  }

  return selected
}

function generateCardGrid(): BingoCell[][] {
  const grid = Array.from({ length: GRID_SIZE }, () =>
    Array.from({ length: GRID_SIZE }, () => createCell(null)),
  )

  COLUMNS.forEach((column: BingoColumn, columnIndex) => {
    const [min, max] = COLUMN_RANGES[column]
    const values = pickUniqueInRange(min, max, GRID_SIZE)
    values.forEach((value, rowIndex) => {
      grid[rowIndex][columnIndex] = createCell(value)
    })
  })

  const center = Math.floor(GRID_SIZE / 2)
  grid[center][center] = createCell(null, true)
  return grid
}

export function createBingoCard(): BingoCard {
  return {
    id: crypto.randomUUID(),
    grid: generateCardGrid(),
  }
}

export function createBingoCards(count: number): BingoCard[] {
  return Array.from({ length: count }, () => createBingoCard())
}

export function markNumber(card: BingoCard, number: number): void {
  for (let row = 0; row < GRID_SIZE; row++) {
    for (let col = 0; col < GRID_SIZE; col++) {
      const cell = card.grid[row][col]
      if (cell.number === number) {
        cell.marked = true
      }
    }
  }
}

export function checkWinningPatterns(card: BingoCard): WinningPattern[] {
  const isBlackout = card.grid.flat().every((cell) => cell.marked || cell.isFreeSpace)
  return isBlackout ? ['blackout'] : []
}

export function isWinner(card: BingoCard): boolean {
  return checkWinningPatterns(card).length > 0
}

import { describe, expect, it } from 'vitest'
import { checkWinningPatterns, createBingoCard, createBingoCards, markNumber } from './card'

describe('bingo-blackout card logic', () => {
  it('creates a 5x5 card with center free space', () => {
    const card = createBingoCard()
    expect(card.grid).toHaveLength(5)
    expect(card.grid[0]).toHaveLength(5)
    expect(card.grid[2][2].isFreeSpace).toBe(true)
    expect(card.grid[2][2].marked).toBe(true)
  })

  it('generates numbers in 1-90 segmented ranges', () => {
    const card = createBingoCard()
    for (let row = 0; row < 5; row++) {
      expect(card.grid[row][0].number).toBeGreaterThanOrEqual(1)
      expect(card.grid[row][0].number).toBeLessThanOrEqual(18)
      expect(card.grid[row][1].number).toBeGreaterThanOrEqual(19)
      expect(card.grid[row][1].number).toBeLessThanOrEqual(36)
      expect(card.grid[row][3].number).toBeGreaterThanOrEqual(55)
      expect(card.grid[row][3].number).toBeLessThanOrEqual(72)
      expect(card.grid[row][4].number).toBeGreaterThanOrEqual(73)
      expect(card.grid[row][4].number).toBeLessThanOrEqual(90)
    }
  })

  it('detects blackout only after all playable cells are marked', () => {
    const card = createBingoCard()
    expect(checkWinningPatterns(card)).toEqual([])

    card.grid
      .flat()
      .filter((cell) => !cell.isFreeSpace && cell.number !== null)
      .forEach((cell) => markNumber(card, cell.number as number))

    expect(checkWinningPatterns(card)).toEqual(['blackout'])
  })

  it('creates multiple cards with unique ids', () => {
    const cards = createBingoCards(3)
    expect(cards).toHaveLength(3)
    const ids = new Set(cards.map((card) => card.id))
    expect(ids.size).toBe(3)
  })
})

import { describe, expect, it } from 'vitest'
import {
  createGameState,
  drawNumber,
  drawNumbers,
  getGameStats,
  getRemainingNumbers,
  resetGame,
} from './rules'

describe('bingo-blackout integration', () => {
  it('supports draw flow with consistent stats', () => {
    const state = createGameState(2)
    const results = drawNumbers(state, 10)
    expect(results.filter(Boolean).length).toBe(10)
    expect(state.drawnNumbers.size).toBe(10)

    const stats = getGameStats(state)
    expect(stats.totalCards).toBe(2)
    expect(stats.numbersDrawn).toBe(10)
    expect(stats.numbersRemaining).toBe(80)
    expect(stats.completion).toBeGreaterThanOrEqual(0)
  })

  it('never draws duplicate numbers until pool exhaustion', () => {
    const state = createGameState(1)
    for (let i = 0; i < 90; i++) {
      drawNumber(state)
    }
    expect(state.drawnNumbers.size).toBe(90)
    expect(getRemainingNumbers(state)).toHaveLength(0)
    expect(drawNumber(state)).toBeNull()
  })

  it('resets round while preserving card ids', () => {
    const state = createGameState(3)
    const originalIds = state.cards.map((card) => card.id)
    drawNumbers(state, 20)
    resetGame(state)
    expect(state.drawnNumbers.size).toBe(0)
    expect(state.currentDrawn).toBeNull()
    expect(state.winners).toHaveLength(0)
    expect(state.cards.map((card) => card.id)).toEqual(originalIds)
  })
})

import { checkWinningPatterns, createBingoCards, isWinner, markNumber } from './card'
import { ALL_NUMBERS, DEFAULT_DRAW_SPEED } from './constants'
import type { BlackoutBingoGameState, DrawResult, WinnerCheck, WinningPattern } from './types'
import { MAX_CARDS, MIN_CARDS } from './types'

export function createGameState(
  cardCount: number = 1,
  drawSpeed: number = DEFAULT_DRAW_SPEED,
): BlackoutBingoGameState {
  const safeCardCount = Math.max(MIN_CARDS, Math.min(MAX_CARDS, cardCount))
  return {
    cards: createBingoCards(safeCardCount),
    drawnNumbers: new Set(),
    winners: [],
    gameActive: true,
    currentDrawn: null,
    drawSpeed,
    isAutoDrawing: false,
  }
}

export function drawNumber(state: BlackoutBingoGameState): DrawResult | null {
  if (!state.gameActive || state.drawnNumbers.size >= ALL_NUMBERS.length) {
    return null
  }

  const available = ALL_NUMBERS.filter((n) => !state.drawnNumbers.has(n))
  if (available.length === 0) {
    return null
  }

  const number = available[Math.floor(Math.random() * available.length)]
  state.drawnNumbers.add(number)
  state.currentDrawn = number

  for (const card of state.cards) {
    markNumber(card, number)
  }

  const newWinners = state.cards
    .filter((card) => !state.winners.includes(card.id) && isWinner(card))
    .map((card) => card.id)

  state.winners.push(...newWinners)
  if (state.winners.length > 0) {
    state.gameActive = false
    state.isAutoDrawing = false
  }

  return { number, winners: newWinners }
}

export function startAutoDraw(state: BlackoutBingoGameState): void {
  state.isAutoDrawing = true
}

export function stopAutoDraw(state: BlackoutBingoGameState): void {
  state.isAutoDrawing = false
}

export function setDrawSpeed(state: BlackoutBingoGameState, speed: number): void {
  state.drawSpeed = Math.max(250, speed)
}

export function drawNumbers(state: BlackoutBingoGameState, count: number): (DrawResult | null)[] {
  const results: (DrawResult | null)[] = []
  for (let i = 0; i < count; i++) {
    const result = drawNumber(state)
    results.push(result)
    if (!result || !state.gameActive) {
      break
    }
  }
  return results
}

export function getRemainingNumbers(state: BlackoutBingoGameState): number[] {
  return ALL_NUMBERS.filter((n) => !state.drawnNumbers.has(n))
}

export function getCardPatterns(state: BlackoutBingoGameState, cardId: string): WinningPattern[] {
  const card = state.cards.find((item) => item.id === cardId)
  return card ? checkWinningPatterns(card) : []
}

export function getWinnerCheck(state: BlackoutBingoGameState, cardId: string): WinnerCheck {
  const patterns = getCardPatterns(state, cardId)
  return {
    isWinner: patterns.length > 0,
    patterns,
  }
}

export function getCardHint(
  state: BlackoutBingoGameState,
  cardId: string,
): { row: number; col: number }[] {
  const card = state.cards.find((item) => item.id === cardId)
  if (!card) {
    return []
  }

  const hints: { row: number; col: number }[] = []
  card.grid.forEach((row, rowIndex) => {
    row.forEach((cell, colIndex) => {
      if (!cell.marked && !cell.isFreeSpace) {
        hints.push({ row: rowIndex, col: colIndex })
      }
    })
  })
  return hints
}

export function resetGame(state: BlackoutBingoGameState): void {
  state.drawnNumbers.clear()
  state.winners.length = 0
  state.gameActive = true
  state.currentDrawn = null
  state.isAutoDrawing = false

  for (const card of state.cards) {
    for (const row of card.grid) {
      for (const cell of row) {
        cell.marked = cell.isFreeSpace
      }
    }
  }
}

export function endGame(state: BlackoutBingoGameState): void {
  state.gameActive = false
  state.isAutoDrawing = false
}

export function getGameStats(state: BlackoutBingoGameState) {
  const targetCellsPerCard = 24
  const totalTargets = targetCellsPerCard * state.cards.length
  const markedTargets = state.cards.reduce(
    (total, card) =>
      total + card.grid.flat().filter((cell) => !cell.isFreeSpace && cell.marked).length,
    0,
  )

  return {
    totalCards: state.cards.length,
    numbersDrawn: state.drawnNumbers.size,
    numbersRemaining: ALL_NUMBERS.length - state.drawnNumbers.size,
    winners: state.winners,
    completion: totalTargets === 0 ? 0 : (markedTargets / totalTargets) * 100,
  }
}

export function cloneGameState(state: BlackoutBingoGameState): BlackoutBingoGameState {
  return {
    ...state,
    cards: state.cards.map((card) => ({
      ...card,
      grid: card.grid.map((row) =>
        row.map((cell) => ({
          ...cell,
        })),
      ),
    })),
    drawnNumbers: new Set(state.drawnNumbers),
    winners: [...state.winners],
  }
}

