      }

      // Card structure should remain valid
      expect(gameState.card.length).toBe(5)
      gameState.card.forEach((row) => {
        expect(row.length).toBe(5)
        row.forEach((cell) => {
          expect(typeof cell.marked).toBe('boolean')
          expect(typeof cell.number).toBe('number')
        })
      })
