  drawnNumbers: number[]
  hints: Array<[number, number]>
}

export const BingoCard: React.FC<Props> = ({ grid, drawnNumbers, hints }) => {
  const hintSet = new Set(hints.map((h) => `${h[0]},${h[1]}`))
  const drawnSet = new Set(drawnNumbers)

  return (
    <div className={styles.card}>
      {grid.map((row, rowIdx) => (
        <div key={rowIdx} className={styles.row}>
          {row.map((cell, colIdx) => {
            const isHint = hintSet.has(`${rowIdx},${colIdx}`)
            const isDrawn = drawnSet.has(cell.number)
            const isMarked = cell.marked
            const isFree = cell.number === 0

            return (
              <div
                key={`${rowIdx}-${colIdx}`}
                className={`${styles.cell} ${isMarked ? styles.marked : ''} ${
                  isHint ? styles.hint : ''
                }`}
                aria-label={isFree ? 'Free' : `${cell.number}${isMarked ? ' marked' : ''}`}
              >
                {!isFree && <span className={styles.number}>{cell.number}</span>}
                {isFree && <span className={styles.free}>FREE</span>}
              </div>
            )
          })}
        </div>
      ))}
    </div>
  )
}

// Bingo Progressive hooks barrel
export { useGame } from './useGame'

export type { GameState } from '@/domain'

/**
 * Progressive Bingo game state management hook
 */

import type { GameState } from '@/domain'
import { createGameState, drawNumber, getHints, getJackpot, getLevel, getWinners } from '@/domain'
import { useCallback, useState } from 'react'

export function useGame(cardCount: number = 1) {
  const [gameState, setGameState] = useState<GameState>(() => createGameState(cardCount))

  const drawSingleNumber = useCallback(() => {
    const result = drawNumber(gameState)
    if (result) {
      setGameState({ ...gameState })
    }
  }, [gameState])

  const handleReset = useCallback(() => {
    setGameState(createGameState(gameState.cards.length))
  }, [gameState.cards.length])

  const handleNewGame = useCallback((newCardCount: number) => {
    setGameState(createGameState(newCardCount))
  }, [])

  const winners = getWinners(gameState)
  const level = getLevel(gameState)
  const jackpot = getJackpot(gameState)
  const hints = getHints(gameState)

  return {
    gameState,
    drawSingleNumber,
    handleReset,
    handleNewGame,
    getWinnerChecks: () => gameState.winners,
    getHintPositions: () => hints,
    level,
    jackpot,
  }
}

export default useGame

/**
 * Progressive Bingo card generation and marking
 */

import { CARD_SIZE, CENTER_INDEX, GRID_SIZE, MAX_NUMBER } from './constants'
import type { Card } from './types'

let fallbackIdCounter = 0

const getWebCrypto = (): Crypto | null =>
  typeof globalThis !== 'undefined' && 'crypto' in globalThis ? globalThis.crypto : null

const getRandomInt = (maxExclusive: number): number => {
  const crypto = getWebCrypto()
  if (crypto?.getRandomValues) {
    const values = new Uint32Array(1)
    crypto.getRandomValues(values)
    return values[0] % maxExclusive
  }
  fallbackIdCounter += 1
  return Math.abs((Date.now() ^ (fallbackIdCounter * 2654435761)) >>> 0) % maxExclusive
}

// UUID generation helper
const generateId = (): string => {
  const crypto = getWebCrypto()
  if (crypto?.randomUUID) {
    return crypto.randomUUID()
  }
  fallbackIdCounter += 1
  return `card-${Date.now()}-${fallbackIdCounter}`
}

/**
 * Generate a single progressive bingo card (5x5 grid with free center)
 */
function generateCard(): Card {
  const squares: (number | null)[] = []
  const used = new Set<number>()
  const marked: boolean[] = []

  // Generate 24 unique numbers from 1-MAX_NUMBER (center is free)
  for (let i = 0; i < CARD_SIZE; i++) {
    if (i === CENTER_INDEX) {
      squares.push(null) // Free center tile
      marked.push(true) // Center is always marked (free space)
    } else {
      let num: number
      do {
        num = getRandomInt(MAX_NUMBER) + 1
      } while (used.has(num))
      squares.push(num)
      marked.push(false)
      used.add(num)
    }
  }

  return {
    id: generateId(),
    squares,
    marked,
  }
}

/**
 * Generate multiple bingo cards
 */
export function createBingoCards(count: number): Card[] {
  return Array.from({ length: count }, () => generateCard())
}

/**
 * Mark a number on all cards
 */
export function markNumber(cards: Card[], number: number): Card[] {
  return cards.map((card) => {
    const newMarked = [...card.marked]
    for (let i = 0; i < card.squares.length; i++) {
      if (card.squares[i] === number) {
        newMarked[i] = true
      }
    }
    return {
      ...card,
      marked: newMarked,
    }
  })
}

/**
 * Check if a row is marked
 */
function isRowMarked(card: Card, row: number): boolean {
  const start = row * GRID_SIZE
  const end = start + GRID_SIZE
  return card.marked.slice(start, end).every((m) => m)
}

/**
 * Check if a column is marked
 */
function isColumnMarked(card: Card, col: number): boolean {
  for (let row = 0; row < GRID_SIZE; row++) {
    if (!card.marked[row * GRID_SIZE + col]) {
      return false
    }
  }
  return true
}

/**
 * Check if diagonal 1 (top-left to bottom-right) is marked
 */
function isDiagonal1Marked(card: Card): boolean {
  for (let i = 0; i < GRID_SIZE; i++) {
    if (!card.marked[i * GRID_SIZE + i]) {
      return false
    }
  }
  return true
}

/**
 * Check if diagonal 2 (top-right to bottom-left) is marked
 */
function isDiagonal2Marked(card: Card): boolean {
  for (let i = 0; i < GRID_SIZE; i++) {
    if (!card.marked[i * GRID_SIZE + (GRID_SIZE - 1 - i)]) {
      return false
    }
  }
  return true
}

/**
 * Check if a card is a winner
 */
export function isWinner(card: Card): boolean {
  // Check rows
  for (let row = 0; row < GRID_SIZE; row++) {
    if (isRowMarked(card, row)) {
      return true
    }
  }

  // Check columns
  for (let col = 0; col < GRID_SIZE; col++) {
    if (isColumnMarked(card, col)) {
      return true
    }
  }

  // Check diagonals
  return isDiagonal1Marked(card) || isDiagonal2Marked(card)
}

import { beforeEach, describe, expect, it } from 'vitest'
import { ALL_NUMBERS, CENTER_INDEX, MAX_NUMBER } from './constants'
import { createGameState, drawNumber, resetGame } from './rules'
import type { GameState } from './types'

describe('bingo-progressive (Progressive 5x5 Bingo) - Integration Tests', () => {
  let gameState: GameState

  beforeEach(() => {
    gameState = createGameState()
  })

  describe('Game Initialization', () => {
    it('should create a valid initial game state', () => {
      expect(gameState).toBeDefined()
      expect(gameState.cards).toBeDefined()
      expect(gameState.cards.length).toBeGreaterThan(0)
      expect(gameState.drawnNumbers).toBeInstanceOf(Set)
      expect(gameState.drawnNumbers.size).toBe(0)
      expect(gameState.winners).toEqual([])
      expect(gameState.gameActive).toBe(true)
      expect(gameState.currentDrawn).toBeNull()
      expect(gameState.level).toBe(1)
      expect(gameState.jackpot).toBeGreaterThan(0)
    })

    it('should have a correctly sized board (5x5)', () => {
      gameState.cards.forEach((card) => {
        // 5x5 = 25 squares
        expect(card.squares.length).toBe(25)
        expect(card.marked.length).toBe(25)
      })
    })

    it('should mark the center square as initialized (free space)', () => {
      gameState.cards.forEach((card) => {
        // Center square (index 12 for 5x5) should be marked (free space)
        expect(card.marked[CENTER_INDEX]).toBe(true)
      })
    })
  })

  describe('Free Center Square', () => {
    it('should have CENTER_INDEX constant correctly calculated', () => {
      // 5x5 grid: center is row 2, col 2 = index 12
      expect(CENTER_INDEX).toBe(12)
    })

    it('should start with center square marked as free', () => {
      gameState.cards.forEach((card) => {
        expect(card.marked[CENTER_INDEX]).toBe(true)
      })
    })

    it('should have center free space in position (2,2)', () => {
      // Verify center index corresponds to position (2,2) in 5x5 grid
      const centerRow = Math.floor(CENTER_INDEX / 5)
      const centerCol = CENTER_INDEX % 5
      expect(centerRow).toBe(2)
      expect(centerCol).toBe(2)
    })
  })

  describe('Number Drawing', () => {
    it('should draw valid numbers between 1 and 75', () => {
      for (let i = 0; i < 30; i++) {
        drawNumber(gameState)
        const drawn = Array.from(gameState.drawnNumbers)
        if (drawn.length > 0) {
          const lastDrawn = drawn[drawn.length - 1]
          expect(lastDrawn).toBeGreaterThanOrEqual(1)
          expect(lastDrawn).toBeLessThanOrEqual(MAX_NUMBER)
        }
      }
    })

    it('should accumulate drawn numbers without duplicates', () => {
      for (let i = 0; i < 50; i++) {
        drawNumber(gameState)
      }

      const drawn = Array.from(gameState.drawnNumbers)
      const uniqueNumbers = new Set(drawn)
      expect(uniqueNumbers.size).toBe(drawn.length) // No duplicates
    })

    it('should mark matching numbers on cards', () => {
      // Get numbers from first card (excluding center which is pre-marked)
      const cardNumbers = new Set<number>()
      gameState.cards[0].squares.forEach((num, idx) => {
        if (idx !== CENTER_INDEX && num !== null) {
          cardNumbers.add(num)
        }
      })

      // Draw some numbers
      for (const num of Array.from(cardNumbers).slice(0, 5)) {
        // Keep drawing until we get this number
        while (!gameState.drawnNumbers.has(num) && gameState.drawnNumbers.size < MAX_NUMBER) {
          drawNumber(gameState)
        }

        if (gameState.drawnNumbers.has(num)) {
          // Check if the number is marked on the card
          const squareIdx = gameState.cards[0].squares.indexOf(num)
          if (squareIdx !== -1) {
            expect(gameState.cards[0].marked[squareIdx]).toBe(true)
          }
        }
      }
    })

    it('should track current drawn number', () => {
      expect(gameState.currentDrawn).toBeNull()

      drawNumber(gameState)
      expect(gameState.currentDrawn).toBeDefined()
      expect(typeof gameState.currentDrawn).toBe('number')
    })

    it('should maintain draw count accuracy', () => {
      for (let i = 0; i < 25; i++) {
        drawNumber(gameState)
      }

      expect(gameState.drawnNumbers.size).toBe(25)
    })
  })

  describe('Progressive Jackpot', () => {
    it('should initialize with level 1', () => {
      expect(gameState.level).toBe(1)
    })

    it('should have initial jackpot value', () => {
      expect(gameState.jackpot).toBeGreaterThan(0)
    })

    it('should track winners', () => {
      expect(gameState.winners).toEqual([])
      expect(Array.isArray(gameState.winners)).toBe(true)
    })
  })

  describe('Winning Conditions', () => {
    it('should detect winners when card is complete', () => {
      // Mark all squares on first card
      gameState.cards[0].marked = gameState.cards[0].marked.map(() => true)

      // Verify all marked
      const allMarked = gameState.cards[0].marked.every((m) => m === true)
      expect(allMarked).toBe(true)
    })

    it('should track winning card IDs', () => {
      expect(gameState.winners).toEqual([])
      expect(Array.isArray(gameState.winners)).toBe(true)
    })

    it('should support multiple cards with independent tracking', () => {
      const multiCardState = createGameState(2)
      expect(multiCardState.cards.length).toBe(2)
      expect(multiCardState.cards[0].id).not.toBe(multiCardState.cards[1].id)
    })
  })

  describe('Game Reset', () => {
    it('should reset game state correctly', () => {
      // Play a few rounds
      for (let i = 0; i < 20; i++) {
        drawNumber(gameState)
      }

      expect(gameState.drawnNumbers.size).toBeGreaterThan(0)

      // Reset
      const resetState = resetGame(gameState)

      expect(resetState.drawnNumbers.size).toBe(0)
      expect(resetState.winners).toEqual([])
      expect(resetState.gameActive).toBe(true)
      expect(resetState.level).toBe(1)
    })

    it('should generate fresh cards after reset', () => {
      const resetState = resetGame(gameState)

      expect(resetState.drawnNumbers.size).toBe(0)
      expect(resetState.cards.length).toBe(gameState.cards.length)
    })

    it('should reset level to 1 on game reset', () => {
      const resetState = resetGame(gameState)
      expect(resetState.level).toBe(1)
    })
  })

  describe('Constants Validation', () => {
    it('should have ALL_NUMBERS constant with correct length', () => {
      expect(ALL_NUMBERS.length).toBe(MAX_NUMBER)
      expect(MAX_NUMBER).toBe(75)
    })

    it('should have ALL_NUMBERS containing values 1 through 75', () => {
      for (let i = 1; i <= MAX_NUMBER; i++) {
        expect(ALL_NUMBERS).toContain(i)
      }
    })

    it('should have no duplicate numbers in ALL_NUMBERS', () => {
      const uniqueNumbers = new Set(ALL_NUMBERS)
      expect(uniqueNumbers.size).toBe(ALL_NUMBERS.length)
    })

    it('should have CENTER_INDEX constant', () => {
      expect(CENTER_INDEX).toBeDefined()
      expect(typeof CENTER_INDEX).toBe('number')
    })
  })

  describe('Grid Configuration', () => {
    it('should maintain 5x5 grid structure per card', () => {
      gameState.cards.forEach((card) => {
        // 25 squares = 5x5 grid
        expect(card.squares.length).toBe(25)
        expect(card.marked.length).toBe(25)
      })
    })

    it('should have 25 cells total', () => {
      gameState.cards.forEach((card) => {
        expect(card.squares.length).toBe(25)
      })
    })

    it('should have valid MAX_NUMBER constant', () => {
      expect(MAX_NUMBER).toBe(75)
    })
  })

  describe('Game Flow', () => {
    it('should support extended play scenarios', () => {
      let roundsPlayed = 0

      while (roundsPlayed < 30 && gameState.drawnNumbers.size < MAX_NUMBER) {
        drawNumber(gameState)
        roundsPlayed++
      }

      expect(gameState.drawnNumbers.size).toBeLessThanOrEqual(30)
      expect(gameState.gameActive).toBe(true) // Or could be false if all marked
    })

    it('should maintain game state consistency during play', () => {
      for (let i = 0; i < 20; i++) {
        drawNumber(gameState)

        // State invariants
        expect(gameState.drawnNumbers.size).toBeLessThanOrEqual(MAX_NUMBER)
        expect(Array.isArray(gameState.winners)).toBe(true)
      }
    })

    it('should track progressive level changes', () => {
      const initialLevel = gameState.level
      expect(gameState.level).toBe(1)

      // Level changes when winners occur (handled by drawNumber)
      for (let i = 0; i < 30; i++) {
        drawNumber(gameState)
      }

      // Level should still be tracked
      expect(typeof gameState.level).toBe('number')
      expect(gameState.level).toBeGreaterThanOrEqual(initialLevel)
    })

    it('should support multiple cards in a game', () => {
      const twoCardState = createGameState(2)
      expect(twoCardState.cards.length).toBe(2)

      for (let i = 0; i < 10; i++) {
        drawNumber(twoCardState)
      }

      expect(twoCardState.drawnNumbers.size).toBe(10)
    })
  })
})

/**
 * Progressive Bingo game rules and state management
 * Standard 5x5 grid (75 balls) with progressive jackpot levels
 */

import { createBingoCards, isWinner, markNumber } from './card'
import { ALL_NUMBERS } from './constants'
import type { DrawResult, GameState } from './types'

const BASE_JACKPOT = 100
const LEVEL_MULTIPLIER = 2

/**
 * Initialize a new progressive bingo game
 */
export function createGameState(cardCount: number = 1): GameState {
  return {
    cards: createBingoCards(cardCount),
    drawnNumbers: new Set(),
    winners: [],
    gameActive: true,
    currentDrawn: null,
    level: 1,
    jackpot: BASE_JACKPOT,
  }
}

/**
 * Draw the next random number
 */
export function drawNumber(state: GameState): DrawResult | null {
  if (!state.gameActive || state.drawnNumbers.size >= ALL_NUMBERS.length) {
    return null
  }

  let number: number
  do {
    number = ALL_NUMBERS[Math.floor(Math.random() * ALL_NUMBERS.length)]
  } while (state.drawnNumbers.has(number))

  const newDrawnNumbers = new Set(state.drawnNumbers)
  newDrawnNumbers.add(number)

  const markedCards = markNumber(state.cards, number)
  const newWinners: string[] = []

  markedCards.forEach((card) => {
    if (!state.winners.includes(card.id) && isWinner(card)) {
      newWinners.push(card.id)
    }
  })

  state.drawnNumbers = newDrawnNumbers
  state.cards = markedCards
  state.winners = [...state.winners, ...newWinners]
  state.currentDrawn = number

  // Update level and jackpot based on winners
  if (newWinners.length > 0) {
    state.level += newWinners.length
    state.jackpot = BASE_JACKPOT * Math.pow(LEVEL_MULTIPLIER, state.level - 1)
  }

  state.gameActive = newWinners.length === 0 || state.winners.length < state.cards.length

  return {
    number,
    drawnCount: newDrawnNumbers.size,
    totalNumbers: ALL_NUMBERS.length,
  }
}

/**
 * Reset the current game
 */
export function resetGame(state: GameState): GameState {
  return createGameState(state.cards.length)
}

/**
 * Get winning card IDs
 */
export function getWinners(state: GameState): string[] {
  return state.winners
}

/**
 * Get current level
 */
export function getLevel(state: GameState): number {
  return state.level
}

/**
 * Get current jackpot
 */
export function getJackpot(state: GameState): number {
  return state.jackpot
}

/**
 * Get hint positions for the last drawn number
 */
export function getHints(state: GameState): number[] {
  if (!state.currentDrawn) {
    return []
  }
  const positions: number[] = []
  state.cards.forEach((card) => {
    card.squares.forEach((square, idx) => {
      if (square === state.currentDrawn) {
        positions.push(idx)
      }
    })
  })
  return positions
}

