 * Ensures no duplicates within the card.
 */
function generateColumnNumbers(column: 'B' | 'I' | 'N' | 'G' | 'O', count: number = 5): number[] {
  const [min, max] = COLUMN_RANGES[column]
  const range = Array.from({ length: max - min + 1 }, (_, i) => min + i)

  const shuffled = range.sort(() => Math.random() - 0.5)
  return shuffled.slice(0, count)
}

/**
 * Create a new bingo card with random numbers.
 * Center cell is always a free space.
 */
export function createBingoCard(id: string = crypto.randomUUID()): BingoCard {
  const grid: BingoCell[][] = []

  for (let row = 0; row < GRID_SIZE; row++) {
    const gridRow: BingoCell[] = []

    for (let col = 0; col < GRID_SIZE; col++) {
      const columnKey = ['B', 'I', 'N', 'G', 'O'][col] as 'B' | 'I' | 'N' | 'G' | 'O'
      const isFreeSpace = row === 2 && col === 2

      if (isFreeSpace) {
        gridRow.push({
          number: null,
          marked: true, // Free space is always marked
          isFreeSpace: true,
        })
      } else {
        let number: number | null = null
        try {
          const numbers = generateColumnNumbers(columnKey)
          number = numbers[row] || null
        } catch (e) {
          console.error(`Error generating number for ${columnKey}${row}:`, e)
        }

        gridRow.push({
          number,
          marked: false,
          isFreeSpace: false,
        })
      }
    }

    grid.push(gridRow)
  }

  return { id, grid }
}

/**
 * Create multiple bingo cards.
 */
export function createBingoCards(count: number): BingoCard[] {
  return Array.from({ length: count }, (_, i) => createBingoCard(`card-${i}`))
}

/**
 * Mark a number on a card if it exists.
 * Returns true if number was found and marked.
 */
export function markNumber(card: BingoCard, number: number): boolean {
  for (const row of card.grid) {
    for (const cell of row) {
      if (cell.number === number && !cell.marked) {
        cell.marked = true
        return true
      }
    }
  }
  return false
}

/**
 * Get all marked cells for a card.
 */
export function getMarkedCells(card: BingoCard): BingoCell[] {
  return card.grid.flat().filter((cell) => cell.marked)
}

/**
 * Check if a card has a complete row.
 */
export function hasCompleteRow(card: BingoCard): boolean {
  return card.grid.some((row) => row.every((cell) => cell.marked))
}

/**
 * Check if a card has a complete column.
 */
export function hasCompleteColumn(card: BingoCard): boolean {
  for (let col = 0; col < GRID_SIZE; col++) {
    if (card.grid.every((row) => row[col].marked)) {
      return true
    }
  }
  return false
}

/**
 * Check if a card has a complete diagonal (top-left to bottom-right).
 */
export function hasCompleteDiagonalLeft(card: BingoCard): boolean {
  for (let i = 0; i < GRID_SIZE; i++) {
    if (!card.grid[i][i].marked) {
      return false
    }
  }
  return true
}

/**
 * Check if a card has a complete diagonal (top-right to bottom-left).
 */
export function hasCompleteDiagonalRight(card: BingoCard): boolean {
  for (let i = 0; i < GRID_SIZE; i++) {
    if (!card.grid[i][GRID_SIZE - 1 - i].marked) {
      return false
    }
  }
  return true
}

/**
 * Check if a card has all four corners marked.
 */
export function hasFourCorners(card: BingoCard): boolean {
  const corners = [
    card.grid[0][0],
    card.grid[0][GRID_SIZE - 1],
    card.grid[GRID_SIZE - 1][0],
    card.grid[GRID_SIZE - 1][GRID_SIZE - 1],
  ]
  return corners.every((cell) => cell.marked)
}

/**
 * Check if a card has all cells marked (blackout/full card).
 */
export function isBlackout(card: BingoCard): boolean {
  return card.grid.every((row) => row.every((cell) => cell.marked))
}

/**
 * Check if a card is a winner (standard 5-in-a-row).
 */
export function isWinner(card: BingoCard): boolean {
  return (
    hasCompleteRow(card) ||
    hasCompleteColumn(card) ||
    hasCompleteDiagonalLeft(card) ||
    hasCompleteDiagonalRight(card)
  )
}

/**
 * Check for all possible winning patterns.
 */
export function checkWinningPatterns(card: BingoCard): string[] {
  const patterns: string[] = []

  if (hasCompleteRow(card)) {
    patterns.push('horizontal')
  }
  if (hasCompleteColumn(card)) {
    patterns.push('vertical')
  }
  if (hasCompleteDiagonalLeft(card)) {
    patterns.push('diagonal-left')
  }
  if (hasCompleteDiagonalRight(card)) {
    patterns.push('diagonal-right')
  }
  if (hasFourCorners(card)) {
    patterns.push('four-corners')
  }
  if (isBlackout(card)) {
    patterns.push('blackout')
  }

  return patterns
}

/**
 * Bingo game rules and state management.
 */

import { checkWinningPatterns, createBingoCards, isWinner, markNumber } from './card'
import type { BingoGameState, DrawResult } from './types'

const ALL_NUMBERS = Array.from({ length: 75 }, (_, i) => i + 1)

/**
 * Initialize a new game with specified number of cards.
 */
export function createGameState(cardCount: number = 1): BingoGameState {
  return {
    cards: createBingoCards(cardCount),
    drawnNumbers: new Set(),
    winners: [],
    gameActive: true,
    currentDrawn: null,
  }
}

/**
 * Draw the next random number from the pool.
 */
export function drawNumber(state: BingoGameState): DrawResult | null {
  if (!state.gameActive || state.drawnNumbers.size >= ALL_NUMBERS.length) {
    return null
  }

  const availableNumbers = ALL_NUMBERS.filter((n) => !state.drawnNumbers.has(n))
  if (availableNumbers.length === 0) {
    return null
  }

  const number = availableNumbers[Math.floor(Math.random() * availableNumbers.length)]
  state.drawnNumbers.add(number)
  state.currentDrawn = number

  // Mark number on all cards
  for (const card of state.cards) {
    markNumber(card, number)
  }

  // Check for winners
  const newWinners = state.cards
    .filter((card) => !state.winners.includes(card.id) && isWinner(card))
    .map((card) => card.id)

  state.winners.push(...newWinners)

  return {
    number,
    winners: newWinners,
  }
}

/**
 * Draw multiple numbers in sequence.
 */
export function drawNumbers(state: BingoGameState, count: number): (DrawResult | null)[] {
  const results: (DrawResult | null)[] = []
  for (let i = 0; i < count; i++) {
    const result = drawNumber(state)
    results.push(result)
    if (!result) {
      break
    }
  }
  return results
}

/**
 * Get the next number that would be drawn from the pool.
 */
export function peekNextNumber(state: BingoGameState): number | null {
  const availableNumbers = ALL_NUMBERS.filter((n) => !state.drawnNumbers.has(n))
  return availableNumbers.length > 0 ? availableNumbers[0] : null
}

/**
 * Get all remaining numbers in the draw pool.
 */
export function getRemainingNumbers(state: BingoGameState): number[] {
  return ALL_NUMBERS.filter((n) => !state.drawnNumbers.has(n))
}

/**
 * Check if a card is a winner.
 */
export function checkCardWin(state: BingoGameState, cardId: string): boolean {
  const card = state.cards.find((c) => c.id === cardId)
  return card ? isWinner(card) : false
}

/**
 * Get winning patterns for a card.
 */
export function getCardPatterns(state: BingoGameState, cardId: string): string[] {
  const card = state.cards.find((c) => c.id === cardId)
  return card ? checkWinningPatterns(card) : []
}

/**
 * Get hint for a card - returns positions of unmarked numbers that are still available.
 */
export function getCardHint(state: BingoGameState, cardId: string): { row: number; col: number }[] {
  const card = state.cards.find((c) => c.id === cardId)
  if (!card) {
    return []
  }

  const hintPositions: { row: number; col: number }[] = []

  for (let row = 0; row < card.grid.length; row++) {
    for (let col = 0; col < card.grid[row].length; col++) {
      const cell = card.grid[row][col]
      // Only hint for unmarked cells that have numbers and are still available
      if (!cell.marked && cell.number && !state.drawnNumbers.has(cell.number)) {
        hintPositions.push({ row, col })
      }
    }
  }

  return hintPositions
}

/**
 * Reset the game state (keep cards, reset draws).
 */
export function resetGame(state: BingoGameState): BingoGameState {
  return {
    ...state,
    drawnNumbers: new Set(),
    winners: [],
    gameActive: true,
    currentDrawn: null,
  }
}

/**
 * Get game statistics.
 */
export function getGameStats(state: BingoGameState) {
  return {
    totalCards: state.cards.length,
    numbersDrawn: state.drawnNumbers.size,
    numbersRemaining: ALL_NUMBERS.length - state.drawnNumbers.size,
    winners: state.winners,
    completion: (state.drawnNumbers.size / ALL_NUMBERS.length) * 100,
  }
}

