/**
 * Game Context - Central game state management
 * Provides a React Context for sharing game state across components
 */

import type { GameAction, GameState } from '@/domain'
import { createGameState, dealInitialHands, playDealerTurn, processPlayerAction } from '@/domain'
import React, { createContext, ReactNode, useReducer } from 'react'

export interface GameContextValue {
  gameState: GameState
  dispatch: React.Dispatch<GameContextAction>
}

export type GameContextAction =
  | { type: 'RESET_GAME'; payload?: { balance?: number } }
  | { type: 'SET_BET'; payload: number }
  | { type: 'DEAL_HANDS'; payload: { playerCards: any[]; dealerCards: any[] } }
  | { type: 'PLAYER_ACTION'; payload: { action: GameAction; card?: any } }
  | { type: 'DEALER_TURN'; payload: { cards: any[] } }
  | { type: 'SETTLEMENT' }
  | { type: 'NEW_ROUND' }

function gameReducer(state: GameState, action: GameContextAction): GameState {
  switch (action.type) {
    case 'RESET_GAME':
      return createGameState(action.payload?.balance)

    case 'SET_BET': {
      const player = state.players[0]
      if (!player) {return state}
      return {
        ...state,
        players: [
          {
            ...player,
            currentHand: {
              ...player.currentHand,
              bet: action.payload,
            },
          },
          ...state.players.slice(1),
        ],
      }
    }

    case 'DEAL_HANDS':
      return dealInitialHands(state, action.payload.playerCards, action.payload.dealerCards)

    case 'PLAYER_ACTION':
      return processPlayerAction(state, action.payload.action)

    case 'DEALER_TURN':
      return playDealerTurn(state)

    case 'SETTLEMENT':
      return {
        ...state,
        phase: 'settling',
      }

    case 'NEW_ROUND': {
      const player = state.players[0]
      const balance = player?.balance ?? 0
      return createGameState(balance)
    }

    default:
      return state
  }
}

export const GameContext = createContext<GameContextValue | undefined>(undefined)

export function GameProvider({ children }: { children: ReactNode }) {
  const [gameState, dispatch] = useReducer(gameReducer, createGameState())

  return <GameContext.Provider value={{ gameState, dispatch }}>{children}</GameContext.Provider>
}

export function useGameContext() {
  const context = React.useContext(GameContext)
  if (!context) {
    throw new Error('useGameContext must be used within GameProvider')
  }
  return context
}

import { createBankroll, createGamingSession, createTableConfig, endSession, getSessionStats, updateSessionAfterRound, } from '@games/banking';
import { useEffect, useState } from 'react';
/**
 * useBankroll — Manages player bankroll, table selection, and gaming sessions.
 *
 * This hook:
 * - Creates/loads player bankroll from localStorage
 * - Manages table selection and chip set
 * - Creates and tracks gaming sessions
 * - Records bets and updates bankroll after each hand
 * - Provides session statistics
 *
 * Because gamer progression across tables needs cross-game consistency,
 * bankroll is stored with a player ID and persists across all games.
 */
export const useBankroll = (playerId, gameId) => {
    // Bankroll state
    const [bankroll, setBankroll] = useState(null);
    const [isLoadingBankroll, setIsLoadingBankroll] = useState(true);
    // Table selection state
    const [selectedTableVariant, setSelectedTableVariant] = useState(null);
    const [tableConfig, setTableConfig] = useState(null);
    const [selectedChipSet, setSelectedChipSet] = useState([]);
    // Gaming session state
    const [gameSession, setGameSession] = useState(null);
    const [betHistory, setBetHistory] = useState([]);
    // Storage keys
    const bankrollKey = `bankroll:${playerId}`;
    const sessionKey = `session:${playerId}:${gameId}`;
    /**
     * Load bankroll from localStorage on mount
     * If no bankroll exists, create a default one ($100 starting balance)
     */
    useEffect(() => {
        const loadBankroll = async () => {
            try {
                const stored = localStorage.getItem(bankrollKey);
                if (stored) {
                    setBankroll(JSON.parse(stored));
                }
                else {
                    // Create new bankroll with $100 starting amount
                    const newBankroll = createBankroll(playerId, 100, 'USD');
                    setBankroll(newBankroll);
                    localStorage.setItem(bankrollKey, JSON.stringify(newBankroll));
                }
            }
            finally {
                setIsLoadingBankroll(false);
            }
        };
        loadBankroll();
    }, [playerId, bankrollKey]);
    /**
     * Handle table selection
     * Creates gaming session and sets up table configuration
     */
    const handleSelectTable = (variant, chipSet) => {
        if (!bankroll) {
            return;
        }
        // Create table configuration with game-specific settings
        const config = createTableConfig(gameId, variant, {
        // Optional: Add blackjack-specific house rules here
        });
        // Create gaming session
        const session = createGamingSession(playerId, gameId, config.id || variant, bankroll.amount);
        setSelectedTableVariant(variant);
        setTableConfig(config);
        setSelectedChipSet(chipSet);
        setGameSession(session);
        // Persist session to localStorage
        localStorage.setItem(sessionKey, JSON.stringify(session));
    };
    /**
     * Record a bet in the current session
     * Updates bankroll immediately
     * Do NOT update session yet - that happens after the game result
     */
    const recordBet = (betAmount) => {
        if (!bankroll || !gameSession) {
            console.warn('Cannot record bet: no bankroll or game session');
            return false;
        }
        // Check if player can afford the bet
        if (betAmount > bankroll.amount) {
            console.warn(`Insufficient funds: bet $${betAmount}, balance $${bankroll.amount}`);
            return false;
        }
        // Deduct bet from bankroll (money is "in play")
        const updatedBalance = bankroll.amount - betAmount;
        const updatedBankroll = {
            ...bankroll,
            amount: updatedBalance,
            updatedAt: new Date(),
        };
        setBankroll(updatedBankroll);
        localStorage.setItem(bankrollKey, JSON.stringify(updatedBankroll));
        return true;
    };
    /**
     * Record game result and update session
     * Called after each hand resolves (win/loss/push)
     */
    const recordGameResult = (result) => {
        if (!bankroll || !gameSession) {
            console.warn('Cannot record result: no bankroll or game session');
            return;
        }
        // 1. Update session with game result
        const updatedSession = updateSessionAfterRound(gameSession, result.betAmount, result.payout);
        setGameSession(updatedSession);
        // 2. Update bankroll with winnings
        const newBalance = bankroll.amount + result.payout;
        const updatedBankroll = {
            ...bankroll,
            amount: newBalance,
            updatedAt: new Date(),
        };
        setBankroll(updatedBankroll);
        localStorage.setItem(bankrollKey, JSON.stringify(updatedBankroll));
        // 3. Record bet in history
        const betRecord = {
            id: `${gameSession.id}-${Date.now()}`,
            sessionId: gameSession.id,
            gameId: gameId,
            tableId: gameSession.tableId,
            amount: result.betAmount,
            result: result.result,
            payout: result.payout,
            timestamp: new Date(),
            metadata: {
                variant: selectedTableVariant,
            },
        };
        setBetHistory((prev) => [...prev, betRecord]);
        // Persist updated session
        localStorage.setItem(sessionKey, JSON.stringify(updatedSession));
    };
    /**
     * End current gaming session and get final statistics
     */
    const endCurrentSession = () => {
        if (!gameSession) {
            return null;
        }
        const completedSession = endSession(gameSession);
        const stats = getSessionStats(completedSession);
        // Clear session from localStorage
        localStorage.removeItem(sessionKey);
        setGameSession(null);
        setBetHistory([]);
        return {
            session: completedSession,
            stats,
        };
    };
    /**
     * Cancel current session without saving (for quit/abandon)
     */
    const cancelSession = () => {
        localStorage.removeItem(sessionKey);
        setGameSession(null);
        setSelectedTableVariant(null);
        setTableConfig(null);
        setSelectedChipSet([]);
        setBetHistory([]);
    };
    return {
        // Bankroll
        bankroll,
        isLoadingBankroll,
        // Table selection
        selectedTableVariant,
        tableConfig,
        selectedChipSet,
        handleSelectTable,
        // Gaming session
        gameSession,
        betHistory,
        recordBet,
        recordGameResult,
        endCurrentSession,
        cancelSession,
        // Computed properties
        currentBalance: bankroll?.amount ?? 0,
        isTableSelected: selectedTableVariant !== null,
        isGameSessionActive: gameSession !== null,
    };
};

/**
 * useBasicStrategy Hook
 *
 * Manages basic strategy recommendations and tracking for player decisions.
 * Provides visual hints and accuracy feedback for learning mode.
 */

import type { GameAction, StrategyHint } from '@/domain'
import { getBasicStrategyRecommendation } from '@/domain'
import type { Card } from '@games/card-deck-core'
import { useCallback, useState } from 'react'

interface UseBasicStrategyProps {
  enabled: boolean
  learningMode: boolean
}

interface UseBasicStrategyResult {
  currentHint: StrategyHint | null
  correctDecisions: number
  totalDecisions: number
  accuracyRate: number
  getRecommendation: (
    playerValue: number | { hard: number; soft?: number },
    dealerUpCard: Card,
    playerAction: GameAction,
  ) => { recommendedAction: string; isCorrect: boolean }
  recordDecision: (isCorrect: boolean) => void
  resetStats: () => void
}

export const useBasicStrategy = ({
  enabled,
  learningMode,
}: UseBasicStrategyProps): UseBasicStrategyResult => {
  const [currentHint, setCurrentHint] = useState<StrategyHint | null>(null)
  const [correctDecisions, setCorrectDecisions] = useState(0)
  const [totalDecisions, setTotalDecisions] = useState(0)

  const accuracyRate = totalDecisions > 0 ? (correctDecisions / totalDecisions) * 100 : 0

  // Get recommendation for regular hand decision
  const getRecommendation = useCallback(
    (
      playerValue: number | { hard: number; soft?: number },
      dealerUpCard: Card,
      playerAction: GameAction,
    ) => {
      if (!enabled) {
        return { recommendedAction: '', isCorrect: false }
      }

      // Insurance is not part of basic strategy - skip recommendation
      if (playerAction === 'insurance') {
        return { recommendedAction: '', isCorrect: false }
      }

      // Extract hard and soft values
      const playerHardValue = typeof playerValue === 'number' ? playerValue : playerValue.hard
      const playerSoftValue = typeof playerValue === 'object' ? playerValue.soft : undefined

      const recommendation = getBasicStrategyRecommendation(
        playerHardValue,
        playerSoftValue,
        dealerUpCard,
        playerAction as Exclude<GameAction, 'insurance'>,
      )

      // Generate hint if learning mode is enabled
      if (learningMode) {
        const hint: StrategyHint = {
          type: 'action',
          message: recommendation.explanation,
          priority: recommendation.isCorrect ? 'low' : 'high',
          showInLearningMode: true,
        }
        setCurrentHint(hint)
      }

      // Auto-record decision if learning mode
      if (learningMode) {
        recordDecision(recommendation.isCorrect)
      }

      return {
        recommendedAction: recommendation.recommendedAction,
        isCorrect: recommendation.isCorrect,
      }
    },
    [enabled, learningMode],
  )

  // Record a decision as correct or incorrect
  const recordDecision = useCallback((isCorrect: boolean) => {
    setTotalDecisions((prev) => prev + 1)
    if (isCorrect) {
      setCorrectDecisions((prev) => prev + 1)
    }
  }, [])

  // Reset statistics
  const resetStats = useCallback(() => {
    setCorrectDecisions(0)
    setTotalDecisions(0)
    setCurrentHint(null)
  }, [])

  return {
    currentHint,
    correctDecisions,
    totalDecisions,
    accuracyRate,
    getRecommendation,
    recordDecision,
    resetStats,
  }
}

export default useBasicStrategy

