 */
export function getStrategyAccuracyFeedback(isCorrect, correctStreak) {
    if (!isCorrect) {
        return '❌ Not optimal play';
    }
    if (correctStreak >= 100) {
        return '🏆 Perfect strategy!!';
    }
    if (correctStreak >= 50) {
        return '⭐ Excellent strategy knowledge!';
    }
    if (correctStreak >= 20) {
