import type { GameState, Player, RollResult } from '@/domain'
import {
  advanceRound,
  applyRoll,
  CPU_DELAY_MS,
  createInitialState,
  ROLL_ANIMATION_MS,
  rollDice,
  scoreRoll,
} from '@/domain'
import { useEffect, useState } from 'react'

export interface GameCallbacks {
  onRollStart?: (isHuman: boolean) => void
  onRollResult?: (result: RollResult) => void
  onGameEnd?: (winner: Player) => void
}

export const useGame = (callbacks?: GameCallbacks) => {
  const [state, setState] = useState<GameState>(createInitialState)

  const executeRoll = (isHuman: boolean) => {
    callbacks?.onRollStart?.(isHuman)

    setState((previous) => {
      if (previous.isGameOver || previous.roundOver || previous.isRolling) {
        return previous
      }

      if (isHuman && previous.currentPlayer !== 'human') {
        return previous
      }

      if (!isHuman && previous.currentPlayer !== 'cpu') {
        return previous
      }

      return {
        ...previous,
        isRolling: true,
      }
    })

    window.setTimeout(() => {
      setState((previous) => {
        if (previous.isGameOver || previous.roundOver || !previous.isRolling) {
          return previous
        }

        const rollResult = scoreRoll(rollDice(), previous.target)
        const result = applyRoll(previous, rollResult)

        callbacks?.onRollResult?.(rollResult)
        return result
      })
    }, ROLL_ANIMATION_MS)
  }

  const roll = () => {
    executeRoll(true)
  }

  const nextRound = () => {
    setState((previous) => {
      if (!previous.roundOver || previous.isGameOver) {
        return previous
      }

      const advanced = advanceRound(previous)
      if (advanced.isGameOver && advanced.gameWinner) {
        callbacks?.onGameEnd?.(advanced.gameWinner)
      }
      return advanced
    })
  }

  const newGame = () => {
    setState(createInitialState())
  }

  useEffect(() => {
    if (state.currentPlayer !== 'cpu' || state.isGameOver || state.roundOver || state.isRolling) {
      return
    }

    const timerId = window.setTimeout(() => {
      executeRoll(false)
    }, CPU_DELAY_MS)

    return () => {
      window.clearTimeout(timerId)
    }
  }, [state.currentPlayer, state.isGameOver, state.roundOver, state.isRolling])

  return {
    state,
    roll,
    nextRound,
    newGame,
  }
}

export default useGame

/**
 * useGameEvents — composes sound effects, haptics, and stats tracking
 * into a GameCallbacks object for useGame.
 *
 * This hook bridges side-effect systems with the game state machine
 * without coupling them together.
 */

import { useMemo } from 'react'

import { vibrate } from './haptics'
import type { GameCallbacks } from './useGame'
import { useSoundEffects } from './useSoundEffects'
import { useStats } from './useStats'

export function useGameEvents() {
  const sounds = useSoundEffects()
  const { stats, recordWin, recordLoss, resetStats } = useStats()

  const callbacks: GameCallbacks = useMemo(
    () => ({
      onRollStart(isHuman) {
        if (isHuman) {
          sounds.onDiceRoll()
          vibrate(30)
        } else {
          sounds.onCpuMove()
        }
      },

      onRollResult(result) {
        if (result.isBunco) {
          sounds.onBunco()
          vibrate([100, 50, 100, 50, 100])
        } else if (result.isMiniBunco) {
          vibrate([50, 30, 50])
        }
      },

      onGameEnd(winner) {
        if (winner === 'human') {
          sounds.onWin()
          vibrate([50, 30, 50, 30, 100])
          recordWin()
        } else {
          sounds.onLose()
          vibrate(200)
          recordLoss()
        }
      },
    }),
    [sounds, recordWin, recordLoss],
  )

  return { callbacks, stats, resetStats }
}

export default useGameEvents

import type { DieValue } from './types'

/**
 * Rolls three dice, returning random values 1-6.
 * Bunco is purely luck-based — no strategy computation needed.
 */
export function rollDice(): [DieValue, DieValue, DieValue] {
  const roll = (): DieValue => (Math.floor(Math.random() * 6) + 1) as DieValue
  return [roll(), roll(), roll()]
}

