      counts[2],
      counts[3],
      counts[4],
      counts[5],
      counts[6],
      counts[7],
      state.piles.length,
      mode,
    )
    move = { pileId: (encoded >> 8) & 0xffff, removeCount: encoded & 0xff }
    engine = 'wasm'
  } else {
    move = selectMove(state)
  }

  self.postMessage({ move, engine })
}

