/**
 * Connect-Four AI Service
 *
 * Scale-aware orchestration for minimax AI:
 * - Sync path: Direct JS minimax (< 100ms for shallow depths)
 * - Async path: Worker-backed with timeout fallback (up to 500ms)
 *
 * Decision tree:
 *   easy (depth 1): Sync only, always < 10ms
 *   medium (depth 4): Optional async, typically 60-100ms; worker if needed
 *   hard (depth 8): Async required, typically 150-500ms; timeout to sync fallback
 *
 * WASM-first: Worker prefers WASM bitboard (~10x faster), falls back to JS minimax.
 */

import type { Board, Difficulty, Player } from '@/domain'
import { selectMove as selectMoveJS } from '@/domain'

export interface AiResult {
  move: number
  difficulty: Difficulty
  duration: number
  source: 'sync-js' | 'async-worker' | 'async-worker-fallback'
}

interface WorkerRequest {
  board: Board
  player: Player
  difficulty: Difficulty
}

// ── Worker lifecycle ────────────────────────────────────────────────────

let asyncWorker: Worker | null = null

/**
 * Initialize the async worker once per session.
 * On error, worker remains null and async paths fall back to sync.
 */
export function ensureAsyncWorkerReady(): void {
  if (asyncWorker) {
    return
  }
  try {
    asyncWorker = new Worker(new URL('../workers/ai.worker.ts', import.meta.url), {
      type: 'module',
    })
  } catch {
    // Worker load failed; async paths will use sync fallback
    asyncWorker = null
  }
}

/**
 * Terminate the async worker.
 * Call on app unmount to clean up resources.
 */
export function terminateAsyncWorker(): void {
  if (asyncWorker) {
    asyncWorker.terminate()
    asyncWorker = null
  }
}

// ── Sync path (main thread) ────────────────────────────────────────────

/**
 * Synchronous AI move computation (main thread).
 *
 * Uses JS minimax directly. Suitable for:
 *   - Easy difficulty (depth 1, always < 10ms)
 *   - Fallback when worker is unavailable
 *   - Testing and development
 *
 * @param board 42-cell flattened board state
 * @param player AI player (1 or 2)
 * @param difficulty 'easy' | 'medium' | 'hard'
 * @returns AiResult with move, timing, and source
 */
export function computeMove(board: Board, player: Player, difficulty: Difficulty): AiResult {
  const startTime = performance.now()
  const move = selectMoveJS(board, player, difficulty)
  const duration = performance.now() - startTime

  return {
    move,
    difficulty,
    duration,
    source: 'sync-js',
  }
}

// ── Async path (worker-backed) ────────────────────────────────────────

/**
 * Asynchronous AI move computation (worker-backed with fallback).
 *
 * Strategy:
 *   1. Dispatch to worker (WASM-first, JS fallback)
 *   2. Cap at 80% of expected max duration for that difficulty
 *   3. If timeout, fall back to sync JS on main thread
 *   4. If worker unavailable, use sync directly
 *
 * Suitable for:
 *   - Medium/hard difficulty where deep minimax may block UI
 *   - Ensuring UI responsiveness even during complex AI searches
 *   - Graceful degradation when workers fail
 *
 * Performance targets:
 *   - Easy: 10-20ms (worker overkill; use sync)
 *   - Medium: 80-100ms (worker helpful for concurrent requests)
 *   - Hard: 150-500ms (worker essential, timeout fallback safe)
 *
 * @param board Board state
 * @param player AI player
 * @param difficulty Game difficulty
 * @param timeoutMs Maximum time to wait for worker (defaults per difficulty)
 * @returns Promise<AiResult> with move, timing, and source
 */
export async function computeMoveAsync(
  board: Board,
  player: Player,
  difficulty: Difficulty,
  timeoutMs?: number,
): Promise<AiResult> {
  ensureAsyncWorkerReady()

  // Determine timeout based on difficulty
  const timeout =
    timeoutMs ??
    {
      easy: 50,
      medium: 120,
      hard: 400,
    }[difficulty]

  // If no worker available, fall back to sync
  if (!asyncWorker) {
    return computeMove(board, player, difficulty)
  }

  const startTime = performance.now()

  return new Promise((resolve) => {
    let resolved = false
    let timeoutId: ReturnType<typeof setTimeout> | null = null

    const timeoutHandle = setTimeout(() => {
      timeoutId = null
      if (!resolved) {
        resolved = true
        // Timeout: fall back to sync JS
        const result = computeMove(board, player, difficulty)
        resolve({
          ...result,
          duration: performance.now() - startTime,
          source: 'async-worker-fallback',
        })
      }
    }, timeout)

    const handler = (e: MessageEvent<{ move: number }>) => {
      if (timeoutId !== null) {
        clearTimeout(timeoutHandle)
        timeoutId = null
      }
      if (!resolved) {
        resolved = true
        const move = e.data.move
        resolve({
          move,
          difficulty,
          duration: performance.now() - startTime,
          source: 'async-worker',
        })
      }
    }

    asyncWorker!.addEventListener('message', handler, { once: true })
    asyncWorker!.postMessage({
      board,
      player,
      difficulty,
    } as WorkerRequest)
  })
}

/**
 * Make AI move decision, choosing sync or async based on difficulty.
 *
 * Heuristic:
 *   - easy: Always sync (< 10ms)
 *   - medium: Sync, but async available if needed
 *   - hard: Async default, with sync fallback on timeout
 *
 * @param board Board state
 * @param player AI player
 * @param difficulty Game difficulty
 * @param forceAsync Force async path (for hard mode)
 * @returns Promise<AiResult> (awaitable; sync returns resolved promise)
 */
export async function selectAiMove(
  board: Board,
  player: Player,
  difficulty: Difficulty,
  forceAsync: boolean = difficulty === 'hard',
): Promise<AiResult> {
  if (forceAsync) {
    return computeMoveAsync(board, player, difficulty)
  }
  return Promise.resolve(computeMove(board, player, difficulty))
}

/**
 * Connect-Four AI Service Tests
 *
 * Validates:
 * 1. Sync path: Direct JS minimax produces valid moves, completes within target
 * 2. Async path: Worker-backed execution, timeout fallback, equivalence
 * 3. Edge cases: Invalid boards, no playable columns, immediate wins/blocks
 * 4. Architecture: Correct source attribution, graceful degradation
 */

import type { Board } from '@/domain'
import { createInitialState, dropDisc, getCell, getPlayableColumns } from '@/domain'
import { describe, expect, it } from 'vitest'
import {
  computeMove,
  computeMoveAsync,
  ensureAsyncWorkerReady,
  selectAiMove,
  terminateAsyncWorker,
} from './connectFourAiService'

describe('connectFourAiService', () => {
  // ── Sync Path Tests ──────────────────────────────────────────────────

  describe('computeMove (sync)', () => {
    it('should produce valid move for easy difficulty', () => {
      const { board } = createInitialState('pvc', 'easy')
      const result = computeMove(board, 2, 'easy')

      expect(result.move).toBeGreaterThanOrEqual(0)
      expect(result.move).toBeLessThan(7)
      expect(result.source).toBe('sync-js')
      expect(result.duration).toBeLessThan(100)
    })

    it('should produce valid move for medium difficulty', () => {
      const { board } = createInitialState('pvc', 'medium')
      const result = computeMove(board, 2, 'medium')

      expect(result.move).toBeGreaterThanOrEqual(0)
      expect(result.move).toBeLessThan(7)
      expect(result.source).toBe('sync-js')
      expect(result.duration).toBeLessThan(200) // Medium may be slower
    })

    it('should produce valid move for hard difficulty', () => {
      const { board } = createInitialState('pvc', 'hard')
      const result = computeMove(board, 2, 'hard')

      expect(result.move).toBeGreaterThanOrEqual(0)
      expect(result.move).toBeLessThan(7)
      expect(result.source).toBe('sync-js')
      expect(result.duration).toBeLessThan(1000) // Hard may be slow
    })

    it('should complete easy difficulty in < 50ms', () => {
      const { board } = createInitialState('pvc', 'easy')
      const result = computeMove(board, 2, 'easy')

      expect(result.duration).toBeLessThan(50)
    })

    it('should return move even for full board (no valid moves)', () => {
      // Create a full board by filling it
      const board: Board = Array(42).fill(0) as Board
      // Fill columns 0-6 with alternating players
      for (let col = 0; col < 7; col++) {
        for (let row = 0; row < 6; row++) {
          const idx = row * 7 + col
          board[idx] = (col + row) % 2 === 0 ? 1 : 2
        }
      }

      const result = computeMove(board, 1, 'easy')
      expect(result.move).toBe(-1) // No valid move
    })

    it('should take immediate winning move', () => {
      // Set up a board where AI can win with column 3
      const board: Board = Array(42).fill(0) as Board
      // Place three AI discs horizontally with empty spot
      // Bottom row: [1, 2, 2, 0, 2, 1, 0]
      board[0 * 7 + 0] = 1
      board[0 * 7 + 1] = 2
      board[0 * 7 + 2] = 2
      board[0 * 7 + 3] = 0
      board[0 * 7 + 4] = 2
      board[0 * 7 + 5] = 1
      board[0 * 7 + 6] = 0

      const result = computeMove(board, 2, 'hard')
      // AI should prefer winning move in column 3 or column 4 (creating threat)
      expect([3, 4]).toContain(result.move)
    })

    it('should consider playable columns only', () => {
      const { board } = createInitialState('pvc', 'easy')
      const playable = getPlayableColumns(board)
      const result = computeMove(board, 2, 'easy')

      expect(playable).toContain(result.move)
    })
  })

  // ── Async Path Tests ─────────────────────────────────────────────────

  describe('computeMoveAsync (async, worker unavailable in Node)', () => {
    it('should fall back to sync when worker unavailable', async () => {
      const { board } = createInitialState('pvc', 'easy')
      // In Node test environment, worker is unavailable
      const result = await computeMoveAsync(board, 2, 'easy')

      expect(result.move).toBeGreaterThanOrEqual(0)
      expect(result.move).toBeLessThan(7)
      // Should fall back to sync since no worker in Node
      expect(['sync-js', 'async-worker-fallback']).toContain(result.source)
    })

    it('should complete within reasonable timeout for easy', async () => {
      const { board } = createInitialState('pvc', 'easy')
      const start = Date.now()
      const result = await computeMoveAsync(board, 2, 'easy', 50)
      const elapsed = Date.now() - start

      expect(result.move).toBeGreaterThanOrEqual(0)
      // Should timeout and fall back to sync, but still complete
      expect(elapsed).toBeLessThan(100)
    })

    it('should accept custom timeout', async () => {
      const { board } = createInitialState('pvc', 'medium')
      const start = Date.now()
      const result = await computeMoveAsync(board, 2, 'medium', 30)
      const elapsed = Date.now() - start

      expect(result.move).toBeGreaterThanOrEqual(0)
      // 30ms timeout is shorter than typical medium (60-100ms), should fallback
      expect(elapsed).toBeLessThan(100)
    })
  })

  describe('selectAiMove (heuristic dispatcher)', () => {
    it('should use sync for easy by default', async () => {
      const { board } = createInitialState('pvc', 'easy')
      const result = await selectAiMove(board, 2, 'easy')

      expect(result.move).toBeGreaterThanOrEqual(0)
      expect(result.source).toBe('sync-js')
    })

    it('should use sync for medium by default', async () => {
      const { board } = createInitialState('pvc', 'medium')
      const result = await selectAiMove(board, 2, 'medium', false)

      expect(result.move).toBeGreaterThanOrEqual(0)
      expect(result.source).toBe('sync-js')
    })

    it('should use async for hard by default', async () => {
      const { board } = createInitialState('pvc', 'hard')
      const result = await selectAiMove(board, 2, 'hard', true)

      expect(result.move).toBeGreaterThanOrEqual(0)
      // Will fall back to sync in Node environment, but should attempt async
      expect(['async-worker', 'async-worker-fallback']).toContain(result.source)
    })

    it('should respect forceAsync flag', async () => {
      const { board } = createInitialState('pvc', 'easy')
      const result = await selectAiMove(board, 2, 'easy', true)

      expect(result.move).toBeGreaterThanOrEqual(0)
      // Should attempt async even for easy, but may fall back to sync in Node test env
      expect(['sync-js', 'async-worker', 'async-worker-fallback']).toContain(result.source)
    })
  })

  // ── Worker Lifecycle Tests ─────────────────────────────────────────────

  describe('Worker lifecycle', () => {
    it('should initialize worker once', () => {
      ensureAsyncWorkerReady()
      // Note: In Node test env, this is a no-op since Worker is not available
      // But the function should not throw
      expect(true).toBe(true)
    })

    it('should terminate worker cleanly', () => {
      ensureAsyncWorkerReady()
      expect(() => {
        terminateAsyncWorker()
      }).not.toThrow()
    })
  })

  // ── Architecture & Documentation Tests ────────────────────────────────

  describe('Architecture decision documentation', () => {
    it('easy mode should always use sync (depth 1, < 10ms)', () => {
      const { board } = createInitialState('pvc', 'easy')
      const result = computeMove(board, 2, 'easy')

      // By design: easy is shallow enough for main thread
      expect(result.source).toBe('sync-js')
      expect(result.duration).toBeLessThan(50) // Well under 100ms budget
    })

    it('medium mode can use sync or async (depth 4, 60-100ms)', () => {
      const { board } = createInitialState('pvc', 'medium')
      const syncResult = computeMove(board, 2, 'medium')

      // By design: medium is borderline; sync ok if < 100ms
      expect(syncResult.source).toBe('sync-js')
      expect(syncResult.duration).toBeLessThan(150) // Some variance on complex positions
    })

    it('hard mode should dispatch to async (depth 8, 150-500ms)', async () => {
      const { board } = createInitialState('pvc', 'hard')
      const asyncResult = await computeMoveAsync(board, 2, 'hard')

      // By design: hard dispatches to worker, with sync fallback on 400ms timeout
      // In Node test env, worker unavailable so falls back to sync
      expect(['sync-js', 'async-worker', 'async-worker-fallback']).toContain(asyncResult.source)
    })

    it('both paths should produce valid moves (equivalence)', async () => {
      const { board } = createInitialState('pvc', 'medium')
      const syncResult = computeMove(board, 2, 'medium')
      const asyncResult = await computeMoveAsync(board, 2, 'medium')

      // Both should return valid playable columns
      expect(syncResult.move).toBeGreaterThanOrEqual(0)
      expect(asyncResult.move).toBeGreaterThanOrEqual(0)
      expect(syncResult.move).toBeLessThan(7)
      expect(asyncResult.move).toBeLessThan(7)

      // In Node test env, async falls back to sync, so may be identical
      // In browser, they might differ due to timing, but both are valid
      const playable = getPlayableColumns(board)
      expect(playable).toContain(syncResult.move)
      expect(playable).toContain(asyncResult.move)
    })
  })

  // ── Integration with game rules ──────────────────────────────────────

  describe('Integration withConnect-Four rules', () => {
    it('should produce only moves that dont violate board rules', () => {
      const game = createInitialState('pvc', 'medium')
      const result = computeMove(game.board, 2, 'medium')

      const playable = getPlayableColumns(game.board)
      expect(playable).toContain(result.move)

      // Verify the move can be applied without error
      const moveResult = dropDisc(game.board, result.move, 2)
      expect(moveResult).not.toBeNull()
    })

    it('should apply move and not break game state', () => {
      const game = createInitialState('pvc', 'medium')
      const aiResult = computeMove(game.board, 2, 'medium')

      // Apply the AI move
      const moveResult = dropDisc(game.board, aiResult.move, 2)
      expect(moveResult).not.toBeNull()

      if (moveResult) {
        const [newBoard, row] = moveResult
        expect(newBoard.length).toBe(42)
        // Verify AI player's disc is at the correct position using getCell
        expect(getCell(newBoard, aiResult.move, row)).toBe(2)
      }
    })
  })
})

import { useCallback, useEffect, useState } from 'react'

import { useKeyboardControls, vibrate } from '@/app'
import { useGridNavigationInput } from '@games/app-hook-utils'
import type { Difficulty, GameMode, GameState } from '@/domain'
import { COLS, isColumnPlayable } from '@/domain'

import { useSoundContext } from '@games/sound-context'
import { useGame } from './useGame'

const PLAYER_LABEL: Record<1 | 2, string> = { 1: 'Red', 2: 'Yellow' }
const DIFFICULTY_LABEL: Record<Difficulty, string> = {
  easy: 'Easy',
  medium: 'Medium',
  hard: 'Hard',
}

export interface UseConnectFourAppReturn {
  game: GameState
  activeCol: number
  isThinking: boolean
  soundEnabled: boolean
  statusText: string
  isGameOver: boolean
  isCpuTurn: boolean
  selectedColumn: number | null
  disableInteraction: boolean
  modeLabel: string
  difficultyLabel: string
  onColumnClick: (col: number) => void
  onNewGame: () => void
  onUndo: () => void
  onExit: () => void
  onToggleSound: () => void
  onModeChange: (mode: GameMode) => void
  onDifficultyChange: (difficulty: Difficulty) => void
}

export const useConnectFourApp = (): UseConnectFourAppReturn => {
  const { state: game, isThinking, playColumn, newGame, setMode, setDifficulty, undo } = useGame()
  const { soundEnabled, toggleSound } = useSoundContext()
  const [activeCol, setActiveCol] = useState(0)

  const isGameOver = game.result.status !== 'playing'
  const isCpuTurn = game.mode === 'pvc' && game.currentPlayer === 2 && !isGameOver

  const handleColumnClick = useCallback(
    (col: number) => {
      if (isGameOver || isThinking || isCpuTurn) {
        return
      }

      if (!isColumnPlayable(game.board, col)) {
        return
      }

      vibrate(15)
      playColumn(col)
      setActiveCol(col)
    },
    [game, isCpuTurn, isGameOver, isThinking, playColumn],
  )

  const findNextPlayableColumn = useCallback(
    (startCol: number, direction: -1 | 1) => {
      let candidate = startCol
      while (true) {
        candidate += direction
        if (candidate < 0 || candidate >= COLS) {
          return startCol
        }
        if (isColumnPlayable(game.board, candidate)) {
          return candidate
        }
      }
    },
    [game.board],
  )

  const moveActiveColumn = useCallback(
    (direction: -1 | 1) => {
      const nextCol = findNextPlayableColumn(activeCol, direction)
      setActiveCol(nextCol)
    },
    [activeCol, findNextPlayableColumn],
  )

  const dropAtActiveColumn = useCallback(() => {
    if (isColumnPlayable(game.board, activeCol)) {
      handleColumnClick(activeCol)
    }
  }, [activeCol, game.board, handleColumnClick])

  const onNewGame = useCallback(() => {
    newGame(game.mode, game.difficulty)
    setActiveCol(0)
  }, [game.difficulty, game.mode, newGame])

  const onModeChange = useCallback(
    (mode: GameMode) => {
      setMode(mode)
      setActiveCol(0)
    },
    [setMode],
  )

  const onDifficultyChange = useCallback(
    (difficulty: Difficulty) => {
      setDifficulty(difficulty)
      setActiveCol(0)
    },
    [setDifficulty],
  )

  const onUndo = useCallback(() => {
    undo()
    setActiveCol(0)
  }, [undo])

  useEffect(() => {
    if (!isColumnPlayable(game.board, activeCol)) {
      setActiveCol(findNextPlayableColumn(activeCol, 1))
    }
  }, [activeCol, findNextPlayableColumn, game.board])

  useGridNavigationInput(
    {
      onMove: (direction) => {
        if (direction === 'left') {
          moveActiveColumn(-1)
        }
        if (direction === 'right') {
          moveActiveColumn(1)
        }
      },
      onSelect: dropAtActiveColumn,
    },
    {
      enabled: !isGameOver,
      selectKeys: ['ArrowDown', 'KeyS', 'Enter', 'Space'],
      includeWasd: false,
    },
  )

  useKeyboardControls(
    [
      { action: 'new-game', keys: ['KeyN'], onTrigger: onNewGame },
      {
        action: 'undo',
        keys: ['KeyU'],
        onTrigger: onUndo,
        enabled: game.moveHistory.length > 0 && !isThinking,
      },
    ],
    { enabled: true },
  )

  const statusText = (() => {
    if (game.result.status === 'win') {
      return `${PLAYER_LABEL[game.result.winner]} wins! 🎉`
    }
    if (game.result.status === 'draw') {
      return "It's a draw!"
    }
    if (isThinking) {
      return 'CPU is thinking…'
    }
    return `${PLAYER_LABEL[game.currentPlayer]}'s turn`
  })()

  return {
    game,
    activeCol,
    isThinking,
    soundEnabled,
    statusText,
    isGameOver,
    isCpuTurn,
    selectedColumn: !isGameOver && !isThinking && !isCpuTurn ? activeCol : null,
    disableInteraction: isGameOver || isThinking || isCpuTurn,
    modeLabel: game.mode === 'pvc' ? 'vs CPU' : '2 Player',
    difficultyLabel: DIFFICULTY_LABEL[game.difficulty],
    onColumnClick: handleColumnClick,
    onNewGame,
    onUndo,
    onExit: onNewGame,
    onToggleSound: toggleSound,
    onModeChange,
    onDifficultyChange,
  }
}

import type { Column, Difficulty, GameMode, GameState } from '@/domain'
import { applyMove, checkGameResult, createInitialState, isColumnPlayable } from '@/domain'
import { useCallback, useEffect, useState } from 'react'

import {
  computeMoveAsync,
  ensureAsyncWorkerReady,
  terminateAsyncWorker,
} from '../connectFourAiService'
import { load, save } from '../storageService'

const MODE_KEY = 'connect-four-mode'
const DIFFICULTY_KEY = 'connect-four-difficulty'
const GAME_KEY = 'connect-four-state'

export const useGame = () => {
  const [state, setState] = useState<GameState>(() => {
    const mode = load<GameMode>(MODE_KEY, 'pvc')
    const difficulty = load<Difficulty>(DIFFICULTY_KEY, 'medium')
    return load<GameState>(GAME_KEY, createInitialState(mode, difficulty))
  })
  const [isThinking, setIsThinking] = useState(false)

  useEffect(() => {
    ensureAsyncWorkerReady()
    return () => {
      terminateAsyncWorker()
    }
  }, [])

  const playColumn = useCallback(
    (column: number) => {
      if (state.result.status !== 'playing' || !isColumnPlayable(state.board, column)) {
        return
      }

      const next = applyMove(state, column as Column, checkGameResult)
      if (!next) {
        return
      }

      setState(next)
      save(GAME_KEY, next)
    },
    [state],
  )

  useEffect(() => {
    if (state.mode !== 'pvc' || state.currentPlayer !== 2 || state.result.status !== 'playing') {
      return
    }

    let active = true
    setIsThinking(true)

    void computeMoveAsync(state.board, 2, state.difficulty).then((result) => {
      if (!active) {
        return
      }
      const next = applyMove(state, result.move as Column, checkGameResult)
      if (next) {
        setState(next)
        save(GAME_KEY, next)
      }
      setIsThinking(false)
    })

    return () => {
      active = false
      setIsThinking(false)
    }
  }, [state])

  const newGame = useCallback(
    (mode: GameMode = state.mode, difficulty: Difficulty = state.difficulty) => {
      const next = createInitialState(mode, difficulty)
      setState(next)
      setIsThinking(false)
      save(MODE_KEY, mode)
      save(DIFFICULTY_KEY, difficulty)
      save(GAME_KEY, next)
    },
    [state.difficulty, state.mode],
  )

  const setMode = useCallback(
    (mode: GameMode) => {
      newGame(mode, state.difficulty)
    },
    [newGame, state.difficulty],
  )

  const setDifficulty = useCallback(
    (difficulty: Difficulty) => {
      newGame(state.mode, difficulty)
    },
    [newGame, state.mode],
  )

  const undo = useCallback(() => {
    if (state.moveHistory.length === 0) {
      return
    }

    const stepsBack = state.mode === 'pvc' && state.moveHistory.length >= 2 ? 2 : 1
    let nextState = createInitialState(state.mode, state.difficulty)
    const moves = state.moveHistory.slice(0, -stepsBack)

    for (const column of moves) {
      const next = applyMove(nextState, column, checkGameResult)
      if (next) {
        nextState = next
      }
    }

    setState(nextState)
    setIsThinking(false)
    save(GAME_KEY, nextState)
  }, [state])

  return {
    state,
    isThinking,
    playColumn,
    newGame,
    setMode,
    setDifficulty,
    undo,
  }
}

/**
 * AI move selection — CPU player logic.
 * Pure functions: given a board state, return the best move.
 *
 * Uses @games/ai-framework for minimax + alpha-beta pruning.
 * Game-specific logic (window evaluation, move ordering) remains here.
 * Difficulty modes handled via depth parameter.
 *
 * Move representation: column index (0-6)
 */

import type { GameAI } from '@games/ai-framework'
import { minimax } from '@games/ai-framework'
import { dropDisc, getCell, getPlayableColumns, otherPlayer } from './board'
import { AI_DEPTH, COLS, ROWS, WIN_LENGTH } from './constants'
import { checkWinAt } from './rules'
import type { Board, Difficulty, Player } from './types'

/** Scoring constants for the evaluation function */
const SCORE_WIN = 1_000_000
const SCORE_THREE = 50
const SCORE_TWO = 10
const SCORE_CENTER = 3

/** Evaluate a window of `WIN_LENGTH` cells for a given player. */
function evaluateWindow(window: number[], player: Player): number {
  const opponent = otherPlayer(player)
  const playerCount = window.filter((c) => c === player).length
  const opponentCount = window.filter((c) => c === opponent).length
  const emptyCount = window.filter((c) => c === 0).length

  if (playerCount === 4) {
    return SCORE_WIN
  }
  if (opponentCount === 4) {
    return -SCORE_WIN
  }
  if (playerCount === 3 && emptyCount === 1) {
    return SCORE_THREE
  }
  if (opponentCount === 3 && emptyCount === 1) {
    return -SCORE_THREE
  }
  if (playerCount === 2 && emptyCount === 2) {
    return SCORE_TWO
  }
  if (opponentCount === 2 && emptyCount === 2) {
    return -SCORE_TWO
  }
  return 0
}

/** Heuristic board evaluation for minimax. */
function evaluateBoard(board: Board, player: Player): number {
  let score = 0

  // Center column preference
  const centerCol = Math.floor(COLS / 2)
  for (let row = 0; row < ROWS; row++) {
    if (getCell(board, centerCol, row) === player) {
      score += SCORE_CENTER
    }
  }

  // Horizontal windows
  for (let row = 0; row < ROWS; row++) {
    for (let col = 0; col <= COLS - WIN_LENGTH; col++) {
      const window: number[] = []
      for (let i = 0; i < WIN_LENGTH; i++) {
        window.push(getCell(board, col + i, row))
      }
      score += evaluateWindow(window, player)
    }
  }

  // Vertical windows
  for (let col = 0; col < COLS; col++) {
    for (let row = 0; row <= ROWS - WIN_LENGTH; row++) {
      const window: number[] = []
      for (let i = 0; i < WIN_LENGTH; i++) {
        window.push(getCell(board, col, row + i))
      }
      score += evaluateWindow(window, player)
    }
  }

  // Diagonal ↗ windows
  for (let col = 0; col <= COLS - WIN_LENGTH; col++) {
    for (let row = 0; row <= ROWS - WIN_LENGTH; row++) {
      const window: number[] = []
      for (let i = 0; i < WIN_LENGTH; i++) {
        window.push(getCell(board, col + i, row + i))
      }
      score += evaluateWindow(window, player)
    }
  }

  // Diagonal ↘ windows
  for (let col = 0; col <= COLS - WIN_LENGTH; col++) {
    for (let row = WIN_LENGTH - 1; row < ROWS; row++) {
      const window: number[] = []
      for (let i = 0; i < WIN_LENGTH; i++) {
        window.push(getCell(board, col + i, row - i))
      }
      score += evaluateWindow(window, player)
    }
  }

  return score
}

/** Check if a move results in an immediate win. */
function isWinningMove(board: Board, col: number, player: Player): boolean {
  const result = dropDisc(board, col, player)
  if (!result) {
    return false
  }
  const [newBoard, row] = result
  return checkWinAt(newBoard, col, row, player) !== null
}

/**
 * Minimax with alpha-beta pruning — handled by @games/ai-framework
 * This class adapts Connect-Four to the GameAI interface
 */
class ConnectFourAI implements GameAI<Board, number, Player> {
  private aiPlayer: Player

  constructor(aiPlayer: Player) {
    this.aiPlayer = aiPlayer
  }

  evaluateBoard(board: Board, _player: Player): number {
    return evaluateBoard(board, this.aiPlayer)
  }

  getLegalMoves(board: Board, _player: Player): number[] {
    const playable = getPlayableColumns(board)
    // Order columns for better pruning effectiveness
    const center = Math.floor(COLS / 2)
    return [...playable].sort((a, b) => Math.abs(a - center) - Math.abs(b - center))
  }

  applyMove(board: Board, col: number): Board {
    const result = dropDisc(board, col, this.aiPlayer)
    if (!result) {
      throw new Error(`Cannot drop disc in column ${col}`)
    }
    const [newBoard] = result
    return newBoard
  }

  getWinner(board: Board): Player | null {
    // Check all positions for a win
    for (let col = 0; col < COLS; col++) {
      for (let row = 0; row < ROWS; row++) {
        const cell = getCell(board, col, row)
        if (cell !== 0) {
          if (checkWinAt(board, col, row, cell as Player) !== null) {
            return cell as Player
          }
        }
      }
    }
    return null
  }

  getOpponent(player: Player): Player {
    return otherPlayer(player)
  }
}

/**
 * Select the best move for the AI player.
 * Returns a column index.
 * Difficulty handled via depth parameter to minimax.
 */
export function selectMove(board: Board, player: Player, difficulty: Difficulty): number {
  const playable = getPlayableColumns(board)
  if (playable.length === 0) {
    return -1
  }

  // Easy: random move (with chance to block obvious wins)
  if (difficulty === 'easy') {
    // Still block immediate opponent wins 50% of the time
    const opponent = otherPlayer(player)
    for (const col of playable) {
      if (isWinningMove(board, col, opponent) && Math.random() < 0.5) {
        return col
      }
    }
    // Take immediate wins always
    for (const col of playable) {
      if (isWinningMove(board, col, player)) {
        return col
      }
    }
    // playable is guaranteed non-empty (checked at function entry)
    return playable[Math.floor(Math.random() * playable.length)] as number
  }

  const depth = AI_DEPTH[difficulty] ?? 4
  const ordered = playable
    .slice()
    .sort((a, b) => Math.abs(a - Math.floor(COLS / 2)) - Math.abs(b - Math.floor(COLS / 2)))

  // Check for immediate winning move
  for (const col of ordered) {
    if (isWinningMove(board, col, player)) {
      return col
    }
  }

  // Check for immediate opponent threat
  const opponent = otherPlayer(player)
  for (const col of ordered) {
    if (isWinningMove(board, col, opponent)) {
      return col
    }
  }

  // Use minimax from framework
  const game = new ConnectFourAI(player)
  const result = minimax(board, player, depth, game, {
    alphaBetaPruning: true,
    moveOrdering: true,
  })

  return (result.move as number) ?? (ordered[0] as number)
}

/**
 * Board operations — pure functions for creating and manipulating game state.
 * No React, no DOM — purely functional transformations.
 */

import { COLS, ROWS, TOTAL_CELLS } from './constants'
import type { Board, Cell, Column, GameResult, GameState, Player } from './types'

/** Create an empty board (all zeros) */
export function createBoard(): Board {
  return new Array<Cell>(TOTAL_CELLS).fill(0)
}

/** Get cell value at (col, row). Row 0 = bottom. */
export function getCell(board: Board, col: number, row: number): Cell {
  return (board[col * ROWS + row] ?? 0) as Cell
}

/** Set cell value at (col, row). Returns a new board. */
export function setCell(board: Board, col: number, row: number, value: Cell): Board {
  const next = [...board] as Board
  next[col * ROWS + row] = value
  return next
}

/** Find the lowest empty row in a column, or -1 if full. */
export function getLowestEmptyRow(board: Board, col: number): number {
  for (let row = 0; row < ROWS; row++) {
    if (getCell(board, col, row) === 0) {
      return row
    }
  }
  return -1
}

/** Check if a column can accept another disc. */
export function isColumnPlayable(board: Board, col: number): boolean {
  return getLowestEmptyRow(board, col) !== -1
}

/** Get all columns that can still accept a disc. */
export function getPlayableColumns(board: Board): number[] {
  const cols: number[] = []
  for (let c = 0; c < COLS; c++) {
    if (isColumnPlayable(board, c)) {
      cols.push(c)
    }
  }
  return cols
}

/** Drop a disc into a column. Returns [newBoard, landingRow] or null if column is full. */
export function dropDisc(board: Board, col: number, player: Player): [Board, number] | null {
  const row = getLowestEmptyRow(board, col)
  if (row === -1) {
    return null
  }
  return [setCell(board, col, row, player), row]
}

/** Switch the current player. */
export function otherPlayer(player: Player): Player {
  return player === 1 ? 2 : 1
}

/** Create the initial game state. */
export function createInitialState(
  mode: GameState['mode'] = 'pvc',
  difficulty: GameState['difficulty'] = 'medium',
): GameState {
  return {
    board: createBoard(),
    currentPlayer: 1,
    result: { status: 'playing' },
    mode,
    difficulty,
    moveHistory: [],
  }
}

/** Apply a move and return the new game state, or null if the move is invalid. */
export function applyMove(
  state: GameState,
  col: Column,
  checkResult: (board: Board, col: number, row: number, player: Player) => GameResult,
): GameState | null {
  if (state.result.status !== 'playing') {
    return null
  }
  const drop = dropDisc(state.board, col, state.currentPlayer)
  if (!drop) {
    return null
  }

  const [newBoard, row] = drop
  const result = checkResult(newBoard, col, row, state.currentPlayer)

  return {
    ...state,
    board: newBoard,
    currentPlayer: otherPlayer(state.currentPlayer),
    result,
    moveHistory: [...state.moveHistory, col],
  }
}

/**
 * Board Logic Unit Tests
 *
 * Tests all board manipulation functions:
 * - createBoard, getCell, setCell
 * - getLowestEmptyRow, isColumnPlayable, getPlayableColumns
 * - dropDisc, otherPlayer
 * - createInitialState, applyMove
 *
 * Validates:
 * ✓ Board initialization and state
