/**
 * Crossclimb App Layer
 * React hooks for game state management
 */

import { useCallback, useEffect, useState } from 'react'
import type { CrossclimbState, Difficulty, NodeId, SearchResult } from '../../domain'
import { createInitialState, findPathAStar, getHintMove, makeMove, resetGame } from '../../domain'

const CANVAS_WIDTH = 800
const CANVAS_HEIGHT = 600

export const useCrossclimbGame = (difficulty: Difficulty) => {
  const [gameState, setGameState] = useState<CrossclimbState>(() =>
    createInitialState(difficulty, CANVAS_WIDTH, CANVAS_HEIGHT),
  )
  const [gameTime, setGameTime] = useState(0)
  const [isTimerRunning, setIsTimerRunning] = useState(false)
  const [hintNode, setHintNode] = useState<NodeId | null>(null)
  const [isSolving, setIsSolving] = useState(false)

  // Timer effect
  useEffect(() => {
    let interval: ReturnType<typeof setInterval> | null = null

    if (isTimerRunning && !gameState.isComplete) {
      interval = setInterval(() => {
        setGameTime((prev) => prev + 1)
      }, 1000)
    }

    return () => {
      if (interval) {
        clearInterval(interval)
      }
    }
  }, [isTimerRunning, gameState.isComplete])

  // Start timer when first move is made
  useEffect(() => {
    if (gameState.moves > 0 && !isTimerRunning && !gameState.isComplete) {
      setIsTimerRunning(true)
    }
  }, [gameState.moves, isTimerRunning, gameState.isComplete])

  const moveToNode = useCallback((nodeId: NodeId) => {
    setGameState((prevState) => {
      const newState = makeMove(prevState, nodeId)
      if (newState.moves !== prevState.moves) {
        setHintNode(null) // Clear hint after successful move
      }
      return newState
    })
  }, [])

  const newPuzzle = useCallback(() => {
    setGameState(createInitialState(difficulty, CANVAS_WIDTH, CANVAS_HEIGHT))
    setGameTime(0)
    setIsTimerRunning(false)
    setHintNode(null)
    setIsSolving(false)
  }, [difficulty])

  const resetCurrentGame = useCallback(() => {
    setGameState((prevState) => resetGame(prevState))
    setGameTime(0)
    setIsTimerRunning(false)
    setHintNode(null)
    setIsSolving(false)
  }, [])

  const changeDifficulty = useCallback((newDifficulty: Difficulty) => {
    setGameState(createInitialState(newDifficulty, CANVAS_WIDTH, CANVAS_HEIGHT))
    setGameTime(0)
    setIsTimerRunning(false)
    setHintNode(null)
    setIsSolving(false)
  }, [])

  const getHint = useCallback(() => {
    const hint = getHintMove(gameState.currentPath, gameState.graph)
    if (hint) {
      setHintNode(hint)
      // Auto-clear hint after 3 seconds
      setTimeout(() => setHintNode(null), 3000)
    }
    return hint
  }, [gameState.currentPath, gameState.graph])

  const solveCompletely = useCallback(async () => {
    setIsSolving(true)
    try {
      // Use A* to find optimal solution
      const result: SearchResult = findPathAStar(gameState.graph)

      if (result.found && result.path) {
        // Animate the solution step by step
        for (let i = 1; i < result.path.nodes.length; i++) {
          const nodeId = result.path.nodes[i]
          await new Promise((resolve) => setTimeout(resolve, 500)) // 500ms delay between moves

          setGameState((prevState) => {
            const newState = makeMove(prevState, nodeId)
            return newState
          })
        }
      }
    } finally {
      setIsSolving(false)
    }
  }, [gameState.graph])

  const canMoveToNode = useCallback(
    (nodeId: NodeId): boolean => {
      const currentNodeId = gameState.currentPath[gameState.currentPath.length - 1]
      return gameState.graph.nodes.get(currentNodeId)?.connections.includes(nodeId) ?? false
    },
    [gameState.currentPath, gameState.graph.nodes],
  )

  return {
    gameState,
    gameTime,
    hintNode,
    isSolving,
    moveToNode,
    canMoveToNode,
    newPuzzle,
    resetCurrentGame,
    changeDifficulty,
    getHint,
    solveCompletely,
  }
}

export default useCrossclimbGame

/**
 * Crossclimb AI Algorithms
 * Graph search algorithms for pathfinding
 */

import { MAX_SEARCH_DEPTH, SEARCH_TIMEOUT } from './constants'
import { calculatePathWeight, isValidPath } from './rules'
import type { Graph, NodeId, Path, SearchResult } from './types'

/**
 * Breadth-First Search for finding any valid path
 */
export const findPathBFS = (graph: Graph): SearchResult => {
  const startTime = Date.now()
  const startNode = graph.startNode
  const endNode = graph.endNode

  const queue: Array<{ path: NodeId[]; visited: Set<NodeId> }> = [
    { path: [startNode], visited: new Set([startNode]) },
  ]

  let bestPath: Path | null = null
  let minWeight = Infinity

  while (queue.length > 0 && Date.now() - startTime < SEARCH_TIMEOUT) {
    const { path, visited } = queue.shift()!
    const currentNodeId = path[path.length - 1]

    // Check if we reached the end with all checkpoints
    if (currentNodeId === endNode && isValidPath(path, graph)) {
      const weight = calculatePathWeight(path, graph)
      if (weight < minWeight) {
        minWeight = weight
        bestPath = {
          nodes: path,
          edges: [], // Will be filled below
          totalWeight: weight,
          valid: true,
        }
      }
      continue // Continue searching for potentially better paths
    }

    // Prevent infinite loops
    if (path.length > MAX_SEARCH_DEPTH) {
      continue
    }

    const currentNode = graph.nodes.get(currentNodeId)!
    for (const neighborId of currentNode.connections) {
      if (!visited.has(neighborId)) {
        const newPath = [...path, neighborId]
        const newVisited = new Set([...visited, neighborId])
        queue.push({ path: newPath, visited: newVisited })
      }
    }
  }

  if (bestPath !== null) {
    bestPath.edges = generateEdgeList(bestPath.nodes, graph)
  }

  return {
    path: bestPath,
    visited: new Set(),
    cost: bestPath?.totalWeight || 0,
    found: bestPath !== null,
  }
}

/**
 * Depth-First Search with backtracking
 */
export const findPathDFS = (graph: Graph): SearchResult => {
  const startTime = Date.now()
  const startNode = graph.startNode
  const endNode = graph.endNode

  let bestPath: Path | null = null
  let minWeight = Infinity

  const dfs = (currentPath: NodeId[], visited: Set<NodeId>): void => {
    if (Date.now() - startTime > SEARCH_TIMEOUT) {
      return
    }
    if (currentPath.length > MAX_SEARCH_DEPTH) {
      return
    }

    const currentNodeId = currentPath[currentPath.length - 1]

    // Check if we found a valid path
    if (currentNodeId === endNode && isValidPath(currentPath, graph)) {
      const weight = calculatePathWeight(currentPath, graph)
      if (weight < minWeight) {
        minWeight = weight
        bestPath = {
          nodes: [...currentPath],
          edges: [],
          totalWeight: weight,
          valid: true,
        }
      }
      return
    }

    const currentNode = graph.nodes.get(currentNodeId)!
    for (const neighborId of currentNode.connections) {
      if (!visited.has(neighborId)) {
        currentPath.push(neighborId)
        visited.add(neighborId)
        dfs(currentPath, visited)
        currentPath.pop()
        visited.delete(neighborId)
      }
    }
  }

  dfs([startNode], new Set([startNode]))

  const resolvedPath = bestPath as Path | null
  if (resolvedPath !== null) {
    resolvedPath.edges = generateEdgeList(resolvedPath.nodes, graph)
  }

  return {
    path: resolvedPath,
    visited: new Set(),
    cost: resolvedPath?.totalWeight || 0,
    found: resolvedPath !== null,
  }
}

/**
 * A* Search with heuristic for optimal pathfinding
 */
export const findPathAStar = (graph: Graph): SearchResult => {
  const startTime = Date.now()
  const startNode = graph.startNode
  const endNode = graph.endNode

  const openSet = new Set([startNode])
  const cameFrom = new Map<NodeId, NodeId>()
  const gScore = new Map<NodeId, number>()
  const fScore = new Map<NodeId, number>()

  // Initialize scores
  gScore.set(startNode, 0)
  fScore.set(startNode, heuristic(startNode, graph))

  while (openSet.size > 0 && Date.now() - startTime < SEARCH_TIMEOUT) {
    // Find node with lowest fScore
    let current: NodeId | null = null
    let lowestFScore = Infinity

    for (const nodeId of openSet) {
      const score = fScore.get(nodeId) || Infinity
      if (score < lowestFScore) {
        lowestFScore = score
        current = nodeId
      }
    }

    if (!current) {
      break
    }

    if (current === endNode) {
      // Reconstruct path
      const path = reconstructPath(cameFrom, current)
      if (isValidPath(path, graph)) {
        const totalWeight = calculatePathWeight(path, graph)
        return {
          path: {
            nodes: path,
            edges: generateEdgeList(path, graph),
            totalWeight,
            valid: true,
          },
          visited: new Set(cameFrom.keys()),
          cost: totalWeight,
          found: true,
        }
      }
    }

    openSet.delete(current)
    const currentNode = graph.nodes.get(current)!

    for (const neighborId of currentNode.connections) {
      // Find edge weight
      let edgeWeight = 1
      const edgeId1 = `edge-${current}-${neighborId}`
      const edgeId2 = `edge-${neighborId}-${current}`
      const edge = graph.edges.get(edgeId1) || graph.edges.get(edgeId2)
      if (edge) {
        edgeWeight = edge.weight
      }

      const tentativeGScore = (gScore.get(current) || 0) + edgeWeight

      if (tentativeGScore < (gScore.get(neighborId) || Infinity)) {
        cameFrom.set(neighborId, current)
        gScore.set(neighborId, tentativeGScore)
        fScore.set(neighborId, tentativeGScore + heuristic(neighborId, graph))

        if (!openSet.has(neighborId)) {
          openSet.add(neighborId)
        }
      }
    }
  }

  return {
    path: null,
    visited: new Set(cameFrom.keys()),
    cost: 0,
    found: false,
  }
}

/**
 * Heuristic function for A* (Manhattan distance + checkpoint penalty)
 */
const heuristic = (nodeId: NodeId, graph: Graph): number => {
  const node = graph.nodes.get(nodeId)!
  const endNode = graph.nodes.get(graph.endNode)!

  // Basic distance
  const distance =
    Math.abs(node.position.x - endNode.position.x) + Math.abs(node.position.y - endNode.position.y)

  // Penalty for unvisited checkpoints
  const unvisitedCheckpoints = graph.checkpoints.filter(
    (cp) => !graph.nodes.get(cp)?.visited,
  ).length

  return distance + unvisitedCheckpoints * 50
}

/**
 * Reconstruct path from A* cameFrom map
 */
const reconstructPath = (cameFrom: Map<NodeId, NodeId>, current: NodeId): NodeId[] => {
  const path = [current]
  while (cameFrom.has(current)) {
    current = cameFrom.get(current)!
    path.unshift(current)
  }
  return path
}

/**
 * Generate edge list from node path
 */
const generateEdgeList = (nodes: NodeId[], graph: Graph): string[] => {
  const edges: string[] = []

  for (let i = 0; i < nodes.length - 1; i++) {
    const fromId = nodes[i]
    const toId = nodes[i + 1]
    const edgeId1 = `edge-${fromId}-${toId}`
    const edgeId2 = `edge-${toId}-${fromId}`

    const edge = graph.edges.get(edgeId1) || graph.edges.get(edgeId2)
    if (edge) {
      edges.push(edge.id)
    }
  }

  return edges
}

/**
 * Get hint for next move (simplified A* for immediate next step)
 */
export const getHintMove = (currentPath: NodeId[], graph: Graph): NodeId | null => {
  const currentNodeId = currentPath[currentPath.length - 1]
  const currentNode = graph.nodes.get(currentNodeId)!

  let bestNeighbor: NodeId | null = null
  let bestScore = Infinity

  for (const neighborId of currentNode.connections) {
    if (currentPath.includes(neighborId)) {
      continue
    } // Avoid cycles

    const neighbor = graph.nodes.get(neighborId)!
    const distance =
      Math.abs(neighbor.position.x - graph.nodes.get(graph.endNode)!.position.x) +
      Math.abs(neighbor.position.y - graph.nodes.get(graph.endNode)!.position.y)

    // Prefer checkpoints
    const checkpointBonus = neighbor.type === 'checkpoint' ? -20 : 0

    const score = distance + checkpointBonus

    if (score < bestScore) {
      bestScore = score
      bestNeighbor = neighborId
    }
  }

  return bestNeighbor
}

/**
 * Check if graph is solvable
 */
export const isGraphSolvable = (graph: Graph): boolean => {
  const result = findPathBFS(graph)
  return result.found
}

/**
 * Crossclimb Domain Rules
 * Core game logic for graph search puzzle
 */

import { CANVAS_PADDING, DIFFICULTY_CONFIGS } from './constants'
import type {
  CrossclimbState,
  Difficulty,
  Edge,
  EdgeId,
  Graph,
  Node,
  NodeId,
  Position,
} from './types'

/**
 * Generate a random position within canvas bounds
 */
export const generateRandomPosition = (
  canvasWidth: number,
  canvasHeight: number,
  existingPositions: Position[],
  minDistance: number = 60,
): Position => {
  let attempts = 0
  const maxAttempts = 100

  while (attempts < maxAttempts) {
    const x = CANVAS_PADDING + Math.random() * (canvasWidth - 2 * CANVAS_PADDING)
    const y = CANVAS_PADDING + Math.random() * (canvasHeight - 2 * CANVAS_PADDING)
    const position = { x, y }

    const tooClose = existingPositions.some(
      (existing) => Math.sqrt((x - existing.x) ** 2 + (y - existing.y) ** 2) < minDistance,
    )

    if (!tooClose) {
      return position
    }
    attempts++
  }

  // Fallback: return a position anyway
  return {
    x: CANVAS_PADDING + Math.random() * (canvasWidth - 2 * CANVAS_PADDING),
    y: CANVAS_PADDING + Math.random() * (canvasHeight - 2 * CANVAS_PADDING),
  }
}

/**
 * Create a random graph for the given difficulty
 */
export const createRandomGraph = (
  difficulty: Difficulty,
  canvasWidth: number,
  canvasHeight: number,
): Graph => {
  const config = DIFFICULTY_CONFIGS[difficulty]
  const nodes = new Map<NodeId, Node>()
  const edges = new Map<EdgeId, Edge>()
  const positions: Position[] = []

  // Create nodes
  for (let i = 0; i < config.nodeCount; i++) {
    const id = `node-${i}`
    const position = generateRandomPosition(canvasWidth, canvasHeight, positions)
    positions.push(position)

    const nodeType =
      i === 0
        ? 'start'
        : i === config.nodeCount - 1
          ? 'end'
          : i < config.checkpointCount + 1
            ? 'checkpoint'
            : 'normal'

    nodes.set(id, {
      id,
      position,
      type: nodeType,
      connections: [],
      visited: false,
      required: nodeType === 'checkpoint' || nodeType === 'start' || nodeType === 'end',
    })
  }

  // Create edges based on proximity and density
  const nodeIds = Array.from(nodes.keys())
  for (let i = 0; i < nodeIds.length; i++) {
    for (let j = i + 1; j < nodeIds.length; j++) {
      const nodeA = nodes.get(nodeIds[i])!
      const nodeB = nodes.get(nodeIds[j])!

      const distance = Math.sqrt(
        (nodeA.position.x - nodeB.position.x) ** 2 + (nodeA.position.y - nodeB.position.y) ** 2,
      )

      // Create edge if nodes are close enough and random chance passes
      if (distance < 150 && Math.random() < config.edgeDensity) {
        const edgeId = `edge-${i}-${j}`
        const weight = Math.floor(Math.random() * config.maxWeight) + 1

        edges.set(edgeId, {
          id: edgeId,
          from: nodeIds[i],
          to: nodeIds[j],
          weight,
          traversable: true,
        })

        // Add connections
        nodeA.connections.push(nodeIds[j])
        nodeB.connections.push(nodeIds[i])
      }
    }
  }

  // Ensure graph is connected (add minimum spanning tree if needed)
  ensureConnectivity(nodes, edges, nodeIds)

  const checkpoints = nodeIds.filter((id) => nodes.get(id)!.type === 'checkpoint')

  return {
    nodes,
    edges,
    startNode: 'node-0',
    endNode: `node-${config.nodeCount - 1}`,
    checkpoints,
  }
}

/**
 * Ensure the graph is connected by adding necessary edges
 */
const ensureConnectivity = (
  nodes: Map<NodeId, Node>,
  edges: Map<EdgeId, Edge>,
  nodeIds: NodeId[],
): void => {
  const visited = new Set<NodeId>()
  const toVisit = ['node-0']

  // BFS to find connected components
  while (toVisit.length > 0) {
    const currentId = toVisit.shift()!
    if (visited.has(currentId)) {
      continue
    }

    visited.add(currentId)
    const currentNode = nodes.get(currentId)!

    for (const neighborId of currentNode.connections) {
      if (!visited.has(neighborId)) {
        toVisit.push(neighborId)
      }
    }
  }

  // Connect disconnected components
  for (const nodeId of nodeIds) {
    if (!visited.has(nodeId)) {
      // Find closest connected node
      let closestId: NodeId | null = null
      let minDistance = Infinity

      for (const connectedId of visited) {
        const nodeA = nodes.get(nodeId)!
        const nodeB = nodes.get(connectedId)!
        const distance = Math.sqrt(
          (nodeA.position.x - nodeB.position.x) ** 2 + (nodeA.position.y - nodeB.position.y) ** 2,
        )

        if (distance < minDistance) {
          minDistance = distance
          closestId = connectedId
        }
      }

      if (closestId) {
        const edgeId = `edge-connect-${nodeId}-${closestId}`
        edges.set(edgeId, {
          id: edgeId,
          from: nodeId,
          to: closestId,
          weight: 1,
          traversable: true,
        })

        nodes.get(nodeId)!.connections.push(closestId)
        nodes.get(closestId)!.connections.push(nodeId)
        visited.add(nodeId)
      }
    }
  }
}

/**
 * Create initial game state
 */
export const createInitialState = (
  difficulty: Difficulty,
  canvasWidth: number,
  canvasHeight: number,
): CrossclimbState => {
  let graph = createRandomGraph(difficulty, canvasWidth, canvasHeight)
  let attempts = 0
  const maxAttempts = 10

  while (!hasCheckpointCompletePath(graph) && attempts < maxAttempts) {
    graph = createRandomGraph(difficulty, canvasWidth, canvasHeight)
    attempts++
  }

  return {
    graph,
    currentPath: [graph.startNode],
    visitedNodes: new Set([graph.startNode]),
    collectedCheckpoints: new Set(),
    isComplete: false,
    moves: 0,
  }
}

/**
 * Check if a move to a node is valid
 */
export const isValidMove = (fromNodeId: NodeId, toNodeId: NodeId, graph: Graph): boolean => {
  const fromNode = graph.nodes.get(fromNodeId)
  if (!fromNode) {
    return false
  }

  return fromNode.connections.includes(toNodeId)
}

/**
 * Make a move in the game
 */
export const makeMove = (state: CrossclimbState, toNodeId: NodeId): CrossclimbState => {
  if (!isValidMove(state.currentPath[state.currentPath.length - 1], toNodeId, state.graph)) {
    return state
  }

  const newPath = [...state.currentPath, toNodeId]
  const newVisitedNodes = new Set(state.visitedNodes)
  newVisitedNodes.add(toNodeId)

  const targetNode = state.graph.nodes.get(toNodeId)!
  const newCollectedCheckpoints = new Set(state.collectedCheckpoints)

  if (targetNode.type === 'checkpoint') {
    newCollectedCheckpoints.add(toNodeId)
  }

  const isComplete =
    toNodeId === state.graph.endNode &&
    state.graph.checkpoints.every((cp) => newCollectedCheckpoints.has(cp))

  return {
    ...state,
    currentPath: newPath,
    visitedNodes: newVisitedNodes,
    collectedCheckpoints: newCollectedCheckpoints,
    isComplete,
    moves: state.moves + 1,
  }
}

/**
 * Check if the current path is valid (visits all checkpoints)
 */
export const isValidPath = (path: NodeId[], graph: Graph): boolean => {
  if (path.length < 2) {
    return false
  }
  if (path[0] !== graph.startNode) {
    return false
  }
  if (path[path.length - 1] !== graph.endNode) {
    return false
  }

  // Check all checkpoints are visited
  const visitedCheckpoints = new Set(
    path.filter((nodeId) => graph.nodes.get(nodeId)?.type === 'checkpoint'),
  )

  return graph.checkpoints.every((cp) => visitedCheckpoints.has(cp))
}

/**
 * Calculate path weight
 */
export const calculatePathWeight = (path: NodeId[], graph: Graph): number => {
  let totalWeight = 0

  for (let i = 0; i < path.length - 1; i++) {
    const fromId = path[i]
    const toId = path[i + 1]
    const edgeId = `edge-${fromId}-${toId}`

    // Try both directions
    let edge = graph.edges.get(edgeId)
    if (!edge) {
      edge = graph.edges.get(`edge-${toId}-${fromId}`)
    }

    if (edge) {
      totalWeight += edge.weight
    }
  }

  return totalWeight
}

/**
 * Reset the game state
 */
export const resetGame = (state: CrossclimbState): CrossclimbState => {
  return {
    ...state,
    currentPath: [state.graph.startNode],
    visitedNodes: new Set([state.graph.startNode]),
    collectedCheckpoints: new Set(),
    isComplete: false,
    moves: 0,
  }
}

/**
 * Determine if graph has a valid start->end path that visits all checkpoints.
 */
export const hasCheckpointCompletePath = (graph: Graph): boolean => {
  const checkpointSet = new Set(graph.checkpoints)
  const initialCollected = new Set<NodeId>()
  if (checkpointSet.has(graph.startNode)) {
    initialCollected.add(graph.startNode)
  }

  const search = (currentNodeId: NodeId, visited: Set<NodeId>, collected: Set<NodeId>): boolean => {
    if (currentNodeId === graph.endNode && graph.checkpoints.every((id) => collected.has(id))) {
      return true
    }

    const currentNode = graph.nodes.get(currentNodeId)
    if (!currentNode) {
      return false
    }

    for (const nextNodeId of currentNode.connections) {
      if (visited.has(nextNodeId)) {
        continue
      }

      const nextVisited = new Set(visited)
      nextVisited.add(nextNodeId)

      const nextCollected = new Set(collected)
      if (checkpointSet.has(nextNodeId)) {
        nextCollected.add(nextNodeId)
      }

      if (search(nextNodeId, nextVisited, nextCollected)) {
        return true
      }
    }

    return false
  }

  return search(graph.startNode, new Set([graph.startNode]), initialCollected)
}

