import { INITIAL_STATE } from './constants'
import { applyRunnerCommand, stepRunnerSimulation } from './simulation'
import type { GameState } from './types'

export type GameAction =
  | 'primary'
  | 'secondary'
  | 'tertiary'
  | 'laneLeft'
  | 'laneRight'
  | 'tick'
  | 'reset'

export const reduceGameState = (state: GameState, action: GameAction): GameState => {
  if (action === 'reset') {
    return INITIAL_STATE
  }
  if (state.phase === 'gameOver') {
    return state
  }

  if (action === 'tick') {
    return stepRunnerSimulation(state)
  }

  return applyRunnerCommand(state, action)
}

import { describe, expect, it } from 'vitest'
import { INITIAL_STATE } from './constants'
import { reduceGameState } from './rules'
import type { GameState } from './types'

const createState = (overrides: Partial<GameState> = {}): GameState => ({
  ...INITIAL_STATE,
  ...overrides,
})

describe('dash-lanes rules', () => {
  it('clamps lane switching at boundaries', () => {
    const leftEdge = createState({
      runner: { lane: 0 },
    })
    const afterLeft = reduceGameState(leftEdge, 'laneLeft')
    expect(afterLeft.runner.lane).toBe(0)

    const rightEdge = createState({
      runner: { lane: 2 },
    })
    const afterRight = reduceGameState(rightEdge, 'laneRight')
    expect(afterRight.runner.lane).toBe(2)
  })

  it('decrements lives on collision without dash protection', () => {
    const state = createState({
      lives: 3,
      intensity: 10,
      speed: 25,
      runner: { lane: 1 },
      obstacles: [
        {
          id: 1,
          kind: 'blocker',
          lane: 1,
          distance: 1,
          spawnTick: 0,
        },
      ],
      dashTicksRemaining: 0,
      spawnCooldownMs: 10_000,
    })

    const next = reduceGameState(state, 'tick')
    expect(next.lives).toBe(2)
    expect(next.phase).toBe('playing')
  })

  it('transitions to gameOver when lives reach zero', () => {
    const state = createState({
      lives: 1,
      intensity: 10,
      speed: 25,
      runner: { lane: 1 },
      obstacles: [
        {
          id: 1,
          kind: 'blocker',
          lane: 1,
          distance: 1,
          spawnTick: 0,
        },
      ],
      dashTicksRemaining: 0,
      spawnCooldownMs: 10_000,
    })

    const next = reduceGameState(state, 'tick')
    expect(next.phase).toBe('gameOver')
    expect(next.status).toContain('System collapse')
  })

  it('ramps speed and reduces spawn interval over time', () => {
    const state = createState({
      speed: 22,
      spawnIntervalMs: 900,
      spawnCooldownMs: 800,
    })

    const next = reduceGameState(state, 'tick')
    expect(next.speed).toBeGreaterThan(state.speed)
    expect(next.spawnIntervalMs).toBeLessThan(state.spawnIntervalMs)
  })

  it('resets session to initial state', () => {
    const progressed = createState({
      score: 88,
      lives: 1,
      tick: 45,
      runner: { lane: 2 },
      distance: 400,
      status: 'temporary',
    })

    const reset = reduceGameState(progressed, 'reset')
    expect(reset).toEqual(INITIAL_STATE)
  })
})

import {
  CENTER_LANE,
  COLLISION_DISTANCE,
  DASH_DURATION_TICKS,
  DESPAWN_OBSTACLE_DISTANCE,
  DIFFICULTY_CURVE,
  LANE_COUNT,
  OBSTACLE_PATTERNS,
  PROGRESS_TARGET,
  START_OBSTACLE_DISTANCE,
  TICK_INTERVAL_MS,
} from './constants'
import type { GameState, LaneIndex, Obstacle } from './types'

const clamp = (value: number, min: number, max: number): number => {
  if (value < min) {
    return min
  }
  if (value > max) {
    return max
  }
  return value
}

const toLaneIndex = (lane: number): LaneIndex => {
  const clamped = clamp(lane, 0, LANE_COUNT - 1)
  return clamped as LaneIndex
}

const nextPattern = (state: GameState) =>
  OBSTACLE_PATTERNS[state.nextObstacleId % OBSTACLE_PATTERNS.length]

const spawnObstacles = (state: GameState): GameState => {
  if (state.spawnCooldownMs > 0) {
    return state
  }

  const pattern = nextPattern(state)
  const spawned: Obstacle[] = pattern.lanes.map((lane, offset) => ({
    id: state.nextObstacleId + offset,
    kind: 'blocker',
    lane,
    distance: START_OBSTACLE_DISTANCE + offset * 6,
    spawnTick: state.tick,
  }))

  return {
    ...state,
    nextObstacleId: state.nextObstacleId + spawned.length,
    spawnCooldownMs: state.spawnIntervalMs,
    obstacles: [...state.obstacles, ...spawned],
    status: `Obstacle cadence rising: lane threat at ${pattern.lanes.join('/')}`,
  }
}

const moveObstaclesAndResolveCollisions = (state: GameState, deltaSeconds: number): GameState => {
  const speedScale = 1 + state.intensity / 220
  const moved = state.obstacles.map((obstacle) => ({
    ...obstacle,
    distance: obstacle.distance - state.speed * deltaSeconds * speedScale,
  }))

  let collisions = 0
  let dodged = 0

  const active = moved.filter((obstacle) => {
    if (obstacle.distance < DESPAWN_OBSTACLE_DISTANCE) {
      dodged += 1
      return false
    }

    const collides =
      obstacle.lane === state.runner.lane &&
      obstacle.distance <= COLLISION_DISTANCE &&
      obstacle.distance >= -COLLISION_DISTANCE
    if (!collides) {
      return true
    }

    if (state.dashTicksRemaining > 0) {
      return false
    }

    collisions += 1
    return false
  })

  const lifeLoss = Math.min(collisions, state.lives)
  const scoreGain = dodged * 6 + (collisions === 0 ? 0 : -3 * collisions)

  const status =
    collisions > 0
      ? 'Collision registered. System integrity degraded.'
      : dodged > 0
        ? 'Clean dodge. Maintain lane rhythm.'
        : state.status

  return {
    ...state,
    lives: state.lives - lifeLoss,
    score: Math.max(0, state.score + scoreGain),
    obstacles: active,
    status,
  }
}

const withGameOverCheck = (state: GameState): GameState => {
  if (state.lives <= 0) {
    return {
      ...state,
      phase: 'gameOver',
      focus: 0,
      status: 'System collapse: retry run',
    }
  }
  return state
}

export const stepRunnerSimulation = (
  state: GameState,
  deltaMs: number = TICK_INTERVAL_MS,
): GameState => {
  const deltaSeconds = deltaMs / 1000
  const speed = clamp(
    state.speed + DIFFICULTY_CURVE.speedRampPerSecond * deltaSeconds,
    DIFFICULTY_CURVE.baseSpeed,
    DIFFICULTY_CURVE.maxSpeed,
  )
  const spawnIntervalMs = clamp(
    state.spawnIntervalMs - DIFFICULTY_CURVE.spawnRampPerSecond * deltaSeconds,
    DIFFICULTY_CURVE.minSpawnIntervalMs,
    DIFFICULTY_CURVE.baseSpawnIntervalMs,
  )
  const distance = state.distance + speed * deltaSeconds
  const intensity = clamp(
    state.intensity +
      DIFFICULTY_CURVE.intensityRampPerSecond * deltaSeconds +
      (speed / DIFFICULTY_CURVE.maxSpeed) * 1.5,
    0,
    100,
  )
  const focus = clamp(state.focus - deltaSeconds * 2.5 - intensity * 0.005, 0, 100)
  const runScoreGain = Math.round(speed * deltaSeconds * (1 + intensity / 125))
  const progress = clamp((distance / PROGRESS_TARGET) * 100, 0, 100)

  const baseNext: GameState = {
    ...state,
    tick: state.tick + 1,
    runTimeMs: state.runTimeMs + deltaMs,
    speed,
    spawnIntervalMs,
    spawnCooldownMs: state.spawnCooldownMs - deltaMs,
    distance,
    progress,
    intensity,
    focus,
    dashTicksRemaining: Math.max(0, state.dashTicksRemaining - 1),
    score: state.score + runScoreGain,
    status: 'Forward velocity increasing. Read lane cadence.',
  }

  const spawned = spawnObstacles(baseNext)
  const resolved = moveObstaclesAndResolveCollisions(spawned, deltaSeconds)
  return withGameOverCheck(resolved)
}

export const applyRunnerCommand = (
  state: GameState,
  action: 'laneLeft' | 'laneRight' | 'primary' | 'secondary' | 'tertiary',
): GameState => {
  if (action === 'laneLeft') {
    return {
      ...state,
      runner: { lane: toLaneIndex(state.runner.lane - 1) },
      status: 'Lane shift left.',
    }
  }

  if (action === 'laneRight') {
    return {
      ...state,
      runner: { lane: toLaneIndex(state.runner.lane + 1) },
      status: 'Lane shift right.',
    }
  }

  if (action === 'primary') {
    return {
      ...state,
      speed: clamp(state.speed + 1.4, DIFFICULTY_CURVE.baseSpeed, DIFFICULTY_CURVE.maxSpeed),
      score: state.score + 8,
      focus: clamp(state.focus + 3, 0, 100),
      status: 'Forward push engaged.',
    }
  }

  if (action === 'secondary') {
    return {
      ...state,
      runner: { lane: CENTER_LANE as LaneIndex },
      intensity: clamp(state.intensity - 8, 0, 100),
      focus: clamp(state.focus + 12, 0, 100),
      score: state.score + 2,
      status: 'Lane reset stabilized trajectory.',
    }
  }

  return {
    ...state,
    dashTicksRemaining: Math.max(state.dashTicksRemaining, DASH_DURATION_TICKS),
    intensity: clamp(state.intensity + 6, 0, 100),
    focus: clamp(state.focus - 4, 0, 100),
    score: state.score + 5,
    status: 'Dash surge armed. Collision bypass active.',
  }
}

import type { Domino, GameState } from '@/domain'
import { createGameState, getValidMoves } from '@/domain'
import { useCallback, useReducer } from 'react'

// ─── Reducer ─────────────────────────────────────────────────────────────────

type GameAction =
  | { type: 'START' }
  | { type: 'PLACE_TILE'; domino: Domino; side: 'left' | 'right' }
  | { type: 'DRAW_FROM_BONEYARD' }
  | { type: 'CPU_TURN' }
  | { type: 'RESET' }

function getTableEnds(table: Domino[]): { left: number | null; right: number | null } {
  if (table.length === 0) {return { left: null, right: null }}
  return { left: table[0].left, right: table[table.length - 1].right }
}

function reducer(state: GameState, action: GameAction): GameState {
  switch (action.type) {
    case 'START':
    case 'RESET':
      return createGameState()

    case 'PLACE_TILE': {
      if (state.currentPlayer !== 'player') {return state}
      const { domino, side } = action
      const table = [...state.table]

      let placedDomino: Domino = domino
      if (side === 'left') {
        const leftEnd = table[0]?.left ?? null
        if (leftEnd !== null && domino.right !== leftEnd) {
          placedDomino = { left: domino.right, right: domino.left }
        }
        table.unshift(placedDomino)
      } else {
        const rightEnd = table[table.length - 1]?.right ?? null
        if (rightEnd !== null && domino.left !== rightEnd) {
          placedDomino = { left: domino.right, right: domino.left }
        }
        table.push(placedDomino)
      }

      const playerHand = state.playerHand.filter((d) => d !== domino)
      const gameOver = playerHand.length === 0
      return {
        ...state,
        table,
        playerHand,
        phase: gameOver ? 'game-over' : 'playing',
        gameOver,
        currentPlayer: 'computer',
      }
    }

    case 'DRAW_FROM_BONEYARD': {
      if (state.boneyard.length === 0) {return state}
      const [drawn, ...remaining] = state.boneyard
      return {
        ...state,
        playerHand: [...state.playerHand, drawn],
        boneyard: remaining,
      }
    }

    case 'CPU_TURN': {
      if (state.currentPlayer !== 'computer') {return state}
      const { left, right } = getTableEnds(state.table)
      const valid = getValidMoves(state.computerHand, left, right)

      if (valid.length === 0) {
        // CPU passes — switch back
        return { ...state, currentPlayer: 'player' }
      }

      const chosen = valid[0]
      const table = [...state.table]
      if (left === null || chosen.left === right || chosen.right === right) {
        table.push(chosen)
      } else {
        table.unshift({ left: chosen.right, right: chosen.left })
      }

      const computerHand = state.computerHand.filter((d) => d !== chosen)
      const gameOver = computerHand.length === 0
      return {
        ...state,
        table,
        computerHand,
        phase: gameOver ? 'game-over' : 'playing',
        gameOver,
        currentPlayer: 'player',
      }
    }

    default:
      return state
  }
}

// ─── Hook ────────────────────────────────────────────────────────────────────

export interface UseGameReturn {
  gameState: GameState
  isPlayerTurn: boolean
  validPlayerMoves: Domino[]
  start: () => void
  placeTile: (domino: Domino, side: 'left' | 'right') => void
  drawFromBoneyard: () => void
  cpuTurn: () => void
  reset: () => void
}

export function useGame(): UseGameReturn {
  const [state, dispatch] = useReducer(reducer, undefined, createGameState)

  const start = useCallback(() => dispatch({ type: 'START' }), [])
  const placeTile = useCallback(
    (domino: Domino, side: 'left' | 'right') => dispatch({ type: 'PLACE_TILE', domino, side }),
    [],
  )
  const drawFromBoneyard = useCallback(() => dispatch({ type: 'DRAW_FROM_BONEYARD' }), [])
  const cpuTurn = useCallback(() => dispatch({ type: 'CPU_TURN' }), [])
  const reset = useCallback(() => dispatch({ type: 'RESET' }), [])

  const { left, right } = getTableEnds(state.table)
  const validPlayerMoves = getValidMoves(state.playerHand, left, right)

  return {
    gameState: state,
    isPlayerTurn: state.currentPlayer === 'player',
    validPlayerMoves,
    start,
    placeTile,
    drawFromBoneyard,
    cpuTurn,
    reset,
  }
}

/**
 * Dominoes domain rules — pure functions for game mechanics.
 */

import { INITIAL_HAND_SIZE, MAX_PIPS } from './constants'
import type { Domino, GameState } from './types'

/** Generate all tiles in a standard double-6 set. */
export function generateBoneyard(): Domino[] {
  const tiles: Domino[] = []
  for (let left = 0; left <= MAX_PIPS; left++) {
    for (let right = left; right <= MAX_PIPS; right++) {
      tiles.push({ left, right })
    }
  }
  return shuffle(tiles)
}

/** Fisher-Yates shuffle. */
function shuffle<T>(arr: T[]): T[] {
  const out = [...arr]
  for (let i = out.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1))
    ;[out[i], out[j]] = [out[j], out[i]]
  }
  return out
}

/** Create the initial game state. */
export function createGameState(): GameState {
  const boneyard = generateBoneyard()
  const playerHand = boneyard.splice(0, INITIAL_HAND_SIZE)
  const computerHand = boneyard.splice(0, INITIAL_HAND_SIZE)
  return {
    phase: 'playing',
    playerHand,
    computerHand,
    boneyard,
    table: [],
    currentPlayer: 'player',
    playerScore: 0,
    computerScore: 0,
    gameOver: false,
  }
}

/** Check if a domino can be placed at the given end of the table. */
export function canPlace(domino: Domino, tableEnd: number | null): boolean {
  if (tableEnd === null) {return true}
  return domino.left === tableEnd || domino.right === tableEnd
}

/** Get valid moves from a hand given the current table ends. */
export function getValidMoves(
  hand: Domino[],
  leftEnd: number | null,
  rightEnd: number | null,
): Domino[] {
  return hand.filter((d) => canPlace(d, leftEnd) || canPlace(d, rightEnd))
}

/** Calculate the pip count of a hand (used for scoring when passing). */
export function handPipCount(hand: Domino[]): number {
  return hand.reduce((sum, d) => sum + d.left + d.right, 0)
}

/** Check if a player has blocked (no valid moves and boneyard empty). */
export function isBlocked(
  hand: Domino[],
  leftEnd: number | null,
  rightEnd: number | null,
  boneyardEmpty: boolean,
): boolean {
  return boneyardEmpty && getValidMoves(hand, leftEnd, rightEnd).length === 0
}

