/**
 * Farkle game hook
 * Manages game state including dice rolling, selection, and banking
 */

import type { DieValue, GameState } from '@/domain'
import { calculateScore, isValidSelection } from '@/domain/rules'
import { useCallback, useState } from 'react'

// Simple dice roller
function rollDice(count: number): DieValue[] {
  return Array.from({ length: count }, () => (Math.floor(Math.random() * 6) + 1) as DieValue)
}

export function useGame() {
  const [gameState, setGameState] = useState<GameState>({
    phase: 'rolling',
    currentPlayer: 'human',
    dice: {
      allDice: [],
      selectedIndices: new Set(),
      heldDice: [],
      remainingDice: [],
      isRolling: false,
    },
    banking: {
      bankedScore: 0,
      atRiskScore: 0,
      roundScore: 0,
    },
    humanTotal: 0,
    cpuTotal: 0,
    roundHistory: [],
    winner: null,
    isGameOver: false,
  })

  // Roll all dice
  const rollAll = useCallback(() => {
    const newDice = rollDice(6)
    setGameState((prev) => ({
      ...prev,
      dice: {
        ...prev.dice,
        allDice: newDice,
        selectedIndices: new Set(),
        remainingDice: newDice,
        isRolling: false,
      },
      banking: {
        ...prev.banking,
        atRiskScore: 0,
      },
      phase: 'selecting',
    }))
  }, [])

  // Roll remaining dice
  const rollRemaining = useCallback(() => {
    setGameState((prev) => {
      const newRemaining = rollDice(6 - prev.dice.heldDice.length)
      return {
        ...prev,
        dice: {
          ...prev.dice,
          allDice: [...prev.dice.heldDice, ...newRemaining],
          remainingDice: newRemaining,
          selectedIndices: new Set(),
          isRolling: false,
        },
        banking: {
          ...prev.banking,
          atRiskScore: 0,
        },
        phase: 'selecting',
      }
    })
  }, [])

  // Toggle die selection
  const toggleDieSelection = useCallback((index: number) => {
    setGameState((prev) => {
      const newSelected = new Set(prev.dice.selectedIndices)
      if (newSelected.has(index)) {
        newSelected.delete(index)
      } else {
        newSelected.add(index)
      }

      // Calculate new at risk score
      const selectedDice = Array.from(newSelected).map((i) => prev.dice.allDice[i])
      const atRiskScore = calculateScore(selectedDice)

      return {
        ...prev,
        dice: {
          ...prev.dice,
          selectedIndices: newSelected,
        },
        banking: {
          ...prev.banking,
          atRiskScore,
        },
      }
    })
  }, [])

  // Bank current selection
  const bankSelection = useCallback(() => {
    setGameState((prev) => {
      const selectedDice = Array.from(prev.dice.selectedIndices).map((i) => prev.dice.allDice[i])
      const selectionScore = calculateScore(selectedDice)

      if (!isValidSelection(selectedDice)) {
        return prev // Invalid selection
      }

      const newBanked = prev.banking.bankedScore + selectionScore
      const newHeld = prev.dice.allDice.filter((_, i) => !prev.dice.selectedIndices.has(i))

      // If all dice are held, can roll all 6 again
      if (newHeld.length === 0) {
        return {
          ...prev,
          dice: {
            ...prev.dice,
            heldDice: [],
            selectedIndices: new Set(),
            allDice: [],
            remainingDice: [],
          },
          banking: {
            ...prev.banking,
            bankedScore: newBanked,
            atRiskScore: 0,
          },
          phase: 'rolling',
        }
      }

      return {
        ...prev,
        dice: {
          ...prev.dice,
          heldDice: newHeld,
          selectedIndices: new Set(),
        },
        banking: {
          ...prev.banking,
          bankedScore: newBanked,
          atRiskScore: 0,
        },
        phase: 'banking',
      }
    })
  }, [])

  // End turn (bank and pass to next player)
  const endTurn = useCallback(() => {
    setGameState((prev) => {
      if (prev.currentPlayer === 'human') {
        return {
          ...prev,
          humanTotal: prev.humanTotal + prev.banking.bankedScore,
          currentPlayer: 'cpu',
          banking: {
            bankedScore: 0,
            atRiskScore: 0,
            roundScore: 0,
          },
          dice: {
            allDice: [],
            selectedIndices: new Set(),
            heldDice: [],
            remainingDice: [],
            isRolling: false,
          },
          phase: 'rolling',
        }
      } else {
        return {
          ...prev,
          cpuTotal: prev.cpuTotal + prev.banking.bankedScore,
          currentPlayer: 'human',
          banking: {
            bankedScore: 0,
            atRiskScore: 0,
            roundScore: 0,
          },
          dice: {
            allDice: [],
            selectedIndices: new Set(),
            heldDice: [],
            remainingDice: [],
            isRolling: false,
          },
          phase: 'rolling',
        }
      }
    })
  }, [])

  // Farkle! (no scoreable dice)
  const farkle = useCallback(() => {
    setGameState((prev) => ({
      ...prev,
      currentPlayer: prev.currentPlayer === 'human' ? 'cpu' : 'human',
      banking: {
        bankedScore: 0,
        atRiskScore: 0,
        roundScore: 0,
      },
      dice: {
        allDice: [],
        selectedIndices: new Set(),
        heldDice: [],
        remainingDice: [],
        isRolling: false,
      },
      phase: 'rolling',
    }))
  }, [])

  const startGame = useCallback(() => {
    rollAll()
  }, [rollAll])

  return {
    gameState,
    startGame,
    rollAll,
    rollRemaining,
    toggleDieSelection,
    bankSelection,
    endTurn,
    farkle,
  }
}

import { Move as AIMove, GameState } from './types'

/**
 * Calculates the current Nim-sum (XOR sum) of all piles.
 * The core strategy of Nim depends on whether this sum is 0 or non-zero.
 */
export const calculateNimSum = (state: GameState): number => {
  return state.piles.reduce((acc, p) => acc ^ p.count, 0)
}

/**
 * Misere Play strategy logic:
 * If there is only one pile with > 1 object, reduce it to 1 or 0
 * to ensure an odd number of piles with count 1 remains.
 */
const getMisereMove = (state: GameState): AIMove | null => {
  const bigPiles = state.piles.filter((p) => p.count > 1)
  if (bigPiles.length === 1) {
    const singleBigPile = bigPiles[0]
    const onesPiles = state.piles.filter((p) => p.count === 1).length
    // We want to leave an odd number of piles with count 1.
    const targetCount = onesPiles % 2 === 0 ? 1 : 0
    return { pileId: singleBigPile.id, removeCount: singleBigPile.count - targetCount }
  }
  return null
}

/**
 * Selects the best move for the CPU using the Nim-sum strategy.
 * This is optimal for both Normal play and (mostly) Misère play.
 */
export const selectMove = (state: GameState): AIMove => {
  // Check for specialized Misère end-game first
  if (state.mode === 'misere') {
    const misereMove = getMisereMove(state)
    if (misereMove) {
      return misereMove
    }
  }

  const nimSum = calculateNimSum(state)

  if (nimSum !== 0) {
    // There exists a winning move: make nimSum 0.
    for (const pile of state.piles) {
      const targetCount = pile.count ^ nimSum
      if (targetCount < pile.count) {
        return { pileId: pile.id, removeCount: pile.count - targetCount }
      }
    }
  }

  // If nimSum is 0 (losing position), just take 1 from the first non-empty pile.
  const firstNonEmpty = state.piles.find((p) => p.count > 0)
  if (firstNonEmpty) {
    return { pileId: firstNonEmpty.id, removeCount: 1 }
  }

  // Should never happen if checkGameOver works.
  return { pileId: 0, removeCount: 0 }
}

import { GameMode, GameState, Move, Player } from './types'

/**
 * Creates the initial game state from a list of counts.
 */
export const createInitialBoard = (
  initialCounts: number[],
  startingPlayer: Player = 'human',
  mode: GameMode = 'misere',
): GameState => ({
  piles: initialCounts.map((count, id) => ({ id, count })),
  currentPlayer: startingPlayer,
  winner: null,
  isGameOver: false,
  mode,
})

/**
 * Validates whether a move is legal.
 */
export const isValidMove = (state: GameState, move: Move): boolean => {
  const pile = state.piles.find((p) => p.id === move.pileId)
  return !!pile && move.removeCount > 0 && move.removeCount <= pile.count
}

/**
 * Applies a move to the board and returns a new state.
 */
export const applyMove = (state: GameState, move: Move): GameState => {
  if (!isValidMove(state, move)) {
    return state
  }

  const newPiles = state.piles.map((p) =>
    p.id === move.pileId ? { ...p, count: p.count - move.removeCount } : p,
  )

  return {
    ...state,
    piles: newPiles,
  }
}

