import type { CardRank, GameState } from '@/domain'
import { collectBooks, createGameState, isGameOver, processAsk } from '@/domain'
import { useCallback, useReducer } from 'react'

type GameAction =
  | { type: 'START' }
  | { type: 'PLAYER_ASK'; rank: CardRank }
  | { type: 'CPU_TURN' }
  | { type: 'RESET' }

function reducer(state: GameState, action: GameAction): GameState {
  switch (action.type) {
    case 'START':
    case 'RESET':
      return createGameState()

    case 'PLAYER_ASK': {
      const { rank } = action
      const result = processAsk(state.playerHand, state.computerHand, rank)
      let { askerHand, targetHand } = result
      const { goFish } = result

      if (goFish && state.deck.length > 0) {
        askerHand = [...askerHand, state.deck[0]]
      }

      const { hand: cleanPlayerHand, booksFound } = collectBooks(askerHand)

      const newState: GameState = {
        ...state,
        playerHand: cleanPlayerHand,
        computerHand: targetHand,
        deck: goFish ? state.deck.slice(1) : state.deck,
        playerSets: state.playerSets + booksFound,
        currentPlayer: goFish ? 'computer' : 'player',
      }

      const done = isGameOver(newState)
      return { ...newState, gameOver: done, phase: done ? 'game-over' : 'playing' }
    }

    case 'CPU_TURN': {
      if (state.currentPlayer !== 'computer' || state.computerHand.length === 0) {return state}

      const rankCounts = new Map<CardRank, number>()
      for (const card of state.computerHand) {
        rankCounts.set(card.rank, (rankCounts.get(card.rank) ?? 0) + 1)
      }
      const askRank = [...rankCounts.entries()].sort((a, b) => b[1] - a[1])[0][0]

      const result = processAsk(state.computerHand, state.playerHand, askRank)
      let { askerHand, targetHand } = result
      const { goFish } = result

      if (goFish && state.deck.length > 0) {
        askerHand = [...askerHand, state.deck[0]]
      }

      const { hand: cleanCpuHand, booksFound } = collectBooks(askerHand)

      const newState: GameState = {
        ...state,
        computerHand: cleanCpuHand,
        playerHand: targetHand,
        deck: goFish ? state.deck.slice(1) : state.deck,
        computerSets: state.computerSets + booksFound,
        currentPlayer: goFish ? 'player' : 'computer',
      }

      const done = isGameOver(newState)
      return { ...newState, gameOver: done, phase: done ? 'game-over' : 'playing' }
    }

    default:
      return state
  }
}

export interface UseGameReturn {
  gameState: GameState
  isPlayerTurn: boolean
  isGameOver: boolean
  winner: 'player' | 'computer' | 'draw' | null
  start: () => void
  playerAsk: (rank: CardRank) => void
  cpuTurn: () => void
  reset: () => void
}

export function useGame(): UseGameReturn {
  const [state, dispatch] = useReducer(reducer, undefined, createGameState)

  const start = useCallback(() => dispatch({ type: 'START' }), [])
  const playerAsk = useCallback((rank: CardRank) => dispatch({ type: 'PLAYER_ASK', rank }), [])
  const cpuTurn = useCallback(() => dispatch({ type: 'CPU_TURN' }), [])
  const reset = useCallback(() => dispatch({ type: 'RESET' }), [])

  const winner = state.gameOver
    ? state.playerSets > state.computerSets
      ? 'player'
      : state.computerSets > state.playerSets
        ? 'computer'
        : 'draw'
    : null

  return {
    gameState: state,
    isPlayerTurn: state.currentPlayer === 'player',
    isGameOver: state.gameOver,
    winner,
    start,
    playerAsk,
    cpuTurn,
    reset,
  }
}

/**
 * Go Fish domain rules — pure functions for game mechanics.
 */

import { CARD_RANKS, INITIAL_HAND_SIZE, SUITS_PER_RANK } from './constants'
import type { Card, CardRank, GameState } from './types'

/** Generate a complete shuffled 52-card deck. */
export function generateDeck(): Card[] {
  const deck: Card[] = []
  for (const rank of CARD_RANKS) {
    for (let suit = 0; suit < SUITS_PER_RANK; suit++) {
      deck.push({ rank })
    }
  }
  return shuffle(deck)
}

function shuffle<T>(arr: T[]): T[] {
  const out = [...arr]
  for (let i = out.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1))
    ;[out[i], out[j]] = [out[j], out[i]]
  }
  return out
}

/** Create the initial game state. */
export function createGameState(): GameState {
  const deck = generateDeck()
  const playerHand = deck.splice(0, INITIAL_HAND_SIZE)
  const computerHand = deck.splice(0, INITIAL_HAND_SIZE)
  return {
    phase: 'playing',
    playerHand,
    computerHand,
    deck,
    playerSets: 0,
    computerSets: 0,
    currentPlayer: 'player',
    gameOver: false,
  }
}

/** Count cards of a given rank in a hand. */
export function countRankInHand(hand: Card[], rank: CardRank): number {
  return hand.filter((c) => c.rank === rank).length
}

/** Check if a hand contains a book (4 cards of the same rank). */
export function findBooks(hand: Card[]): CardRank[] {
  const counts = new Map<CardRank, number>()
  for (const card of hand) {
    counts.set(card.rank, (counts.get(card.rank) ?? 0) + 1)
  }
  return CARD_RANKS.filter((r) => (counts.get(r) ?? 0) === SUITS_PER_RANK)
}

/** Remove all books from a hand and return cleaned hand + count. */
export function collectBooks(hand: Card[]): { hand: Card[]; booksFound: number } {
  const books = findBooks(hand)
  const booksFound = books.length
  const cleaned = hand.filter((c) => !books.includes(c.rank))
  return { hand: cleaned, booksFound }
}

/** Process an "ask" — transfer matching cards from target hand to asking hand. */
export function processAsk(
  askerHand: Card[],
  targetHand: Card[],
  rank: CardRank,
): { askerHand: Card[]; targetHand: Card[]; gained: number; goFish: boolean } {
  const matching = targetHand.filter((c) => c.rank === rank)
  if (matching.length === 0) {
    return { askerHand, targetHand, gained: 0, goFish: true }
  }
  return {
    askerHand: [...askerHand, ...matching],
    targetHand: targetHand.filter((c) => c.rank !== rank),
    gained: matching.length,
    goFish: false,
  }
}

/** Check if the game is over (deck empty and one player has no cards). */
export function isGameOver(state: GameState): boolean {
  return (
    state.deck.length === 0 && (state.playerHand.length === 0 || state.computerHand.length === 0)
  )
}

