 *
 * This module maintained for backward compatibility.
 */

import type { Difficulty } from '@/domain'
import { ensureAsyncWorkerReady, selectAiMove, terminateAsyncWorker } from './aiService'

/**
 * Select AI move with WASM acceleration and worker support.
 * Delegates to new aiService for optimal performance.
 *
 * @param board - Game board array (14 elements)
 * @param player - Current player (0 or 1)
 * @param difficulty - Difficulty level
 * @returns Pit index to move from, or null if no valid moves
 */
export async function selectMoveWithWasm(
  board: number[],
  player: number,
  difficulty: Difficulty,
): Promise<number | null> {
  try {
    const result = await selectAiMove(board, player, difficulty)
    return result.pit ?? null
  } catch (error) {
    console.warn('[WASM AI Service] Move selection failed:', error)
    return null
  }
}

/**
 * Pre-initialize WASM and worker pool.
 * Call at app startup for best performance.
 */
export async function preloadWasm(): Promise<void> {
  try {
    await ensureAsyncWorkerReady()
  } catch (error) {
    console.warn('[WASM AI Service] Preload failed (non-critical):', error)
  }
}

/**
 * Cleanup: Terminate worker thread when done.
 */
export function cleanupWasm(): void {
  terminateAsyncWorker()
}

/**
 * Mancala AI — move selection logic (pure domain, no framework).
 *
 * Strategies by difficulty:
 * - veryEasy/easy: Random valid move
 * - medium: Greedy heuristic (prefer moves that land in store, lead to captures)
 * - mediumHard/hard/veryHard: Minimax with alpha-beta pruning (delegated to WASM)
 */

import {
  checkAndApplyCapture,
  getScores as getBoardScores,
  getValidMoves,
  PLAYER0_STORE,
  PLAYER1_STORE,
  sowSeeds,
} from './board'
import { isGameOver } from './rules'
import type { Difficulty } from './types'

/**
 * Select the best pit for the AI player based on difficulty.
 *
 * @param board Array of 14 pit values
 * @param player Player index (0 or 1)
 * @param difficulty AI difficulty level
 * @returns Pit index, or -1 if no valid move
 */
export function selectMove(board: number[], player: number, difficulty: Difficulty): number | null {
  const validMoves = getValidMoves(board, player as 0 | 1)

  if (validMoves.length === 0) {
    return null
  }

  // Map new difficulty tiers to classic strategies
  if (difficulty === 'veryEasy' || difficulty === 'easy') {
    return selectMoveEasy(validMoves)
  } else if (difficulty === 'medium') {
    return selectMoveMedium(board, player as 0 | 1, validMoves)
  } else {
    // mediumHard, hard, veryHard: use minimax (or delegate to WASM)
    return selectMoveHard(board, player as 0 | 1, validMoves)
  }
}

/**
 * Easy AI: Pick a random valid move.
 */
function selectMoveEasy(validMoves: number[]): number {
  return validMoves[Math.floor(Math.random() * validMoves.length)]
}

/**
 * Medium AI: Greedy heuristic scoring.
 * Prefer moves that:
 * 1. Land in own store (bonus turn)
 * 2. Result in captures
 * 3. Maximize immediate score gain
 */
function selectMoveMedium(board: number[], player: 0 | 1, validMoves: number[]): number {
  let bestMove = validMoves[0]
  let bestScore = -Infinity

  for (const pit of validMoves) {
    const { newBoard: boardAfterSow, landingPit, storeBonus } = sowSeeds(board, player, pit)
    const { captured } = checkAndApplyCapture(boardAfterSow, player, landingPit)

    // Score: bonus turn (10) + capture points (1 per stone) + future capture potential
    let moveScore = 0
    if (storeBonus) {
      moveScore += 10
    }
    if (captured > 0) {
      moveScore += captured * 2
    }
    // Add heuristic for future capture potential
    moveScore += detected(boardAfterSow, player)

    if (moveScore > bestScore) {
      bestScore = moveScore
      bestMove = pit
    }
  }

  return bestMove
}

/**
 * Hard AI: Minimax with alpha-beta pruning and depth limit.
 * Searches 3-4 plies ahead depending on branching factor.
 */
function selectMoveHard(board: number[], player: 0 | 1, validMoves: number[]): number {
  let bestMove = validMoves[0]
  let bestValue = -Infinity
  const maxDepth = 4

  for (const move of validMoves) {
    const value = minimax(board, player, move, 1, maxDepth, -Infinity, Infinity, player)
    if (value > bestValue) {
      bestValue = value
      bestMove = move
    }
  }

  return bestMove
}

/**
 * Minimax evaluation with alpha-beta pruning.
 */
function minimax(
  board: number[],
  player: 0 | 1,
  move: number,
  depth: number,
  maxDepth: number,
  alpha: number,
  beta: number,
  originalPlayer: 0 | 1,
): number {
  // Apply move
  const { newBoard, landingPit, storeBonus } = sowSeeds(board, player, move)
  const { newBoard: boardAfterCapture } = checkAndApplyCapture(newBoard, player, landingPit)

  const nextPlayer: 0 | 1 = storeBonus ? player : player === 0 ? 1 : 0

  // Terminal node or max depth reached?
  if (depth >= maxDepth || isGameOver(boardAfterCapture)) {
    return evaluateBoard(boardAfterCapture, originalPlayer)
  }

  // Recursively evaluate next moves
  const nextMoves = getValidMoves(boardAfterCapture, nextPlayer)

  if (nextMoves.length === 0) {
    return evaluateBoard(boardAfterCapture, originalPlayer)
  }

  if (nextPlayer === originalPlayer) {
    // Maximizing player
    let maxEval = -Infinity
    for (const nextMove of nextMoves) {
      const eval_ = minimax(
        boardAfterCapture,
        nextPlayer,
        nextMove,
        depth + 1,
        maxDepth,
        alpha,
        beta,
        originalPlayer,
      )
      maxEval = Math.max(maxEval, eval_)
      alpha = Math.max(alpha, eval_)
      if (beta <= alpha) {
        break // Beta cutoff
      }
    }
    return maxEval
  } else {
    // Minimizing player (opponent)
    let minEval = Infinity
    for (const nextMove of nextMoves) {
      const eval_ = minimax(
        boardAfterCapture,
        nextPlayer,
        nextMove,
        depth + 1,
        maxDepth,
        alpha,
        beta,
        originalPlayer,
      )
      minEval = Math.min(minEval, eval_)
      beta = Math.min(beta, eval_)
      if (beta <= alpha) {
        break // Alpha cutoff
      }
    }
    return minEval
  }
}

/**
 * Heuristic evaluation of board state.
 * Returns a score favoring the given player.
 *
 * Score = own store - opponent store + positional factors
 */
function evaluateBoard(board: number[], player: 0 | 1): number {
  const [score0, score1] = getScores(board)
  let score = player === 0 ? score0 - score1 : score1 - score0

  // Positional bonus: stones near own store are worth more
  // (more likely to contribute to future bonus turns)
  const ownSideStart = player === 0 ? 0 : 7
  for (let i = 0; i < 6; i++) {
    const pit = ownSideStart + i
    const distance = 5 - i // Distance to own store (5 to 0)
    score += board[pit] * (0.1 / (distance + 1)) // Bonus diminishes with distance
  }

  return score
}

/**
 * Get future capture potential (heuristic for medium AI).
 */
function detected(board: number[], player: 0 | 1): number {
  // Count opponent stones in pits directly across from our empty pits
  let potential = 0

  const ownStart = player === 0 ? 0 : 7
  const oppStart = player === 0 ? 7 : 0

  for (let i = 0; i < 6; i++) {
    const ownPit = ownStart + i
    const oppPit = oppStart + (5 - i) // Opposite pit

    if (board[ownPit] === 0 && board[oppPit] > 0) {
      potential += board[oppPit] * 0.5 // Potential future captures
    }
  }

  return potential
}

/**
 * Simple heuristic for immediate stone count advantage.
 */
export function evaluateBoardSimple(board: number[], player: 0 | 1): number {
  const ownStore = player === 0 ? PLAYER0_STORE : PLAYER1_STORE
  const oppStore = player === 0 ? PLAYER1_STORE : PLAYER0_STORE
  return board[ownStore] - board[oppStore]
}

/**
 * Helper: wrap board getScores for internal use.
 */
function getScores(board: number[]): [number, number] {
  return getBoardScores(board)
}

/**
 * Board operations — pure functions for creating and manipulating game state.
 * No React, no DOM — purely functional transformations.
 *
 * Board layout (14 pits):
 *  Player 0: pits 0-5 (left to right), store at 6
 *  Player 1: pits 7-12 (left to right), store at 13
 *
 * Sowing direction: counter-clockwise from player 0's perspective
 *  Player 0 sows: 0→1→2→3→4→5→store(6)→loop
 *  Player 1 sows: 7→8→9→10→11→12→store(13)→loop
 */

import type { PlayerIndex } from './types'

export const PITS_PER_SIDE = 6
export const STONES_PER_PIT = 4
export const TOTAL_PITS = 14
export const PLAYER0_STORE = 6
export const PLAYER1_STORE = 13

/**
 * Create a fresh game board with standard setup.
 * @param stones Number of stones per pit (default 4 for Kalah)
 * @returns Array of 14 pit values
 */
export function createBoard(stones: number = STONES_PER_PIT): number[] {
  const board = new Array(TOTAL_PITS).fill(0)

  // Fill player 0 pits (0-5)
  for (let i = 0; i < PITS_PER_SIDE; i++) {
    board[i] = stones
  }

  // Store 0 is empty (index 6)
  board[PLAYER0_STORE] = 0

  // Fill player 1 pits (7-12)
  for (let i = 7; i < 13; i++) {
    board[i] = stones
  }

  // Store 1 is empty (index 13)
  board[PLAYER1_STORE] = 0

  return board
}

/**
 * Get valid move indices for a player.
 * A pit is valid if it contains stones AND is on the player's side.
 */
export function getValidMoves(board: number[], player: PlayerIndex): number[] {
  const startPit = player === 0 ? 0 : 7
  const endPit = player === 0 ? PITS_PER_SIDE : 13

  const valid: number[] = []
  for (let pit = startPit; pit < endPit; pit++) {
    if (board[pit] > 0) {
      valid.push(pit)
    }
  }

  return valid
}

/**
 * Check if a player has any valid moves left.
 */
export function hasValidMoves(board: number[], player: PlayerIndex): boolean {
  return getValidMoves(board, player).length > 0
}

/**
 * Sow seeds from a pit and return the new board state and landing pit.
 * Handles skipping opponent stores.
 *
 * @param board Current board state
 * @param player Player making the move
 * @param pit Pit to sow from (0-5 for player 0, 7-12 for player 1)
 * @returns { newBoard, landingPit, storeBonus } where storeBonus indicates if player gets extra turn
 */
export function sowSeeds(
  board: number[],
  player: PlayerIndex,
  pit: number,
): { newBoard: number[]; landingPit: number; storeBonus: boolean } {
  // Validate pit belongs to player
  const startPit = player === 0 ? 0 : 7
  const endPit = player === 0 ? PITS_PER_SIDE : 13

  if (pit < startPit || pit >= endPit || board[pit] === 0) {
    throw new Error(`Invalid move: pit ${pit} for player ${player}`)
  }

  const newBoard = [...board]
  let seeds = newBoard[pit]
  newBoard[pit] = 0

  const ownStore = player === 0 ? PLAYER0_STORE : PLAYER1_STORE
  const opponentStore = player === 0 ? PLAYER1_STORE : PLAYER0_STORE

  let currentPit = pit
  let landingPit = pit

  // Sow seeds counter-clockwise
  while (seeds > 0) {
    currentPit = (currentPit + 1) % TOTAL_PITS

    // Skip opponent's store
    if (currentPit === opponentStore) {
      continue
    }

    // Place seed
    newBoard[currentPit]++
    seeds--
    landingPit = currentPit
  }

  // Check if last seed landed in own store (bonus turn)
  const storeBonus = landingPit === ownStore

  return { newBoard, landingPit, storeBonus }
}

/**
 * Check if a capture is possible and perform it if valid.
 * Capture: landing in empty pit on your side with opposite pit having seeds.
 *
 * @returns { newBoard, captured } where captured is number of stones taken
 */
export function checkAndApplyCapture(
  board: number[],
  player: PlayerIndex,
  landingPit: number,
): { newBoard: number[]; captured: number } {
  const newBoard = [...board]
  const ownStore = player === 0 ? PLAYER0_STORE : PLAYER1_STORE
  const startPit = player === 0 ? 0 : 7
  const endPit = player === 0 ? PITS_PER_SIDE : 13

  // Can only capture if:
  // 1. Landing pit is on your side (not store)
  // 2. Landing pit was empty before this seed
  // 3. Opposite pit has seeds

  const isOnOwnSide = landingPit >= startPit && landingPit < endPit
  const wasEmpty = newBoard[landingPit] === 1 // Now has 1 seed from sow
  // Calculate opposite pit: pit i is opposite to pit (12 - i)
  const oppositeIndex = 12 - landingPit
  const hasOppositeSeed = newBoard[oppositeIndex] > 0

  if (isOnOwnSide && wasEmpty && hasOppositeSeed) {
    // Capture!
    const capturedCount = newBoard[landingPit] + newBoard[oppositeIndex]
    newBoard[landingPit] = 0
    newBoard[oppositeIndex] = 0
    newBoard[ownStore] += capturedCount

    return { newBoard, captured: capturedCount }
  }

  return { newBoard, captured: 0 }
}

/**
 * Collect remaining stones to the player with stones left.
 * Called when one side is empty.
 *
 * @returns newBoard with remaining stones collected
 */
export function collectRemainingStones(board: number[]): number[] {
  const newBoard = [...board]

  // Check if player 0 side is empty
  const player0Empty = !hasValidMoves(newBoard, 0)
  if (player0Empty) {
    // Player 1 collects their side
    let collected = 0
    for (let i = 7; i < 13; i++) {
      collected += newBoard[i]
      newBoard[i] = 0
    }
    newBoard[PLAYER1_STORE] += collected
  } else {
    // Player 0 collects their side
    let collected = 0
    for (let i = 0; i < 6; i++) {
      collected += newBoard[i]
      newBoard[i] = 0
    }
    newBoard[PLAYER0_STORE] += collected
  }

  return newBoard
}

/**
 * Get the score for each player.
 */
export function getScores(board: number[]): [player0: number, player1: number] {
  return [board[PLAYER0_STORE], board[PLAYER1_STORE]]
}

/**
 * Determine winner (null if tie).
 */
export function determineWinner(board: number[]): 0 | 1 | null {
  const [score0, score1] = getScores(board)
  if (score0 > score1) {
    return 0
  }
  if (score1 > score0) {
    return 1
  }
  return null // Draw
}

/**
 * Human-readable pit name for debugging.
 */
export function pitName(pit: number): string {
  if (pit === PLAYER0_STORE) {
    return 'P0 Store'
  }
  if (pit === PLAYER1_STORE) {
    return 'P1 Store'
  }
  if (pit < PITS_PER_SIDE) {
    return `P0 Pit ${pit}`
  }
  return `P1 Pit ${pit - 7}`
}

/**
 * Layer (z-index) configuration for Battleship
 * Centralizes z-index values and CSS variable generation
 */

export interface LayerConfig {
  name: string
  zIndex: number
}

export interface LayerStack {
  [key: string]: number
}

/**
 * Get z-index stack configuration for the game theme
 * Returns layering configuration appropriate for the color theme
 */
export const getLayerStack = (_colorTheme: string): LayerStack => {
  // Standard layer configuration for Battleship
  // Can be customized per theme if needed
  return {
    '--z-base': 1,
    '--z-board': 10,
    '--z-cells': 20,
    '--z-overlay': 100,
    '--z-menu': 200,
    '--z-modal': 300,
  }
}

/**
 * Convert layer stack to CSS variables object
 * Returns object suitable for applying to element.style.setProperty()
 */
export const layerStackToCssVars = (stack: LayerStack): Record<string, string> => {
  const vars: Record<string, string> = {}
  for (const [key, value] of Object.entries(stack)) {
    vars[key] = String(value)
  }
  return vars
}

export const LAYER_Z = {
  base: 1,
  board: 10,
  cells: 20,
  overlay: 100,
  menu: 200,
  modal: 300,
} as const

