        {/* Player 0 (human) pits - bottom row */}
        <div className={styles.pits}>
          {player0Pits.map((stones, idx) => {
            const pitIndex = idx
            const isValid = game.validMoves.includes(pitIndex)
            const isDisabled = !game.isHumanTurn || game.isGameOver
