import { placeMines, type Board } from '@/domain'
import { getMinesweeperWasmSync } from '@/wasm/minesweeper-wasm'

const MINE_BIT = 0b100
const ADJACENT_SHIFT = 3
const ADJACENT_MASK = 0b1111

function createSeed(): number {
  if (typeof crypto !== 'undefined' && typeof crypto.getRandomValues === 'function') {
    return crypto.getRandomValues(new Uint32Array(1))[0] ?? Date.now()
  }

  return (Date.now() ^ Math.floor(Math.random() * 0xffffffff)) >>> 0
}

export function placeMinesWithEngine(
  board: Board,
  count: number,
  safeRow: number,
  safeCol: number,
  seed = createSeed(),
): Board {
  const rows = board.length
  const cols = board[0]?.length ?? 0
  const length = rows * cols
  const safeIndex = safeRow * cols + safeCol
  const wasm = getMinesweeperWasmSync()

  if (!wasm || cols === 0) {
    return placeMines(board, count, safeRow, safeCol)
  }

  const clone = board.map((row) => row.map((cell) => ({ ...cell, mine: false, adjacentMines: 0 })))
  for (let index = 0; index < length; index++) {
    wasm.setCell(index, 0)
  }

  const placedCount = wasm.generateMinePositions(length, count, safeIndex, seed >>> 0)

  for (let index = 0; index < placedCount; index++) {
    const mineIndex = wasm.getMinePosition(index)
    if (mineIndex < 0) {
      continue
    }

    wasm.setCell(mineIndex, MINE_BIT)
  }

  wasm.computeAdjacency(length, cols)

  for (let index = 0; index < length; index++) {
    const encoded = wasm.getCell(index)
    const row = Math.floor(index / cols)
    const col = index % cols
    clone[row][col].mine = (encoded & MINE_BIT) !== 0
    clone[row][col].adjacentMines = (encoded >> ADJACENT_SHIFT) & ADJACENT_MASK
  }

  return clone
}

import { createEmptyBoard } from '@/domain'
import { ensureWasmReady } from './aiEngine'
import { placeMinesWithEngine } from './minePlacementEngine'

describe('minePlacementEngine', () => {
  beforeAll(async () => {
    await ensureWasmReady()
  })

  it('never places a mine on the first-click safe cell', () => {
    const board = createEmptyBoard(9, 9)
    const seeded = placeMinesWithEngine(board, 10, 4, 4, 12345)

    expect(seeded[4][4].mine).toBe(false)
    expect(seeded.flat().filter((cell) => cell.mine)).toHaveLength(10)
  })

  it('produces deterministic placement for a given seed', () => {
    const board = createEmptyBoard(4, 4)
    const first = placeMinesWithEngine(board, 4, 0, 0, 77)
    const second = placeMinesWithEngine(board, 4, 0, 0, 77)

    expect(first.map((row) => row.map((cell) => cell.mine))).toEqual(
      second.map((row) => row.map((cell) => cell.mine)),
    )
  })

  it('computes adjacent mine counts as part of WASM board generation', () => {
    const board = createEmptyBoard(3, 3)
    const seeded = placeMinesWithEngine(board, 2, 1, 1, 5)

    for (let row = 0; row < seeded.length; row++) {
      for (let col = 0; col < seeded[row].length; col++) {
        const cell = seeded[row][col]
        if (cell.mine) {
          continue
        }

        let expected = 0
        for (let dr = -1; dr <= 1; dr++) {
          for (let dc = -1; dc <= 1; dc++) {
            if (dr === 0 && dc === 0) {
              continue
            }

            const nextRow = row + dr
            const nextCol = col + dc
            if (
              nextRow < 0 ||
              nextRow >= seeded.length ||
              nextCol < 0 ||
              nextCol >= seeded[row].length
            ) {
              continue
            }

            if (seeded[nextRow][nextCol].mine) {
              expected++
            }
          }
        }

        expect(cell.adjacentMines).toBe(expected)
      }
    }
  })
})

// AI / hint system for Minesweeper
import type { Board, Cell } from './types'

const HINT_STATE_HIDDEN = 0
const HINT_STATE_FLAGGED = 1
const HINT_STATE_REVEALED = 2
const HINT_STATE_MASK = 0b11
const HINT_MINE_BIT = 0b100
const HINT_ADJACENT_SHIFT = 3
const HINT_ADJACENT_MASK = 0b1111

export interface HintCell {
  row: number
  col: number
}

function encodeCell(cell: Cell): number {
  const state =
    cell.state === 'hidden'
      ? HINT_STATE_HIDDEN
      : cell.state === 'flagged'
        ? HINT_STATE_FLAGGED
        : HINT_STATE_REVEALED

  return state | (cell.mine ? HINT_MINE_BIT : 0) | (cell.adjacentMines << HINT_ADJACENT_SHIFT)
}

export function encodeBoardForHint(board: Board): Int32Array {
  const encoded = new Int32Array(board.length * (board[0]?.length ?? 0))
  let index = 0

  for (const row of board) {
    for (const cell of row) {
      encoded[index++] = encodeCell(cell)
    }
  }

  return encoded
}

export function decodeHintIndex(index: number, cols: number): HintCell | null {
  if (index < 0 || cols <= 0) {
    return null
  }

  return {
    row: Math.floor(index / cols),
    col: index % cols,
  }
}

export function findSafeCellIndexInEncodedCells(cells: ArrayLike<number>): number {
  let bestIndex = -1
  let bestAdjacent = Number.POSITIVE_INFINITY

  for (let index = 0; index < cells.length; index++) {
    const encoded = cells[index]
    const state = encoded & HINT_STATE_MASK
    const mine = (encoded & HINT_MINE_BIT) !== 0
    if (state !== HINT_STATE_HIDDEN || mine) {
      continue
    }

    const adjacent = (encoded >> HINT_ADJACENT_SHIFT) & HINT_ADJACENT_MASK
    if (adjacent < bestAdjacent) {
      bestIndex = index
      bestAdjacent = adjacent

      if (adjacent === 0) {
        return index
      }
    }
  }

  return bestIndex
}

export function findSafeCell(board: Board): HintCell | null {
  const cols = board[0]?.length ?? 0
  const index = findSafeCellIndexInEncodedCells(encodeBoardForHint(board))
  return decodeHintIndex(index, cols)
}

// Board operations: create, place mines, compute adjacency
import { DIRECTIONS } from './constants'
import type { Board, Cell } from './types'

export function createEmptyBoard(rows: number, cols: number): Board {
  return Array.from({ length: rows }, (_, row) =>
    Array.from(
      { length: cols },
      (_, col): Cell => ({
        row,
        col,
        mine: false,
        adjacentMines: 0,
        state: 'hidden',
      }),
    ),
  )
}

export function placeMines(board: Board, count: number, safeRow: number, safeCol: number): Board {
  const rows = board.length
  const cols = board[0].length
  const clone = board.map((r) => r.map((c) => ({ ...c })))
  const targetCount = Math.min(count, rows * cols - 1)
  let placed = 0
  while (placed < targetCount) {
    const r = Math.floor(Math.random() * rows)
    const c = Math.floor(Math.random() * cols)
    if (!clone[r][c].mine && !(r === safeRow && c === safeCol)) {
      clone[r][c].mine = true
      placed++
    }
  }
  return computeAdjacency(clone)
}

export function computeAdjacency(board: Board): Board {
  const rows = board.length
  const cols = board[0].length
  for (let r = 0; r < rows; r++) {
    for (let c = 0; c < cols; c++) {
      if (board[r][c].mine) {
        continue
      }
      let count = 0
      for (const [dr, dc] of DIRECTIONS) {
        const nr = r + dr,
          nc = c + dc
        if (nr >= 0 && nr < rows && nc >= 0 && nc < cols && board[nr][nc].mine) {
          count++
        }
      }
      board[r][c].adjacentMines = count
    }
  }
  return board
}

/**
 * Layer (z-index) configuration for Battleship
 * Centralizes z-index values and CSS variable generation
 */

export interface LayerConfig {
