import type { Cell, CellState } from '@/domain'
import styles from './BoardCell.module.css'

/**
 * Map cell game state to CSS module classes
 *
 * Each cell state has a corresponding visual appearance
 */
const cellStateStyles: Record<CellState, string> = {
  hidden: styles.hidden,
  flagged: styles.flagged,
  revealed: styles.empty, // Will be overridden for numbered/mine cells
}

/**
 * Map cell content to CSS module number classes
 *
 * Uses standard minesweeper color coding for numbers 1-8
 */
const numberStyles: Record<number, string> = {
  1: styles.n1,
  2: styles.n2,
  3: styles.n3,
  4: styles.n4,
  5: styles.n5,
  6: styles.n6,
  7: styles.n7,
  8: styles.n8,
}

/**
 * Generate appropriate content display for cell state
 */
function cellContent(cell: Pick<Cell, 'mine' | 'adjacentMines' | 'state'>): string {
  if (cell.state === 'flagged') {
    return '🚩'
  }

  if (cell.state === 'hidden') {
    return ''
  }

  if (cell.mine) {
    return '💣'
  }

  return cell.adjacentMines === 0 ? '' : String(cell.adjacentMines)
}

interface BoardCellProps {
  cell: Cell
  highlighted: boolean
  selected: boolean
  disabled: boolean
  cornerType?: 'top-left' | 'top-right' | 'bottom-left' | 'bottom-right' | null
  onReveal: (row: number, col: number) => void
  onToggleFlag: (event: React.MouseEvent<HTMLButtonElement>, row: number, col: number) => void
  onChord: (event: React.MouseEvent<HTMLButtonElement>, row: number, col: number) => void
}

export function BoardCell({
  cell,
  highlighted,
  selected,
  disabled,
  cornerType,
  onReveal,
  onToggleFlag,
  onChord,
}: BoardCellProps) {
  // Build class list from component state
  const classes: string[] = [styles.cell]

  // Add state-specific styling
  classes.push(cellStateStyles[cell.state])

  // Add number color coding for revealed numbered cells
  if (cell.state === 'revealed' && !cell.mine && cell.adjacentMines > 0) {
    classes.push(numberStyles[cell.adjacentMines] || '')
  }

  // Add mine styling for revealed mines
  if (cell.state === 'revealed' && cell.mine) {
    classes.push(styles.mine)
  }

  // Add selection highlight (keyboard navigation)
  if (selected) {
    classes.push(styles.selected)
  }

  // Add hint/suggestion highlight
  if (highlighted) {
    classes.push(styles.hint)
  }

  // Add corner rounding for board edges
  if (cornerType) {
    const cornerKey = `corner${cornerType
      .split('-')
      .map((part) => part.charAt(0).toUpperCase() + part.slice(1))
      .join('')}`
    classes.push(styles[cornerKey as keyof typeof styles] || '')
  }

  // Add disabled state styling
  if (disabled) {
    classes.push(styles.disabled)
  }

  const className = classes.filter(Boolean).join(' ')

  return (
    <button
      type="button"
      className={className}
      data-number={cell.state === 'revealed' && !cell.mine ? cell.adjacentMines : undefined}
      onClick={() => onReveal(cell.row, cell.col)}
      onContextMenu={(event) => onToggleFlag(event, cell.row, cell.col)}
      onDoubleClick={(event) => onChord(event, cell.row, cell.col)}
      disabled={disabled}
      aria-label={`cell-${cell.row}-${cell.col}`}
    >
      {cellContent(cell)}
    </button>
  )
}

import type { Board } from '@/domain'
import { BoardCell } from '@/ui'
import { BoardGrid, type BoardCell as SharedBoardCell } from '@games/ui-board-core'
import type { ReactNode } from 'react'

interface GameBoardProps {
  board: Board
  cols: number
  hint: { row: number; col: number } | null
  selected: { row: number; col: number }
  disabled: boolean
  onReveal: (row: number, col: number) => void
  onToggleFlag: (event: React.MouseEvent<HTMLButtonElement>, row: number, col: number) => void
  onChord: (event: React.MouseEvent<HTMLButtonElement>, row: number, col: number) => void
}

export function GameBoard({
  board,
  cols,
  hint,
  selected,
  disabled,
  onReveal,
  onToggleFlag,
  onChord,
}: GameBoardProps) {
  // Calculate rows from board
  const rows = board.length

  // Build cells array for BoardGrid
  const cells: SharedBoardCell[] = []
  for (let row = 0; row < rows; row++) {
    for (let col = 0; col < cols; col++) {
      const cell = board[row]?.[col]
      if (!cell) {continue}

      cells.push({
        position: { row, col },
        isDarkSquare: true,
        isPlayable: true,
        content: {
          type: 'custom',
          customRender: () => (
            <span className="ms-cell-content" aria-hidden="true">
              {cell.state === 'revealed' ? (
                cell.mine ? (
                  <span className="ms-mine">💣</span>
                ) : cell.adjacentMines > 0 ? (
                  <span className="ms-number">{cell.adjacentMines}</span>
                ) : null
              ) : cell.state === 'flagged' ? (
                <span className="ms-flag">🚩</span>
              ) : null}
            </span>
          ),
        },
        state: {
          selected: selected.row === row && selected.col === col,
          hint: hint ? hint.row === row && hint.col === col : false,
        },
      })
    }
  }

  // Custom cell renderer for minesweeper
  const renderCell = (
    cell: SharedBoardCell,
    isSelected: boolean,
    _isFocused: boolean,
  ): ReactNode => {
    const minesweeperCell = board[cell.position.row]?.[cell.position.col]
    if (!minesweeperCell) {return null}

    // Determine which corner this cell is (if any)
    let cornerType: 'top-left' | 'top-right' | 'bottom-left' | 'bottom-right' | null = null
    if (cell.position.row === 0 && cell.position.col === 0) {
      cornerType = 'top-left'
    } else if (cell.position.row === 0 && cell.position.col === cols - 1) {
      cornerType = 'top-right'
    } else if (cell.position.row === rows - 1 && cell.position.col === 0) {
      cornerType = 'bottom-left'
    } else if (cell.position.row === rows - 1 && cell.position.col === cols - 1) {
      cornerType = 'bottom-right'
    }

    return (
      <BoardCell
        cell={minesweeperCell}
        highlighted={cell.state?.hint ?? false}
        selected={isSelected}
        disabled={disabled}
        cornerType={cornerType}
        onReveal={onReveal}
        onToggleFlag={onToggleFlag}
        onChord={onChord}
      />
    )
  }

  return (
    <section className="ms-board">
      <BoardGrid
        rows={rows}
        cols={cols}
        cells={cells}
        selectedPosition={selected}
        renderCell={renderCell}
        ariaLabel="Minesweeper board"
      />
    </section>
  )
}

