import { useCallback, useEffect } from 'react'

import { useGridNavigationInput } from '@games/app-hook-utils'
import type { Cell } from '@/domain'

interface UseMiniSudokuInputParams {
  selectedCell: { row: number; col: number } | undefined
  editableBoard: { grid: (number | null)[][] }
  onCellSelect: (row: number, col: number) => void
  onCellChange: (row: number, col: number, value: Cell) => void
}

/**
 * Unified input handler for mini-sudoku
 * Handles grid navigation (arrows + WASD) and digit input (1-9)
 */
export const useMiniSudokuInput = ({
  selectedCell,
  editableBoard,
  onCellSelect,
  onCellChange,
}: UseMiniSudokuInputParams): void => {
  const gridSize = 4 // 4x4 sudoku

  // Grid navigation with arrow keys and WASD
  useGridNavigationInput(
    {
      onMove: (direction) => {
        if (!selectedCell) {
          onCellSelect(0, 0)
          return
        }

        let newRow = selectedCell.row
        let newCol = selectedCell.col

        if (direction === 'up') {
          newRow = Math.max(0, selectedCell.row - 1)
        } else if (direction === 'down') {
          newRow = Math.min(gridSize - 1, selectedCell.row + 1)
        } else if (direction === 'left') {
          newCol = Math.max(0, selectedCell.col - 1)
        } else if (direction === 'right') {
          newCol = Math.min(gridSize - 1, selectedCell.col + 1)
        }

        if (newRow !== selectedCell.row || newCol !== selectedCell.col) {
          onCellSelect(newRow, newCol)
        }
      },
      onCancel: () => {
        onCellSelect(-1, -1)
      },
    },
    { enabled: true, includeWasd: true, allowRepeat: false },
  )

  // Digit input (1-9 to fill cell, 0/Backspace to clear)
  useEffect(() => {
    const handleKeyDown = (event: KeyboardEvent) => {
      if (!selectedCell || selectedCell.row < 0 || selectedCell.col < 0) {
        return
      }

      // Check if cell is editable
      const isEditable =
        selectedCell.row >= 0 &&
        selectedCell.row < gridSize &&
        selectedCell.col >= 0 &&
        selectedCell.col < gridSize &&
        editableBoard.grid?.[selectedCell.row]?.[selectedCell.col] !== 0

      if (!isEditable) {
        return
      }

      const key = event.key.toLowerCase()

      // Handle digit input 1-9
      if (key >= '1' && key <= '9') {
        event.preventDefault()
        onCellChange(selectedCell.row, selectedCell.col, parseInt(key, 10) as Cell)
        return
      }

      // Handle clear (0, Backspace, Delete)
      if (key === '0' || key === 'backspace' || key === 'delete') {
        event.preventDefault()
        onCellChange(selectedCell.row, selectedCell.col, null)
        return
      }
    }

    window.addEventListener('keydown', handleKeyDown)
    return () => {
      window.removeEventListener('keydown', handleKeyDown)
    }
  }, [selectedCell, editableBoard, onCellChange, onCellSelect])
}

/**
 * Mini Sudoku AI & Hint System
 * Provides hints and estimates puzzle difficulty
 */

import { getCellsInBox, getCellsInCol, getCellsInRow } from './constants'
import { updateAllCandidates } from './rules'
import type { Board, DifficultyMetrics, Hint } from './types'
import { Difficulty } from './types'

/**
 * Hint type: candidates
 * Returns all candidates for a cell
 */
function getHint_Candidates(board: Board, cellId: string): Hint | null {
  const cell = board.get(cellId)
  if (!cell || cell.value || cell.isGiven) {
    return null
  }

  const candidates = new Set(cell.candidates)
  if (candidates.size === 0) {
    return null
  }

  return {
    type: 'candidates',
    cellId,
    candidates,
    reason: `Cell ${cellId} can be: ${Array.from(candidates).join(', ')}`,
  }
}

/**
 * Hint type: naked_single
 * Cell has exactly one candidate
 */
function getHint_NakedSingle(board: Board): Hint | null {
  for (const cell of board.values()) {
    if (cell.value || cell.isGiven) {
      continue
    }
    if (cell.candidates.size === 1) {
      const candidates = Array.from(cell.candidates)
      const value = candidates[0]
      return {
        type: 'naked_single',
        cellId: cell.id,
        value,
        reason: `Cell ${cell.id} has only one candidate: ${candidates[0]}`,
      }
    }
  }
  return null
}

/**
 * Check a group of cells for a hidden single (value that can only go in one cell)
 */
function findHiddenSingleInGroup(board: Board, cellIds: string[], regionName: string): Hint | null {
  for (const value of ['1', '2', '3', '4'] as const) {
    let count = 0
    let candidateCell: string | null = null

    for (const cellId of cellIds) {
      const cell = board.get(cellId)
      if (cell?.value === undefined && cell?.candidates.has(value)) {
        count++
        candidateCell = cellId
      }
    }

    if (count === 1 && candidateCell) {
      return {
        type: 'hidden_single',
        cellId: candidateCell,
        value,
        reason: `Value ${value} can only go in ${candidateCell} in ${regionName}`,
      }
    }
  }
  return null
}

/**
 * Hint type: hidden_single
 * Value appears in only one cell's candidates in a region
 */
function getHint_HiddenSingle(board: Board): Hint | null {
  // Check rows
  for (let row = 0; row < 4; row++) {
    const hint = findHiddenSingleInGroup(board, getCellsInRow(row), `row ${row}`)
    if (hint) {
      return hint
    }
  }

  // Check columns
  for (let col = 0; col < 4; col++) {
    const hint = findHiddenSingleInGroup(board, getCellsInCol(col), `column ${col}`)
    if (hint) {
      return hint
    }
  }

  // Check boxes
  for (let box = 0; box < 4; box++) {
    const hint = findHiddenSingleInGroup(board, getCellsInBox(box), `box ${box}`)
    if (hint) {
      return hint
    }
  }

  return null
}

/**
 * Get next hint for player
 * Uses simple techniques: candidates → naked single → hidden single
 */
export function provideHint(board: Board, cellId?: string): Hint | null {
  const boardCopy = new Map(board)
  for (const [key, cell] of boardCopy) {
    boardCopy.set(key, { ...cell, candidates: new Set(cell.candidates) })
  }
  updateAllCandidates(boardCopy)

  // If specific cell requested, return candidates for that cell
  if (cellId) {
    return getHint_Candidates(boardCopy, cellId)
  }

  // Try techniques in order of complexity
  let hint = getHint_NakedSingle(boardCopy)
  if (hint) {
    return hint
  }

  hint = getHint_HiddenSingle(boardCopy)
  if (hint) {
    return hint
  }

  // Last resort: return first cell with candidates
  for (const cell of boardCopy.values()) {
    if (!cell.value && !cell.isGiven && cell.candidates.size > 0) {
      return getHint_Candidates(boardCopy, cell.id)
    }
  }

  return null
}

/**
 * Estimate puzzle difficulty metrics
 */
export function estimateDifficulty(board: Board): DifficultyMetrics {
  const boardCopy = new Map(board)
  for (const [key, cell] of boardCopy) {
    boardCopy.set(key, { ...cell, candidates: new Set(cell.candidates) })
  }
  updateAllCandidates(boardCopy)

  // Count clues
  let clueCount = 0
  for (const cell of boardCopy.values()) {
    if (cell.isGiven) {
      clueCount++
    }
  }

  // Calculate constraint density (how constrained is the puzzle)
  let totalCandidates = 0
  let emptyCount = 0
  for (const cell of boardCopy.values()) {
    if (!cell.value) {
      totalCandidates += cell.candidates.size
      emptyCount++
    }
  }
  const averageCandidates = emptyCount > 0 ? totalCandidates / emptyCount : 0
  const constraintDensity = 1 - averageCandidates / 4 // Higher = more constrained

  // Estimate level based on clue count and constraint density
  let estimatedLevel: Difficulty
  if (clueCount <= 6) {
    estimatedLevel = Difficulty.HARD
  } else if (clueCount <= 8) {
    estimatedLevel = Difficulty.MEDIUM
  } else {
    estimatedLevel = Difficulty.EASY
  }

  return {
    estimatedLevel,
    clueCount,
    constraintDensity,
    averageCandidates,
  }
}

/**
 * Estimate solve time in milliseconds
 */
export function estimateSolveTime(board: Board): number {
  const metrics = estimateDifficulty(board)

  // Base time: 5s per clue
  let baseTime = (10 - metrics.clueCount) * 5000

  // Adjust for constraint density
  baseTime *= 1 + metrics.constraintDensity

  // Adjust for average candidates (more candidates = harder)
  baseTime *= 1 + (4 - metrics.averageCandidates) / 4

  return Math.max(5000, Math.min(120000, baseTime)) // Clamp 5-120 seconds
}

/**
 * Count how many steps of simple logic can solve
 * Useful for difficulty estimation
 */
export function countSolvableByLogic(board: Board): number {
  const boardCopy = new Map(board)
  for (const [key, cell] of boardCopy) {
    boardCopy.set(key, { ...cell, candidates: new Set(cell.candidates) })
  }

  let stepsSolved = 0

  while (true) {
    let foundHint = false

    // Try naked singles
    for (const cell of boardCopy.values()) {
      if (!cell.value && cell.candidates.size === 1) {
        const value = Array.from(cell.candidates)[0]
        cell.value = value
        cell.candidates.clear()
        foundHint = true
        stepsSolved++
        break
      }
    }

    if (!foundHint) {
      break
    }
  }

  return stepsSolved
}

/**
 * Mini Sudoku Constraints
 * CSP constraint classes for Mini Sudoku (4×4, 2×2 boxes)
 */

import { BOARD_SIZE, BOX_SIZE, getBoxIndex, parseCellId } from './constants'
import type { Board, CellValue } from './types'

/**
 * Base class for all constraints
 */
abstract class MiniSudokuConstraint {
  abstract name: string
  abstract cellIds: string[]
  abstract isSatisfied(board: Board): boolean
  abstract eliminate(cellId: string, value: CellValue, board: Board): boolean
}

/**
 * Uniqueness Constraint: No two cells in row/col/box have same value
 */
export class UniquenessConstraint extends MiniSudokuConstraint {
  name = 'Uniqueness'
  cellIds: string[]

  constructor(cellIds: string[]) {
    super()
    this.cellIds = cellIds
  }

  isSatisfied(board: Board): boolean {
    const filledValues = new Set<CellValue>()
    for (const cellId of this.cellIds) {
      const cell = board.get(cellId)
      if (cell?.value) {
        if (filledValues.has(cell.value)) {
          return false
        }
        filledValues.add(cell.value)
      }
    }
    return true
  }

  eliminate(cellId: string, value: CellValue, board: Board): boolean {
    if (!value) {
      return false
    }

    for (const otherId of this.cellIds) {
      if (otherId === cellId) {
        continue
      }
      const other = board.get(otherId)
      if (other?.value === value) {
        return true // Conflict detected
      }
    }
    return false
  }
}

/**
 * Row Uniqueness: All values in a row must be unique
 */
export class RowUniquenessConstraint extends UniquenessConstraint {
  constructor(row: number) {
    const cellIds = []
    for (let col = 0; col < BOARD_SIZE; col++) {
      cellIds.push(`r${row}c${col}`)
    }
    super(cellIds)
  }
}

/**
 * Column Uniqueness: All values in a column must be unique
 */
export class ColUniquenessConstraint extends UniquenessConstraint {
  constructor(col: number) {
    const cellIds = []
    for (let row = 0; row < BOARD_SIZE; row++) {
      cellIds.push(`r${row}c${col}`)
    }
    super(cellIds)
  }
}

/**
 * Box Uniqueness: All values in a 2×2 box must be unique
 */
export class BoxUniquenessConstraint extends UniquenessConstraint {
  constructor(boxIndex: number) {
    const cellIds = []
    const startRow = Math.floor(boxIndex / BOX_SIZE) * BOX_SIZE
    const startCol = (boxIndex % BOX_SIZE) * BOX_SIZE

    for (let r = startRow; r < startRow + BOX_SIZE; r++) {
      for (let c = startCol; c < startCol + BOX_SIZE; c++) {
        cellIds.push(`r${r}c${c}`)
      }
    }
    super(cellIds)
  }
}

/**
 * Value Range Constraint: All cells have values 1-4
 */
export class ValueRangeConstraint extends MiniSudokuConstraint {
  name = 'ValueRange'
  cellIds: string[]

  constructor(cellId: string) {
    super()
    this.cellIds = [cellId]
  }

  isSatisfied(board: Board): boolean {
    const cell = board.get(this.cellIds[0])
    if (!cell?.value) {
      return true
    }
    return ['1', '2', '3', '4'].includes(cell.value)
  }

  eliminate(_cellId: string, value: CellValue): boolean {
    // This constraint allows only 1-4, so any other value is invalid
    return !['1', '2', '3', '4'].includes(value)
  }
}

/**
 * Factory: Create all CSP constraints for Mini Sudoku
 */
export function createAllConstraints(): MiniSudokuConstraint[] {
  const constraints: MiniSudokuConstraint[] = []

  // Row uniqueness
  for (let row = 0; row < BOARD_SIZE; row++) {
    constraints.push(new RowUniquenessConstraint(row))
  }

  // Column uniqueness
  for (let col = 0; col < BOARD_SIZE; col++) {
    constraints.push(new ColUniquenessConstraint(col))
  }

  // Box uniqueness (4 boxes in 4×4)
  for (let box = 0; box < BOARD_SIZE; box++) {
    constraints.push(new BoxUniquenessConstraint(box))
  }

  // Value range per cell
  for (let row = 0; row < BOARD_SIZE; row++) {
    for (let col = 0; col < BOARD_SIZE; col++) {
      constraints.push(new ValueRangeConstraint(`r${row}c${col}`))
    }
  }

  return constraints
}

/**
 * Get all constraints affecting a specific cell
 */
export function getConstraintsForCell(cellId: string): MiniSudokuConstraint[] {
  const { row, col } = parseCellId(cellId)
  const boxIndex = getBoxIndex(row, col)

  return [
    new RowUniquenessConstraint(row),
    new ColUniquenessConstraint(col),
    new BoxUniquenessConstraint(boxIndex),
    new ValueRangeConstraint(cellId),
  ]
}

/**
 * Validate that a board satisfies all constraints
 */
export function validateBoard(board: Board): boolean {
  const constraints = createAllConstraints()
  return constraints.every((c) => c.isSatisfied(board))
}

/**
 * Mini Sudoku Validation Rules
 * Core game logic: move validation, conflict detection, completion checks
 */

import { getBoxIndex, getCellsInBox, getCellsInCol, getCellsInRow, parseCellId } from './constants'
import { createPuzzleAtDifficulty } from './templates'
import type { Board, CellConflict, CellValue, Difficulty, MiniSudokuState } from './types'

/**
 * Check if a value assignment is valid (no conflicts)
 */
export function isValidMove(board: Board, cellId: string, value: CellValue): boolean {
  if (!value) {
    return true
  } // Clearing is always valid

  const cell = board.get(cellId)
  if (!cell || cell.isGiven) {
    return false
  } // Can't move given cell

  const { row, col } = parseCellId(cellId)

  // Check uniqueness in row, column, and box
  return (
    isValueUniqueInRow(board, row, cellId, value) &&
    isValueUniqueInCol(board, col, cellId, value) &&
    isValueUniqueInBox(board, row, col, cellId, value)
  )
}

/**
 * Check if value is unique in the given row (excluding the current cell)
 */
function isValueUniqueInRow(
  board: Board,
  row: number,
  excludeCellId: string,
  value: CellValue,
): boolean {
  for (const otherCellId of getCellsInRow(row)) {
    if (otherCellId !== excludeCellId) {
      const other = board.get(otherCellId)
      if (other?.value === value) {
        return false
      }
    }
  }
  return true
}

/**
 * Check if value is unique in the given column (excluding the current cell)
 */
function isValueUniqueInCol(
  board: Board,
  col: number,
  excludeCellId: string,
  value: CellValue,
): boolean {
  for (const otherCellId of getCellsInCol(col)) {
    if (otherCellId !== excludeCellId) {
      const other = board.get(otherCellId)
      if (other?.value === value) {
        return false
      }
    }
  }
  return true
}

/**
 * Check if value is unique in the box containing the given cell (excluding the current cell)
 */
function isValueUniqueInBox(
  board: Board,
  row: number,
  col: number,
  excludeCellId: string,
  value: CellValue,
): boolean {
  const boxIndex = getBoxIndex(row, col)
  for (const otherCellId of getCellsInBox(boxIndex)) {
    if (otherCellId !== excludeCellId) {
      const other = board.get(otherCellId)
      if (other?.value === value) {
        return false
      }
    }
  }
  return true
}

/**
 * Find conflicting cells in a row for a given value
 */
function findConflictsInRow(board: Board, cellId: string, value: CellValue, row: number): string[] {
  const conflicts: string[] = []
  for (const otherId of getCellsInRow(row)) {
    if (otherId !== cellId) {
      const other = board.get(otherId)
      if (other?.value === value) {
        conflicts.push(otherId)
      }
    }
  }
  return conflicts
}

/**
 * Find conflicting cells in a column for a given value
 */
function findConflictsInCol(board: Board, cellId: string, value: CellValue, col: number): string[] {
  const conflicts: string[] = []
  for (const otherId of getCellsInCol(col)) {
    if (otherId !== cellId) {
      const other = board.get(otherId)
      if (other?.value === value) {
        conflicts.push(otherId)
      }
    }
  }
  return conflicts
}

/**
 * Find conflicting cells in a box for a given value
 */
function findConflictsInBox(
  board: Board,
  cellId: string,
  value: CellValue,
  boxIndex: number,
): string[] {
  const conflicts: string[] = []
  for (const otherId of getCellsInBox(boxIndex)) {
    if (otherId !== cellId) {
      const other = board.get(otherId)
      if (other?.value === value) {
        conflicts.push(otherId)
      }
    }
  }
  return conflicts
}

/**
 * Get all cells that conflict with assigning value to cellId
 */
export function getConflictingCells(
  board: Board,
  cellId: string,
  value: CellValue,
): CellConflict[] {
  if (!value) {
    return []
  } // No conflicts when clearing

  const conflicts: CellConflict[] = []
  const { row, col } = parseCellId(cellId)
  const boxIndex = getBoxIndex(row, col)

  // Row conflicts
  const rowConflicts = findConflictsInRow(board, cellId, value, row)
  if (rowConflicts.length > 0) {
    conflicts.push({
      cellId,
      conflictingCellIds: rowConflicts,
      reason: 'row',
    })
  }

  // Column conflicts
  const colConflicts = findConflictsInCol(board, cellId, value, col)
  if (colConflicts.length > 0) {
    conflicts.push({
      cellId,
      conflictingCellIds: colConflicts,
      reason: 'col',
    })
  }

  // Box conflicts
  const boxConflicts = findConflictsInBox(board, cellId, value, boxIndex)
  if (boxConflicts.length > 0) {
    conflicts.push({
      cellId,
      conflictingCellIds: boxConflicts,
      reason: 'box',
    })
  }

  return conflicts
}

/**
 * Check if puzzle is complete (all cells filled)
 */
export function isComplete(board: Board): boolean {
  for (const cell of board.values()) {
    if (!cell.value) {
      return false
    }
  }
  return true
}

/**
 * Check if a row is valid (all cells filled, no duplicates)
 */
function isRowValid(board: Board, row: number): boolean {
  const values = new Set<CellValue>()
  for (const cellId of getCellsInRow(row)) {
    const cell = board.get(cellId)
    if (!cell?.value) {
      return false
    }
    if (values.has(cell.value)) {
      return false
    }
    values.add(cell.value)
  }
  return values.size === 4
}

/**
 * Check if a column is valid (all cells filled, no duplicates)
 */
function isColValid(board: Board, col: number): boolean {
  const values = new Set<CellValue>()
  for (const cellId of getCellsInCol(col)) {
    const cell = board.get(cellId)
    if (!cell?.value) {
      return false
    }
    if (values.has(cell.value)) {
      return false
    }
    values.add(cell.value)
  }
  return values.size === 4
}

/**
 * Check if a box is valid (all cells filled, no duplicates)
 */
function isBoxValid(board: Board, box: number): boolean {
  const values = new Set<CellValue>()
  for (const cellId of getCellsInBox(box)) {
    const cell = board.get(cellId)
    if (!cell?.value) {
      return false
    }
    if (values.has(cell.value)) {
      return false
    }
    values.add(cell.value)
  }
  return values.size === 4
}

/**
 * Check if puzzle is solved (complete and valid)
 */
export function isSolved(board: Board): boolean {
  if (!isComplete(board)) {
    return false
  }

  // Verify all rows are valid
  for (let row = 0; row < 4; row++) {
    if (!isRowValid(board, row)) {
      return false
    }
  }

  // Verify all columns are valid
  for (let col = 0; col < 4; col++) {
    if (!isColValid(board, col)) {
      return false
    }
  }

  // Verify all boxes are valid
  for (let box = 0; box < 4; box++) {
    if (!isBoxValid(board, box)) {
      return false
    }
  }

  return true
}

/**
 * Count empty cells
 */
export function countEmpty(board: Board): number {
  let count = 0
  for (const cell of board.values()) {
    if (!cell.value) {
      count++
    }
  }
  return count
}

/**
 * Get all cells in a given region (row, col, or box)
 */
export function getCellsInRegion(regionType: 'row' | 'col' | 'box', index: number): string[] {
  switch (regionType) {
    case 'row':
      return getCellsInRow(index)
    case 'col':
      return getCellsInCol(index)
    case 'box':
      return getCellsInBox(index)
  }
}

/**
 * Update cell candidates based on current board state
 */
export function updateCellCandidates(board: Board, cellId: string): void {
  const cell = board.get(cellId)
  if (!cell || cell.value || cell.isGiven) {
    return
  }

  const { row, col } = parseCellId(cellId)
  const boxIndex = getBoxIndex(row, col)

  // Start with all values possible
  cell.candidates = new Set(['1', '2', '3', '4'])

  // Remove values that appear in same row
  for (const otherId of getCellsInRow(row)) {
    const other = board.get(otherId)
    if (other?.value) {
      cell.candidates.delete(other.value)
    }
  }

  // Remove values that appear in same column
  for (const otherId of getCellsInCol(col)) {
    const other = board.get(otherId)
    if (other?.value) {
      cell.candidates.delete(other.value)
    }
  }

  // Remove values that appear in same box
  for (const otherId of getCellsInBox(boxIndex)) {
    const other = board.get(otherId)
    if (other?.value) {
      cell.candidates.delete(other.value)
    }
  }
}

/**
 * Update all cell candidates in the board
 */
export function updateAllCandidates(board: Board): void {
  for (const cellId of board.keys()) {
    updateCellCandidates(board, cellId)
  }
}

/**
 * Get candidates for a specific cell
 */
export function getCellCandidates(board: Board, cellId: string): Set<CellValue> {
  const cell = board.get(cellId)
  if (!cell) {
    return new Set()
  }
  if (cell.value) {
    return new Set()
  }
  return new Set(cell.candidates)
}

/**
 * Calculate elapsed game time in seconds
 */
export function calculateGameTime(startTime: number): number {
  return Math.floor((Date.now() - startTime) / 1000)
}

/**
 * Create a new game state for the given difficulty
 */
export function createGameState(difficulty: Difficulty): MiniSudokuState {
  const board = createPuzzleAtDifficulty(difficulty)
  return {
    id: `puzzle-${Date.now()}`,
    board,
    difficulty,
    isComplete: false,
    isSolved: false,
    moveCount: 0,
    startTime: Date.now(),
    hintCount: 0,
    mistakes: 0,
  }
}

/**
 * Check if the game is complete (all cells filled)
 */
export function isGameComplete(gameState: MiniSudokuState): boolean {
  return isComplete(gameState.board)
}

/**
 * Make a move on the game state
 */
export function makeMove(
  gameState: MiniSudokuState,
  row: number,
  col: number,
  value: CellValue,
): MiniSudokuState {
  const cellId = `r${row}c${col}`
  const cell = gameState.board.get(cellId)

  if (!cell || cell.isGiven) {
    return gameState // Invalid move, return unchanged state
  }

  // Create new board with the move
  const newBoard = new Map(gameState.board)
  const newCell = { ...cell, value }
  newBoard.set(cellId, newCell)

  // Update candidates for affected cells
  updateAllCandidates(newBoard)

  return {
    ...gameState,
    board: newBoard,
    moveCount: gameState.moveCount + (value ? 1 : 0), // Only count non-empty moves
    isComplete: isComplete(newBoard),
    isSolved: isSolved(newBoard),
  }
}

/**
 * Mini Sudoku CSP Templates
 * Creates CSP (Constraint Satisfaction Problem) objects for solver & generator
 */

import { generateSudokuPuzzle, type SudokuConfig } from '@games/domain-shared'
import { ALL_CELL_IDS, BOARD_SIZE, DEFAULT_CANDIDATES } from './constants'
import { createAllConstraints } from './constraints'
import type { Board, Cell, CellValue, Difficulty } from './types'

// Mini Sudoku 4x4 configuration
const MINI_SUDOKU_CONFIG: SudokuConfig = {
  boardSize: 4,
  boxSize: 2,
  emptyCell: 0,
}

/**
 * Create empty board (all cells blank, no candidates)
 */
export function createEmptyBoard(): Board {
  const board = new Map<string, Cell>()

  for (let row = 0; row < BOARD_SIZE; row++) {
    for (let col = 0; col < BOARD_SIZE; col++) {
      const cellId = `r${row}c${col}`
      const box = Math.floor(row / 2) * 2 + Math.floor(col / 2)

      board.set(cellId, {
        id: cellId,
        row,
        col,
        box,
        value: '',
        candidates: new Set(DEFAULT_CANDIDATES),
        isGiven: false,
      })
    }
  }

  return board
}

/**
 * Create a full valid solution board
 * Returns a generated valid 4×4 sudoku
 */
export function createSolvedBoard(): Board {
  const solution = generateSudokuPuzzle(MINI_SUDOKU_CONFIG, 'easy').solution

  const board = createEmptyBoard()

  // Fill all cells from the solution
  for (let row = 0; row < BOARD_SIZE; row++) {
    for (let col = 0; col < BOARD_SIZE; col++) {
      const cellId = `r${row}c${col}`
      const value = solution.grid[row][col]

      const cell = board.get(cellId)!
      cell.value = value.toString() as CellValue
      cell.candidates.clear()
    }
  }

  return board
}

/**
 * Calculate clue count based on difficulty level
 */
function getClueCountForDifficulty(difficulty: Difficulty): number {
  switch (difficulty) {
    case 'EASY':
      return 9 + Math.floor(Math.random() * 2) // 9-10 clues
    case 'MEDIUM':
      return 7 + Math.floor(Math.random() * 2) // 7-8 clues
    case 'HARD':
    default:
      return 5 + Math.floor(Math.random() * 2) // 5-6 clues
  }
}

/**
 * Create puzzle from a solved board by revealing clues
 */
function createPuzzleFromSolution(solved: Board, clueCount: number): Board {
  const puzzle = new Map(solved)
  const allCells = Array.from(puzzle.values())
  const cellsToKeep = new Set<string>()

  // Randomly select cells to keep as clues
  let kept = 0
  for (const cell of allCells) {
    if (kept >= clueCount) {break}
    if (Math.random() < clueCount / allCells.length) {
      cellsToKeep.add(cell.id)
      kept++
    }
  }

  // Clear non-clue cells
  for (const cell of puzzle.values()) {
    if (!cellsToKeep.has(cell.id)) {
      cell.value = ''
      cell.isGiven = false
      cell.candidates = new Set(DEFAULT_CANDIDATES)
    }
  }

  return puzzle
}

/**
 * Create puzzle at specific difficulty level
 */
export function createPuzzleAtDifficulty(difficulty: Difficulty): Board {
  const solved = createSolvedBoard()
  const clueCount = getClueCountForDifficulty(difficulty)
  return createPuzzleFromSolution(solved, clueCount)
}

/**
 * Create CSP representation: board with all constraints defined
 * Used by solver to work with puzzle
 */
export interface MiniSudokuCSP {
  board: Board
  constraints: ReturnType<typeof createAllConstraints>
  variables: string[] // Cell IDs
  domain: Map<string, Set<string>> // cellId -> possible values
}

/**
 * Create CSP from puzzle board
 */
export function createCSP(puzzle: Board): MiniSudokuCSP {
  const domain = new Map<string, Set<string>>()

  // Initialize domain for each cell
  for (const cellId of ALL_CELL_IDS) {
    const cell = puzzle.get(cellId)
    if (!cell) {
      continue
    }
    if (cell.value) {
      domain.set(cellId, new Set([cell.value]))
    } else {
      domain.set(cellId, new Set(DEFAULT_CANDIDATES))
    }
  }

  return {
    board: puzzle,
    constraints: createAllConstraints(),
    variables: [...ALL_CELL_IDS],
    domain,
  }
}

/**
 * Clone a puzzle board (deep copy)
 */
export function clonePuzzle(board: Board): Board {
  const cloned = new Map<string, Cell>()
  for (const [cellId, cell] of board) {
    cloned.set(cellId, {
      ...cell,
      candidates: new Set(cell.candidates),
    })
  }
  return cloned
}

/**
 * Count clues (given/locked cells)
 */
export function countClues(board: Board): number {
  let count = 0
  for (const cell of board.values()) {
    if (cell.isGiven) {
      count++
    }
  }
  return count
}

/**
 * Count filled cells
 */
export function countFilled(board: Board): number {
  let count = 0
  for (const cell of board.values()) {
    if (cell.value) {
      count++
    }
  }
  return count
}

