  const isEditable = (row: number, col: number): boolean => {
    if (row < 0 || row >= 4 || col < 0 || col >= 4) {
      return false
    }
    const grid = editableBoard?.grid
    if (!Array.isArray(grid)) {return false}
    const rowArr = grid[row]
