import { useCallback, useReducer } from 'react'

// ─── Types ────────────────────────────────────────────────────────────────────

export type Player = 'human' | 'cpu'
export type GamePhase = 'idle' | 'playing' | 'game-over'

export interface MoncholaBoard {
  cells: number[]
  size: number
}

export interface MoncholaGameState {
  phase: GamePhase
  board: MoncholaBoard
  currentPlayer: Player
  humanScore: number
  cpuScore: number
  winner: Player | 'draw' | null
  turnCount: number
}

function createBoard(size = 9): MoncholaBoard {
  return { cells: Array(size).fill(0), size }
}

function createInitialState(): MoncholaGameState {
  return {
    phase: 'idle',
    board: createBoard(),
    currentPlayer: 'human',
    humanScore: 0,
    cpuScore: 0,
    winner: null,
    turnCount: 0,
  }
}

function isPlayableCell(cells: number[], cellIndex: number): boolean {
  return Number.isInteger(cellIndex) && cellIndex >= 0 && cellIndex < cells.length
}

// ─── Reducer ─────────────────────────────────────────────────────────────────

type GameAction =
  | { type: 'START' }
  | { type: 'MAKE_MOVE'; cellIndex: number }
  | { type: 'CPU_MOVE' }
  | { type: 'RESET' }

function checkWinner(state: MoncholaGameState): Player | 'draw' | null {
  // Monchola: player with most points when board is full wins
  if (state.board.cells.every((c) => c !== 0)) {
    if (state.humanScore > state.cpuScore) {
      return 'human'
    }
    if (state.cpuScore > state.humanScore) {
      return 'cpu'
    }
    return 'draw'
  }
  return null
}

function reducer(state: MoncholaGameState, action: GameAction): MoncholaGameState {
  switch (action.type) {
    case 'START':
      return { ...createInitialState(), phase: 'playing' }

    case 'MAKE_MOVE': {
      if (state.phase !== 'playing' || state.currentPlayer !== 'human') {
        return state
      }
      if (!isPlayableCell(state.board.cells, action.cellIndex)) {
        return state
      }
      if (state.board.cells.slice(action.cellIndex, action.cellIndex + 1)[0] !== 0) {
        return state
      }

      const newCells = [...state.board.cells]
      newCells.splice(action.cellIndex, 1, 1) // human mark
      const newHumanScore = state.humanScore + 1
      const newState: MoncholaGameState = {
        ...state,
        board: { ...state.board, cells: newCells },
        humanScore: newHumanScore,
        currentPlayer: 'cpu',
        turnCount: state.turnCount + 1,
      }
      const winner = checkWinner(newState)
      return { ...newState, winner, phase: winner ? 'game-over' : 'playing' }
    }

    case 'CPU_MOVE': {
      if (state.phase !== 'playing' || state.currentPlayer !== 'cpu') {
        return state
      }
      const emptyCells = state.board.cells.map((v, i) => (v === 0 ? i : -1)).filter((i) => i !== -1)
      if (emptyCells.length === 0) {
        return state
      }

      const pick = emptyCells[Math.floor(Math.random() * emptyCells.length)]
      if (!isPlayableCell(state.board.cells, pick)) {
        return state
      }
      const newCells = [...state.board.cells]
      newCells.splice(pick, 1, 2) // cpu mark
      const newCpuScore = state.cpuScore + 1
      const newState: MoncholaGameState = {
        ...state,
        board: { ...state.board, cells: newCells },
        cpuScore: newCpuScore,
        currentPlayer: 'human',
        turnCount: state.turnCount + 1,
      }
      const winner = checkWinner(newState)
      return { ...newState, winner, phase: winner ? 'game-over' : 'playing' }
    }

    case 'RESET':
      return createInitialState()

    default:
      return state
  }
}

// ─── Hook ────────────────────────────────────────────────────────────────────

export interface UseGameReturn {
  gameState: MoncholaGameState
  isGameOver: boolean
  start: () => void
  makeMove: (cellIndex: number) => void
  cpuMove: () => void
  reset: () => void
}

export function useGame(): UseGameReturn {
  const [state, dispatch] = useReducer(reducer, undefined, createInitialState)

  const start = useCallback(() => dispatch({ type: 'START' }), [])
  const makeMove = useCallback(
    (cellIndex: number) => dispatch({ type: 'MAKE_MOVE', cellIndex }),
    [],
  )
  const cpuMove = useCallback(() => dispatch({ type: 'CPU_MOVE' }), [])
  const reset = useCallback(() => dispatch({ type: 'RESET' }), [])

  return {
    gameState: state,
    isGameOver: state.phase === 'game-over',
    start,
    makeMove,
    cpuMove,
    reset,
  }
}

/**
 * Monchola — Domain Board Operations
 * Pure functions for creating and manipulating the game board.
 * No React, no DOM — purely functional transformations.
 */

import type { CellOwner, GameState, MoncholaBoard, Player } from './types'

export const DEFAULT_BOARD_SIZE = 9

/**
 * Create a fresh empty board.
 */
export function createBoard(size: number = DEFAULT_BOARD_SIZE): MoncholaBoard {
  return {
    cells: Array<CellOwner>(size).fill(0),
    size,
  }
}

/**
 * Create the initial game state.
 */
export function createInitialState(): GameState {
  return {
    phase: 'idle',
    board: createBoard(),
    currentPlayer: 'human',
    humanScore: 0,
    cpuScore: 0,
    winner: null,
    turnCount: 0,
  }
}

/**
 * Apply a move for the given player at the given cell index.
 * Returns a new state — never mutates.
 */
export function applyMove(state: GameState, cellIndex: number, player: Player): GameState {
  if (state.phase !== 'playing') {
    return state
  }
  if (!Number.isInteger(cellIndex) || cellIndex < 0 || cellIndex >= state.board.cells.length) {
    return state
  }
  if (state.board.cells.slice(cellIndex, cellIndex + 1)[0] !== 0) {
    return state
  }

  const mark: CellOwner = player === 'human' ? 1 : 2
  const newCells = [...state.board.cells] as CellOwner[]
  newCells.splice(cellIndex, 1, mark)

  const newHumanScore = player === 'human' ? state.humanScore + 1 : state.humanScore
  const newCpuScore = player === 'cpu' ? state.cpuScore + 1 : state.cpuScore
  const nextPlayer: Player = player === 'human' ? 'cpu' : 'human'

  return {
    ...state,
    board: { ...state.board, cells: newCells },
    humanScore: newHumanScore,
    cpuScore: newCpuScore,
    currentPlayer: nextPlayer,
    turnCount: state.turnCount + 1,
  }
}

/**
 * Get all empty cell indices.
 */
export function getEmptyCells(board: MoncholaBoard): number[] {
  return board.cells.map((v, i) => (v === 0 ? i : -1)).filter((i) => i !== -1)
}

/**
 * Monchola — Domain Rules
 * Win/loss/draw detection and game state queries.
 * Pure functions operating on domain types only.
 */

import { getEmptyCells } from './board'
import type { GameState, MoncholaBoard, Player } from './types'

/**
 * Check if the board is completely filled.
 */
export function isBoardFull(board: MoncholaBoard): boolean {
  return board.cells.every((c) => c !== 0)
}

/**
 * Determine the winner when the board is full.
 * The player with the most claimed cells wins.
 */
export function getWinner(state: GameState): Player | 'draw' | null {
  if (!isBoardFull(state.board)) {
    return null
  }

  if (state.humanScore > state.cpuScore) {
    return 'human'
  }
  if (state.cpuScore > state.humanScore) {
    return 'cpu'
  }
  return 'draw'
}

/**
 * Check if the game is over.
 */
export function isGameOver(state: GameState): boolean {
  return state.phase === 'game-over' || isBoardFull(state.board)
}

/**
 * Pick a random CPU move (basic AI).
 */
export function selectCpuMove(state: GameState): number | null {
  const empty = getEmptyCells(state.board)
  if (empty.length === 0) {
    return null
  }
  return empty[Math.floor(Math.random() * empty.length)]
}

/**
 * Return the lead margin (positive = human leading, negative = cpu leading).
 */
export function getLeadMargin(state: GameState): number {
  return state.humanScore - state.cpuScore
}

