  }

  const next = {
    ...state,
    score: state.score + 15,
    progress: state.progress + 7,
    intensity: clamp(state.intensity + 7, 0, 100),
    focus: clamp(state.focus - 6, 0, 100),
    status: 'Chain Hop high-risk burst',
  }
  return withGameOverCheck(next)
}

