/**
 * Cross-platform app lifecycle management
 * Handle pause, resume, and app exit across Capacitor, Electron, and Web
 */

import { useEffect } from 'react'
import { usePlatform } from './usePlatform'
import { useAppLifecycle as useCapacitorLifecycle } from './useCapacitor'

interface LifecycleCallbacks {
  onPause?: () => void
  onResume?: () => void
  onBeforeUnload?: () => void
}

/**
 * useAppLifecycle - Listen to app lifecycle events across platforms
 *
 * - Capacitor (Android/iOS): pause/resume/backButton events
 * - Electron: window-all-closed, before-quit events (via IPC)
 * - Web: beforeunload, visibilitychange events
 *
 * Example:
 *   const { onPause, onResume } = useAppLifecycle()
 *   useAppLifecycle({ onPause, onResume, onBeforeUnload })
 */
export const useAppLifecycle = (callbacks: LifecycleCallbacks = {}) => {
  const { platform, isCapacitor, isElectron, isWeb } = usePlatform()
  const capacitorLifecycle = useCapacitorLifecycle()

  useEffect(() => {
    const cleanups: (() => void)[] = []

    if (isCapacitor) {
      // Capacitor: Use native lifecycle listeners (async, wrapped in promises)
      if (callbacks.onPause) {
        capacitorLifecycle.onPause(callbacks.onPause).then((handle) => {
          cleanups.push(() => handle?.remove?.())
        }).catch(() => {
          // Listener failed to attach, continue gracefully
        })
      }
      if (callbacks.onResume) {
        capacitorLifecycle.onResume(callbacks.onResume).then((handle) => {
          cleanups.push(() => handle?.remove?.())
        }).catch(() => {
          // Listener failed to attach, continue gracefully
        })
      }
    } else if (isElectron) {
      // Electron: Use IPC to listen for window/app events
      const ipc = (window as any).electron?.ipcRenderer

      if (ipc && callbacks.onPause) {
        ipc.on('app:pause', callbacks.onPause)
        cleanups.push(() => ipc.off('app:pause', callbacks.onPause))
      }

      if (ipc && callbacks.onResume) {
        ipc.on('app:resume', callbacks.onResume)
        cleanups.push(() => ipc.off('app:resume', callbacks.onResume))
      }

      if (ipc && callbacks.onBeforeUnload) {
        ipc.on('app:before-quit', callbacks.onBeforeUnload)
        cleanups.push(() => ipc.off('app:before-quit', callbacks.onBeforeUnload))
      }
    } else {
      // Web: Use standard browser events
      const handleBeforeUnload = () => callbacks.onBeforeUnload?.()

      const handleVisibilityChange = () => {
        if (document.hidden) {
          callbacks.onPause?.()
        } else {
          callbacks.onResume?.()
        }
      }

      if (callbacks.onBeforeUnload) {
        window.addEventListener('beforeunload', handleBeforeUnload)
        cleanups.push(() => window.removeEventListener('beforeunload', handleBeforeUnload))
      }

      if (callbacks.onPause || callbacks.onResume) {
        document.addEventListener('visibilitychange', handleVisibilityChange)
        cleanups.push(() =>
          document.removeEventListener('visibilitychange', handleVisibilityChange),
        )
      }
    }

    return () => {
      cleanups.forEach((cleanup) => cleanup())
    }
  }, [isCapacitor, isElectron, isWeb, callbacks, capacitorLifecycle])

  return { platform, isPaused: false }
}

/**
 * useAppPauseResume - Simple wrapper for pause/resume callbacks
 *
 * Example:
 *   useAppPauseResume(
 *     () => { console.log('App paused') },
 *     () => { console.log('App resumed') }
 *   )
 */
export const useAppPauseResume = (onPause?: () => void, onResume?: () => void) => {
  useAppLifecycle({ onPause, onResume })
}

/**
 * useAppBeforeUnload - Hook for cleanup before app closes
 *
 * Example:
 *   useAppBeforeUnload(() => {
 *     console.log('Saving game state...')
 *     saveGameState()
 *   })
 */
export const useAppBeforeUnload = (callback: () => void) => {
  useAppLifecycle({ onBeforeUnload: callback })
}

/**
 * useDarkMode — Convenience hook for dark mode toggling.
 *
 * Wraps useTheme to provide a simpler API for apps that just need light/dark mode.
 *
 * Usage:
 *   const [isDarkMode, setDarkMode] = useDarkMode()
 *
 *   <button onClick={() => setDarkMode(!isDarkMode)}>Toggle Dark</button>
 */

import { useCallback } from 'react'

import { useTheme } from './useTheme'

export function useDarkMode(): [boolean, (isDark: boolean) => void] {
  const theme = useTheme()

  const isDarkMode = theme.settings.mode === 'dark'

  const setDarkMode = useCallback(
    (isDark: boolean) => {
      theme.setMode(isDark ? 'dark' : 'light')
    },
    [theme],
  )

  return [isDarkMode, setDarkMode]
}

/**
 * Cross-platform game persistence
 * Saves/loads game state to native storage (Capacitor), IndexedDB, or localStorage
 */

import { useCallback } from 'react'
import { usePlatform } from './usePlatform'
import { useCapacitorStorage } from './useCapacitor'
import type { GameState } from '@/domain'

interface GamePersistence {
  saveGame: (state: GameState) => Promise<void>
  loadGame: () => Promise<GameState | null>
  deleteGame: () => Promise<void>
}

const GAME_STATE_KEY = 'nim-game-state'

/**
 * useGamePersistence - Save/load game state across platforms
 *
 * - Capacitor (Android/iOS): Native Preferences storage
 * - Electron: localStorage (with fs fallback available via IPC)
 * - Web: localStorage + IndexedDB fallback
 *
 * Auto-saves game state on every render; can also be called manually
 */
export const useGamePersistence = (): GamePersistence => {
  const { isCapacitor, isElectron } = usePlatform()
  const capacitorStorage = useCapacitorStorage()

  // Electron IPC helpers (no-op if not Electron)
  const electronSave = useCallback(async (key: string, data: string) => {
    if (!isElectron) {return}
    try {
      const ipc = (window as any).electron?.ipcRenderer
      if (ipc) {
        await ipc.invoke('persist:save', { key, data })
      }
    } catch (err) {
      console.warn('Electron persist save failed, falling back to localStorage:', err)
      localStorage.setItem(key, data)
    }
  }, [isElectron])

  const electronLoad = useCallback(async (key: string): Promise<string | null> => {
    if (!isElectron) {return null}
    try {
      const ipc = (window as any).electron?.ipcRenderer
      if (ipc) {
        return await ipc.invoke('persist:load', { key })
      }
    } catch (err) {
      console.warn('Electron persist load failed, falling back to localStorage:', err)
      return localStorage.getItem(key)
    }
    return null
  }, [isElectron])

  const saveGame = useCallback(
    async (state: GameState) => {
      const serialized = JSON.stringify(state)

      if (isCapacitor) {
        // Native Capacitor storage (Preferences)
        await capacitorStorage.setItem(GAME_STATE_KEY, serialized)
      } else if (isElectron) {
        // Electron: use IPC to save to filesystem, fallback to localStorage
        await electronSave(GAME_STATE_KEY, serialized)
      } else {
        // Web: localStorage + IndexedDB fallback
        try {
          localStorage.setItem(GAME_STATE_KEY, serialized)
          // Optional: Also save to IndexedDB for larger data
          try {
            const objectStore = await openIndexedDB()
            await new Promise<void>((resolve, reject) => {
              const request = objectStore.put({ key: GAME_STATE_KEY, data: serialized })
              request.onerror = () => reject(request.error)
              request.onsuccess = () => resolve()
            })
          } catch (e) {
            console.warn('IndexedDB save failed:', e)
          }
        } catch (err) {
          console.error('Game state save failed:', err)
        }
      }
    },
    [isCapacitor, isElectron, capacitorStorage, electronSave],
  )

  const loadGame = useCallback(async (): Promise<GameState | null> => {
    try {
      let serialized: string | null = null

      if (isCapacitor) {
        // Native Capacitor storage
        serialized = await capacitorStorage.getItem(GAME_STATE_KEY)
      } else if (isElectron) {
        // Electron: load from IPC (fs), fallback to localStorage
        serialized = await electronLoad(GAME_STATE_KEY)
      } else {
        // Web: try localStorage first, then IndexedDB
        serialized = localStorage.getItem(GAME_STATE_KEY)
        if (!serialized) {
          try {
            const objectStore = await openIndexedDB()
            const item = await new Promise<{ key: string; data: string } | undefined>(
              (resolve, reject) => {
                const request = objectStore.get(GAME_STATE_KEY)
                request.onerror = () => reject(request.error)
                request.onsuccess = () => resolve(request.result)
              },
            )
            if (item) {
              serialized = item.data
            }
          } catch (e) {
            console.warn('IndexedDB load failed:', e)
          }
        }
      }

      return serialized ? JSON.parse(serialized) : null
    } catch (err) {
      console.error('Game state load failed:', err)
      return null
    }
  }, [isCapacitor, isElectron, capacitorStorage, electronLoad])

  const deleteGame = useCallback(async () => {
    if (isCapacitor) {
      await capacitorStorage.removeItem(GAME_STATE_KEY)
    } else if (isElectron) {
      try {
        const ipc = (window as any).electron?.ipcRenderer
        if (ipc) {
          await ipc.invoke('persist:delete', { key: GAME_STATE_KEY })
        }
      } catch (err) {
        console.warn('Electron persist delete failed, falling back to localStorage:', err)
        localStorage.removeItem(GAME_STATE_KEY)
      }
    } else {
      localStorage.removeItem(GAME_STATE_KEY)
      try {
        const objectStore = await openIndexedDB()
        await new Promise<void>((resolve, reject) => {
          const request = objectStore.delete(GAME_STATE_KEY)
          request.onerror = () => reject(request.error)
          request.onsuccess = () => resolve()
        })
      } catch (e) {
        console.warn('IndexedDB delete failed:', e)
      }
    }
  }, [isCapacitor, isElectron, capacitorStorage])

  return { saveGame, loadGame, deleteGame }
}

/**
 * Opens IndexedDB for web fallback storage
 * @internal
 */
async function openIndexedDB(): Promise<IDBObjectStore> {
  return new Promise((resolve, reject) => {
    const request = indexedDB.open('nim-game-db', 1)

    request.onerror = () => reject(request.error)
    request.onsuccess = () => {
      const db = request.result
      const transaction = db.transaction('game-state', 'readwrite')
      resolve(transaction.objectStore('game-state'))
    }

    request.onupgradeneeded = (event) => {
      const db = (event.target as IDBOpenDBRequest).result
      if (!db.objectStoreNames.contains('game-state')) {
        db.createObjectStore('game-state')
      }
    }
  })
}

/**
 * Cross-platform haptics — Capacitor haptics + audio feedback
 * Integrates native vibration (Android/iOS) with sound effects (all platforms)
 */

import { useCallback } from 'react'
import { usePlatform } from './usePlatform'
import { useCapacitorHaptics } from './useCapacitor'
import { useSoundEffects } from './useSoundEffects'

interface HapticFeedback {
  select: () => Promise<void>
  confirm: () => Promise<void>
  cpuMove: () => Promise<void>
  win: () => Promise<void>
  lose: () => Promise<void>
  vibrate: (duration?: number) => Promise<void>
  light: () => Promise<void>
  medium: () => Promise<void>
  strong: () => Promise<void>
}

/**
 * useHaptics - Unified haptic feedback across all platforms
 *
 * - Capacitor (Android/iOS): Uses native vibration + sound
 * - Electron: Sound feedback only
 * - Web: Sound feedback only
 *
 * Example:
 *   const haptics = useHaptics()
 *   await haptics.select()    // Light vibrate + sound
 *   await haptics.confirm()   // Strong vibrate + sound
 */
export const useHaptics = (): HapticFeedback => {
  const { isCapacitor } = usePlatform()
  const capacitorHaptics = useCapacitorHaptics()
  const sounds = useSoundEffects()

  const select = useCallback(async () => {
    sounds.onSelect()
    if (isCapacitor) {
      await capacitorHaptics.vibrate(30)
    }
  }, [isCapacitor, capacitorHaptics, sounds])

  const confirm = useCallback(async () => {
    sounds.onConfirm()
    if (isCapacitor) {
      await capacitorHaptics.vibrate(80)
    }
  }, [isCapacitor, capacitorHaptics, sounds])

  const cpuMove = useCallback(async () => {
    sounds.onCpuMove()
    if (isCapacitor) {
      await capacitorHaptics.vibrate(50)
    }
  }, [isCapacitor, capacitorHaptics, sounds])

  const win = useCallback(async () => {
    sounds.onWin()
    if (isCapacitor) {
      // Multi-pulse win pattern
      await capacitorHaptics.vibrate(100)
      await new Promise((r) => setTimeout(r, 100))
      await capacitorHaptics.vibrate(100)
    }
  }, [isCapacitor, capacitorHaptics, sounds])

  const lose = useCallback(async () => {
    sounds.onLose()
    if (isCapacitor) {
      // Double pulse lose pattern
      await capacitorHaptics.vibrate(50)
      await new Promise((r) => setTimeout(r, 50))
      await capacitorHaptics.vibrate(50)
    }
  }, [isCapacitor, capacitorHaptics, sounds])

  const vibrate = useCallback(
    async (duration = 50) => {
      if (isCapacitor) {
        await capacitorHaptics.vibrate(duration)
      }
    },
    [isCapacitor, capacitorHaptics],
  )

  const light = useCallback(async () => {
    sounds.onClick()
    if (isCapacitor) {
      await capacitorHaptics.vibrate(20)
    }
  }, [isCapacitor, capacitorHaptics, sounds])

  const medium = useCallback(async () => {
    sounds.onClick()
    if (isCapacitor) {
      await capacitorHaptics.vibrate(50)
    }
  }, [isCapacitor, capacitorHaptics, sounds])

  const strong = useCallback(async () => {
    sounds.onConfirm()
    if (isCapacitor) {
      await capacitorHaptics.vibrate(100)
    }
  }, [isCapacitor, capacitorHaptics, sounds])

  return { select, confirm, cpuMove, win, lose, vibrate, light, medium, strong }
}

/**
 * useIonicPlatform — Platform detection hook using browser APIs and Capacitor detection.
 *
 * REFACTORED to remove Ionic dependency. Provides semantic information about the current runtime environment:
 * - Device category (mobile, tablet, desktop)
 * - Operating system (iOS, Android)
 * - Runtime environment (web, Electron, hybrid Capacitor)
 *
 * Usage:
 * const platform = useIonicPlatform()
 * if (platform.isMobileDevice) {
 *   // Render mobile-optimized UI
 * }
 *
 * Implementation:
 * - Uses User-Agent parsing for OS detection (iOS/Android)
 * - Uses Capacitor API detection for hybrid apps
 * - Uses window.electron detection for Electron
 * - Uses responsive viewport and browser detection for web
 *
 * Alternative to useResponsiveState for OS/runtime detection.
 * Use useResponsiveState for viewport-based (5-tier) layout decisions.
 * Use useIonicPlatform for OS-based (iOS/Android/web) behavior decisions.
 */

export interface IonicPlatformInfo {
  /** True if running on actual mobile OS (iOS or Android) */
  isMobileDevice: boolean
  /** True if running on iOS (iPhone, iPad) */
  isIOS: boolean
  /** True if running on Android */
  isAndroid: boolean
  /** True if running in a web browser (not native/Electron) */
  isWeb: boolean
  /** True if running in Electron (desktop app) */
  isElectron: boolean
  /** True if running in Capacitor hybrid wrapper (iOS/Android native container) */
  isHybrid: boolean
  /** True if running on tablet (Capacitor mobile OR responsive tablet breakpoint) */
  isTablet: boolean
  /** True if running on mobile phone device */
  isMobile: boolean
  /** True if running in desktop-like environment (web desktop, Electron, macOS app) */
  isDesktopEnvironment: boolean
}

/**
 * Detect platform info using browser APIs, without Ionic dependency.
 * Caches result since platform doesn't change during app runtime.
 */
let cachedPlatformInfo: IonicPlatformInfo | null = null

function detectPlatform(): IonicPlatformInfo {
  // Parse User-Agent for OS detection
  const ua = typeof window !== 'undefined' ? navigator.userAgent : ''
  const isIOS = /iPad|iPhone|iPod/.test(ua)
  const isAndroid = /Android/.test(ua)
  const isMobileOS = isIOS || isAndroid

  // Detect Electron
  const isElectron =
    typeof window !== 'undefined' &&
    typeof (window as any).electron !== 'undefined'

  // Detect Capacitor/Hybrid
  const isHybrid =
    typeof window !== 'undefined' &&
    typeof (window as any).Capacitor !== 'undefined'

  // Detect PWA
  const isPwa =
    typeof window !== 'undefined' &&
    (navigator.standalone === true ||
      window.matchMedia('(display-mode: standalone)').matches)

  // Web is anything that's not hybrid/electron
  const isWeb = !isHybrid && !isElectron

  // Mobile/tablet detection: use viewport + UA
  const viewport = typeof window !== 'undefined' ? window.innerWidth : 0
  const isMobile = viewport < 600 || /Mobile|Android/.test(ua)
  const isTablet =
    (viewport >= 600 && viewport < 900) ||
    (/iPad/.test(ua) && !/(Mini|Pad)/.test(ua))

  // Mobile web is web browser on mobile device
  const isMobileWeb = isWeb && (isMobile || (isTablet && isMobileOS))

  // Desktop environment: Electron OR web on desktop OR tablet web without mobile OS
  const isDesktopEnvironment =
    isElectron ||
    (isWeb && !isMobileWeb) ||
    (isWeb && isTablet && !isMobileOS)

  return {
    isMobileDevice: isMobileOS,
    isIOS,
    isAndroid,
    isWeb,
    isElectron,
    isHybrid,
    isTablet,
    isMobile,
    isDesktopEnvironment,
  }
}

export function useIonicPlatform(): IonicPlatformInfo {
  if (cachedPlatformInfo) {
    return cachedPlatformInfo
  }

  cachedPlatformInfo = detectPlatform()
  return cachedPlatformInfo
}

/**
 * Resets cached platform info (for testing or if platform changes dynamically).
 * Normally not needed since platform is constant during app lifetime.
 */
export function resetPlatformCache() {
  cachedPlatformInfo = null
}

/**
 * Platform detection — Electron, Capacitor (Android/iOS), or Web
 * Use this to branch logic for native APIs
 */

import { Capacitor } from '@capacitor/core'

export type Platform = 'electron' | 'capacitor-android' | 'capacitor-ios' | 'web'

interface PlatformInfo {
  platform: Platform
  isElectron: boolean
  isCapacitor: boolean
  isWeb: boolean
  isNative: boolean // Electron or Capacitor
}

/**
 * Detect runtime platform
 * Priority: Electron > Capacitor > Web
 */
export const usePlatform = (): PlatformInfo => {
  // Check Electron first
  const isElectron =
    typeof window !== 'undefined' &&
    typeof (window as any).electron !== 'undefined'

  if (isElectron) {
    return {
      platform: 'electron',
      isElectron: true,
      isCapacitor: false,
      isWeb: false,
      isNative: true,
    }
  }

  // Check Capacitor second
  const isCapacitor = Capacitor.isNativePlatform()
  if (isCapacitor) {
    const capPlatform = Capacitor.getPlatform()
    const platform =
      capPlatform === 'android'
        ? ('capacitor-android' as const)
        : capPlatform === 'ios'
          ? ('capacitor-ios' as const)
          : ('web' as const)

    return {
      platform,
      isElectron: false,
      isCapacitor: true,
      isWeb: platform === 'web',
      isNative: platform !== 'web',
    }
  }

  // Default: Web
  return {
    platform: 'web',
    isElectron: false,
    isCapacitor: false,
    isWeb: true,
    isNative: false,
  }
}

/**
 * useStats — win/loss/streak tracking persisted to localStorage.
 * Standard logic uses shared helpers; PvP logic is game-specific.
 */

import { useCallback, useState } from 'react'

import { nextLossStats, nextWinStats } from '@games/stats-utils'

import type { GameStats } from '@/domain'
import { DEFAULT_STATS } from '@/domain'

import { storageService } from '../services/storageService'

const loadStats = (): GameStats => storageService.loadGameStats() ?? DEFAULT_STATS

export const useStats = () => {
  const [stats, setStats] = useState<GameStats>(loadStats)

  const persist = useCallback((nextStats: GameStats) => {
    setStats(nextStats)
    storageService.saveGameStats(nextStats)
  }, [])

  const recordWin = useCallback(() => {
    persist(nextWinStats(stats))
  }, [stats, persist])

  const recordLoss = useCallback(() => {
    persist(nextLossStats(stats))
  }, [stats, persist])

  const recordPvpWin = useCallback(
    (winner: 'player1' | 'player2') => {
      const nextStreakWinner = stats.streakWinner === winner ? stats.streakWinner : winner
      const nextStreakCount = stats.streakWinner === winner ? stats.streakCount + 1 : 1

      const shouldUpdateBest = nextStreakCount > stats.bestStreakCount

      persist({
        ...stats,
        pvp1Wins: winner === 'player1' ? stats.pvp1Wins + 1 : stats.pvp1Wins,
        pvp2Wins: winner === 'player2' ? stats.pvp2Wins + 1 : stats.pvp2Wins,
        streakWinner: nextStreakWinner,
        streakCount: nextStreakCount,
        bestStreakWinner: shouldUpdateBest ? winner : stats.bestStreakWinner,
        bestStreakCount: shouldUpdateBest ? nextStreakCount : stats.bestStreakCount,
      })
    },
    [stats, persist],
  )

  const resetStats = useCallback(() => {
    persist(DEFAULT_STATS)
  }, [persist])

  return {
    stats,
    recordWin,
    recordLoss,
    recordPvpWin,
    resetStats,
  }
}

/**
 * Theme Hook — manages theme state and persistence.
 * UI synchronization is handled by the UI theme service.
 */

import { useCallback, useEffect, useState } from 'react'

import { load, save } from '@/infrastructure/storage'
import { DEFAULT_SETTINGS } from '@/domain'

