import { useEffect, useRef, useState, useCallback } from 'react'

interface ParticleData {
  x: number
  y: number
  opacity: number
  colorIndex: number
}

interface UseWasmParticlesReturn {
  particles: ParticleData[]
  isReady: boolean
  triggerBurst: (centerX: number, centerY: number, count: number, speed: number) => void
}

/**
 * Hook for WASM-powered particle system
 * Manages particle physics calculations via AssemblyScript/WASM
 */
export function useWasmParticles(
  containerWidth: number,
  containerHeight: number,
  colorCount: number,
): UseWasmParticlesReturn {
  const [particles, setParticles] = useState<ParticleData[]>([])
  const [isReady, setIsReady] = useState(false)
  const particleSystemRef = useRef<any>(null)
  const animationFrameRef = useRef<number | null>(null)

  // Initialize WASM module
  useEffect(() => {
    const initWasm = async () => {
      try {
        // Dynamically import the WASM module
        // In production, this comes from src/wasm/ai-wasm.ts (but we'll use particles module)
        // For now, we'll use a fallback that doesn't require the full WASM setup
        setIsReady(true)
      } catch (error) {
        console.warn('WASM particle system unavailable, using fallback', error)
        setIsReady(true)
      }
    }

    initWasm()
  }, [])

  // Animation loop
  useEffect(() => {
    if (!isReady) {return}

    const animate = () => {
      if (particleSystemRef.current) {
        // Update particles
        particleSystemRef.current.update()

        // Get particle data and convert to array
        const count = particleSystemRef.current.getParticleCount()
        const newParticles: ParticleData[] = []

        for (let i = 0; i < count; i++) {
          // Simplified representation – in full WASM implementation
          // we'd extract binary data from memory
          newParticles.push({
            x: Math.random() * containerWidth,
            y: Math.random() * containerHeight,
            opacity: Math.random(),
            colorIndex: i % colorCount,
          })
        }

        setParticles(newParticles)
      }

      animationFrameRef.current = requestAnimationFrame(animate)
    }

    animationFrameRef.current = requestAnimationFrame(animate)

    return () => {
      if (animationFrameRef.current !== null) {
        cancelAnimationFrame(animationFrameRef.current)
      }
    }
  }, [isReady, containerWidth, containerHeight, colorCount])

  const triggerBurst = useCallback(
    (centerX: number, centerY: number, count: number, speed: number) => {
      if (!particleSystemRef.current) {
        // Fallback: create particles directly
        const newParticles: ParticleData[] = []
        for (let i = 0; i < count; i++) {
          const angle = (i / count) * Math.PI * 2
          const velocity = speed * (0.7 + (i % 3) * 0.15)
          const vx = Math.cos(angle) * velocity
          const vy = Math.sin(angle) * velocity

          newParticles.push({
            x: centerX + vx,
            y: centerY + vy,
            opacity: 1,
            colorIndex: i % colorCount,
          })
        }
        setParticles(newParticles)
      } else {
        particleSystemRef.current.createBurst(centerX, centerY, count, speed, colorCount)
      }
    },
    [colorCount],
  )

  return {
    particles,
    isReady,
    triggerBurst,
  }
}

/**
 * Sprite Manager — Centralized asset registry for theme visual resources.
 *
 * SOLID: Single Responsibility — one place to manage all theme sprites.
 * Adding a new theme background? Add one entry here — no CSS changes needed.
 *
 * Each theme maps to a sprite set (currently just a background image).
 * Extend ThemeSpriteSet to add more sprite slots (e.g., patterns, icons).
 */

/** A single visual asset (image, pattern, etc.) */
export interface SpriteAsset {
  readonly id: string
  readonly src: string
  readonly alt: string
}

/** Complete set of sprites for a single theme */
export interface ThemeSpriteSet {
  readonly background: SpriteAsset | null
}

/** Central sprite registry — maps theme ID → sprite set */
const SPRITE_REGISTRY: Readonly<Record<string, ThemeSpriteSet>> = {
  classic: {
    background: {
      id: 'classic-bg',
      src: '/backgrounds/matrix.png',
      alt: 'Matrix digital rain pattern',
    },
  },
  'neon-arcade': {
    background: {
      id: 'neon-arcade-bg',
      src: '/backgrounds/cityscape.png',
      alt: 'Cityscape skyline',
    },
  },
  'night-district': {
    background: null,
  },
  gridline: {
    background: {
      id: 'gridline-bg',
      src: '/backgrounds/matrix.png',
      alt: 'Matrix digital rain pattern',
    },
  },
  vaporwave: {
    background: {
      id: 'vaporwave-bg',
      src: '/backgrounds/laser.png',
      alt: 'Laser grid pattern',
    },
  },
  synthwave: {
    background: {
      id: 'synthwave-bg',
      src: '/backgrounds/circuit.png',
      alt: 'Circuit board traces',
    },
  },
  'high-contrast': {
    background: null,
  },
}

/** Get the sprite set for a theme (returns empty set if theme unknown) */
export const getThemeSprites = (themeId: string): ThemeSpriteSet =>
  SPRITE_REGISTRY[themeId] ?? { background: null }

/** Get the background image as a CSS url() value, or 'none' */
export const getBackgroundCssValue = (themeId: string): string => {
  const sprite = SPRITE_REGISTRY[themeId]?.background
  return sprite ? `url('${sprite.src}')` : 'none'
}

/** Get all unique sprite sources across all themes (for bulk preloading) */
export const getAllSpriteSources = (): readonly string[] => {
  const sources = new Set<string>()
  for (const spriteSet of Object.values(SPRITE_REGISTRY)) {
    if (spriteSet.background) {
      sources.add(spriteSet.background.src)
    }
  }
  return [...sources]
}

/** Preload a single sprite image into the browser cache */
export const preloadSprite = (src: string): Promise<void> =>
  new Promise<void>((resolve, reject) => {
    const img = new Image()
    img.onload = () => resolve()
    img.onerror = () => reject(new Error(`Failed to preload sprite: ${src}`))
    img.src = src
  })

/** Preload all theme sprites (fire-and-forget, errors silently ignored) */
export const preloadAllSprites = (): void => {
  for (const src of getAllSpriteSources()) {
    preloadSprite(src).catch(() => {})
  }
}

import type { Difficulty, GameMode, GameState, Move as AIMove } from './types'

const getCounts = (state: GameState): number[] => state.piles.map((pile) => pile.count)

const getLegalMoves = (counts: number[]): AIMove[] => {
  const moves: AIMove[] = []
  for (let pileId = 0; pileId < counts.length; pileId += 1) {
    const count = counts[pileId]
    for (let removeCount = 1; removeCount <= count; removeCount += 1) {
      moves.push({ pileId, removeCount })
    }
  }
  return moves
}

const applyMoveToCounts = (counts: number[], move: AIMove): number[] => {
  const next = [...counts]
  next[move.pileId] -= move.removeCount
  return next
}

const isTerminal = (counts: number[]): boolean => counts.every((count) => count === 0)

const makeMemoKey = (counts: number[], mode: GameMode): string => `${mode}:${counts.join(',')}`

/**
 * Returns whether the current position is winning for the player to move.
 *
 * Normal play terminal condition:
 * - No legal move => loss for player to move.
 *
 * Misère terminal condition:
 * - No legal move => win for player to move (opponent took last and loses).
 */
const isWinningPosition = (counts: number[], mode: GameMode, memo: Map<string, boolean>): boolean => {
  if (isTerminal(counts)) {
    return mode === 'misere'
  }

  const key = makeMemoKey(counts, mode)
  const cached = memo.get(key)
  if (cached !== undefined) {
    return cached
  }

  const legalMoves = getLegalMoves(counts)
  for (const move of legalMoves) {
    const nextCounts = applyMoveToCounts(counts, move)
    const opponentWinning = isWinningPosition(nextCounts, mode, memo)
    if (!opponentWinning) {
      memo.set(key, true)
      return true
    }
  }

  memo.set(key, false)
  return false
}

const getWinningMoves = (state: GameState): AIMove[] => {
  const counts = getCounts(state)
  const memo = new Map<string, boolean>()
  const legalMoves = getLegalMoves(counts)

  return legalMoves.filter((move) => {
    const nextCounts = applyMoveToCounts(counts, move)
    return !isWinningPosition(nextCounts, state.mode, memo)
  })
}

const getRandomMove = (state: GameState): AIMove => {
  const legalMoves = getLegalMoves(getCounts(state))
  if (legalMoves.length === 0) {
    return { pileId: 0, removeCount: 0 }
  }
  return legalMoves[Math.floor(Math.random() * legalMoves.length)]
}

/**
 * Easy AI — random legal move.
 */
const selectMoveEasy = (state: GameState): AIMove => {
  return getRandomMove(state)
}

/**
 * Medium AI — prefers winning moves, but intentionally allows imperfection.
 * - 60%: choose a winning move if available.
 * - 40%: random legal move.
 */
const selectMoveMedium = (state: GameState): AIMove => {
  const winningMoves = getWinningMoves(state)
  if (winningMoves.length > 0 && Math.random() < 0.6) {
    return winningMoves[Math.floor(Math.random() * winningMoves.length)]
  }
  return getRandomMove(state)
}

/**
 * Hard AI — always chooses a winning move when one exists.
 * Fully mode-aware (normal + misère) via game-state solving.
 */
const selectMoveHard = (state: GameState): AIMove => {
  const winningMoves = getWinningMoves(state)
  if (winningMoves.length > 0) {
    return winningMoves[0]
  }

  // No forced win exists from this position; return legal fallback.
  return getRandomMove(state)
}

/**
 * Selects a move based on difficulty level.
 */
export const selectMove = (state: GameState, difficulty: Difficulty = 'hard'): AIMove => {
  switch (difficulty) {
    case 'easy':
      return selectMoveEasy(state)
    case 'medium':
      return selectMoveMedium(state)
    case 'hard':
      return selectMoveHard(state)
  }
}

import { GameMode, GameState, Move, Player } from './types'

/**
 * Creates the initial game state from a list of counts.
 */
export const createInitialBoard = (
  initialCounts: number[],
  startingPlayer: Player = 'human',
  mode: GameMode = 'misere',
): GameState => ({
  piles: initialCounts.map((count, id) => ({ id, count })),
  currentPlayer: startingPlayer,
  winner: null,
  isGameOver: false,
  mode,
  lastMove: null,
})

/**
 * Validates whether a move is legal.
 */
export const isValidMove = (state: GameState, move: Move): boolean => {
  const pile = state.piles.find((p) => p.id === move.pileId)
  return !!pile && move.removeCount > 0 && move.removeCount <= pile.count
}

/**
 * Applies a move to the board and returns a new state.
 */
export const applyMove = (state: GameState, move: Move): GameState => {
  if (!isValidMove(state, move)) {
    return state
  }

  const newPiles = state.piles.map((p) =>
    p.id === move.pileId ? { ...p, count: p.count - move.removeCount } : p,
  )

  return {
    ...state,
    piles: newPiles,
  }
}

