// ─── Platform Union ──────────────────────────────

/**
 * PlatformApi: DI container for all platform capabilities
 *
 * Implementations:
 * - 'web': Browser-based (Vibration API, localStorage, etc.)
 * - 'electron': Desktop Electron (native modules, file system access)
 * - 'capacitor': Mobile (Capacitor plugins for iOS/Android)
 */
export interface PlatformApi {
  haptics: HapticsApi
  storage: StorageApi
  diagnostics: DiagnosticsApi
  audio: AudioApi
  device: DeviceApi
  name: 'web' | 'electron' | 'capacitor'
}

/**
 * Platform Detection
 * Determine which platform runtime we're on
 */

export type DetectedPlatform = 'web' | 'electron' | 'capacitor'

export function detectPlatform(): DetectedPlatform {
  // Check for Electron
  if (typeof window !== 'undefined' && (window as any).__ELECTRON_PRELOAD__) {
    return 'electron'
  }

  // Check for Capacitor
  if (typeof window !== 'undefined' && (window as any).Capacitor) {
    return 'capacitor'
  }

  // Default to web
  return 'web'
}

