/**
 * GlitchText — Applies WebGL glitch effect to text using react-vfx.
 * Cyberpunk/hacker aesthetic for error messages, notifications, warnings.
 *
 * Usage:
 *   <GlitchText intensity="high">Game Over!</GlitchText>
 *   <GlitchText intensity="low">Warning</GlitchText>
 *
 * Intensity levels:
 * - low: 0.3 (subtle shimmer)
 * - medium: 0.6 (noticeable glitch, default)
 * - high: 0.9 (aggressive digital distortion)
 *
 * Shader is externalized to GlitchText.glsl and imported as raw string.
 * This prevents re-compilation on every render (performance optimization).
 *
 * Uses react-vfx VFXSpan component with shader prop (component-based API, not hooks).
 */

import { VFXProvider, VFXSpan } from 'react-vfx'
import { ReactNode } from 'react'
import glitchShader from './GlitchText.glsl?raw'

interface GlitchTextProps {
  children: ReactNode
  intensity?: 'low' | 'medium' | 'high'
  className?: string
  style?: React.CSSProperties
}

export const GlitchText = ({ children, className, style }: GlitchTextProps) => {
  // Note: intensity parameter kept in props interface for API stability.
  // Currently, react-vfx VFXSpan applies the shader uniformly.
  // Custom intensity control would require shader uniform updates (not exposed in current API).
  return (
    <VFXProvider>
      <VFXSpan
        className={className}
        style={{
          display: 'inline-block',
          ...style,
        }}
        shader={glitchShader}
      >
        {children}
      </VFXSpan>
    </VFXProvider>
  )
}

/**
 * IonicButton — Ionic-powered button component with platform awareness.
 *
 * Features:
 * - Touch-optimized on mobile/tablet
 * - Hover effects on desktop
 * - Platform-aware sizing via useIonicPlatform()
 * - Responsive typography
 * - Integrates with Ionic theming (CSS variables)
 * - Supports loading state
 * - Semantic sizing: small, default, large
 *
 * Usage:
 * <IonicButton onClick={handleClick}>Click me</IonicButton>
 * <IonicButton size="large" color="primary">Large primary</IonicButton>
 * <IonicButton disabled>Disabled</IonicButton>
 * <IonicButton loading>Loading...</IonicButton>
 */

import { IonButton, IonSpinner } from '@ionic/react'
import React from 'react'

import { useIonicPlatform } from '@/app'
import styles from './IonicButton.module.css'

interface IonicButtonProps
  extends Omit<React.ComponentProps<typeof IonButton>, 'size' | 'color' | 'fill' | 'expand' | 'shape'> {
  /**
   * Visual variant: primary, secondary, danger, success, warning, light, dark
   */
  color?: 'primary' | 'secondary' | 'danger' | 'success' | 'warning' | 'light' | 'dark'

  /**
   * Button size: small, default, large
   * Default: 'default'
   * On mobile, automatically scales up for touch targets
   */
  size?: 'small' | 'default' | 'large'

  /**
   * Visually fills the button with background color
   */
  fill?: boolean

  /**
   * Show loading spinner (disables click events)
   */
  loading?: boolean

  /**
   * Button content (text, children, or custom)
   */
  children?: React.ReactNode

  /**
   * Expand button to full width
   */
  expand?: boolean

  /**
   * Shape: default, round
   */
  shape?: 'default' | 'round'
}

/**
 * IonicButton component using Ionic's IonButton with platform awareness.
 * Automatically adjusts size and styling based on device type.
 */
export const IonicButton = React.forwardRef<HTMLIonButtonElement, IonicButtonProps>(
  function IonicButton(
    { color = 'primary', size = 'default', fill = false, loading = false, expand = false, shape = 'default', children, className, ...props },
    ref,
  ) {
    const platform = useIonicPlatform()

    // Size adjustment: larger touch targets on mobile/tablet
    const effectiveSize =
      platform.isMobileDevice && size === 'default' ? 'large' : size

    // Render loading state
    if (loading) {
      return (
        <IonButton
          ref={ref}
          color={color}
          size={effectiveSize}
          fill={fill ? 'solid' : 'outline'}
          disabled
          className={`${styles.button} ${styles.loading}`}
        >
          <IonSpinner name="crescent" slot="start" />
          {children}
        </IonButton>
      )
    }

    return (
      <IonButton
        ref={ref}
        color={color}
        size={effectiveSize}
        fill={fill ? 'solid' : 'outline'}
        expand={expand ? 'block' : undefined}
        shape={shape === 'round' ? 'round' : undefined}
        className={`${styles.button} ${className || ''}`}
        {...props}
      >
        {children}
      </IonButton>
    )
  },
)

IonicButton.displayName = 'IonicButton'

import { useI18nContext } from '@/app'
import React, { useRef, useState } from 'react'

export interface NimObjectProps {
  id: number
  selected?: boolean
  onClick?: () => void
}

/**
 * A single Nim object (a 3D-effect coin stack element).
 */
export const NimObject: React.FC<NimObjectProps> = ({ onClick, selected }) => {
  const { t } = useI18nContext()
  const [isHovered, setIsHovered] = useState(false)
  const [isPressed, setIsPressed] = useState(false)
  const [isLongPress, setIsLongPress] = useState(false)
  const longPressTimer = useRef<number | null>(null)

  const clearLongPressTimer = () => {
    if (longPressTimer.current !== null) {
      window.clearTimeout(longPressTimer.current)
      longPressTimer.current = null
    }
  }

  const handleTouchStart = () => {
    setIsPressed(true)
    setIsLongPress(false)
    clearLongPressTimer()
    longPressTimer.current = window.setTimeout(() => {
      setIsLongPress(true)
    }, 220)
  }

  const handleTouchEnd = () => {
    clearLongPressTimer()
    setIsPressed(false)
    setIsLongPress(false)
  }

  const dynamicTransform = selected
    ? 'scale(1.1) translateY(-4px)'
    : isLongPress
      ? 'scale(1.14) translateY(-5px)'
      : isPressed
        ? 'scale(1.1) translateY(-3px)'
        : isHovered
          ? 'scale(1.06) translateY(-2px)'
          : 'translateY(0)'

  const dynamicShadow = selected
    ? '0 6px 12px rgba(255, 143, 0, 0.4)'
    : isLongPress
      ? '0 8px 16px rgba(255, 143, 0, 0.45)'
      : isHovered || isPressed
        ? '0 4px 10px rgba(255, 143, 0, 0.35)'
        : '0 2px 0 rgba(0, 0, 0, 0.2)'

  return (
    <button
      type="button"
      onClick={onClick}
      onMouseEnter={() => setIsHovered(true)}
      onMouseLeave={() => {
        setIsHovered(false)
        setIsPressed(false)
        setIsLongPress(false)
        clearLongPressTimer()
      }}
      onMouseDown={() => setIsPressed(true)}
      onMouseUp={() => setIsPressed(false)}
      onTouchStart={handleTouchStart}
      onTouchEnd={handleTouchEnd}
      onTouchCancel={handleTouchEnd}
      style={{
        width: '40px',
        height: '14px',
        background: selected
          ? 'linear-gradient(180deg, #ffc107 0%, #ff8f00 100%)'
          : 'linear-gradient(180deg, #ffd54f 0%, #ffc107 100%)',
        margin: '2px 0',
        cursor: 'pointer',
        border: '1px solid rgba(0,0,0,0.1)',
        borderRadius: '50% / 4px',
        display: 'block',
        position: 'relative',
        transition: 'all 0.2s cubic-bezier(0.17, 0.67, 0.83, 0.67)',
        transform: dynamicTransform,
        boxShadow: dynamicShadow,
        zIndex: selected ? 10 : 1,
      }}
      aria-label={t('nim.coinAria')}
    >
      {/* 3D Rim Effect */}
      <div
        style={{
          position: 'absolute',
          top: '1px',
          left: '2px',
          right: '2px',
          height: '4px',
          background: 'rgba(255, 255, 255, 0.3)',
          borderRadius: '50% / 2px',
        }}
      />
    </button>
  )
}

