/**
 * App — Phase-based navigation wrapper for the Nim game.
 *
 * Manages game phases:
 * - loading: Splash screen (1.2s + instant gradient background)
 * - menu: Main menu with stats
 * - playing: Active game board
 * - help: Help overlay (future)
 * - stats: Stats overlay (future)
 *
 * Responsive: Uses useResponsiveState for semantic breakpoints.
 * Board scaling: Dynamic sizing using CSS custom properties + clamp().
 */

import { useCallback, useEffect, useRef, useState } from 'react'

import { App as CapacitorApp } from '@capacitor/app'
import type { PluginListenerHandle } from '@capacitor/core'

import {
  useGame,
  useI18nContext,
  useIonicToast,
  useResponsiveState,
  useSoundEffects,
  useStats,
  useThemeContext,
} from '@/app'
import { GAME_PRESETS } from '@/domain'
import { haptics } from '@/infrastructure/haptics'
import {
  COLOR_THEMES,
  HamburgerLanguageSection,
  HamburgerPilesSection,
  OfflineIndicator,
  QuickGameSettings,
  QuickThemePicker,
  SplashScreen,
  StarExplosion,
} from '@/ui'
import { HamburgerMenu } from '@games/common'
import { applyThemeToDOM, initializeThemeSystem } from '@/ui/services/themeService'

import styles from './App.module.css'
import { DeviceInfoScreen } from './DeviceInfoScreen'
import { GameBoard } from './GameBoard'

type AppPhase = 'splash' | 'menu' | 'playing' | 'device-info'

export default function App() {
  const responsive = useResponsiveState()
  const game = useGame()
  const { stats, recordWin, recordLoss, recordPvpWin } = useStats()
  const sfx = useSoundEffects()
  const toast = useIonicToast()
  const { settings, setColorTheme } = useThemeContext()
  const { locale, setLocale, t } = useI18nContext()
  const [phase, setPhase] = useState<AppPhase>('splash')
  const [testStars, setTestStars] = useState(false)
  const [setup, setSetup] = useState<number[]>(game.setup)
  const prevGameOver = useRef(false)
  const leaveGameAlertRef = useRef<{
    present: () => Promise<void>
    dismiss: () => Promise<void>
  } | null>(null)
  const deviceInfoAlertRef = useRef<{
    present: () => Promise<void>
    dismiss: () => Promise<void>
  } | null>(null)

  // Initialize theme system on mount
  useEffect(() => {
    initializeThemeSystem()
  }, [])

  // Apply theme settings to DOM when they change
  useEffect(() => {
    applyThemeToDOM(settings).catch(() => {})
  }, [settings])

  // Splash screen complete callback
  const handleSplashComplete = useCallback(() => {
    setPhase('menu')
  }, [])

  // Sound + haptic + stats on game over
  useEffect(() => {
    if (game.state.isGameOver && !prevGameOver.current) {
      if (game.opponent === 'cpu') {
        if (game.state.winner === 'human') {
          sfx.onWin()
          haptics.success()
          recordWin()
        } else {
          sfx.onLose()
          haptics.error()
          recordLoss()
        }
      } else if (game.opponent === 'local') {
        // PvP mode: record stats for winner
        if (game.state.winner === 'human') {
          recordPvpWin('player1')
          sfx.onWin()
          haptics.success()
        } else {
          recordPvpWin('player2')
          sfx.onWin()
          haptics.success()
        }
      }
    }
    prevGameOver.current = game.state.isGameOver
  }, [
    game.state.isGameOver,
    game.state.winner,
    game.opponent,
    sfx,
    recordWin,
    recordLoss,
    recordPvpWin,
  ])

  // Sound on CPU move
  useEffect(() => {
    if (game.state.lastMove?.player === 'cpu') {
      sfx.onCpuMove()
      haptics.light()
    }
  }, [game.state.lastMove, sfx])

  // Sync setup state with game setup
  useEffect(() => {
    setSetup(game.setup)
  }, [game.setup])

  // ─── Setup Handlers ───
  const handlePileChange = useCallback(
    (index: number, value: string) => {
      const parsed = Number.parseInt(value, 10)
      const nextValue = Number.isNaN(parsed) ? 1 : Math.max(1, Math.min(parsed, 15))
      const nextSetup = [...setup]
      nextSetup[index] = nextValue
      setSetup(nextSetup)
      game.updateSetup(nextSetup)
    },
    [setup, game],
  )

  const handleApplyPreset = useCallback(
    (counts: number[]) => {
      setSetup([...counts])
      game.updateSetup([...counts])
    },
    [game],
  )

  const isPresetActive = (counts: readonly number[]) =>
    counts.length === setup.length && counts.every((count, index) => count === setup[index])

  // ─── Navigation Handlers ───
  const handlePlayVsCpu = useCallback(() => {
    game.setOpponent('cpu')
    game.resetGame()
    sfx.onClick()
    setPhase('playing')
  }, [game, sfx])

  const handlePlayLocal = useCallback(() => {
    game.setOpponent('local')
    game.resetGame()
    sfx.onClick()
    setPhase('playing')
  }, [game, sfx])

  const handleAutoResetGame = useCallback(() => {
    game.resetGame()
  }, [game])

  const handleShowDeviceInfo = useCallback(() => {
    if (phase === 'playing' && !game.state.isGameOver) {
      void deviceInfoAlertRef.current?.present()
      return
    }

    sfx.onClick()
    setPhase('device-info')
    void toast.text(t('app.toast.openedDeviceInfo'))
  }, [phase, game.state.isGameOver, sfx, toast, t])

  const handleCloseDeviceInfo = useCallback(() => {
    sfx.onClick()
    setPhase('menu')
  }, [sfx])

  const isMainMenuPhase = phase === 'menu'
  const isBackNavigationPhase = phase === 'device-info'
  const headerBackIcon = isBackNavigationPhase ? '←' : '✕'
  const headerBackAriaLabel = isBackNavigationPhase ? t('app.backToMenu') : t('app.closeGame')
  const headerBackTitle = isBackNavigationPhase
    ? t('app.backButtonTitle')
    : t('app.closeGameButtonTitle')

  const handleBackToMenu = useCallback(() => {
    if (phase === 'playing' && !game.state.isGameOver) {
      void leaveGameAlertRef.current?.present()
      return
    }

    sfx.onClick()
    setPhase('menu')
  }, [phase, game.state.isGameOver, sfx])

  const handleHeaderBack = useCallback(() => {
    if (phase === 'device-info') {
      handleCloseDeviceInfo()
      return
    }

    handleBackToMenu()
  }, [phase, handleCloseDeviceInfo, handleBackToMenu])

  const handleObjectClick = useCallback(
    (pileId: number, index: number) => {
      sfx.onSelect()
      haptics.light()
      game.handleObjectClick(pileId, index)
    },
    [game, sfx],
  )

  const handleConfirm = useCallback(() => {
    try {
      sfx.onConfirm()
      haptics.light()
      game.confirmMove()
    } catch {
      void toast.error(t('error.unexpected'))
    }
  }, [game, sfx, toast, t])

  const handleLeaveGameDismiss = useCallback(
    (data: { role?: string }) => {
      if (data?.role === 'default' || data?.role === 'confirm') {
        sfx.onClick()
        setPhase('menu')
      }
    },
    [sfx],
  )

  const handleDeviceInfoDismiss = useCallback(
    (data: { role?: string }) => {
      if (data?.role === 'default' || data?.role === 'confirm') {
        sfx.onClick()
        setPhase('device-info')
        void toast.text(t('app.toast.openedDeviceInfo'))
      }
    },
    [sfx, toast, t],
  )

  // Capacitor lifecycle: pause, resume, hardwareBackPress
  useEffect(() => {
    const unlisteners: PluginListenerHandle[] = []

    // Setup listeners asynchronously
    const setupListeners = async () => {
      // Handle app pause (native app suspension on iOS/Android)
      const pauseListener = await CapacitorApp.addListener('pause', () => {
        // Game state is already persisted via hooks (useGame, useStats, etc.)
        // No additional action needed here
      })
      unlisteners.push(pauseListener)

      // Handle app resume (app returned to foreground)
      const resumeListener = await CapacitorApp.addListener('resume', () => {
        // Could re-initialize if needed (e.g., analytics tracking, sound context)
      })
      unlisteners.push(resumeListener)

      // Handle Android hardware back button
      const backListener = await CapacitorApp.addListener('backButton', async () => {
        // Navigate based on current phase
        if (phase === 'playing') {
          handleBackToMenu()
        } else if (phase === 'menu' || phase === 'splash') {
          // Allow OS to handle (app exit)
          // Optional: show exit confirmation
        }
      })
      unlisteners.push(backListener)
    }

    setupListeners().catch((err) => console.error('[Capacitor] Setup failed:', err))

    return () => {
      unlisteners.forEach((listener) => listener.remove())
    }
  }, [phase, handleBackToMenu])

  // ─── Show Splash ───
  if (phase === 'splash') {
    return <SplashScreen onComplete={handleSplashComplete} />
  }

  // ─── Show Menu / Device Info Surface ───
  if (phase === 'menu' || phase === 'device-info') {
    return (
      <div id="nim-main-content" className={styles.appContainer}>
        <StarExplosion isActive={testStars} palette={['#fbbf24', '#ef4444', '#667eea']}>
          <div style={{ position: 'absolute', top: '10px', right: '10px', zIndex: 50 }}>
            <button onClick={() => setTestStars(!testStars)} style={{ padding: '8px 12px' }}>
              {testStars ? '★ Stars ON' : '★ Stars OFF'}
            </button>
          </div>
        </StarExplosion>
        <OfflineIndicator />
        <header className={styles.appHeader}>
          <div className={styles.headerLeft}>
            <button
              type="button"
              className={`${styles.backBtn} ${isMainMenuPhase ? styles.backBtnHidden : ''}`}
              onClick={handleHeaderBack}
              disabled={isMainMenuPhase}
              tabIndex={isMainMenuPhase ? -1 : 0}
              aria-hidden={isMainMenuPhase}
              aria-label={headerBackAriaLabel}
              title={headerBackTitle}
            >
              {headerBackIcon}
            </button>
          </div>

          <h1 className={styles.headerTitle}>{t('app.headerTitle')}</h1>

          <div className={styles.headerRight}>
            <HamburgerMenu>
              <div className={styles.hamburgerPanelContent}>
                <QuickThemePicker
                  themes={COLOR_THEMES}
                  activeThemeId={settings.colorTheme}
                  onSelectTheme={(themeId) => {
                    sfx.onClick()
                    setColorTheme(themeId)
                  }}
                />

                <QuickGameSettings
                  difficulty={game.difficulty}
                  mode={game.state.mode}
                  onSelectDifficulty={(difficulty) => {
                    sfx.onClick()
                    game.setDifficulty(difficulty)
                  }}
                  onSelectMode={(mode) => {
                    sfx.onClick()
                    game.setMode(mode)
                  }}
                />

                <HamburgerPilesSection
                  setup={setup}
                  presets={GAME_PRESETS}
                  onPileChange={handlePileChange}
                  onApplyPreset={handleApplyPreset}
                  isPresetActive={isPresetActive}
                />

                <HamburgerLanguageSection
                  locale={locale}
                  onSelectLocale={(newLocale) => {
                    sfx.onClick()
                    setLocale(newLocale)
                  }}
                />

                <button
                  type="button"
                  onClick={() => {
                    sfx.onClick()
                    handleShowDeviceInfo()
                  }}
                  className={styles.hamburgerMenuButton}
                >
                  📱 Device Info
                </button>
              </div>
            </HamburgerMenu>
          </div>
        </header>

        <div className={styles.appContent}>
          {phase === 'device-info' ? (
            <div
              style={{
                display: 'flex',
                flexDirection: 'column',
                alignItems: 'center',
                justifyContent: 'flex-start',
                padding: '1rem',
                minHeight: '100%',
                width: '100%',
              }}
            >
              <DeviceInfoScreen />
            </div>
          ) : (
            <>
              <div className={styles.menuTableLayout}>
                <GameBoard
                  state={game.state}
                  selectedPileId={game.selectedPileId}
                  selectedCount={game.selectedCount}
                  opponent={game.opponent}
                  cpuThinking={false}
                  isMobile={responsive.isMobile}
                  onObjectClick={handleObjectClick}
                  onConfirm={handleConfirm}
                  readonlyView
                  menuStats={stats}
                  onStartVsAi={handlePlayVsCpu}
                  onStartLocal={handlePlayLocal}
                />

                <p className={styles.menuHint}>
                  {t('mainMenu.hintLine1')}
                  <br />
                  {t('mainMenu.hintLine2')}
                </p>
              </div>
            </>
          )}
        </div>
      </div>
    )
  }

  // ─── Show Game Board with Persistent Header ───
  return (
    <div id="nim-main-content" className={styles.appContainer}>
      <StarExplosion isActive={testStars} palette={['#fbbf24', '#ef4444', '#667eea']}>
        <div style={{ position: 'absolute', top: '10px', right: '10px', zIndex: 50 }}>
          <button onClick={() => setTestStars(!testStars)} style={{ padding: '8px 12px' }}>
            {testStars ? '★ Stars ON' : '★ Stars OFF'}
          </button>
        </div>
      </StarExplosion>
      <OfflineIndicator />

      {/* Persistent App Header */}
      <header className={styles.appHeader}>
        <div className={styles.headerLeft}>
          <button
            type="button"
            className={styles.backBtn}
            onClick={handleBackToMenu}
            aria-label={t('app.backToMenu')}
            title={t('app.backButtonTitle')}
          >
            ✕
          </button>
        </div>

        <h1 className={styles.headerTitle}>{t('app.headerTitle')}</h1>

        <div className={styles.headerRight}>
          <HamburgerMenu>
            <div className={styles.hamburgerPanelContent}>
              <QuickThemePicker
                themes={COLOR_THEMES}
                activeThemeId={settings.colorTheme}
                onSelectTheme={(themeId) => {
                  sfx.onClick()
                  setColorTheme(themeId)
                }}
              />

              <QuickGameSettings
                difficulty={game.difficulty}
                mode={game.state.mode}
                onSelectDifficulty={(difficulty) => {
                  sfx.onClick()
                  game.setDifficulty(difficulty)
                }}
                onSelectMode={(mode) => {
                  sfx.onClick()
                  game.setMode(mode)
                }}
              />

              <HamburgerPilesSection
                setup={setup}
                presets={GAME_PRESETS}
                onPileChange={handlePileChange}
                onApplyPreset={handleApplyPreset}
                isPresetActive={isPresetActive}
              />

              <HamburgerLanguageSection
                locale={locale}
                onSelectLocale={(newLocale) => {
                  sfx.onClick()
                  setLocale(newLocale)
                }}
              />

              <button
                type="button"
                onClick={() => {
                  sfx.onClick()
                  handleShowDeviceInfo()
                }}
                className={styles.hamburgerMenuButton}
              >
                📱 Device Info
              </button>
            </div>
          </HamburgerMenu>
        </div>
      </header>

      {/* Game Content Area */}
      <div className={styles.appContent}>
        <GameBoard
          state={game.state}
          selectedPileId={game.selectedPileId}
          selectedCount={game.selectedCount}
          opponent={game.opponent}
          cpuThinking={game.cpuThinking}
          isMobile={responsive.isMobile}
          onObjectClick={handleObjectClick}
          onConfirm={handleConfirm}
          menuStats={stats}
          onGameOverAutoReset={handleAutoResetGame}
        />
      </div>

      <IonicAlertDialog
        ref={leaveGameAlertRef}
        title={t('app.dialog.leaveGameTitle')}
        message={t('app.dialog.leaveGameMessage')}
        okText={t('settings.confirm')}
        cancelText={t('settings.cancel')}
        onDismiss={handleLeaveGameDismiss}
      />

      <IonicAlertDialog
        ref={deviceInfoAlertRef}
        title={t('app.dialog.deviceInfoTitle')}
        message={t('app.dialog.deviceInfoMessage')}
        okText={t('settings.confirm')}
        cancelText={t('settings.cancel')}
        onDismiss={handleDeviceInfoDismiss}
      />
    </div>
  )
}

/**
 * Device Info Screen — Shows platform and device information
 * Accessible from hamburger menu
 */

import { useEffect, useState } from 'react'
import { usePlatform } from '@/app'
import { useResponsiveState } from '@games/app-hook-utils'
import type { DeviceInfo as CapacitorDeviceInfo } from '@capacitor/device'
import styles from './DeviceInfoScreen.module.css'

interface DisplayInfo {
  label: string
  value: string
}

export const DeviceInfoScreen = () => {
  const { platform, isCapacitor, isElectron } = usePlatform()
  const responsive = useResponsiveState()
  const [deviceInfo, setDeviceInfo] = useState<CapacitorDeviceInfo | null>(null)
  const [loading, setLoading] = useState(false)
  const [error, setError] = useState<string | null>(null)

  useEffect(() => {
    if (!isCapacitor) {return}

    const loadDeviceInfo = async () => {
      setLoading(true)
      setError(null)
      try {
        const { Device } = await import('@capacitor/device')
        const info = await Device.getInfo()
        setDeviceInfo(info)
      } catch (err) {
        setError(err instanceof Error ? err.message : 'Failed to load device info')
      } finally {
        setLoading(false)
      }
    }

    loadDeviceInfo()
  }, [isCapacitor])

  const platformInfo: DisplayInfo[] = [
    [
      { label: 'Runtime', value: isElectron ? 'Electron' : isCapacitor ? 'Capacitor' : 'Browser' },
    ],
    [
      {
        label: 'Platform',
        value:
          platform === 'capacitor-android'
            ? 'Android'
            : platform === 'capacitor-ios'
              ? 'iOS'
              : platform === 'electron'
                ? 'Electron'
                : 'Web',
      },
    ],
    [{ label: 'User Agent', value: navigator.userAgent.substring(0, 80) }],
  ].flat()

  const deviceDisplayInfo: DisplayInfo[] = deviceInfo
    ? [
        { label: 'Device Model', value: deviceInfo.model || 'Unknown' },
        { label: 'OS Version', value: deviceInfo.osVersion || 'Unknown' },
        {
          label: 'Manufacturer',
          value: (deviceInfo.manufacturer as unknown as string) || 'Unknown',
        },
        {
          label: 'Real Device',
          value: deviceInfo.isVirtual ? 'No (Virtual)' : 'Yes',
        },
      ]
    : []

  const allInfo = [...platformInfo, ...deviceDisplayInfo]

  return (
    <div
      className={styles.root}
      style={{
        padding: responsive.contentDensity === 'compact' ? '1rem' : '1.5rem',
        gap: responsive.contentDensity === 'spacious' ? '2rem' : '1.5rem',
      }}
    >
      <div>
        <h2 className={styles.title}>Device Information</h2>
        <p className={styles.subtitle}>Platform and device details</p>
      </div>

      {loading && (
        <div className={styles.state}>
          <p>Loading device info...</p>
        </div>
      )}

      {error && (
        <div className={styles.state} style={{ color: 'var(--color-danger, #d32f2f)' }}>
          <p>Error: {error}</p>
        </div>
      )}

      {!loading && !error && (
        <div className={styles.infoList}>
          {allInfo.map((item, idx) => (
            <div key={idx} className={styles.infoItem}>
              <div className={styles.infoLabel}>{item.label}</div>
              <div className={styles.infoValue}>{item.value}</div>
            </div>
          ))}
        </div>
      )}

      <div className={styles.note}>
        <p>
          <small>💡 This information helps debug platform-specific issues.</small>
        </p>
      </div>
    </div>
  )
}

import { useCallback, useEffect, memo, useMemo, useState } from 'react'

import { getThemeColorPalette, useI18nContext, useTheme } from '@/app'
import { useKeyboardControls, useResponsiveState } from '@games/app-hook-utils'
import type { GameState, GameStats, Opponent } from '@/domain'
import { cx, PileToggle, StarExplosion } from '@/ui'

import styles from './GameBoard.module.css'

type TakeLockVariant = 'soft' | 'strong'

const TAKE_LOCK_VARIANT: TakeLockVariant = 'soft'

interface GameBoardProps {
  state: GameState
  selectedPileId: number | null
  selectedCount: number
  opponent: Opponent
  cpuThinking: boolean
  isMobile: boolean
  onObjectClick: (pileId: number, index: number) => void
  onConfirm: () => void
  readonlyView?: boolean
  menuStats?: GameStats
  onStartVsAi?: () => void
  onStartLocal?: () => void
  onGameOverAutoReset?: () => void
}

function getWinnerLabel(
  opponent: Opponent,
  winner: 'human' | 'cpu' | null,
  t: (key: 'game.player1Wins' | 'game.player2Wins' | 'game.youWon' | 'game.youLost') => string,
): string {
  if (!winner) {
    return ''
  }
  if (opponent === 'local') {
    return winner === 'human' ? t('game.player1Wins') : t('game.player2Wins')
  }
  return winner === 'human' ? t('game.youWon') : t('game.youLost')
}

function GameBoardRaw({
  state,
  selectedPileId,
  selectedCount,
  opponent,
  cpuThinking,
  isMobile,
  onObjectClick,
  onConfirm,
  readonlyView = false,
  menuStats,
  onStartVsAi,
  onStartLocal,
  onGameOverAutoReset,
}: GameBoardProps) {
  const responsive = useResponsiveState()
  const { t } = useI18nContext()
  const { settings: themeSettings } = useTheme()
  const [showTurnNotification, setShowTurnNotification] = useState(false)

  const explosionPalette = useMemo(
    () => getThemeColorPalette(themeSettings.colorTheme),
    [themeSettings.colorTheme],
  )

  // Auto-reset game 3 seconds after game over
  useEffect(() => {
    if (!state.isGameOver || !onGameOverAutoReset) {
      return
    }

    const timer = setTimeout(() => {
      onGameOverAutoReset()
    }, 3000)

    return () => clearTimeout(timer)
  }, [state.isGameOver, onGameOverAutoReset])

  // Declare variables early for use in effects
  const canConfirm = selectedPileId !== null && selectedCount > 0
  const isHumanTurn = state.currentPlayer === 'human'
  const canInteract = !readonlyView && (opponent === 'local' || isHumanTurn)
  const playerWon = opponent === 'local' ? true : state.winner === 'human'
  const takeLockClass =
    TAKE_LOCK_VARIANT === 'strong' ? styles.takeAllBtnLockedStrong : styles.takeAllBtnLockedSoft
  const currentLocalPlayer = opponent === 'local' ? (isHumanTurn ? 1 : 2) : null

  // Show turn notification when a player's turn starts
  useEffect(() => {
    // In local/PvP mode, show notification for both players
    // In vs AI mode, show only for human player
    const shouldShowTurn = opponent === 'local' ? !state.isGameOver : !state.isGameOver && isHumanTurn

    if (!shouldShowTurn) {
      setShowTurnNotification(false)
      return
    }

    setShowTurnNotification(true)
    const timer = setTimeout(() => {
      setShowTurnNotification(false)
    }, 2500)

    return () => clearTimeout(timer)
  }, [opponent, isHumanTurn, state.isGameOver])

  const selectAdjacentPile = useCallback(
    (direction: 'left' | 'right') => {
      if (state.isGameOver || !canInteract) {
        return
      }

      const nonEmpty = state.piles.filter((p) => p.count > 0)
      if (nonEmpty.length === 0) {
        return
      }

      const currentIdx = nonEmpty.findIndex((p) => p.id === selectedPileId)
      const nextIdx =
        direction === 'right'
          ? currentIdx < 0
            ? 0
            : (currentIdx + 1) % nonEmpty.length
          : currentIdx <= 0
            ? nonEmpty.length - 1
            : currentIdx - 1

      onObjectClick(nonEmpty[nextIdx].id, 0)
    },
    [state, canInteract, selectedPileId, onObjectClick],
  )

  const increaseSelection = useCallback(() => {
    if (state.isGameOver || !canInteract || selectedPileId === null) {
      return
    }
    const pile = state.piles.find((p) => p.id === selectedPileId)
    if (pile && selectedCount < pile.count) {
      onObjectClick(selectedPileId, selectedCount)
    }
  }, [state, canInteract, selectedPileId, selectedCount, onObjectClick])

  const decreaseSelection = useCallback(() => {
    if (state.isGameOver || !canInteract || selectedPileId === null) {
      return
    }
    if (selectedCount > 1) {
      onObjectClick(selectedPileId, selectedCount - 2)
    }
  }, [state, canInteract, selectedPileId, selectedCount, onObjectClick])

  const confirmSelection = useCallback(() => {
    if (canConfirm) {
      onConfirm()
    }
  }, [canConfirm, onConfirm])

  useKeyboardControls(
    [
      {
        action: 'moveLeft',
        keys: ['ArrowLeft', 'KeyA'],
        onTrigger: () => selectAdjacentPile('left'),
      },
      {
        action: 'moveRight',
        keys: ['ArrowRight', 'KeyD'],
        onTrigger: () => selectAdjacentPile('right'),
      },
      {
        action: 'moveUp',
        keys: ['ArrowUp', 'KeyW'],
        onTrigger: increaseSelection,
      },
      {
        action: 'moveDown',
        keys: ['ArrowDown', 'KeyS'],
        onTrigger: decreaseSelection,
      },
      {
        action: 'confirm',
        keys: ['Enter', 'NumpadEnter', 'Space'],
        onTrigger: confirmSelection,
      },
    ],
    {
      enabled: !state.isGameOver,
      ignoreInputs: true,
    },
  )

  return (
    <div
      className={cx(styles.root, isMobile && styles.rootMobile, state.isGameOver && styles.rootGameOver)}
      data-content-density={responsive.contentDensity}
    >
      {menuStats && (
        <div className={styles.menuScoreboard}>
          {opponent === 'local' ? (
            <>
              <div className={styles.menuScoreColumn}>
                <span className={styles.menuScoreCoin} role="img" aria-label="Player 1">
                  👤
                </span>
                <span className={styles.menuScoreValue}>{menuStats.pvp1Wins}</span>
                <span className={styles.menuScoreLabel}>PLAYER 1</span>
              </div>
              <div className={styles.menuScoreColumn}>
                <span className={styles.menuScoreCoin} role="img" aria-label="Player 2">
                  👤
                </span>
                <span className={styles.menuScoreValue}>{menuStats.pvp2Wins}</span>
                <span className={styles.menuScoreLabel}>PLAYER 2</span>
              </div>
              <div className={styles.menuScoreColumn}>
                <span className={styles.menuScoreCoin} role="img" aria-label="Best Streak">
                  🏆
                </span>
                <span className={styles.menuScoreValue}>{menuStats.bestStreakCount}</span>
                <span className={styles.menuScoreLabel}>
                  {menuStats.bestStreakWinner === 'player1' ? 'PLAYER 1 STREAK' : 'PLAYER 2 STREAK'}
                </span>
              </div>
            </>
          ) : (
            <>
              <div className={styles.menuScoreColumn}>
                <span className={styles.menuScoreCoin} role="img" aria-label="Player wins">
                  👤
                </span>
                <span className={styles.menuScoreValue}>{menuStats.wins}</span>
                <span className={styles.menuScoreLabel}>{t('mainMenu.wins')}</span>
              </div>
              <div className={styles.menuScoreColumn}>
                <span className={styles.menuScoreCoin} role="img" aria-label="Robot losses">
                  🤖
                </span>
                <span className={styles.menuScoreValue}>{menuStats.losses}</span>
                <span className={styles.menuScoreLabel}>{t('mainMenu.losses')}</span>
              </div>
              <div className={styles.menuScoreColumn}>
                <span className={styles.menuScoreCoin} role="img" aria-label="Best streak">
                  🏆
                </span>
                <span className={styles.menuScoreValue}>{menuStats.bestStreak}</span>
                <span className={styles.menuScoreLabel}>{t('mainMenu.bestStreak')}</span>
              </div>
            </>
          )}
        </div>
      )}

      {/* Piles */}
      <div className={styles.pilesArea}>
        {state.piles.map((pile) => {
          const isTakeDisabled = !canInteract || state.isGameOver || pile.count <= 0

          return (
            <div
              key={pile.id}
              className={cx(
                styles.pileColumn,
                state.lastMove?.pileId === pile.id && styles.lastMovePile,
              )}
            >
              <div
                className={styles.pileWrapper}
              >
                <PileToggle
                  id={pile.id}
                  count={pile.count}
                  selectedCount={selectedPileId === pile.id ? selectedCount : 0}
                  onObjectClick={onObjectClick}
                  disabled={!canInteract || state.isGameOver}
                />
              </div>
              {!readonlyView && (
                <button
                  className={cx(styles.takeAllBtn, isTakeDisabled && takeLockClass)}
                  onClick={() => {
                    if (isTakeDisabled) {
                      return
                    }
                    onObjectClick(pile.id, pile.count - 1)
                    onConfirm()
                  }}
                  aria-label={t('game.takeAllFromPile', { pile: pile.id + 1 })}
                  aria-disabled={isTakeDisabled}
                  tabIndex={isTakeDisabled ? -1 : 0}
                  disabled={isTakeDisabled}
                >
                  {selectedPileId === pile.id ? 'TAKE' : 'PICK'}
                </button>
              )}
            </div>
          )
        })}
      </div>

      {/* Bottom */}
      {readonlyView && onStartVsAi && onStartLocal && (
        <div className={styles.menuStartActions}>
          <button
            type="button"
            className={styles.menuPrimaryBtn}
            onClick={onStartVsAi}
            aria-label={t('mainMenu.playVsAi')}
            title={t('mainMenu.playVsAi')}
          >
            <span className={styles.menuModeIconPair} aria-hidden="true">
              <span className={styles.menuModeIcon}>👤</span>
              <span className={styles.menuModeVs}>vs</span>
              <span className={styles.menuModeIcon}>🤖</span>
            </span>
          </button>
          <button
            type="button"
            className={styles.menuSecondaryBtn}
            onClick={onStartLocal}
            aria-label={t('mainMenu.twoPlayer')}
            title={t('mainMenu.twoPlayer')}
          >
            <span className={styles.menuModeIconPair} aria-hidden="true">
              <span className={styles.menuModeIcon}>👤</span>
              <span className={styles.menuModeVs}>vs</span>
              <span className={styles.menuModeIcon}>👤</span>
            </span>
          </button>
        </div>
      )}

      {!readonlyView && (
        <>
          {state.isGameOver ? (
            <>
              <StarExplosion isActive={state.isGameOver} palette={explosionPalette}>
                <div className={styles.winOverlay}>
                  <h2
                    className={cx(styles.winTitle, playerWon ? styles.winTitleWin : styles.winTitleLose)}
                    role="status"
                    aria-live="polite"
                    aria-atomic="true"
                  >
                    {getWinnerLabel(opponent, state.winner, t)}
                  </h2>
                </div>
              </StarExplosion>
            </>
          ) : (
            <>
              {showTurnNotification && (
                <div className={styles.turnNotificationOverlay}>
                  <div className={styles.turnNotificationContent}>
                    <h2 className={styles.turnNotificationText}>
                      {opponent === 'local' ? `PLAYER ${currentLocalPlayer}` : "IT'S YOUR TURN"}
                    </h2>
                  </div>
                </div>
              )}
              {cpuThinking && (
                <div
                  className={styles.cpuThinkingLabel}
                  role="status"
                  aria-live="polite"
                  aria-atomic="true"
                >
                  <div className={styles.cpuThinkingIcons}>
                    <span className={styles.cpuThinkingIcon}>🤖</span>
                    <span className={styles.cpuThinkingIcon}>⏳</span>
                    <span className={styles.cpuThinkingIcon}>🧠</span>
                  </div>
                </div>
              )}
            </>
          )}
        </>
      )}
    </div>
  )
}

/**
 * GameBoard memoized to prevent unnecessary re-renders when parent context updates.
 * Props are compared shallowly via React.memo() — as long as prop identity doesn't change,
