// Auto-generated by scripts/build-wasm-all.js — do not edit manually
// Rebuild with: pnpm wasm:build
// Source: assembly/index.ts → build/ai.wasm (0.9 KB, 917 bytes)

export const AI_WASM_BASE64 = '';

// Size: 0.9 KB (917 bytes)
// Encoded: 2026-04-02T00:45:31.024Z

import { selectMove, type Difficulty, type GameState } from '@/domain'
import { AI_WASM_BASE64 } from '@/wasm/ai-wasm'

// ============================================================================
// WASM AI Engine — loaded on startup, falls back to JS on failure
// ============================================================================

/** selectMove(p0..p7, numPiles, mode) → encoded move */
type WasmSelectMove = (
  p0: number,
  p1: number,
  p2: number,
  p3: number,
  p4: number,
  p5: number,
  p6: number,
  p7: number,
  numPiles: number,
  mode: number,
) => number

/** selectMoveBatch(p0..p7, numPiles, mode, iterations) → encoded move */
type WasmSelectMoveBatch = (
  p0: number,
  p1: number,
  p2: number,
  p3: number,
  p4: number,
  p5: number,
  p6: number,
  p7: number,
  numPiles: number,
  mode: number,
  iterations: number,
) => number

type AiExperimentVariant = 'off' | 'control' | 'batch'

interface AiExperimentConfig {
  variant: AiExperimentVariant
  batchSize: number
}

interface AiBenchmarkResult {
  variant: Exclude<AiExperimentVariant, 'off'>
  batchSize: number
  durationMs: number
}

interface WorkerRequest {
  state: GameState
  difficulty?: Difficulty
  experiment?: AiExperimentConfig
}

interface WorkerResponse {
  move: { pileId: number; removeCount: number }
  engine: 'wasm' | 'js'
  benchmark?: AiBenchmarkResult
}

let wasmSelectMove: WasmSelectMove | null = null
let wasmSelectMoveBatch: WasmSelectMoveBatch | null = null

/** Decode base64 WASM binary and instantiate the module */
async function initWasm(): Promise<void> {
  if (!AI_WASM_BASE64) {
    return
  }
  try {
    const binary = atob(AI_WASM_BASE64)
    const bytes = new Uint8Array(binary.length)
    for (let i = 0; i < binary.length; i++) {
      bytes[i] = binary.charCodeAt(i)
    }
    const imports = { env: { abort: () => {} } }
    const { instance } = await WebAssembly.instantiate(bytes, imports)
    wasmSelectMove = instance.exports.selectMove as WasmSelectMove
    wasmSelectMoveBatch = (instance.exports.selectMoveBatch as WasmSelectMoveBatch | undefined) ?? null
  } catch {
    // WASM unavailable — JS fallback will be used silently
  }
}

// Await WASM readiness before processing any message
const wasmReady = initWasm()

// ============================================================================
// Worker message handler
// ============================================================================

self.onmessage = async (e: MessageEvent<WorkerRequest>) => {
  const { state, difficulty = 'hard', experiment } = e.data
  if (!state) {
    return
  }

  // Ensure WASM has had a chance to load before first move
  await wasmReady

  let move: { pileId: number; removeCount: number }
  let engine: 'wasm' | 'js' = 'js'

  let benchmark: AiBenchmarkResult | undefined

  if (wasmSelectMove && difficulty === 'hard') {
    const counts = state.piles.map((p) => p.count)
    // Pad to 8 slots
    while (counts.length < 8) {
      counts.push(0)
    }
    const mode = state.mode === 'misere' ? 1 : 0

    const runSelectMove = () =>
      wasmSelectMove!(
        counts[0],
        counts[1],
        counts[2],
        counts[3],
        counts[4],
        counts[5],
        counts[6],
        counts[7],
        state.piles.length,
        mode,
      )

    const variant = experiment?.variant ?? 'off'
    const batchSize = Math.max(1, experiment?.batchSize ?? 1)
    let encoded = 0

    if (variant !== 'off' && batchSize > 1) {
      const start = performance.now()

      if (variant === 'batch' && wasmSelectMoveBatch) {
        encoded = wasmSelectMoveBatch(
          counts[0],
          counts[1],
          counts[2],
          counts[3],
          counts[4],
          counts[5],
          counts[6],
          counts[7],
          state.piles.length,
          mode,
          batchSize,
        )
      } else {
        for (let i = 0; i < batchSize; i++) {
          encoded = runSelectMove()
        }
      }

      benchmark = {
        variant: variant === 'batch' && wasmSelectMoveBatch ? 'batch' : 'control',
        batchSize,
        durationMs: performance.now() - start,
      }
    } else {
      encoded = runSelectMove()
    }

    move = { pileId: (encoded >> 8) & 0xffff, removeCount: encoded & 0xff }
    engine = 'wasm'
  } else {
    move = selectMove(state, difficulty)
  }

  const response: WorkerResponse = { move, engine }
  if (benchmark) {
    response.benchmark = benchmark
  }

  self.postMessage(response)
}

export {}

/**
 * Unit tests for usePatternDetection hook
 * Tests pattern detection logic and multiplier scoring
 */

import { act, renderHook } from '@testing-library/react'
import { beforeEach, describe, expect, it } from 'vitest'
import { usePatternDetection } from '../hooks'

describe('usePatternDetection', () => {
  let hook: ReturnType<typeof renderHook<typeof usePatternDetection>>

  beforeEach(() => {
    hook = renderHook(() => usePatternDetection())
  })

  describe('initial state', () => {
    it('starts with empty marked squares', () => {
      const { result } = hook
      expect(result.current.markedSquares.size).toBe(0)
    })

    it('starts with no detected patterns', () => {
      const { result } = hook
      expect(result.current.detectedPatterns).toEqual([])
    })

    it('starts with multiplier 1.0', () => {
      const { result } = hook
      expect(result.current.getNextMultiplier()).toBe(1.0)
    })

    it('starts with total score 0', () => {
      const { result } = hook
      expect(result.current.getTotalScore()).toBe(0)
    })
  })

  describe('square marking', () => {
    it('marks a square correctly', () => {
      const { result } = hook

      act(() => {
        result.current.markSquare(0)
      })

      expect(result.current.markedSquares.has(0)).toBe(true)
      expect(result.current.markedSquares.size).toBe(1)
    })

    it('unmarks a square correctly', () => {
      const { result } = hook

      act(() => {
        result.current.markSquare(0)
        result.current.unmarkSquare(0)
      })

      expect(result.current.markedSquares.has(0)).toBe(false)
      expect(result.current.markedSquares.size).toBe(0)
    })

    it('handles multiple marks and unmarks', () => {
      const { result } = hook

      act(() => {
        result.current.markSquare(0)
        result.current.markSquare(1)
        result.current.markSquare(2)
        result.current.unmarkSquare(1)
      })

      expect(result.current.markedSquares.has(0)).toBe(true)
      expect(result.current.markedSquares.has(1)).toBe(false)
      expect(result.current.markedSquares.has(2)).toBe(true)
      expect(result.current.markedSquares.size).toBe(2)
    })
  })

  describe('pattern detection - LINE', () => {
