      // Mark first column (indices 0, 5, 10, 15, 20)
      act(() => {
        for (let i = 0; i < 5; i++) {
          result.current.markSquare(i * 5)
        }
      })

      act(() => {
        const pattern = result.current.recordPattern()
        expect(pattern).not.toBeNull()
        expect(pattern?.type).toBe('LINE')
        expect(pattern?.coordinates).toEqual([
          [0, 0],
          [1, 0],
          [2, 0],
          [3, 0],
