            <span className={styles.value}>{remainingGuesses}</span>
          </div>
        </div>
      </div>

      <div className={styles.gameBoard}>
        <div className={styles.guessHistory}>
          {gameState.guesses.map((guessResult, index) => (
            <GuessRow key={index} guessResult={guessResult} />
          ))}
        </div>

        {isGameActive && (
          <div className={styles.currentGuessSection}>
            <h3 className={styles.sectionTitle}>Your Guess</h3>
            <CurrentGuess
              guess={currentGuess}
              codeLength={gameState.codeLength}
              onPegRemove={removePegFromGuess}
            />
            <ColorPalette
              availableColors={gameState.availableColors}
              onColorSelect={handleColorSelect}
              disabled={currentGuess.length >= gameState.codeLength}
            />
            <div className={styles.guessControls}>
              <button
                className={styles.controlButton}
                onClick={handleMakeGuess}
                disabled={!canMakeGuess}
                aria-label="Submit current guess"
              >
                Make Guess
              </button>
              <button
                className={styles.controlButton}
                onClick={clearCurrentGuess}
                disabled={currentGuess.length === 0}
                aria-label="Clear current guess"
              >
                Clear
              </button>
            </div>
          </div>
        )}
      </div>

      <div className={styles.gameControls}>
        <div className={styles.aiControls}>
          <button
            className={styles.aiButton}
            onClick={handleHint}
            disabled={!isGameActive}
            aria-label="Get a hint for the next guess"
          >
            Hint
          </button>
          <button
            className={styles.aiButton}
            onClick={handleAiGuess}
            disabled={!isGameActive}
            aria-label="Let AI make a guess"
          >
            AI Guess
          </button>
        </div>

        <div className={styles.gameManagement}>
          <button
            className={styles.resetButton}
            onClick={handleReset}
            aria-label="Reset current game"
          >
            Reset
          </button>
          <select
            className={styles.difficultySelect}
            onChange={(e) => handleNewGame(e.target.value)}
            value={gameState.difficulty}
            aria-label="Select difficulty for new game"
          >
            <option value="easy">Easy</option>
            <option value="medium">Medium</option>
            <option value="hard">Hard</option>
          </select>
        </div>
      </div>

      {showHint && hintGuess && (
        <div className={styles.hintDisplay} role="status" aria-live="polite">
          <p>💡 Hint: Try this combination:</p>
          <div className={styles.hintPegs}>
            {hintGuess.map((color, index) => (
              <div
                key={index}
                className={styles.hintPeg}
                style={{ backgroundColor: color }}
                aria-label={`Hint position ${index + 1}: ${color}`}
              />
            ))}
          </div>
        </div>
      )}

      {gameState.isGameWon && (
        <div className={styles.gameResult} role="status" aria-live="polite">
          🎉 Congratulations! You cracked the code in {gameState.guesses.length} guesses!
        </div>
      )}

      {gameState.isGameLost && (
        <div className={styles.gameResult} role="status" aria-live="polite">
          😞 Game Over! The secret code was: {gameState.secretCode.join(', ')}
        </div>
      )}

      <div className={styles.instructions}>
        <p>
          Crack the secret code! Choose colors and submit guesses. Black pegs = correct color and
          position, white pegs = correct color only.
        </p>
      </div>
    </div>
  )
}

/**
 * Unit tests for usePowerUpManager hook
 * Tests power-up inventory management and earning logic
 */

import { act, renderHook } from '@testing-library/react'
import { beforeEach, describe, expect, it } from 'vitest'
import { usePowerUpManager } from '../hooks'

describe('usePowerUpManager', () => {
  let hook: ReturnType<typeof renderHook<typeof usePowerUpManager>>

  beforeEach(() => {
    hook = renderHook(() => usePowerUpManager('medium'))
  })

  describe('initial state', () => {
    it('starts with empty power-up inventory', () => {
      const { result } = hook
      expect(result.current.inventory).toHaveLength(5)
      result.current.inventory.forEach((powerUp) => {
        expect(powerUp.usageCount).toBe(0)
        expect(powerUp.isActive).toBe(false)
      })
    })

    it('starts with zero patterns completed', () => {
      const { result } = hook
      expect(result.current.totalPatternsCompleted).toBe(0)
    })

    it('starts with zero power-ups earned', () => {
      const { result } = hook
      expect(result.current.totalPowerUpsEarned).toBe(0)
    })
  })

  describe('pattern completion recording', () => {
    it('increments pattern count', () => {
      const { result } = hook

      act(() => {
        result.current.recordPatternCompletion()
      })

      expect(result.current.totalPatternsCompleted).toBe(1)
    })

    it('awards power-ups based on earning rate', () => {
      const { result } = hook

      // Medium difficulty: 0.67 power-ups per pattern
      // Should earn 1 power-up after 2 patterns
      act(() => {
        result.current.recordPatternCompletion() // 1 pattern, 0.67 earned (0 awarded)
        result.current.recordPatternCompletion() // 2 patterns, 1.34 earned (1 awarded)
      })

      expect(result.current.totalPatternsCompleted).toBe(2)
      expect(result.current.totalPowerUpsEarned).toBe(1)
      expect(result.current.inventory.some((pu) => pu.usageCount > 0)).toBe(true)
    })

    it('awards multiple power-ups over time', () => {
      const { result } = hook

      // Medium difficulty: 0.67 power-ups per pattern
      act(() => {
        for (let i = 0; i < 5; i++) {
          result.current.recordPatternCompletion()
        }
      })

      expect(result.current.totalPatternsCompleted).toBe(5)
      expect(result.current.totalPowerUpsEarned).toBe(3) // 5 * 0.67 = 3.35, floor to 3
    })
  })

  describe('power-up activation', () => {
    beforeEach(() => {
      // Award some power-ups for testing
      act(() => {
        hook.result.current.recordPatternCompletion()
        hook.result.current.recordPatternCompletion()
      })
    })

    it('activates power-up when available', () => {
      const { result } = hook

      // Find a power-up that was awarded
      const availablePowerUp = result.current.inventory.find((pu) => pu.usageCount > 0)
      expect(availablePowerUp).toBeDefined()

      const initialCount = availablePowerUp!.usageCount

      act(() => {
        const activated = result.current.activatePowerUp(availablePowerUp!.type)
        expect(activated).toBe(true)
      })

      const updatedPowerUp = result.current.inventory.find(
        (pu) => pu.type === availablePowerUp!.type,
      )
      expect(updatedPowerUp!.usageCount).toBe(initialCount - 1)
      expect(updatedPowerUp!.isActive).toBe(true)
    })

    it('does not activate power-up when unavailable', () => {
      const { result } = hook

      // Find a power-up with zero uses
      const unavailablePowerUp = result.current.inventory.find((pu) => pu.usageCount === 0)
      expect(unavailablePowerUp).toBeDefined()

      act(() => {
        const activated = result.current.activatePowerUp(unavailablePowerUp!.type)
        expect(activated).toBe(false)
      })

      const updatedPowerUp = result.current.inventory.find(
        (pu) => pu.type === unavailablePowerUp!.type,
      )
      expect(updatedPowerUp!.usageCount).toBe(0)
      expect(updatedPowerUp!.isActive).toBe(false)
    })
  })

  describe('power-up deactivation', () => {
    it('deactivates an active power-up', () => {
      const { result } = hook

      // First activate a power-up
      act(() => {
        result.current.recordPatternCompletion()
        result.current.recordPatternCompletion()
      })

      const availablePowerUp = result.current.inventory.find((pu) => pu.usageCount > 0)
      expect(availablePowerUp).toBeDefined()

      act(() => {
        result.current.activatePowerUp(availablePowerUp!.type)
      })

      let updatedPowerUp = result.current.inventory.find((pu) => pu.type === availablePowerUp!.type)
      expect(updatedPowerUp!.isActive).toBe(true)

      // Now deactivate it
      act(() => {
        result.current.deactivatePowerUp(availablePowerUp!.type)
      })

      updatedPowerUp = result.current.inventory.find((pu) => pu.type === availablePowerUp!.type)
      expect(updatedPowerUp!.isActive).toBe(false)
    })
  })

  describe('remaining uses', () => {
    it('returns correct remaining uses', () => {
      const { result } = hook

      // Award some power-ups
      act(() => {
        result.current.recordPatternCompletion()
        result.current.recordPatternCompletion()
      })

      const availablePowerUp = result.current.inventory.find((pu) => pu.usageCount > 0)
      expect(availablePowerUp).toBeDefined()

      expect(result.current.getRemainingUses(availablePowerUp!.type)).toBe(
        availablePowerUp!.usageCount,
      )
    })

    it('returns 0 for unavailable power-ups', () => {
      const { result } = hook

      const unavailablePowerUp = result.current.inventory.find((pu) => pu.usageCount === 0)
      expect(unavailablePowerUp).toBeDefined()

      expect(result.current.getRemainingUses(unavailablePowerUp!.type)).toBe(0)
    })
  })

  describe('inventory management', () => {
    it('checks if inventory is full', () => {
      const { result } = hook

      expect(result.current.isInventoryFull()).toBe(false)

      // Fill inventory to maximum
      act(() => {
        for (let i = 0; i < 50; i++) {
          // More than enough to fill inventory
          result.current.recordPatternCompletion()
        }
      })

      expect(result.current.isInventoryFull()).toBe(true)
    })
  })

  describe('progress tracking', () => {
    it('calculates progress to next power-up', () => {
      const { result } = hook

      const progress = result.current.getProgressToNextPowerUp()
      expect(progress.patternsCompleted).toBe(0)
      expect(progress.patternsNeeded).toBe(2) // Medium difficulty: 1/0.67 ≈ 1.5, ceil to 2
      expect(progress.isNextAvailable).toBe(false)

      act(() => {
        result.current.recordPatternCompletion()
        result.current.recordPatternCompletion()
      })

      const updatedProgress = result.current.getProgressToNextPowerUp()
      expect(updatedProgress.patternsCompleted).toBe(2)
      expect(updatedProgress.isNextAvailable).toBe(true)
    })
  })

  describe('double points multiplier', () => {
    it('returns 1 when double points not active', () => {
      const { result } = hook
      expect(result.current.getDoublePointsMultiplier()).toBe(1)
    })

    it('returns 2 when double points is active', () => {
      const { result } = hook

      // Award and activate double points
      act(() => {
        result.current.recordPatternCompletion()
        result.current.recordPatternCompletion()
      })

      const doublePointsPowerUp = result.current.inventory.find((pu) => pu.type === 'DOUBLE_POINTS')
      if (doublePointsPowerUp && doublePointsPowerUp.usageCount > 0) {
        act(() => {
          result.current.activatePowerUp('DOUBLE_POINTS')
        })
        expect(result.current.getDoublePointsMultiplier()).toBe(2)
      } else {
        // If DOUBLE_POINTS wasn't awarded, test with a different power-up
        expect(result.current.getDoublePointsMultiplier()).toBe(1)
      }
    })
  })

  describe('reset functionality', () => {
    it('resets all state', () => {
      const { result } = hook

      // Build up some state
      act(() => {
        result.current.recordPatternCompletion()
        result.current.recordPatternCompletion()
      })

      expect(result.current.totalPatternsCompleted).toBe(2)
      expect(result.current.totalPowerUpsEarned).toBe(1)

      // Reset
      act(() => {
        result.current.resetManager()
      })

      expect(result.current.totalPatternsCompleted).toBe(0)
      expect(result.current.totalPowerUpsEarned).toBe(0)
      result.current.inventory.forEach((powerUp) => {
        expect(powerUp.usageCount).toBe(0)
        expect(powerUp.isActive).toBe(false)
      })
    })
  })

  describe('difficulty variations', () => {
    it('easy difficulty earns power-ups faster', () => {
      const easyHook = renderHook(() => usePowerUpManager('easy'))

      act(() => {
        easyHook.result.current.recordPatternCompletion() // 1 pattern, 1.0 earned (1 awarded)
      })

      expect(easyHook.result.current.totalPowerUpsEarned).toBe(1)
    })

    it('hard difficulty earns power-ups slower', () => {
      const hardHook = renderHook(() => usePowerUpManager('hard'))

      act(() => {
        hardHook.result.current.recordPatternCompletion() // 1 pattern, 0.5 earned (0 awarded)
        hardHook.result.current.recordPatternCompletion() // 2 patterns, 1.0 earned (1 awarded)
      })

      expect(hardHook.result.current.totalPowerUpsEarned).toBe(1)
    })

    it('expert difficulty earns power-ups slowest', () => {
      const expertHook = renderHook(() => usePowerUpManager('expert'))

      act(() => {
        for (let i = 0; i < 3; i++) {
          act(() => {
            expertHook.result.current.recordPatternCompletion()
          })
        } // 3 patterns, 3 * 0.33 = 0.99 earned (0 awarded)

        act(() => {
          expertHook.result.current.recordPatternCompletion()
        }) // 4 patterns, 4 * 0.33 = 1.32 earned (1 awarded)
      })

      expect(expertHook.result.current.totalPowerUpsEarned).toBe(1)
    })
  })
})

// Power Bingo app hooks barrel
export { usePowerUpManager as useGame } from './usePowerUpManager'
export type { PowerUp, PowerUpType } from './usePowerUpManager'

/**
 * useP owerUpManager — Hook for managing power-up inventory and activation
 * Strategic ability system with earning and spending mechanics
 */

import type { DifficultyConfig } from '@games/bingo-core'
import { useCallback, useState } from 'react'
import { POWER_UP_EARNING_RATES, POWER_UP_EFFECTS, POWER_UP_INVENTORY_MAX } from '../domain'

/**
 * Types of power-ups available in Power Bingo
 */
export type PowerUpType =
  | 'AUTO_MARK'
  | 'INSTANT_PATTERN'
  | 'DOUBLE_POINTS'
  | 'SHIELD'
  | 'TIME_EXTEND'

const POWER_UP_TYPES: PowerUpType[] = [
  'AUTO_MARK',
  'INSTANT_PATTERN',
  'DOUBLE_POINTS',
  'SHIELD',
  'TIME_EXTEND',
]

/**
 * Represents a single power-up in inventory
 */
export interface PowerUp {
  type: PowerUpType
  usageCount: number
  maxUsages: number
  isActive: boolean
}

/**
 * Hook for managing power-up inventory and activation
 *
 * Power-ups:
 * - AUTO_MARK: Auto-marks next 3 called numbers
 * - INSTANT_PATTERN: Completes any one pattern immediately
 * - DOUBLE_POINTS: Next pattern worth 2x points
 * - SHIELD: Prevents next penalty from being applied
 * - TIME_EXTEND: Extends round by X seconds (varies by variant)
 *
 * Earning Rates:
 * - easy: 1 power-up per pattern
 * - medium: 1 power-up per 1.5 patterns (0.67)
 * - hard: 1 power-up per 2 patterns (0.5)
 * - expert: 1 power-up per 3 patterns (0.33)
 */
export const usePowerUpManager = (difficulty: DifficultyConfig) => {
  const [inventory, setInventory] = useState<PowerUp[]>([
    { type: 'AUTO_MARK', usageCount: 0, maxUsages: POWER_UP_EFFECTS.AUTO_MARK, isActive: false },
    {
      type: 'INSTANT_PATTERN',
      usageCount: 0,
      maxUsages: POWER_UP_EFFECTS.INSTANT_PATTERN,
      isActive: false,
    },
    {
      type: 'DOUBLE_POINTS',
      usageCount: 0,
      maxUsages: POWER_UP_EFFECTS.DOUBLE_POINTS,
      isActive: false,
    },
    { type: 'SHIELD', usageCount: 0, maxUsages: POWER_UP_EFFECTS.SHIELD, isActive: false },
    {
      type: 'TIME_EXTEND',
      usageCount: 0,
      maxUsages: POWER_UP_EFFECTS.TIME_EXTEND,
      isActive: false,
    },
  ])

  const [totalPatternsCompleted, setTotalPatternsCompleted] = useState(0)
  const [totalPowerUpsEarned, setTotalPowerUpsEarned] = useState(0)

  /**
   * Gets the earning rate for current difficulty
   */
  const getEarningRate = useCallback(() => {
    return (
      POWER_UP_EARNING_RATES[difficulty as keyof typeof POWER_UP_EARNING_RATES] ||
      POWER_UP_EARNING_RATES.medium
    )
  }, [difficulty])

  /**
   * Records pattern completion and awards power-ups
   */
  const recordPatternCompletion = useCallback(() => {
    setTotalPatternsCompleted((prev) => {
      const newCount = prev + 1
      const earningRate = getEarningRate()

      // Calculate how many power-ups should be earned
      const newEarned = Math.floor(newCount * earningRate)
      const previousEarned = Math.floor(prev * earningRate)
      const powerupsToAward = newEarned - previousEarned

      if (powerupsToAward > 0) {
        setTotalPowerUpsEarned((prevEarned) => prevEarned + powerupsToAward)
        awardRandomPowerUp(powerupsToAward)
      }

      return newCount
    })
  }, [getEarningRate])

  /**
   * Awards random power-ups to reach the target count
   */
  const awardRandomPowerUp = useCallback((count: number) => {
    setInventory((prev) => {
      const updated = [...prev]
      let awarded = 0

      for (let i = 0; i < count && awarded < POWER_UP_INVENTORY_MAX; i++) {
        // Find power-ups that can still be earned
        const availablePowerUps = updated.filter((pu) => pu.usageCount < pu.maxUsages)

        if (availablePowerUps.length === 0) {
          break
        } // Inventory full

        // Random selection from available
        const randomIndex = Math.floor(Math.random() * availablePowerUps.length)
        const selectedPowerUp = availablePowerUps[randomIndex]

        // Find and increment in original array
        const originalIndex = updated.findIndex((pu) => pu.type === selectedPowerUp.type)
        if (originalIndex !== -1) {
          updated[originalIndex] = {
            ...updated[originalIndex],
            usageCount: updated[originalIndex].usageCount + 1,
          }
          awarded++
        }
      }

      return updated
    })
  }, [])

  /**
   * Activates a power-up by type
   */
  const activatePowerUp = useCallback((type: PowerUpType): boolean => {
    setInventory((prev) => {
      const powerUpIndex = prev.findIndex((pu) => pu.type === type)

      if (powerUpIndex === -1 || prev[powerUpIndex].usageCount === 0) {
        return prev // Can't activate - not found or no uses left
      }

      const updated = [...prev]
      updated[powerUpIndex] = {
        ...updated[powerUpIndex],
        usageCount: updated[powerUpIndex].usageCount - 1,
        isActive: true,
      }

      return updated
    })

    return true
  }, [])

  /**
   * Deactivates a power-up (after use)
   */
  const deactivatePowerUp = useCallback((type: PowerUpType) => {
    setInventory((prev) => prev.map((pu) => (pu.type === type ? { ...pu, isActive: false } : pu)))
  }, [])

  /**
   * Gets count of remaining uses for a power-up
   */
  const getRemainingUses = useCallback(
    (type: PowerUpType): number => {
      const powerUp = inventory.find((pu) => pu.type === type)
      return powerUp?.usageCount || 0
    },
    [inventory],
  )

  /**
   * Checks if inventory is full
   */
  const isInventoryFull = useCallback(() => {
    const totalUses = inventory.reduce((sum, pu) => sum + pu.usageCount, 0)
    return totalUses >= POWER_UP_INVENTORY_MAX
  }, [inventory])

  /**
   * Gets next power-up to earn based on pattern progress
   */
  const getProgressToNextPowerUp = useCallback(() => {
    const rate = getEarningRate()
    const nextMilestone = (totalPowerUpsEarned + 1) / rate

    return {
      patternsNeeded: Math.ceil(nextMilestone - totalPatternsCompleted),
      patternsCompleted: totalPatternsCompleted,
      isNextAvailable: nextMilestone <= totalPatternsCompleted,
    }
  }, [totalPatternsCompleted, totalPowerUpsEarned, getEarningRate])

  /**
   * Gets multiplier for double points power-up
   */
  const getDoublePointsMultiplier = useCallback(() => {
    const doublePointsPowerUp = inventory.find((pu) => pu.type === 'DOUBLE_POINTS')
    return doublePointsPowerUp?.isActive ? 2 : 1
  }, [inventory])

  /**
   * Resets power-up manager for new game
   */
  const resetManager = useCallback(() => {
    setInventory([
      { type: 'AUTO_MARK', usageCount: 0, maxUsages: POWER_UP_EFFECTS.AUTO_MARK, isActive: false },
      {
        type: 'INSTANT_PATTERN',
        usageCount: 0,
        maxUsages: POWER_UP_EFFECTS.INSTANT_PATTERN,
        isActive: false,
      },
      {
        type: 'DOUBLE_POINTS',
        usageCount: 0,
        maxUsages: POWER_UP_EFFECTS.DOUBLE_POINTS,
        isActive: false,
      },
      { type: 'SHIELD', usageCount: 0, maxUsages: POWER_UP_EFFECTS.SHIELD, isActive: false },
      {
        type: 'TIME_EXTEND',
        usageCount: 0,
        maxUsages: POWER_UP_EFFECTS.TIME_EXTEND,
        isActive: false,
      },
    ])
    setTotalPatternsCompleted(0)
    setTotalPowerUpsEarned(0)
  }, [])

  /**
   * Computed progress to next power-up (0-1)
   */
  const progressInfo = getProgressToNextPowerUp()
  const progressToNextPowerUp = progressInfo.patternsCompleted / progressInfo.patternsNeeded

  /**
   * Next power-up type that will be earned
   */
  const nextPowerUpType = progressInfo.isNextAvailable
    ? POWER_UP_TYPES[totalPowerUpsEarned % POWER_UP_TYPES.length]
    : POWER_UP_TYPES[0]

  return {
    inventory,
    totalPatternsCompleted,
    totalPowerUpsEarned,
    recordPatternCompletion,
    activatePowerUp,
    deactivatePowerUp,
    getRemainingUses,
    isInventoryFull,
    getProgressToNextPowerUp,
    progressToNextPowerUp,
    nextPowerUpType,
    getDoublePointsMultiplier,
    resetManager,
  }
}

import { describe, expect, it } from 'vitest'
import {
