/**
 * Queens Game Hook
 * React hook for N-Queens game state management
 */

import { useCallback, useEffect, useState } from 'react'
import type { Difficulty, MoveResult, QueensState } from '../../domain'
import {
  BOARD_SIZES,
  countConflicts,
  createGameState,
  generatePuzzle,
  isBoardSolved,
  placeQueen,
  removeQueen,
  solveNQueens,
} from '../../domain'

export function useQueensGame(initialDifficulty: Difficulty = Difficulty.HARD) {
  const size = BOARD_SIZES[initialDifficulty]

  const [gameState, setGameState] = useState<QueensState>(() => ({
    id: `queens-${Date.now()}`,
    board: createGameState(size),
    size,
    isComplete: false,
    isSolved: false,
    moveCount: 0,
    startTime: Date.now(),
    hintCount: 0,
    mistakes: 0,
  }))

  // Update completion status
  useEffect(() => {
    const complete = gameState.board.every((pos) => pos !== -1)
    const solved = isBoardSolved(gameState.board)

    setGameState((prev) => ({
      ...prev,
      isComplete: complete,
      isSolved: solved,
    }))
  }, [gameState.board])

  const makeMove = useCallback((row: number, col: number): MoveResult => {
    setGameState((prev) => {
      const newBoard = [...prev.board]
      const result = placeQueen(newBoard, row, col)

      if (!result.success) {
        return {
          ...prev,
          mistakes: prev.mistakes + 1,
        }
      }

      return {
        ...prev,
        board: newBoard,
        moveCount: prev.moveCount + 1,
      }
    })

    return { success: true }
  }, [])

  const removeQueenAt = useCallback((row: number) => {
    setGameState((prev) => {
      const newBoard = [...prev.board]
      const success = removeQueen(newBoard, row)

      return success
        ? {
            ...prev,
            board: newBoard,
            moveCount: prev.moveCount + 1,
          }
        : prev
    })
  }, [])

  const resetGame = useCallback(() => {
    setGameState({
      id: `queens-${Date.now()}`,
      board: createGameState(size),
      size,
      isComplete: false,
      isSolved: false,
      moveCount: 0,
      startTime: Date.now(),
      hintCount: 0,
      mistakes: 0,
    })
  }, [size])

  const generateNewPuzzle = useCallback(
    (difficulty: 'easy' | 'medium' | 'hard' = 'medium') => {
      const puzzle = generatePuzzle(size, difficulty)
      setGameState({
        id: `queens-${Date.now()}`,
        board: puzzle,
        size,
        isComplete: false,
        isSolved: false,
        moveCount: 0,
        startTime: Date.now(),
        hintCount: 0,
        mistakes: 0,
      })
    },
    [size],
  )

  const solvePuzzle = useCallback(() => {
    const { solutions } = solveNQueens(size)
    if (solutions.length > 0) {
      setGameState((prev) => ({
        ...prev,
        board: solutions[0],
        isComplete: true,
        isSolved: true,
      }))
    }
  }, [size])

  const getHint = useCallback(() => {
    // Find first empty row and suggest a valid move
    for (let row = 0; row < size; row++) {
      if (gameState.board[row] === -1) {
        // Find valid columns for this row
        for (let col = 0; col < size; col++) {
          const testBoard = [...gameState.board]
          if (placeQueen(testBoard, row, col).success) {
            setGameState((prev) => ({
              ...prev,
              hintCount: prev.hintCount + 1,
            }))
            return { row, col }
          }
        }
        break
      }
    }
    return null
  }, [gameState.board, size])

  return {
    gameState,
    makeMove,
    removeQueenAt,
    resetGame,
    generateNewPuzzle,
    solvePuzzle,
    getHint,
    conflicts: countConflicts(gameState.board),
  }
}

/**
 * N-Queens AI Solver
 * Backtracking algorithm to solve N-Queens problem
 */

import { createEmptyBoard, isBoardSolved, isValidPlacement } from './rules'
import type { Board, SolutionStats } from './types'

/**
 * Solve N-Queens using backtracking
 */
export function solveNQueens(size: number): { solutions: Board[]; stats: SolutionStats } {
  const startTime = Date.now()
  const solutions: Board[] = []

  function backtrack(board: Board, row: number): void {
    if (row === size) {
      // Found a solution
      solutions.push([...board])
      return
    }

    for (let col = 0; col < size; col++) {
      if (isValidPlacement(board, row, col)) {
        board[row] = col
        backtrack(board, row + 1)
        board[row] = -1 // Backtrack
      }
    }
  }

  const board = createEmptyBoard(size)
  backtrack(board, 0)

  const endTime = Date.now()
  const stats: SolutionStats = {
    totalSolutions: solutions.length,
    timeToSolve: endTime - startTime,
    algorithm: 'backtracking',
  }

  return { solutions, stats }
}

/**
 * Find first solution using backtracking
 */
export function findFirstSolution(size: number): Board | null {
  function backtrack(board: Board, row: number): boolean {
    if (row === size) {return true}

    for (let col = 0; col < size; col++) {
      if (isValidPlacement(board, row, col)) {
        board[row] = col
        if (backtrack(board, row + 1)) {return true}
        board[row] = -1 // Backtrack
      }
    }
    return false
  }

  const board = createEmptyBoard(size)
  return backtrack(board, 0) ? board : null
}

/**
 * Check if a partial board can still lead to a solution
 */
export function isSolvable(board: Board): boolean {
  const size = board.length
  const placedQueens = board.filter((pos) => pos !== -1).length

  // If board is complete, check if it's solved
  if (placedQueens === size) {
    return isBoardSolved(board)
  }

  // For partial boards, we need to check if there's a valid placement for remaining queens
  // This is a simplified check - in practice, we'd need to run backtracking
  for (let row = 0; row < size; row++) {
    if (board[row] === -1) {
      const validMoves = []
      for (let col = 0; col < size; col++) {
        if (isValidPlacement(board, row, col)) {
          validMoves.push(col)
        }
      }
      if (validMoves.length === 0) {return false}
    }
  }

  return true
}

/**
 * Generate a puzzle by solving and then removing some queens
 */
export function generatePuzzle(
  size: number,
  difficulty: 'easy' | 'medium' | 'hard' = 'medium',
): Board {
  const solution = findFirstSolution(size)
  if (!solution) {return createEmptyBoard(size)}

  // Copy solution
  const puzzle = [...solution]

  // Remove queens based on difficulty
  const keepRatio = difficulty === 'easy' ? 0.7 : difficulty === 'medium' ? 0.5 : 0.3
  const queensToKeep = Math.floor(size * keepRatio)

  // Randomly remove queens
  const indices = Array.from({ length: size }, (_, i) => i)
  for (let i = indices.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1))
    ;[indices[i], indices[j]] = [indices[j], indices[i]]
  }

  // Keep only the specified number of queens
  for (let i = queensToKeep; i < size; i++) {
    puzzle[indices[i]] = -1
  }

  return puzzle
}

/**
 * N-Queens Rules & Validation
 * Core logic for N-Queens puzzle
 */

import type { Board, MoveResult } from './types'

/**
 * Create empty board
 */
export function createEmptyBoard(size: number): Board {
  return new Array(size).fill(-1)
}

/**
 * Check if queen placement is valid
 */
export function isValidPlacement(board: Board, row: number, col: number): boolean {
  for (let i = 0; i < row; i++) {
    // Check same column
    if (board[i] === col) {return false}

    // Check diagonals
    if (Math.abs(board[i] - col) === Math.abs(i - row)) {return false}
  }
  return true
}

/**
 * Check if board is complete (all queens placed)
 */
export function isBoardComplete(board: Board): boolean {
  return board.every((pos) => pos !== -1)
}

/**
 * Check if board is solved (complete and valid)
 */
export function isBoardSolved(board: Board): boolean {
  if (!isBoardComplete(board)) {return false}

  const size = board.length
  for (let row = 0; row < size; row++) {
    if (!isValidPlacement(board, row, board[row])) {return false}
  }
  return true
}

/**
 * Count conflicts on the board
 */
export function countConflicts(board: Board): number {
  let conflicts = 0
  const size = board.length

  for (let row = 0; row < size; row++) {
    const col = board[row]
    if (col === -1) {continue}

    for (let otherRow = row + 1; otherRow < size; otherRow++) {
      const otherCol = board[otherRow]
      if (otherCol === -1) {continue}

      // Same column
      if (col === otherCol) {conflicts++}

      // Same diagonal
      if (Math.abs(col - otherCol) === Math.abs(row - otherRow)) {conflicts++}
    }
  }

  return conflicts
}

/**
 * Place queen on board
 */
export function placeQueen(board: Board, row: number, col: number): MoveResult {
  if (row < 0 || row >= board.length || col < 0 || col >= board.length) {
    return { success: false, message: 'Invalid position' }
  }

  if (board[row] !== -1) {
    return { success: false, message: 'Queen already placed in this row' }
  }

  if (!isValidPlacement(board, row, col)) {
    return { success: false, message: 'Queen would be under attack' }
  }

  board[row] = col
  return { success: true, conflicts: countConflicts(board) }
}

/**
 * Remove queen from board
 */
export function removeQueen(board: Board, row: number): boolean {
  if (row < 0 || row >= board.length) {return false}

  board[row] = -1
  return true
}

/**
 * Get all valid moves for a row
 */
export function getValidMoves(board: Board, row: number): number[] {
  if (row < 0 || row >= board.length || board[row] !== -1) {return []}

  const validMoves: number[] = []
  for (let col = 0; col < board.length; col++) {
    if (isValidPlacement(board, row, col)) {
      validMoves.push(col)
    }
  }
  return validMoves
}

/**
 * Create initial game state
 */
export function createGameState(size: number = 8): Board {
  return createEmptyBoard(size)
}

