export const QueensGame: React.FC = () => {
  const [difficulty, setDifficulty] = useState<Difficulty>('hard')
  const {
    gameState,
    makeMove,
    removeQueenAt,
    resetGame,
    generateNewPuzzle,
    solvePuzzle,
    getHint,
    conflicts,
  } = useQueensGame(difficulty)

  const handleCellClick = (row: number, col: number) => {
    const currentQueen = gameState.board[row]

    if (currentQueen === col) {
      // Remove queen
