    } else if (currentQueen === -1) {
      // Place queen
      makeMove(row, col)
    }
    // If there's already a queen in this row but different column, do nothing
  }

  const handleDifficultyChange = (newDifficulty: Difficulty) => {
    setDifficulty(newDifficulty)
    resetGame()
  }

  const handleHint = () => {
    const hint = getHint()
    if (hint) {
      // Could highlight the suggested cell
      console.log('Hint:', hint)
    }
  }

  const getStatusClass = () => {
    if (gameState.isSolved) {return styles.success}
    if (gameState.isComplete) {return styles.error}
    return styles.info
  }

  return (
    <div className={styles.game}>
      <header className={styles.header}>
        <h1 className={styles.title}>N-Queens Puzzle</h1>
        <p className={styles.subtitle}>
          Place {gameState.size} queens on the board so no queen attacks another
        </p>
      </header>

      <div className={styles.controls}>
        <div className={styles.controlGroup}>
          <label className={styles.label} htmlFor="difficulty-select">
            Difficulty:
          </label>
          <select
            id="difficulty-select"
            className={styles.select}
            value={difficulty}
            onChange={(e) => handleDifficultyChange(e.target.value as Difficulty)}
          >
            <option value="easy">Easy (4×4)</option>
            <option value="medium">Medium (6×6)</option>
            <option value="hard">Hard (8×8)</option>
            <option value="expert">Expert (10×10)</option>
          </select>
        </div>
      </div>

      <div className={`${styles.status} ${getStatusClass()}`}>
        {gameState.isSolved
          ? '✅ Solved! Well done!'
          : gameState.isComplete
            ? '❌ Invalid solution - queens are attacking each other'
            : 'In Progress - place your queens'}
      </div>

      <StatsBar className={styles.stats}>
        <StatPill label="Moves" value={gameState.moveCount} />
        <StatPill label="Mistakes" value={gameState.mistakes} />
        <StatPill label="Hints" value={gameState.hintCount} />
        <StatPill label="Conflicts" value={conflicts} />
      </StatsBar>

      <QueensBoard
        board={gameState.board}
        onCellClick={handleCellClick}
        size={gameState.size}
        conflicts={conflicts}
      />

      <ActionBar className={styles.controls}>
        <Button
          className={`${styles.button} ${styles.secondary}`}
          variant="secondary"
          onClick={resetGame}
        >
          Reset
        </Button>
        <Button
          className={`${styles.button} ${styles.primary}`}
          variant="primary"
          onClick={() => generateNewPuzzle('medium')}
        >
          New Puzzle
        </Button>
        <Button
          className={`${styles.button} ${styles.secondary}`}
          variant="secondary"
          onClick={solvePuzzle}
        >
          Solve
        </Button>
        <Button
          className={`${styles.button} ${styles.secondary}`}
          variant="secondary"
          onClick={handleHint}
        >
          Hint
        </Button>
      </ActionBar>

      <div className={styles.instructions}>
        <h3>How to Play:</h3>
        <ul>
          <li>Click on a square to place a queen in that row</li>
          <li>Queens cannot attack each other (same row, column, or diagonal)</li>
          <li>Place one queen per row</li>
          <li>Click on a queen to remove it</li>
          <li>Use hints if you get stuck</li>
        </ul>
      </div>
    </div>
  )
}

import { createThemeContext } from '@games/theme-context'
import useTheme from './hooks/useTheme'

const { ThemeProvider, useThemeContext } = createThemeContext(useTheme)

export { ThemeProvider, useThemeContext }

import { useCallback, useEffect, useMemo, useRef, useState } from 'react'

import { useKeyboardControls, useGridNavigationInput } from '@games/app-hook-utils'
import { useResponsiveState } from '@games/ui-hooks'

import {
  BOARD_SIZE,
  buildReversiSignalProfile,
  countPieces,
  type Difficulty,
  type GameMode,
  type Position,
} from '@/domain'

import { vibrate } from '../haptics'
import { useSoundContext } from '../SoundContext'
import { useThemeContext } from '../ThemeContext'
import { useReversiGame } from './useReversiGame'
import { useSoundEffects } from './useSoundEffects'
import { useStats } from './useStats'

const DIFFICULTIES: readonly Difficulty[] = ['easy', 'medium', 'hard']

const modeLabel = (mode: GameMode): string =>
  mode === 'pvc' ? 'Player vs CPU' : 'Player vs Player'

const playerLabel = (player: 'black' | 'white'): string => (player === 'black' ? 'Black' : 'White')

export interface UseReversiAppReturn {
  board: ReturnType<typeof useReversiGame>['board']
  currentPlayer: ReturnType<typeof useReversiGame>['currentPlayer']
  validMoves: ReturnType<typeof useReversiGame>['validMoves']
  mode: ReturnType<typeof useReversiGame>['mode']
  difficulty: ReturnType<typeof useReversiGame>['difficulty']
  result: ReturnType<typeof useReversiGame>['result']
  moveCount: number
  passMessage: string | null
  cpuThinking: boolean
  isPlayerTurn: boolean
  counts: ReturnType<typeof countPieces>
  signalProfile: ReturnType<typeof buildReversiSignalProfile>
  stats: ReturnType<typeof useStats>
  responsive: ReturnType<typeof useResponsiveState>
  settings: ReturnType<typeof useThemeContext>['settings']
  soundEnabled: boolean
  showSplash: boolean
  boardVisible: boolean
  showRulesModal: boolean
  showSettingsModal: boolean
  showAboutModal: boolean
  focusedPosition: Position
  statusText: string
  canUndo: boolean
  canReset: boolean
  boardVisibleStyle: { opacity: number; pointerEvents: 'auto' | 'none'; transition: string }
  validMoveLookup: Set<string>
  handleSquarePress: (row: number, col: number) => void
  handleSplashFadeStart: () => void
  handleSplashComplete: () => void
  handleNewGame: () => void
  handleModeChange: (nextMode: GameMode) => void
  handleDifficultyChange: (nextDifficulty: Difficulty) => void
  handleToggleSound: () => void
  handleColorThemeChange: (themeId: string) => void
  handleThemeModeChange: (themeMode: string) => void
  handleColorblindChange: (colorblindMode: string) => void
  undo: () => void
  setShowRulesModal: (open: boolean) => void
  setShowSettingsModal: (open: boolean) => void
  setShowAboutModal: (open: boolean) => void
}

export const useReversiApp = (): UseReversiAppReturn => {
  const [showRulesModal, setShowRulesModal] = useState(false)
  const [showSettingsModal, setShowSettingsModal] = useState(false)
  const [showAboutModal, setShowAboutModal] = useState(false)
  const [showSplash, setShowSplash] = useState(true)
  const [boardVisible, setBoardVisible] = useState(false)
  const [focusedPosition, setFocusedPosition] = useState<Position>({ row: 0, col: 0 })
  const responsive = useResponsiveState()
  const {
    board,
    currentPlayer,
    validMoves,
    mode,
    difficulty,
    result,
    moveCount,
    passMessage,
    cpuThinking,
    isPlayerTurn,
    playMove,
    undo,
    resetGame,
    setMode,
    setDifficulty,
  } = useReversiGame()
  const counts = countPieces(board)
  const signalProfile = useMemo(
    () =>
      buildReversiSignalProfile({
        board,
        currentPlayer,
        validMoves,
        mode,
        difficulty,
        cpuThinking,
        result,
        moveCount,
      }),
    [board, cpuThinking, currentPlayer, difficulty, mode, moveCount, result, validMoves],
  )
  const { settings, setColorTheme, setColorblind, setMode: setThemeMode } = useThemeContext()
  const { soundEnabled, toggleSound } = useSoundContext()
  const sfx = useSoundEffects()
  const stats = useStats()
  const lastRecordedResult = useRef<string>('')

  const validMoveLookup = useMemo(() => {
    const lookup = new Set<string>()
    for (const move of validMoves) {
      lookup.add(`${move.position.row}:${move.position.col}`)
    }
    return lookup
  }, [validMoves])

  useEffect(() => {
    if (result.status === 'playing' || mode !== 'pvc') {
      lastRecordedResult.current = ''
      return
    }

    const signature = `${moveCount}:${result.status}:${result.status === 'win' ? result.winner : 'draw'}`
    if (lastRecordedResult.current === signature) {
      return
    }

    lastRecordedResult.current = signature

    if (result.status === 'draw') {
      stats.recordDraw()
      sfx.onConfirm()
      return
    }

    if (result.winner === 'black') {
      stats.recordWin()
      sfx.onWin()
      return
    }

    stats.recordLoss()
    sfx.onLose()
  }, [mode, moveCount, result, sfx, stats])

  const handleSquarePress = useCallback(
    (row: number, col: number): void => {
      if (!isPlayerTurn || cpuThinking) {
        return
      }

      const didPlay = playMove({ row, col })
      if (didPlay) {
        setFocusedPosition({ row, col })
        vibrate(10)
        sfx.onConfirm()
        return
      }

      sfx.onClick()
    },
    [cpuThinking, isPlayerTurn, playMove, sfx],
  )

  const statusText = useMemo(() => {
    if (result.status === 'win') {
      return `${playerLabel(result.winner)} wins (${result.black}-${result.white})`
    }

    if (result.status === 'draw') {
      return `Draw (${result.black}-${result.white})`
    }

    if (cpuThinking) {
      return 'CPU is thinking...'
    }

    return `${playerLabel(currentPlayer)} to move`
  }, [cpuThinking, currentPlayer, result])

  useGridNavigationInput(
    {
      onMove: (direction) => {
        if (result.status !== 'playing') {return}

        setFocusedPosition((current) => ({
          row: Math.max(0, Math.min(BOARD_SIZE - 1, direction === 'up' ? current.row - 1 : direction === 'down' ? current.row + 1 : current.row)),
          col: Math.max(0, Math.min(BOARD_SIZE - 1, direction === 'left' ? current.col - 1 : direction === 'right' ? current.col + 1 : current.col)),
        }))
      },
      onSelect: () => handleSquarePress(focusedPosition.row, focusedPosition.col),
    },
    {
      enabled: result.status === 'playing' && isPlayerTurn && !cpuThinking,
      includeWasd: true,
      allowRepeat: true,
      selectKeys: ['Space', 'Enter'],
    },
  )

  useKeyboardControls(
    [
      { action: 'new-game', keys: ['KeyN'], onTrigger: resetGame },
      { action: 'undo', keys: ['KeyU'], onTrigger: undo },
    ],
    { enabled: true },
  )

  const handleSplashFadeStart = useCallback(() => {
    setBoardVisible(true)
  }, [])

  const handleSplashComplete = useCallback(() => {
    setShowSplash(false)
  }, [])

  const handleNewGame = useCallback(() => {
    resetGame()
    setFocusedPosition({ row: 0, col: 0 })
  }, [resetGame])

  const handleModeChange = useCallback(
    (nextMode: GameMode) => {
      setMode(nextMode)
      handleNewGame()
    },
    [handleNewGame, setMode],
  )

  const handleDifficultyChange = useCallback(
    (nextDifficulty: Difficulty) => {
      setDifficulty(nextDifficulty)
      handleNewGame()
    },
    [handleNewGame, setDifficulty],
  )

  const handleColorThemeChange = useCallback(
    (themeId: string) => {
      setColorTheme(themeId)
    },
    [setColorTheme],
  )

  const handleThemeModeChange = useCallback(
    (themeMode: string) => {
      setThemeMode(themeMode)
    },
    [setThemeMode],
  )

  const handleColorblindChange = useCallback(
    (colorblindMode: string) => {
      setColorblind(colorblindMode)
    },
    [setColorblind],
  )

  return {
    board,
    currentPlayer,
    validMoves,
    mode,
    difficulty,
    result,
    moveCount,
    passMessage,
    cpuThinking,
    isPlayerTurn,
    counts,
    signalProfile,
    stats,
    responsive,
    settings,
    soundEnabled,
    showSplash,
    boardVisible,
    showRulesModal,
    showSettingsModal,
    showAboutModal,
    focusedPosition,
    statusText,
    canUndo: true,
    canReset: true,
    boardVisibleStyle: {
      opacity: boardVisible ? 1 : 0,
      pointerEvents: boardVisible ? 'auto' : 'none',
      transition: 'opacity 15s ease',
    },
    validMoveLookup,
    handleSquarePress,
    handleSplashFadeStart,
    handleSplashComplete,
    handleNewGame,
    handleModeChange,
    handleDifficultyChange,
    handleToggleSound: toggleSound,
    handleColorThemeChange,
    handleThemeModeChange,
    handleColorblindChange,
    undo,
    setShowRulesModal,
    setShowSettingsModal,
    setShowAboutModal,
  }
}

import { useCallback, useEffect, useMemo, useRef, useState } from 'react'

import {
  applyMove,
  canPlayerMove,
  CPU_DELAY_MS,
  createInitialBoard,
  evaluateGameResult,
  getValidMoves,
  otherPlayer,
  selectMove,
  type Board,
  type Difficulty,
  type GameMode,
  type GameResult,
  type Move,
  type Player,
  type Position,
} from '@/domain'
import { load, save } from '../storageService'

const MODE_KEY = 'reversi-mode'
const DIFFICULTY_KEY = 'reversi-difficulty'

interface HistoryEntry {
  board: Board
  currentPlayer: Player
  result: GameResult
  moveCount: number
  passMessage: string | null
}

export interface UseReversiGameReturn {
  board: Board
  currentPlayer: Player
  validMoves: Move[]
  mode: GameMode
  difficulty: Difficulty
  result: GameResult
  moveCount: number
  passMessage: string | null
  cpuThinking: boolean
  isPlayerTurn: boolean
  playMove: (position: Position) => boolean
  passTurn: () => boolean
  undo: () => void
  resetGame: () => void
  setMode: (mode: GameMode) => void
  setDifficulty: (difficulty: Difficulty) => void
}

const labelForPlayer = (player: Player): string => (player === 'black' ? 'Black' : 'White')

export function useReversiGame(): UseReversiGameReturn {
  const [board, setBoard] = useState<Board>(() => createInitialBoard())
  const [currentPlayer, setCurrentPlayer] = useState<Player>('black')
  const [mode, setModeState] = useState<GameMode>(() => load(MODE_KEY, 'pvc'))
  const [difficulty, setDifficultyState] = useState<Difficulty>(() =>
    load(DIFFICULTY_KEY, 'medium'),
  )
  const [result, setResult] = useState<GameResult>({ status: 'playing' })
  const [moveCount, setMoveCount] = useState(0)
  const [passMessage, setPassMessage] = useState<string | null>(null)
  const [cpuThinking, setCpuThinking] = useState(false)
  const [history, setHistory] = useState<HistoryEntry[]>([])

  const cpuTimerRef = useRef<number | null>(null)

  const validMoves = useMemo(() => {
    if (result.status !== 'playing') {
      return []
    }
    return getValidMoves(board, currentPlayer)
  }, [board, currentPlayer, result.status])

  const isPlayerTurn = mode === 'pvp' || currentPlayer === 'black'

  const resetGame = useCallback(() => {
    setBoard(createInitialBoard())
    setCurrentPlayer('black')
    setResult({ status: 'playing' })
    setMoveCount(0)
    setPassMessage(null)
    setCpuThinking(false)
    setHistory([])
    if (cpuTimerRef.current !== null) {
      window.clearTimeout(cpuTimerRef.current)
      cpuTimerRef.current = null
    }
  }, [])

  const setMode = useCallback((nextMode: GameMode) => {
    setModeState(nextMode)
    save(MODE_KEY, nextMode)
  }, [])

  const setDifficulty = useCallback((nextDifficulty: Difficulty) => {
    setDifficultyState(nextDifficulty)
    save(DIFFICULTY_KEY, nextDifficulty)
  }, [])

  const pushHistory = useCallback(() => {
    setHistory((prev) => [
      ...prev,
      {
        board,
        currentPlayer,
        result,
        moveCount,
        passMessage,
      },
    ])
  }, [board, currentPlayer, result, moveCount, passMessage])

  const playMove = useCallback(
    (position: Position): boolean => {
      if (result.status !== 'playing') {
        return false
      }

      const move = validMoves.find(
        (candidate) =>
          candidate.position.row === position.row && candidate.position.col === position.col,
      )

      if (!move) {
        return false
      }

      pushHistory()
      const nextBoard = applyMove(board, move, currentPlayer)
      const nextResult = evaluateGameResult(nextBoard)

      setBoard(nextBoard)
      setPassMessage(null)
      setMoveCount((prev) => prev + 1)
      setResult(nextResult)
      if (nextResult.status === 'playing') {
        setCurrentPlayer(otherPlayer(currentPlayer))
      }

      return true
    },
    [board, currentPlayer, pushHistory, result.status, validMoves],
  )

  const passTurn = useCallback((): boolean => {
    if (result.status !== 'playing') {
      return false
    }
    if (validMoves.length > 0) {
      return false
    }

    const opponent = otherPlayer(currentPlayer)
    if (!canPlayerMove(board, opponent)) {
      setResult(evaluateGameResult(board))
      return true
    }

    pushHistory()
    setCurrentPlayer(opponent)
    setPassMessage(`${labelForPlayer(currentPlayer)} has no valid moves and must pass.`)
    return true
  }, [board, currentPlayer, pushHistory, result.status, validMoves.length])

  const undo = useCallback(() => {
    if (history.length === 0) {
      return
    }

    const rollback = mode === 'pvc' ? Math.min(2, history.length) : 1
    const snapshot = history[history.length - rollback]
    if (!snapshot) {
      return
    }

    setBoard(snapshot.board)
    setCurrentPlayer(snapshot.currentPlayer)
    setResult(snapshot.result)
    setMoveCount(snapshot.moveCount)
    setPassMessage(snapshot.passMessage)
    setCpuThinking(false)
    setHistory((prev) => prev.slice(0, -rollback))
  }, [history, mode])

  useEffect(() => {
    if (result.status !== 'playing') {
      return
    }
    if (validMoves.length > 0) {
      return
    }
    void passTurn()
  }, [passTurn, result.status, validMoves.length])

  useEffect(() => {
    if (mode !== 'pvc' || currentPlayer !== 'white' || result.status !== 'playing') {
      return
    }
    if (validMoves.length === 0) {
      return
    }

    setCpuThinking(true)
    cpuTimerRef.current = window.setTimeout(() => {
      const selectedMove = selectMove(board, 'white', difficulty)
      if (selectedMove) {
        void playMove(selectedMove.position)
      }
      setCpuThinking(false)
      cpuTimerRef.current = null
    }, CPU_DELAY_MS)

    return () => {
      if (cpuTimerRef.current !== null) {
        window.clearTimeout(cpuTimerRef.current)
        cpuTimerRef.current = null
      }
      setCpuThinking(false)
    }
  }, [board, currentPlayer, difficulty, mode, playMove, result.status, validMoves.length])

  return {
    board,
    currentPlayer,
    validMoves,
    mode,
    difficulty,
    result,
    moveCount,
    passMessage,
    cpuThinking,
    isPlayerTurn,
    playMove,
    passTurn,
    undo,
    resetGame,
    setMode,
    setDifficulty,
  }
}

/**
 * AI move selection — CPU player logic.
 * Pure functions: given a board state, return the best move.
 */

import { countPieces, otherPlayer } from './board'
import { CORNERS, HARD_DEPTH, MEDIUM_DEPTH } from './constants'
import { applyMove, canPlayerMove, evaluateGameResult, getValidMoves } from './rules'
import type { Board, Difficulty, Move, Player } from './types'

const cornerSet = new Set(CORNERS.map(([row, col]) => `${row}:${col}`))

function evaluateBoard(board: Board, perspective: Player): number {
  const counts = countPieces(board)
  const own = perspective === 'black' ? counts.black : counts.white
  const opp = perspective === 'black' ? counts.white : counts.black
  const pieceDelta = own - opp

  const ownMoves = getValidMoves(board, perspective).length
  const oppMoves = getValidMoves(board, otherPlayer(perspective)).length
  const mobility = ownMoves - oppMoves

  let ownCorners = 0
  let oppCorners = 0
  for (const [row, col] of CORNERS) {
    const key = `${row}:${col}`
    if (!cornerSet.has(key)) {
      continue
    }
    const cell = board[row * 8 + col]
    if (cell === perspective) {
      ownCorners++
    } else if (cell === otherPlayer(perspective)) {
      oppCorners++
    }
  }

  return pieceDelta + mobility * 3 + (ownCorners - oppCorners) * 25
}

function minimax(
  board: Board,
  turn: Player,
  perspective: Player,
  depth: number,
  alpha: number,
  beta: number,
): { score: number; move: Move | null } {
  const result = evaluateGameResult(board)
  if (depth === 0 || result.status !== 'playing') {
    if (result.status === 'win') {
      return {
        score: result.winner === perspective ? 10_000 : -10_000,
        move: null,
      }
    }
    if (result.status === 'draw') {
      return { score: 0, move: null }
    }
    return { score: evaluateBoard(board, perspective), move: null }
  }

  const moves = getValidMoves(board, turn)
  if (moves.length === 0) {
    if (!canPlayerMove(board, otherPlayer(turn))) {
      return { score: evaluateBoard(board, perspective), move: null }
    }
    return minimax(board, otherPlayer(turn), perspective, depth - 1, alpha, beta)
  }

  const maximizing = turn === perspective
  let bestMove: Move | null = null

  if (maximizing) {
    let bestScore = -Infinity
    for (const move of moves) {
      const next = applyMove(board, move, turn)
      const { score } = minimax(next, otherPlayer(turn), perspective, depth - 1, alpha, beta)
      if (score > bestScore) {
        bestScore = score
        bestMove = move
      }
      alpha = Math.max(alpha, score)
      if (beta <= alpha) {
        break
      }
    }
    return { score: bestScore, move: bestMove }
  }

  let bestScore = Infinity
  for (const move of moves) {
    const next = applyMove(board, move, turn)
    const { score } = minimax(next, otherPlayer(turn), perspective, depth - 1, alpha, beta)
    if (score < bestScore) {
      bestScore = score
      bestMove = move
    }
    beta = Math.min(beta, score)
    if (beta <= alpha) {
      break
    }
  }
  return { score: bestScore, move: bestMove }
}

function chooseMediumMove(board: Board, player: Player, moves: Move[]): Move {
  const corner = moves.find((move) => cornerSet.has(`${move.position.row}:${move.position.col}`))
  if (corner) {
    return corner
  }

  return moves.reduce((best, move) => {
    const next = applyMove(board, move, player)
    const score = evaluateBoard(next, player) + move.flipped.length * 2
    const bestScore =
      evaluateBoard(applyMove(board, best, player), player) + best.flipped.length * 2
    return score > bestScore ? move : best
  })
}

export function selectMove(board: Board, player: Player, difficulty: Difficulty): Move | null {
  const moves = getValidMoves(board, player)
  if (moves.length === 0) {
    return null
  }

  if (difficulty === 'easy') {
    return moves[Math.floor(Math.random() * moves.length)] ?? null
  }

  if (difficulty === 'medium') {
    return chooseMediumMove(board, player, moves)
  }

  const { move } = minimax(board, player, player, HARD_DEPTH, -Infinity, Infinity)
  if (move) {
    return move
  }

  const mediumFallback = minimax(board, player, player, MEDIUM_DEPTH, -Infinity, Infinity).move
  return mediumFallback ?? moves[0] ?? null
}

/**
 * Board operations — pure functions for creating and manipulating game state.
 * No React, no DOM — purely functional transformations.
 */

import { BOARD_SIZE, TOTAL_CELLS } from './constants'
import type { Board, Cell, Player, Position } from './types'

const toIndex = (row: number, col: number): number => row * BOARD_SIZE + col

export function isOnBoard(row: number, col: number): boolean {
  return row >= 0 && row < BOARD_SIZE && col >= 0 && col < BOARD_SIZE
}

export function createBoard(): Board {
  return new Array<Cell>(TOTAL_CELLS).fill(null)
}

export function getCell(board: Board, row: number, col: number): Cell {
  if (!isOnBoard(row, col)) {
    return null
  }
  return board[toIndex(row, col)] ?? null
}

export function setCell(board: Board, row: number, col: number, value: Cell): Board {
  if (!isOnBoard(row, col)) {
    return board
  }
  const next = [...board]
  next[toIndex(row, col)] = value
  return next
}

export function createInitialBoard(): Board {
  const board = createBoard()
  const mid = BOARD_SIZE / 2
  let next = setCell(board, mid - 1, mid - 1, 'white')
  next = setCell(next, mid, mid, 'white')
  next = setCell(next, mid - 1, mid, 'black')
  next = setCell(next, mid, mid - 1, 'black')
  return next
}

export function countPieces(board: Board): { black: number; white: number; empty: number } {
  let black = 0
  let white = 0
  let empty = 0
  for (const cell of board) {
    if (cell === 'black') {
      black++
    } else if (cell === 'white') {
      white++
    } else {
      empty++
    }
  }
  return { black, white, empty }
}

export function otherPlayer(player: Player): Player {
  return player === 'black' ? 'white' : 'black'
}

export function positionsEqual(a: Position, b: Position): boolean {
  return a.row === b.row && a.col === b.col
}

