/**
 * Game rules — win/loss/draw detection.
 * Pure functions operating on domain types only.
 */

import { countPieces, getCell, isOnBoard, otherPlayer, setCell } from './board'
import { BOARD_SIZE, DIRECTIONS } from './constants'
import type { Board, GameResult, Move, Player, Position } from './types'

export function getFlippedPieces(board: Board, position: Position, player: Player): Position[] {
  if (
    !isOnBoard(position.row, position.col) ||
    getCell(board, position.row, position.col) !== null
  ) {
    return []
  }

  const opponent = otherPlayer(player)
  const flipped: Position[] = []

  for (const [dRow, dCol] of DIRECTIONS) {
    const line: Position[] = []
    let row = position.row + dRow
    let col = position.col + dCol

    while (isOnBoard(row, col)) {
      const cell = getCell(board, row, col)
      if (cell === opponent) {
        line.push({ row, col })
        row += dRow
        col += dCol
        continue
      }

      if (cell === player && line.length > 0) {
        flipped.push(...line)
      }
      break
    }
  }

  return flipped
}

export function isValidMove(board: Board, position: Position, player: Player): boolean {
  return getFlippedPieces(board, position, player).length > 0
}

export function getValidMoves(board: Board, player: Player): Move[] {
  const moves: Move[] = []
  for (let row = 0; row < BOARD_SIZE; row++) {
    for (let col = 0; col < BOARD_SIZE; col++) {
      const position = { row, col }
      const flipped = getFlippedPieces(board, position, player)
      if (flipped.length > 0) {
        moves.push({ position, flipped })
      }
    }
  }
  return moves
}

export function applyMove(board: Board, move: Move, player: Player): Board {
  let next = setCell(board, move.position.row, move.position.col, player)
  for (const flipped of move.flipped) {
    next = setCell(next, flipped.row, flipped.col, player)
  }
  return next
}

export function canPlayerMove(board: Board, player: Player): boolean {
  return getValidMoves(board, player).length > 0
}

export function isBoardFull(board: Board): boolean {
  return countPieces(board).empty === 0
}

export function evaluateGameResult(board: Board): GameResult {
  const counts = countPieces(board)
  const blackCanMove = canPlayerMove(board, 'black')
  const whiteCanMove = canPlayerMove(board, 'white')

  if (!isBoardFull(board) && (blackCanMove || whiteCanMove)) {
    return { status: 'playing' }
  }

  if (counts.black === counts.white) {
    return {
      status: 'draw',
      black: counts.black,
      white: counts.white,
    }
  }

  return {
    status: 'win',
    winner: counts.black > counts.white ? 'black' : 'white',
    black: counts.black,
    white: counts.white,
  }
}

import { countPieces } from './board'
import type { Board, Difficulty, GameMode, GameResult, Move, Player } from './types'

export interface ReversiSignalProfile {
  pressure: number
  intensity: number
  focus: number
  progress: number
}

export interface ReversiSignalInputs {
  board: Board
  currentPlayer: Player
  validMoves: readonly Move[]
  mode: GameMode
  difficulty: Difficulty
  cpuThinking: boolean
  result: GameResult
  moveCount: number
}

export function buildReversiSignalProfile(inputs: ReversiSignalInputs): ReversiSignalProfile {
  const counts = countPieces(inputs.board)
  const occupied = counts.black + counts.white
  const occupancy = occupied / inputs.board.length
  const mobility = inputs.validMoves.length
  const moveScarcity = mobility === 0 ? 1 : clamp01(1 - mobility / 12)
  const flipAverage =
    mobility > 0
      ? inputs.validMoves.reduce((sum, move) => sum + move.flipped.length, 0) / mobility
      : 0
  const flipLoad = clamp01(flipAverage / 8)
  const difficultyLoad = difficultyToLoad(inputs.difficulty)
  const turnLoad =
    inputs.mode === 'pvc' && inputs.currentPlayer === 'white'
      ? 0.75
      : inputs.cpuThinking
        ? 0.9
        : 0.45
  const endgameLoad = inputs.result.status === 'playing' ? occupancy : 1

  return {
    pressure: toPercent(occupancy * 0.4 + moveScarcity * 0.35 + turnLoad * 0.25),
    intensity: toPercent(
      clamp01(inputs.moveCount / 60) * 0.35 +
        difficultyLoad * 0.35 +
        (inputs.cpuThinking ? 1 : 0.25) * 0.2 +
        occupancy * 0.1,
    ),
    focus: toPercent(moveScarcity * 0.45 + flipLoad * 0.35 + (inputs.cpuThinking ? 1 : 0.35) * 0.2),
    progress: toPercent(endgameLoad),
  }
}

function difficultyToLoad(difficulty: Difficulty): number {
  switch (difficulty) {
    case 'easy':
      return 0.25
    case 'medium':
      return 0.6
    case 'hard':
      return 1
  }
}

function clamp01(value: number): number {
  return Math.min(1, Math.max(0, value))
}

function toPercent(value: number): number {
  return Math.round(clamp01(value) * 100)
}

