import styles from './App.module.css'
import { GameOver, GamePlayBoard, GameSetup } from './index'

function GameContent() {
  const { state } = useGameContext()
  const [isLoading, setIsLoading] = useState(true)

  useEffect(() => {
    const timer = setTimeout(() => setIsLoading(false), 2500)
    return () => clearTimeout(timer)
  }, [])

  if (isLoading) {
    return (
      <div className="stb-splash">
        <div className="stb-splash__orb"></div>
        <div className="stb-splash__grid"></div>
        <div className="stb-splash__content">
          <div className="stb-splash__badge">
            <div className="stb-splash__emoji">🛦</div>
          </div>
          <div className="stb-splash__eyebrow">Roll. Choose. Close.</div>
          <h1 className="stb-splash__title">Shut the Box</h1>
          <p className="stb-splash__subtitle">Close all box numbers before running out of moves</p>
          <div className="stb-splash__loading">
            <span className="stb-splash__dot"></span>
            <span className="stb-splash__dot"></span>
            <span className="stb-splash__dot"></span>
          </div>
        </div>
      </div>
    )
  }

  if (state.gamePhase === 'setup') {
    return <GameSetup />
  }

  if (state.gamePhase === 'gameOver') {
    return <GameOver winner={state.winner} players={state.players} />
  }

  return <GamePlayBoard />
}

export function App() {
  return (
    <GameProvider>
      <div className={styles.app}>
        <GameContent />
      </div>
    </GameProvider>
  )
}

import { useGameContext } from '@/app'
import type { Tile } from '@/domain'
import { Button, Dice } from '@/ui/atoms'
import { ScoreBoard, TileGrid } from '@/ui/molecules'
import { useState } from 'react'
import styles from './GamePlayBoard.module.css'

export function GamePlayBoard() {
  const { state, rollDice, selectTile, deselectTile, submitMove, endTurn, canUseOneDie } =
    useGameContext()
  const [isRolling, setIsRolling] = useState(false)
  const [diceValues, setDiceValues] = useState<{
    dice1: number
    dice2: number | null
  } | null>(null)

  const handleRoll = (useOneDie: boolean) => {
    setIsRolling(true)
    setTimeout(() => {
      const result = rollDice(useOneDie)
      setDiceValues(result)
      setIsRolling(false)
    }, 600)
  }

  const handleSelectTile = (tile: Tile) => {
    if (state.board.selectedTiles.includes(tile)) {
      deselectTile(tile)
    } else {
      selectTile(tile)
    }
  }

  const handleSubmitMove = () => {
    if (submitMove()) {
      setDiceValues(null)
    }
  }

  const handleEndTurn = () => {
    setDiceValues(null)
    endTurn()
  }

  const currentPlayer = state.players[state.currentPlayerIndex]
  const canSubmitMove =
    state.board.selectedTiles.length > 0 &&
    state.board.selectedTiles.reduce((sum, tile) => sum + tile, 0) === state.board.diceSum &&
    state.gamePhase === 'choosing'
  const showOneDieOption = canUseOneDie()

  return (
    <div className={styles.gameBoard}>
      <ScoreBoard players={state.players} currentPlayerIndex={state.currentPlayerIndex} />

      <div className={styles.playingSurface}>
        <div className={styles.tileBridge}>
          <TileGrid
            tiles={state.board.tiles}
            selectedTiles={state.board.selectedTiles}
            onTileClick={handleSelectTile}
          />
        </div>

        <div className={styles.currentPlayer}>
          <span>{currentPlayer.name}&rsquo;s Turn</span>
        </div>

        <Dice
          dice1={diceValues?.dice1}
          dice2={diceValues?.dice2}
          sum={state.board.diceSum}
          isRolling={isRolling}
        />

        {state.gamePhase === 'rolling' && (
          <div className={styles.actions}>
            {showOneDieOption ? (
              <>
                <Button onClick={() => handleRoll(true)} disabled={isRolling} variant="primary">
                  {isRolling ? 'Rolling...' : 'Roll 1 Die'}
                </Button>
                <Button onClick={() => handleRoll(false)} disabled={isRolling} variant="secondary">
                  {isRolling ? 'Rolling...' : 'Roll 2 Dice'}
                </Button>
              </>
            ) : (
              <Button
                onClick={() => handleRoll(false)}
                disabled={isRolling}
                variant="primary"
                fullWidth
              >
                {isRolling ? 'Rolling...' : 'Roll Dice'}
              </Button>
            )}
          </div>
        )}

        {state.gamePhase === 'choosing' && (
          <>
            <div className={styles.instruction}>
              Select tiles that sum to <strong>{state.board.diceSum}</strong>
            </div>

            <div className={styles.actions}>
              <Button onClick={handleSubmitMove} disabled={!canSubmitMove} variant="success">
                Submit Move
              </Button>
              <Button onClick={handleEndTurn} variant="secondary">
                End Turn
              </Button>
            </div>
          </>
        )}
      </div>
    </div>
  )
}

import { useGameContext } from '@/app'
import type { Player } from '@/domain'
import { Button } from '@/ui/atoms'
import { useState } from 'react'
import styles from './GameSetup.module.css'

export function GameSetup() {
  const { dispatch } = useGameContext()
  const [numPlayers, setNumPlayers] = useState(2)
  const [playerNames, setPlayerNames] = useState<string[]>(['Player 1', 'Player 2'])

  const handleNumPlayersChange = (num: number) => {
    setNumPlayers(num)
    setPlayerNames(Array.from({ length: num }, (_, i) => `Player ${i + 1}`))
  }

  const handleNameChange = (index: number, name: string) => {
    const newNames = [...playerNames]
    newNames[index] = name || `Player ${index + 1}`
    setPlayerNames(newNames)
  }

  const handleStartGame = () => {
    const players: Player[] = playerNames.map((name, index) => ({
      id: `player-${index}`,
      name,
      score: 0,
      isAI: false,
    }))
    dispatch({ type: 'INITIALIZE_GAME', players })
  }

  return (
    <div className={styles.setup}>
      <div className={styles.container}>
        <h1>Shut the Box</h1>
        <p className={styles.subtitle}>
          Roll dice, flip numbered tiles to match the total. Lowest score wins!
        </p>

        <div className={styles.section}>
          <h2>Number of Players</h2>
          <div className={styles.playerCount}>
            {[2, 3, 4].map((num) => (
              <button
                key={num}
                className={`${styles.countButton} ${numPlayers === num ? styles.active : ''}`}
                onClick={() => handleNumPlayersChange(num)}
              >
                {num}
              </button>
            ))}
          </div>
        </div>

        <div className={styles.section}>
          <h2>Player Names</h2>
          <div className={styles.playerNames}>
            {playerNames.map((name, index) => (
              <input
                key={index}
                type="text"
                value={name}
                onChange={(e) => handleNameChange(index, e.target.value)}
                placeholder={`Player ${index + 1}`}
                className={styles.nameInput}
              />
            ))}
          </div>
        </div>

        <Button
          onClick={handleStartGame}
          variant="success"
          fullWidth
          className={styles.startButton}
        >
          Start Game
        </Button>
      </div>
    </div>
  )
}

