  AppPhase,
  BoardConfig,
  Difficulty,
  Direction,
  GameMode,
  GameState,
  RunState,
} from '@/domain'
import {
  applyAIMoves,
  createInitialGameState,
  createRunState,
  enqueueDirection,
  gameTick,
  MODE_CONFIGS,
} from '@/domain'
import { useCallback, useEffect, useRef, useState } from 'react'
import { computeAIMovesAsync, initAI, terminateAI } from './aiService'
import { load, save } from './storageService'

const SETTINGS_KEY = 'snake-game-settings'
const BEST_SCORES_KEY = 'snake-best-scores'

interface PersistedSettings {
  mode: GameMode
  difficulty: Difficulty
  board: BoardConfig
  soundEnabled: boolean
}

export function useGame() {
  const [state, setState] = useState<GameState>(() => {
    const initial = createInitialGameState()
    const settings = load<Partial<PersistedSettings>>(SETTINGS_KEY, {})
    const bestScores = load(BEST_SCORES_KEY, initial.bestScores)
    return {
      ...initial,
      mode: settings.mode ?? initial.mode,
      difficulty: settings.difficulty ?? initial.difficulty,
      board: settings.board ?? initial.board,
      modeConfig: MODE_CONFIGS[settings.mode ?? initial.mode],
      bestScores,
    }
  })

  const stateRef = useRef(state)
  stateRef.current = state

  const tickTimerRef = useRef<number | null>(null)
  const pendingAIRef = useRef<RunState | null>(null)

  // ─── Initialise AI worker on mount ──────────────────────

  useEffect(() => {
    initAI()
    return terminateAI
  }, [])

  // ─── Persist settings on change ─────────────────────────

  const { mode, difficulty, board } = state
  useEffect(() => {
    save(SETTINGS_KEY, { mode, difficulty, board })
  }, [mode, difficulty, board])

  useEffect(() => {
    save(BEST_SCORES_KEY, state.bestScores)
  }, [state.bestScores])

  // ─── Tick Loop ──────────────────────────────────────────

  const stopTick = useCallback(() => {
    if (tickTimerRef.current !== null) {
      clearTimeout(tickTimerRef.current)
      tickTimerRef.current = null
    }
  }, [])

  const scheduleTick = useCallback(() => {
    stopTick()
    const s = stateRef.current
    if (s.phase !== 'playing' || !s.run) {
      return
    }

    const speed = s.run.speed
    tickTimerRef.current = window.setTimeout(() => {
      const prev = stateRef.current
      if (prev.phase !== 'playing' || !prev.run) {
        return
      }

      // Use pre-computed AI moves if available, else sync JS fallback
      let run: RunState = prev.run
      if (pendingAIRef.current) {
        // Merge AI direction queues into current state (preserving player input)
        const precomputed = pendingAIRef.current
        run = {
          ...prev.run,
          players: prev.run.players.map((p) => {
            if (!p.isAI) {
              return p
            }
            const aiP = precomputed.players.find((ap) => ap.id === p.id)
            return aiP ? { ...p, directionQueue: aiP.directionQueue } : p
          }),
        }
        pendingAIRef.current = null
      } else if (prev.modeConfig.aiCount > 0) {
        // Sync JS fallback when no pre-computed moves arrived
        run = applyAIMoves(run, prev.board, prev.modeConfig, prev.difficulty)
      }

      const nextRun = gameTick(run, prev.board, prev.modeConfig)

      let nextState: GameState = { ...prev, run: nextRun }

      if (nextRun.outcome) {
        const playerScore = nextRun.players.find((p) => p.id === 'player')?.score ?? 0
        if (playerScore > prev.bestScores[prev.mode]) {
          nextState = {
            ...nextState,
            bestScores: { ...prev.bestScores, [prev.mode]: playerScore },
          }
        }
        if (nextRun.outcome.kind === 'win' && 'winnerId' in nextRun.outcome) {
          const wid = nextRun.outcome.winnerId
          nextState = {
            ...nextState,
            roundWins: {
              ...prev.roundWins,
              [wid]: (prev.roundWins[wid] ?? 0) + 1,
            },
          }
        }
        nextState = { ...nextState, phase: 'game-over' }
      }

      setState(nextState)

      // Pre-compute AI moves for the *next* tick asynchronously
      if (!nextRun.outcome && nextState.modeConfig.aiCount > 0 && nextRun) {
        computeAIMovesAsync(
          nextRun,
          nextState.board,
          nextState.modeConfig,
          nextState.difficulty,
        ).then((runWithAI) => {
          pendingAIRef.current = runWithAI
        })
      }

      // Schedule next tick
      scheduleTick()
    }, speed)
  }, [stopTick])

  // Start/stop tick loop based on phase
  useEffect(() => {
    if (state.phase === 'playing') {
      scheduleTick()
    } else {
      stopTick()
    }
    return stopTick
  }, [state.phase, scheduleTick, stopTick])

  // ─── Actions ────────────────────────────────────────────

  const turn = useCallback((direction: Direction) => {
    setState((prev) => {
      if (prev.phase !== 'playing' || !prev.run) {
        return prev
      }
      const updatedPlayers = prev.run.players.map((p) =>
        p.id === 'player' ? enqueueDirection(p, direction) : p,
      )
      return { ...prev, run: { ...prev.run, players: updatedPlayers } }
    })
  }, [])

  const startGame = useCallback(() => {
    setState((prev) => {
      const run = createRunState(prev.mode, prev.difficulty, prev.board)
      return {
        ...prev,
        phase: 'playing' as AppPhase,
        run,
        round: prev.mode === 'tron' ? prev.round + 1 : 1,
      }
    })
  }, [])

  const pause = useCallback(() => {
    setState((prev) => (prev.phase === 'playing' ? { ...prev, phase: 'paused' } : prev))
  }, [])

  const resume = useCallback(() => {
    setState((prev) => (prev.phase === 'paused' ? { ...prev, phase: 'playing' } : prev))
  }, [])

  const restart = useCallback(() => {
    setState((prev) => {
      const run = createRunState(prev.mode, prev.difficulty, prev.board)
      return { ...prev, phase: 'playing' as AppPhase, run }
    })
  }, [])

  const backToMenu = useCallback(() => {
    setState((prev) => ({
      ...prev,
      phase: 'menu' as AppPhase,
      run: null,
      round: 0,
      roundWins: {},
    }))
  }, [])

  const setMode = useCallback((mode: GameMode) => {
    setState((prev) => ({
      ...prev,
      mode,
      modeConfig: MODE_CONFIGS[mode],
    }))
  }, [])

  const setDifficulty = useCallback((difficulty: Difficulty) => {
    setState((prev) => ({ ...prev, difficulty }))
  }, [])

  const setBoardSize = useCallback((width: number, height: number) => {
    setState((prev) => ({
      ...prev,
      board: { ...prev.board, width, height },
    }))
  }, [])

  const toggleWrap = useCallback(() => {
    setState((prev) => ({
      ...prev,
      board: { ...prev.board, wrapMode: !prev.board.wrapMode },
    }))
  }, [])

  const setPhase = useCallback((phase: AppPhase) => {
    setState((prev) => ({ ...prev, phase }))
  }, [])

  return {
    state,
    turn,
    startGame,
    pause,
    resume,
    restart,
    backToMenu,
    setMode,
    setDifficulty,
    setBoardSize,
    toggleWrap,
    setPhase,
  }
}

import { useCallback, useEffect, useRef } from 'react'

import {
  isWasmActive,
  useGame,
  useKeyboardControls,
  useSoundEffects,
  useStats,
  useSwipe,
} from '@/app'
import { createDirectionalKeyboardBindings } from '@games/app-hook-utils'

export interface UseSnakeAppReturn {
  backToMenu: ReturnType<typeof useGame>['backToMenu']
  pause: ReturnType<typeof useGame>['pause']
  restart: ReturnType<typeof useGame>['restart']
  resume: ReturnType<typeof useGame>['resume']
  setBoardSize: ReturnType<typeof useGame>['setBoardSize']
  setDifficulty: ReturnType<typeof useGame>['setDifficulty']
  setMode: ReturnType<typeof useGame>['setMode']
  setPhase: ReturnType<typeof useGame>['setPhase']
  state: ReturnType<typeof useGame>['state']
  startGame: ReturnType<typeof useGame>['startGame']
  stats: ReturnType<typeof useStats>['stats']
  toggleWrap: ReturnType<typeof useGame>['toggleWrap']
  turn: ReturnType<typeof useGame>['turn']
  isWasmActive: boolean
}

export const useSnakeApp = (): UseSnakeAppReturn => {
  const {
    state,
    turn,
    startGame,
    pause,
    resume,
    restart,
    backToMenu,
    setMode,
    setDifficulty,
    setBoardSize,
    toggleWrap,
    setPhase,
  } = useGame()

  const sfx = useSoundEffects()
  const { stats, recordWin, recordLoss, resetStats } = useStats()

  const togglePause = useCallback(() => {
    if (state.phase === 'playing') {
      pause()
      sfx.onPause()
    } else if (state.phase === 'paused') {
      resume()
      sfx.onResume()
    }
  }, [state.phase, pause, resume, sfx])

  const closeOverlayToMenu = useCallback(() => {
    if (
      state.phase === 'settings' ||
      state.phase === 'help' ||
      state.phase === 'stats' ||
      state.phase === 'game-over'
    ) {
      backToMenu()
      sfx.onClick()
    }
  }, [state.phase, backToMenu, sfx])

  const keyboardBindings = createDirectionalKeyboardBindings(
    {
      up: () => turn('up'),
      down: () => turn('down'),
      left: () => turn('left'),
      right: () => turn('right'),
    },
    togglePause,
    () => {
      if (state.phase === 'playing' || state.phase === 'paused') {
        togglePause()
        return
      }

      closeOverlayToMenu()
    },
    {
      enabled: () => state.phase === 'playing' || state.phase === 'paused',
      confirmKeys: ['Space'],
      cancelKeys: ['Escape'],
      actionNames: {
        up: 'move-up',
        down: 'move-down',
        left: 'move-left',
        right: 'move-right',
        upAlt: 'move-up-alt',
        downAlt: 'move-down-alt',
        leftAlt: 'move-left-alt',
        rightAlt: 'move-right-alt',
        confirm: 'toggle-pause',
        cancel: 'escape',
      },
    },
  )

  useKeyboardControls(keyboardBindings)
  useSwipe(turn, state.phase === 'playing')

  const prevOutcomeRef = useRef(state.run?.outcome ?? null)

  useEffect(() => {
    const outcome = state.run?.outcome
    if (outcome && !prevOutcomeRef.current) {
      if (outcome.kind === 'win') {
        sfx.onWin()
        recordWin()
      } else {
        sfx.onLose()
        recordLoss()
      }
    }

    prevOutcomeRef.current = outcome ?? null
  }, [state.run?.outcome, sfx, recordWin, recordLoss])

  return {
    backToMenu,
    pause,
    restart,
    resume,
    setBoardSize,
    setDifficulty,
    setMode,
    setPhase,
    state,
    startGame,
    stats,
    toggleWrap,
    turn,
    isWasmActive: isWasmActive(),
  }
}

import { useCallback, useEffect, useState } from 'react'

import type { ColorTheme } from '@/domain/themes'
import { DEFAULT_SETTINGS } from '@/domain/themes'

import { load, save } from './storageService'

const STORAGE_KEY = 'snake-theme-settings'

interface PersistedThemeSettings {
  colorTheme: ColorTheme
}

const loadThemeSettings = (): PersistedThemeSettings => {
  const parsed = load<Partial<PersistedThemeSettings>>(STORAGE_KEY, {})
  return {
    colorTheme: parsed.colorTheme ?? DEFAULT_SETTINGS.colorTheme,
  }
}

const saveThemeSettings = (settings: PersistedThemeSettings): void => {
  save(STORAGE_KEY, settings)
}

const useTheme = () => {
  const [colorTheme, setColorThemeState] = useState<ColorTheme>(
    () => loadThemeSettings().colorTheme,
  )

  useEffect(() => {
    document.documentElement.setAttribute('data-theme', colorTheme)
    saveThemeSettings({ colorTheme })
  }, [colorTheme])

  const setColorTheme = useCallback((nextTheme: ColorTheme) => {
    setColorThemeState(nextTheme)
  }, [])

  return {
    colorTheme,
    setColorTheme,
  }
}

export default useTheme

/**
 * AI move selection — CPU player logic.
 * Pure functions: given a board state, return the best move.
 *
 * Strategy by difficulty:
 * - Easy: random valid move, occasional mistakes
 * - Normal: prefer safe moves, pursue food opportunistically
 * - Hard: flood-fill space evaluation, food pursuit, trapping
 */

import { addVec, isInBounds, posKey, wrapPos } from './board'
import {
  AI_MISTAKE_RATE,
  AI_REACTION_DELAY,
  DIRECTION_VECTORS,
  OPPOSITE_DIRECTION,
} from './constants'
import type {
  BoardConfig,
  Difficulty,
  Direction,
  ModeConfig,
  Pickup,
  PlayerEntity,
  RunState,
  Vec2,
} from './types'

// ─── Types ──────────────────────────────────────────────────

const DIRECTIONS: readonly Direction[] = ['up', 'down', 'left', 'right']

interface MoveCandidate {
  direction: Direction
  pos: Vec2
  safe: boolean
  foodDist: number
  space: number
}

// ─── Danger Check ───────────────────────────────────────────

function isCellDangerous(
  pos: Vec2,
  board: BoardConfig,
  config: ModeConfig,
  occupied: ReadonlySet<string>,
): boolean {
  if (config.wallIsFatal && !board.wrapMode && !isInBounds(pos, board)) {
    return true
  }
  return occupied.has(posKey(pos))
}

function getOccupied(run: RunState, board: BoardConfig, selfId?: string): ReadonlySet<string> {
  const set = new Set<string>(run.trails)
  for (const p of run.players) {
    for (const seg of p.segments) {
      set.add(posKey(seg))
    }
    // Mark opponent's likely next head positions as occupied so the AI
    // avoids head-on collisions and doesn't run into the opponent's path.
    if (selfId && p.id !== selfId && p.alive) {
      const head = p.segments[0]
      const dir = p.directionQueue.length > 0 ? p.directionQueue[0] : p.direction
      for (const d of DIRECTIONS) {
        if (d === (OPPOSITE_DIRECTION[dir] as Direction)) {
          continue
        }
        const delta = DIRECTION_VECTORS[d]
        let next = addVec(head, delta)
        if (board.wrapMode) {
          next = wrapPos(next, board)
        }
        set.add(posKey(next))
      }
    }
  }
  return set
}

// ─── Manhattan Distance ─────────────────────────────────────

function manhattan(a: Vec2, b: Vec2): number {
  return Math.abs(a.x - b.x) + Math.abs(a.y - b.y)
}

// ─── Flood Fill (space evaluation) ──────────────────────────

function floodFill(
  start: Vec2,
  board: BoardConfig,
  occupied: ReadonlySet<string>,
  maxDepth: number = 50,
): number {
  const visited = new Set<string>()
  const queue: Vec2[] = [start]
  visited.add(posKey(start))
  let count = 0

  while (queue.length > 0 && count < maxDepth) {
    const current = queue.shift()!
    count++

    for (const dir of DIRECTIONS) {
      const delta = DIRECTION_VECTORS[dir]
      let next: Vec2 = addVec(current, delta)
      if (board.wrapMode) {
        next = wrapPos(next, board)
      }

      const key = posKey(next)
      if (visited.has(key)) {
        continue
      }
      if (!isInBounds(next, board)) {
        continue
      }
      if (occupied.has(key)) {
        continue
      }

      visited.add(key)
      queue.push(next)
    }
  }

  return count
}

// ─── Nearest Food Distance ──────────────────────────────────

function nearestFoodDist(pos: Vec2, pickups: readonly Pickup[]): number {
  const foods = pickups.filter((p) => p.kind === 'food')
  if (foods.length === 0) {
    return Infinity
  }
  return Math.min(...foods.map((f) => manhattan(pos, f.pos)))
}

// ─── AI Decision ────────────────────────────────────────────

export function computeAIMove(
  player: PlayerEntity,
  run: RunState,
  board: BoardConfig,
  config: ModeConfig,
  difficulty: Difficulty,
): Direction {
  const head = player.segments[0]
  const occupied = getOccupied(run, board, player.id)
  const currentDir = player.direction
  const opposite = OPPOSITE_DIRECTION[currentDir] as Direction

  // Evaluate candidates
  const candidates: MoveCandidate[] = DIRECTIONS.filter((d) => d !== opposite).map((direction) => {
    const delta = DIRECTION_VECTORS[direction]
    let pos = addVec(head, delta)
    if (board.wrapMode) {
      pos = wrapPos(pos, board)
    }

    const safe = !isCellDangerous(pos, board, config, occupied)
    const foodDist = nearestFoodDist(pos, run.pickups)
    const space = safe ? floodFill(pos, board, occupied, difficulty === 'hard' ? 80 : 30) : 0

    return { direction, pos, safe, foodDist, space }
  })

  const safeMoves = candidates.filter((c) => c.safe)

  // Delayed reaction for easy mode
  if (difficulty === 'easy' && run.tick % (AI_REACTION_DELAY.easy + 1) !== 0) {
    return currentDir
  }

  // Random mistake
  if (Math.random() < AI_MISTAKE_RATE[difficulty]) {
    const validMoves = candidates.filter((c) => c.direction !== opposite)
    if (validMoves.length > 0) {
      return validMoves[Math.floor(Math.random() * validMoves.length)].direction
    }
  }

  if (safeMoves.length === 0) {
    // No safe move — pick any non-opposite
    return candidates.length > 0 ? candidates[0].direction : currentDir
  }

  // Hard: prefer most open space, break ties with food distance
  if (difficulty === 'hard') {
    safeMoves.sort((a, b) => {
      const spaceDiff = b.space - a.space
      if (Math.abs(spaceDiff) > 3) {
        return spaceDiff
      }
      return a.foodDist - b.foodDist
    })
    return safeMoves[0].direction
  }

  // Normal: prefer food, then space
  if (difficulty === 'normal') {
    safeMoves.sort((a, b) => {
      if (a.foodDist !== b.foodDist) {
        return a.foodDist - b.foodDist
      }
      return b.space - a.space
    })
    return safeMoves[0].direction
  }

  // Easy: random safe move
  return safeMoves[Math.floor(Math.random() * safeMoves.length)].direction
}

// ─── Apply AI Moves to Run State ────────────────────────────

export function applyAIMoves(
  run: RunState,
  board: BoardConfig,
  config: ModeConfig,
  difficulty: Difficulty,
): RunState {
  const updatedPlayers = run.players.map((p) => {
    if (!p.isAI || !p.alive) {
      return p
    }
    const dir = computeAIMove(p, run, board, config, difficulty)
    return {
      ...p,
      directionQueue: [dir],
    }
  })

  return { ...run, players: updatedPlayers }
}

/**
 * Board operations — pure functions for creating and manipulating game state.
 * No React, no DOM — purely functional transformations.
 */

import {
  DEFAULT_BOARD,
  DIRECTION_VECTORS,
  getStartPositions,
  MODE_CONFIGS,
  POWERUP_LIFETIME,
  SPEED_BY_DIFFICULTY,
} from './constants'
import type {
  BoardConfig,
  Difficulty,
  GameMode,
  GameState,
  Pickup,
  PickupKind,
  PlayerEntity,
  RunState,
  Vec2,
} from './types'

// ─── Helpers ────────────────────────────────────────────────

export const posKey = (p: Vec2): string => `${p.x},${p.y}`

export const posEqual = (a: Vec2, b: Vec2): boolean => a.x === b.x && a.y === b.y

export function addVec(a: Vec2, b: Vec2): Vec2 {
  return { x: a.x + b.x, y: a.y + b.y }
}

export function wrapPos(pos: Vec2, board: BoardConfig): Vec2 {
  return {
    x: ((pos.x % board.width) + board.width) % board.width,
    y: ((pos.y % board.height) + board.height) % board.height,
  }
}

export function isInBounds(pos: Vec2, board: BoardConfig): boolean {
  return pos.x >= 0 && pos.x < board.width && pos.y >= 0 && pos.y < board.height
}

// ─── Entity Creation ────────────────────────────────────────

export function createPlayer(
  id: string,
  pos: Vec2,
  direction: 'up' | 'down' | 'left' | 'right',
  isAI: boolean,
  initialLength: number = 3,
): PlayerEntity {
  const tailDir =
    DIRECTION_VECTORS[
      direction === 'up'
        ? 'down'
        : direction === 'down'
          ? 'up'
          : direction === 'left'
            ? 'right'
            : 'left'
    ]
  const segments: Vec2[] = []
  for (let i = 0; i < initialLength; i++) {
    segments.push({ x: pos.x + tailDir.x * i, y: pos.y + tailDir.y * i })
  }
  return {
    id,
    segments,
    direction,
    directionQueue: [],
    alive: true,
    score: 0,
    shield: 0,
    phase: 0,
    boost: 0,
    isAI,
  }
}

// ─── Trail Building ────────────────────────────────────────

export function buildTrailSet(players: readonly PlayerEntity[]): ReadonlySet<string> {
  const set = new Set<string>()
  for (const p of players) {
    // all segments except head are trail
    for (let i = 1; i < p.segments.length; i++) {
      set.add(posKey(p.segments[i]))
    }
  }
  return set
}

// ─── Random Position ────────────────────────────────────────

export function randomFreePos(
  board: BoardConfig,
  occupied: ReadonlySet<string>,
  rng: () => number = Math.random,
): Vec2 | null {
  const totalCells = board.width * board.height
  if (occupied.size >= totalCells) {
    return null
  }

  // Try random placement up to 100 times, then fallback to scan
  for (let i = 0; i < 100; i++) {
    const pos: Vec2 = {
      x: Math.floor(rng() * board.width),
      y: Math.floor(rng() * board.height),
    }
    if (!occupied.has(posKey(pos))) {
      return pos
    }
  }

  // Exhaustive fallback
  for (let y = 0; y < board.height; y++) {
    for (let x = 0; x < board.width; x++) {
      const pos: Vec2 = { x, y }
      if (!occupied.has(posKey(pos))) {
        return pos
      }
    }
  }
  return null
}

// ─── Pickup Spawning ────────────────────────────────────────

export function spawnPickup(
  kind: PickupKind,
  board: BoardConfig,
  occupied: ReadonlySet<string>,
  lifetime: number = 0,
): Pickup | null {
  const pos = randomFreePos(board, occupied)
  if (!pos) {
    return null
  }
  return { pos, kind, ticksRemaining: lifetime }
}

// ─── Occupied cells for spawning ────────────────────────────

export function getOccupiedSet(run: RunState): ReadonlySet<string> {
  const set = new Set<string>(run.trails)
  for (const p of run.players) {
    for (const seg of p.segments) {
      set.add(posKey(seg))
    }
  }
  for (const pk of run.pickups) {
    set.add(posKey(pk.pos))
  }
  return set
}

// ─── Initial Run State ──────────────────────────────────────

export function createRunState(
  mode: GameMode,
  difficulty: Difficulty,
  board: BoardConfig,
): RunState {
  const config = MODE_CONFIGS[mode]
  const totalPlayers = 1 + config.aiCount
  const starts = getStartPositions(board, totalPlayers)
  const players: PlayerEntity[] = []

  for (let i = 0; i < totalPlayers; i++) {
    const start = starts[i]
    players.push(
      createPlayer(
        i === 0 ? 'player' : `ai-${i}`,
        start.pos,
        start.direction,
        i > 0,
        mode === 'tron' ? 1 : 3,
      ),
    )
  }

  const speed = SPEED_BY_DIFFICULTY[difficulty]
  const run: RunState = {
    tick: 0,
    players,
    pickups: [],
    trails: buildTrailSet(players),
    speed,
    baseSpeed: speed,
    outcome: null,
  }

  // Spawn initial food if enabled
  if (config.foodEnabled) {
    const occupied = getOccupiedSet(run)
    const food = spawnPickup('food', board, occupied)
    if (food) {
      return { ...run, pickups: [food] }
    }
  }

  return run
}

// ─── Initial Game State ─────────────────────────────────────

export function createInitialGameState(): GameState {
  return {
    phase: 'boot',
    mode: 'hybrid',
    difficulty: 'normal',
    board: DEFAULT_BOARD,
    modeConfig: MODE_CONFIGS.hybrid,
    run: null,
    bestScores: { classic: 0, tron: 0, hybrid: 0 },
    soundEnabled: true,
    round: 0,
    roundWins: {},
  }
}

// ─── Pickup Tick (decrement timers, remove expired) ─────────

export function tickPickups(pickups: readonly Pickup[]): readonly Pickup[] {
  return pickups
    .map((p) => (p.ticksRemaining > 0 ? { ...p, ticksRemaining: p.ticksRemaining - 1 } : p))
    .filter((p) => p.ticksRemaining !== 0 || p.kind === 'food')
}

// ─── Maybe spawn a power-up ────────────────────────────────

export function maybeSpawnPowerUp(run: RunState, board: BoardConfig, chance: number): RunState {
  const hasPowerUp = run.pickups.some((p) => p.kind !== 'food')
  if (hasPowerUp) {
    return run
  }

  if (Math.random() >= chance) {
    return run
  }

  const kinds: PickupKind[] = ['shield', 'phase', 'boost']
  const kind = kinds[Math.floor(Math.random() * kinds.length)]
  const occupied = getOccupiedSet(run)
  const pickup = spawnPickup(kind, board, occupied, POWERUP_LIFETIME)
  if (!pickup) {
    return run
  }

  return { ...run, pickups: [...run.pickups, pickup] }
}

