      <div>
        {player && player.shield > 0 && (
          <span className={`${styles.powerUp} ${styles.shield}`}>Shield {player.shield}</span>
        )}
        {player && player.phase > 0 && (
          <span className={`${styles.powerUp} ${styles.phase}`}>Phase {player.phase}</span>
