/**
 * SettingsOverlay — unified settings panel.
 * Combines game mode, difficulty, wrap, theme, board size, and sound.
 */

import { useSoundContext, useThemeContext } from '@/app'
import type { ColorTheme, Difficulty, GameMode } from '@/domain'
import { BOARD_SIZES, COLOR_THEMES, DIFFICULTY_LABELS, MODE_LABELS } from '@/domain'
import styles from './Overlay.module.css'

const MODES: GameMode[] = ['hybrid', 'classic', 'tron']
const DIFFICULTIES: Difficulty[] = ['easy', 'normal', 'hard']

interface SettingsOverlayProps {
  mode: GameMode
  difficulty: Difficulty
  wrapMode: boolean
  boardWidth: number
  boardHeight: number
  onSetMode: (mode: GameMode) => void
  onSetDifficulty: (d: Difficulty) => void
  onToggleWrap: () => void
  onSetBoardSize: (w: number, h: number) => void
  onBack: () => void
}

export function SettingsOverlay({
  mode,
  difficulty,
  wrapMode,
  boardWidth,
  boardHeight,
  onSetMode,
  onSetDifficulty,
  onToggleWrap,
  onSetBoardSize,
  onBack,
}: SettingsOverlayProps) {
  const { colorTheme, setColorTheme } = useThemeContext()
  const { soundEnabled, toggleSound } = useSoundContext()

  return (
    <div className={styles.overlay}>
      <h1 className={styles.title}>Settings</h1>
      <div className={styles.settingsScroll}>
        <div className={styles.menu}>
          <div className={styles.label}>Game Mode</div>
          <div className={styles.selectorRow}>
            {MODES.map((m) => (
              <button
                key={m}
                className={m === mode ? styles.selectorBtnActive : styles.selectorBtn}
                onClick={() => onSetMode(m)}
              >
                {MODE_LABELS[m]}
              </button>
            ))}
          </div>

          <div className={styles.label}>Difficulty</div>
          <div className={styles.selectorRow}>
            {DIFFICULTIES.map((d) => (
              <button
                key={d}
                className={d === difficulty ? styles.selectorBtnActive : styles.selectorBtn}
                onClick={() => onSetDifficulty(d)}
              >
                {DIFFICULTY_LABELS[d]}
              </button>
            ))}
          </div>

          <div className={styles.label}>Wrap Mode</div>
          <div className={styles.row}>
            <button
              className={wrapMode ? styles.toggleBtnOn : styles.toggleBtn}
              onClick={onToggleWrap}
            >
              {wrapMode ? 'ON' : 'OFF'}
            </button>
          </div>

          <div className={styles.label}>Theme</div>
          <div className={styles.selectorRow}>
            {COLOR_THEMES.map((t) => (
              <button
                key={t}
                className={t === colorTheme ? styles.selectorBtnActive : styles.selectorBtn}
                onClick={() => setColorTheme(t as ColorTheme)}
              >
                {t}
              </button>
            ))}
          </div>

          <div className={styles.label}>Board Size</div>
          <div className={styles.selectorRow}>
            {BOARD_SIZES.map((b) => {
              const active = b.width === boardWidth && b.height === boardHeight
              return (
                <button
                  key={`${b.width}x${b.height}`}
                  className={active ? styles.selectorBtnActive : styles.selectorBtn}
                  onClick={() => onSetBoardSize(b.width, b.height)}
                >
                  {b.width}x{b.height}
                </button>
              )
            })}
          </div>

          <div className={styles.label}>Sound</div>
          <div className={styles.row}>
            <button
              className={soundEnabled ? styles.toggleBtnOn : styles.toggleBtn}
              onClick={toggleSound}
            >
              {soundEnabled ? 'ON' : 'OFF'}
            </button>
          </div>

          <button className={styles.menuBtn} onClick={onBack}>
            Close
          </button>
        </div>
      </div>
    </div>
  )
}

import { useSnakeApp } from '@/app'

import { SnakeSurface } from './SnakeSurface'

export default function App() {
  const app = useSnakeApp()

  return <SnakeSurface app={app} />
}

import type { UseSnakeAppReturn } from '@/app'
import { GameCanvas, HUD, OfflineIndicator } from '@/ui/atoms'
import {
  GameOverOverlay,
  HelpOverlay,
  MainMenu,
  PauseOverlay,
  SettingsOverlay,
  SplashScreen,
  StatsOverlay,
} from '@/ui/molecules'

const CELL_SIZE = 20

export function SnakeSurface({ app }: { app: UseSnakeAppReturn }) {
  const player = app.state.run?.players.find((p) => p.id === 'player')
  const bestScore = app.state.bestScores[app.state.mode]

  return (
    <div className="app">
      <OfflineIndicator />

      {app.state.phase === 'boot' && <SplashScreen onComplete={() => app.setPhase('menu')} />}

      {app.state.phase === 'menu' && (
        <MainMenu
          onPlay={() => {
            app.startGame()
          }}
          onSettings={() => {
            app.setPhase('settings')
          }}
          onHelp={() => {
            app.setPhase('help')
          }}
          onStats={() => {
            app.setPhase('stats')
          }}
        />
      )}

      {app.state.phase === 'settings' && (
        <SettingsOverlay
          mode={app.state.mode}
          difficulty={app.state.difficulty}
          wrapMode={app.state.board.wrapMode}
          boardWidth={app.state.board.width}
          boardHeight={app.state.board.height}
          onSetMode={(m) => {
            app.setMode(m)
          }}
          onSetDifficulty={(d) => {
            app.setDifficulty(d)
          }}
          onToggleWrap={() => {
            app.toggleWrap()
          }}
          onSetBoardSize={(w, h) => {
            app.setBoardSize(w, h)
          }}
          onBack={() => {
            app.backToMenu()
          }}
        />
      )}

      {app.state.phase === 'help' && <HelpOverlay onBack={() => app.backToMenu()} />}

      {app.state.phase === 'stats' && (
        <StatsOverlay
          stats={app.stats}
          bestScores={app.state.bestScores}
          onReset={() => {
            app.setPhase('stats')
          }}
          onBack={() => app.backToMenu()}
        />
      )}

      {(app.state.phase === 'playing' ||
        app.state.phase === 'paused' ||
        app.state.phase === 'game-over') &&
        app.state.run && (
          <div className="game-container">
            <HUD
              player={player}
              bestScore={bestScore}
              mode={app.state.mode}
              wasmActive={app.isWasmActive}
              wrapMode={app.state.board.wrapMode}
            />
            <GameCanvas
              board={app.state.board}
              players={app.state.run.players}
              pickups={app.state.run.pickups}
              trails={app.state.run.trails}
              cellSize={CELL_SIZE}
            />
          </div>
        )}

      {app.state.phase === 'paused' && (
        <PauseOverlay
          onResume={() => {
            app.resume()
          }}
          onRestart={() => {
            app.restart()
          }}
          onMenu={() => {
            app.backToMenu()
          }}
        />
      )}

      {app.state.phase === 'game-over' && app.state.run?.outcome && (
        <GameOverOverlay
          outcome={app.state.run.outcome}
          score={player?.score ?? 0}
          bestScore={bestScore}
          mode={app.state.mode}
          onRestart={() => {
            app.restart()
          }}
          onMenu={() => {
            app.backToMenu()
          }}
        />
      )}
    </div>
  )
}

