import { BOARD_SIZE, DEFAULT_PLAYERS, DICE_MAX, DICE_MIN, LADDERS, SNAKES } from './constants'
import type { BoardEffect, GameState, PlayerState } from './types'

export function createInitialState(players: readonly PlayerState[] = DEFAULT_PLAYERS): GameState {
  return {
    phase: 'playing',
    players: players.map((p) => ({ ...p })),
    currentPlayerIndex: 0,
    winnerId: null,
    winnerName: null,
    turnCount: 0,
    lastTurn: null,
  }
}

export function rollDie(rng: () => number = Math.random): number {
  return Math.floor(rng() * DICE_MAX) + DICE_MIN
}

export function validateRoll(roll: number): void {
  if (!Number.isInteger(roll) || roll < DICE_MIN || roll > DICE_MAX) {
    throw new RangeError(
      `Invalid roll ${roll}. Roll must be an integer from ${DICE_MIN} to ${DICE_MAX}.`,
    )
  }
}

export function resolveBoardEffect(position: number): BoardEffect | null {
  const ladderTo = LADDERS[position]
  if (ladderTo) {
    return { type: 'ladder', from: position, to: ladderTo }
  }

  const snakeTo = SNAKES[position]
  if (snakeTo) {
    return { type: 'snake', from: position, to: snakeTo }
  }

  return null
}

export function applyTurn(state: GameState, roll: number): GameState {
  validateRoll(roll)

  if (state.phase === 'game-over') {
    return state
  }

  const currentPlayer = state.players[state.currentPlayerIndex]
  const tentative = currentPlayer.position + roll
  const overshotFinish = tentative > BOARD_SIZE
  const landedPosition = overshotFinish ? currentPlayer.position : tentative
  const effect = overshotFinish ? null : resolveBoardEffect(landedPosition)
  const finalPosition = effect ? effect.to : landedPosition

  const nextPlayers = state.players.map((player, index) =>
    index === state.currentPlayerIndex ? { ...player, position: finalPosition } : player,
  )

  const won = finalPosition === BOARD_SIZE

  return {
    phase: won ? 'game-over' : 'playing',
    players: nextPlayers,
    currentPlayerIndex: won
      ? state.currentPlayerIndex
      : (state.currentPlayerIndex + 1) % state.players.length,
    winnerId: won ? currentPlayer.id : null,
    winnerName: won ? currentPlayer.name : null,
    turnCount: state.turnCount + 1,
    lastTurn: {
      playerId: currentPlayer.id,
      roll,
      startPosition: currentPlayer.position,
      endPosition: finalPosition,
      overshotFinish,
      effect,
    },
  }
}

import { applyTurn, createInitialState, resolveBoardEffect } from './rules'

describe('snakes-and-ladders rules', () => {
  it('moves player to ladder destination when landing at ladder base', () => {
    const initial = createInitialState([
      { id: 'human', name: 'You', position: 1 },
      { id: 'cpu', name: 'CPU', position: 1 },
    ])

    const next = applyTurn(initial, 3) // 1 -> 4, ladder 4 -> 14

    expect(next.players[0].position).toBe(14)
    expect(next.lastTurn?.effect?.type).toBe('ladder')
    expect(next.lastTurn?.effect?.from).toBe(4)
    expect(next.lastTurn?.effect?.to).toBe(14)
  })

  it('moves player to snake destination when landing on snake head', () => {
    const initial = createInitialState([
      { id: 'human', name: 'You', position: 16 },
      { id: 'cpu', name: 'CPU', position: 1 },
    ])

    const next = applyTurn(initial, 1) // 16 -> 17 (no snake) then next player
    const afterCpu = applyTurn(next, 6) // CPU 1 -> 7
    const forced = {
      ...afterCpu,
      players: [
        { ...afterCpu.players[0], position: 46 }, // human lands on 47
        afterCpu.players[1],
      ],
      currentPlayerIndex: 0,
    }
    const landedOnSnake = applyTurn(forced, 1)

    expect(landedOnSnake.players[0].position).toBe(26)
    expect(landedOnSnake.lastTurn?.effect?.type).toBe('snake')
  })

  it('keeps player in place when roll overshoots 100', () => {
    const initial = createInitialState([
      { id: 'human', name: 'You', position: 98 },
      { id: 'cpu', name: 'CPU', position: 1 },
    ])

    const next = applyTurn(initial, 5)
    expect(next.players[0].position).toBe(98)
    expect(next.lastTurn?.overshotFinish).toBe(true)
    expect(next.phase).toBe('playing')
  })

  it('ends game when player lands exactly on 100', () => {
    const initial = createInitialState([
      { id: 'human', name: 'You', position: 94 },
      { id: 'cpu', name: 'CPU', position: 1 },
    ])

    const next = applyTurn(initial, 6)
    expect(next.players[0].position).toBe(100)
    expect(next.phase).toBe('game-over')
    expect(next.winnerId).toBe('human')
  })

  it('returns null effect for normal squares', () => {
    expect(resolveBoardEffect(2)).toBeNull()
  })

  it('throws on invalid roll', () => {
    const initial = createInitialState()
    expect(() => applyTurn(initial, 0)).toThrow()
    expect(() => applyTurn(initial, 7)).toThrow()
  })
})

