import { useSnakesAndLaddersGame } from '@/app'
import { BOARD_SIZE, LADDERS, SNAKES } from '@/domain'
import { SplashScreen } from '@/ui'
import { useCallback, useMemo, useState } from 'react'

interface CellData {
  number: number
  hasLadder: boolean
  hasSnake: boolean
  humanHere: boolean
  cpuHere: boolean
}

function buildBoardRows(humanPosition: number, cpuPosition: number): CellData[][] {
  const rows: CellData[][] = []

  for (let row = 9; row >= 0; row--) {
    const start = row * 10 + 1
    const numbers = Array.from({ length: 10 }, (_, index) => start + index)
    const serpentine = row % 2 === 0 ? numbers : numbers.reverse()

    rows.push(
      serpentine.map((number) => ({
        number,
        hasLadder: Boolean(LADDERS[number]),
        hasSnake: Boolean(SNAKES[number]),
        humanHere: humanPosition === number,
        cpuHere: cpuPosition === number,
      })),
    )
  }

  return rows
}

export function App() {
  const [showSplash, setShowSplash] = useState(true)
  const { state, isRolling, rollForHuman, resetGame } = useSnakesAndLaddersGame()

  const handleSplashComplete = useCallback(() => {
    setShowSplash(false)
  }, [])

  const human = state.players[0]
  const cpu = state.players[1]
  const boardRows = useMemo(
    () => buildBoardRows(human.position, cpu.position),
    [cpu.position, human.position],
  )

  if (showSplash) {
    return <SplashScreen onComplete={handleSplashComplete} />
  }

  return (
    <div className="app">
      <header className="header">
        <h1>Snakes and Ladders</h1>
        <p className="subheading">Race to square {BOARD_SIZE}. Ladders help; snakes punish.</p>
      </header>

      <section className="statusCard" aria-live="polite">
        <p>
          <strong>Current turn:</strong> {state.players[state.currentPlayerIndex]?.name}
        </p>
        <p>
          <strong>You:</strong> {human.position} &nbsp;|&nbsp; <strong>CPU:</strong> {cpu.position}
        </p>
        {state.lastTurn && (
          <p>
            <strong>Last roll:</strong> {state.lastTurn.playerId === 'human' ? 'You' : 'CPU'} rolled{' '}
            {state.lastTurn.roll} and moved to {state.lastTurn.endPosition}
            {state.lastTurn.effect
              ? ` via ${state.lastTurn.effect.type} ${state.lastTurn.effect.from}→${state.lastTurn.effect.to}`
              : ''}
            {state.lastTurn.overshotFinish ? ' (overshot 100, stayed put)' : ''}
          </p>
        )}
        {state.phase === 'game-over' && (
          <p className="winnerMessage">
            Winner: <strong>{state.winnerName}</strong>
          </p>
        )}
      </section>

      <div className="controls">
        <button
          type="button"
          onClick={rollForHuman}
          disabled={
            isRolling ||
            state.phase !== 'playing' ||
            state.players[state.currentPlayerIndex]?.id !== 'human'
          }
        >
          {isRolling ? 'Rolling...' : 'Roll Dice'}
        </button>
        <button type="button" onClick={resetGame}>
          New Game
        </button>
      </div>

      <section className="board" role="grid" aria-label="Snakes and Ladders board">
        {boardRows.map((row, rowIndex) => (
          <div key={`row-${rowIndex}`} className="boardRow" role="row">
            {row.map((cell) => (
              <div
                key={cell.number}
                className="cell"
                role="gridcell"
                tabIndex={-1}
                aria-label={`Square ${cell.number}`}
              >
                <span className="cellNumber">{cell.number}</span>
                <div className="cellBadges">
                  {cell.hasLadder && <span title="Ladder">🪜</span>}
                  {cell.hasSnake && <span title="Snake">🐍</span>}
                </div>
                <div className="tokens">
                  {cell.humanHere && <span className="token human">You</span>}
                  {cell.cpuHere && <span className="token cpu">CPU</span>}
                </div>
              </div>
            ))}
          </div>
        ))}
      </section>
    </div>
  )
}

import { GRID_SIZE } from './constants'
import type { BingoCard, BingoCell, BingoColumn, WinningPattern } from './types'
import { COLUMNS, COLUMN_RANGES } from './types'

function pickUniqueInRange(min: number, max: number, count: number): number[] {
  const available = Array.from({ length: max - min + 1 }, (_, i) => i + min)
  const selected: number[] = []

  while (selected.length < count && available.length > 0) {
    const index = Math.floor(Math.random() * available.length)
    const [value] = available.splice(index, 1)
    selected.push(value)
  }

  return selected
}

function createRowCell(number: number | null, marked = false): BingoCell {
  return {
    number,
    marked,
    isFreeSpace: number === null,
  }
}

function generateCardGrid(): BingoCell[][] {
  const grid = Array.from({ length: GRID_SIZE }, () =>
    Array.from({ length: GRID_SIZE }, () => createRowCell(null)),
  )

  COLUMNS.forEach((column: BingoColumn, columnIndex) => {
    const [min, max] = COLUMN_RANGES[column]
    const numbers = pickUniqueInRange(min, max, GRID_SIZE)
    numbers.forEach((value, rowIndex) => {
      grid[rowIndex][columnIndex] = createRowCell(value)
    })
  })

  const center = Math.floor(GRID_SIZE / 2)
  grid[center][center] = createRowCell(null, true)

  return grid
}

function isLineMarked(cells: BingoCell[]): boolean {
  return cells.every((cell) => cell.marked || cell.isFreeSpace)
}

export function createBingoCard(): BingoCard {
  return {
    id: crypto.randomUUID(),
    grid: generateCardGrid(),
  }
}

export function createBingoCards(count: number): BingoCard[] {
  return Array.from({ length: count }, () => createBingoCard())
}

export function markNumber(card: BingoCard, number: number): void {
  for (let row = 0; row < GRID_SIZE; row++) {
    for (let col = 0; col < GRID_SIZE; col++) {
      const cell = card.grid[row][col]
      if (cell.number === number) {
        cell.marked = true
      }
    }
  }
}

export function checkWinningPatterns(card: BingoCard): WinningPattern[] {
  const patterns: WinningPattern[] = []

  for (let row = 0; row < GRID_SIZE; row++) {
    if (isLineMarked(card.grid[row])) {
      if (row === 0) {
        patterns.push('horizontal-top')
      }
      if (row === 2) {
        patterns.push('horizontal-middle')
      }
      if (row === GRID_SIZE - 1) {
        patterns.push('horizontal-bottom')
      }
    }
  }

  for (let col = 0; col < GRID_SIZE; col++) {
    const column = card.grid.map((row) => row[col])
    if (isLineMarked(column)) {
      if (col === 0) {
        patterns.push('vertical-left')
      }
      if (col === 2) {
        patterns.push('vertical-center')
      }
      if (col === GRID_SIZE - 1) {
        patterns.push('vertical-right')
      }
    }
  }

  const mainDiagonal = card.grid.map((row, index) => row[index])
  if (isLineMarked(mainDiagonal)) {
    patterns.push('diagonal-main')
  }

  const antiDiagonal = card.grid.map((row, index) => row[GRID_SIZE - 1 - index])
  if (isLineMarked(antiDiagonal)) {
    patterns.push('diagonal-anti')
  }

  const isFullHouse = card.grid.flat().every((cell) => cell.marked || cell.isFreeSpace)
  if (isFullHouse) {
    patterns.push('full-house')
  }

  return patterns
}

export function isWinner(card: BingoCard): boolean {
  return checkWinningPatterns(card).length > 0
}

