/**
 * Speed Bingo Card Component
 * Displays a 5x5 bingo card grid with marked cells and win indicators.
 */

import type { BingoCard as BingoCardType } from '@/domain'
import { useResponsiveState } from '@games/app-hook-utils'
import {
  BoardGrid,
  useKeyboardBoardNavigation,
  type BoardCell,
  type Position,
} from '@games/ui-board-core'
import React, { useMemo, useState } from 'react'
import styles from './BingoCard.module.css'

interface BingoCardProps {
  card: BingoCardType
  patterns?: string[]
  disabled?: boolean
  onCardClick?: (cardId: string) => void
  onCellClick?: (position: Position) => void
  hintPositions?: { row: number; col: number }[]
  showHints?: boolean
}

export const BingoCard: React.FC<BingoCardProps> = ({
  card,
  patterns,
  disabled,
  onCardClick,
  onCellClick,
  hintPositions = [],
  showHints = false,
}) => {
  const responsive = useResponsiveState()
  const [keyboardFocus, setKeyboardFocus] = useState<Position | null>(null)

  const handleCardClick = () => {
    if (!disabled && onCardClick) {
      onCardClick(card.id)
    }
  }

  const handleCellClick = (position: Position) => {
    if (onCellClick) {
      onCellClick(position)
    }
  }

  const getColumnLetter = (colIndex: number): string => {
    return ['B', 'I', 'N', 'G', 'O'][colIndex] || ''
  }

  // Keyboard navigation for the bingo card
  useKeyboardBoardNavigation({
    rows: 5,
    cols: 5,
    keyboardFocus,
    onFocusChange: setKeyboardFocus,
    onAction: () => {
      if (keyboardFocus) {
        handleCellClick(keyboardFocus)
      }
    },
    enabled: !disabled,
  })

  // Convert bingo card data to BoardGrid cells
  const cells: BoardCell[] = useMemo(() => {
    return card.grid.flatMap((row, rowIndex) =>
      row.map((cell, colIndex) => {
        const isHinted =
          showHints && hintPositions.some((pos) => pos.row === rowIndex && pos.col === colIndex)
        return {
          position: { row: rowIndex, col: colIndex },
          content: cell.isFreeSpace
            ? { type: 'text' as const, value: 'FREE' }
            : { type: 'number' as const, value: cell.number },
          state: {
            selected: cell.marked,
            highlighted: isHinted,
          },
          isDarkSquare: (rowIndex + colIndex) % 2 === 0,
          isPlayable: !disabled,
          ariaLabel: cell.isFreeSpace
            ? `Free space, ${cell.marked ? 'marked' : 'unmarked'}${isHinted ? ', hinted' : ''}`
            : `${cell.number}, column ${getColumnLetter(colIndex)}, ${cell.marked ? 'marked' : 'unmarked'}${isHinted ? ', hinted' : ''}`,
        }
      }),
    )
  }, [card.grid, disabled, hintPositions, showHints])

  return (
    <div
      className={`${styles.root} ${patterns && patterns.length > 0 ? styles.winner : ''} ${disabled ? styles.disabled : ''}`}
      onClick={handleCardClick}
      onKeyDown={(e) => {
        if (e.key === 'Enter' || e.key === ' ') {
          e.preventDefault()
          handleCardClick()
        }
      }}
      tabIndex={0}
      role="button"
      aria-label={`Speed bingo card ${card.id}`}
    >
      {/* Headers */}
      <div className={styles.headers}>
        {['B', 'I', 'N', 'G', 'O'].map((letter) => (
          <div key={letter} className={styles.header}>
            {letter}
          </div>
        ))}
      </div>

      {/* Grid using shared BoardGrid component */}
      <BoardGrid
        rows={5}
        cols={5}
        cells={cells}
        keyboardFocus={keyboardFocus}
        onCellClick={handleCellClick}
        className={styles.grid}
        ariaLabel={`Speed bingo card ${card.id} grid`}
        responsive={{
          touchOptimized: responsive.isMobile,
          supportsHover: responsive.supportsHover,
          compactViewport: responsive.compactViewport,
        }}
      />

      {/* Win Indicator */}
      {patterns && patterns.length > 0 && (
        <div className={styles.winIndicator}>
          <div className={styles.winLabel}>SPEED BINGO!</div>
          <div className={styles.patterns}>{patterns.join(', ')}</div>
        </div>
      )}
    </div>
  )
}

import { useCallback, useEffect } from 'react'

import { useGridNavigationInput } from '@games/app-hook-utils'

interface UseSudokuInputParams {
  selectedCell: { row: number; col: number } | undefined
  selectedDigit: 1 | 2 | 3 | 4 | 5 | 6 | 7 | 8 | 9
  onCellSelect: (row: number, col: number) => void
  onDigitSelect: (digit: 1 | 2 | 3 | 4 | 5 | 6 | 7 | 8 | 9) => void
  onApplyDigit: (value: number) => void
}

/**
 * Unified input handler for sudoku (9x9 grid)
 * Handles grid navigation (arrows + WASD) and digit input (1-9)
 * Grid wraps at boundaries (modulo behavior)
 */
export const useSudokuInput = ({
  selectedCell,
  onCellSelect,
  onApplyDigit,
}: UseSudokuInputParams): void => {
  const gridSize = 9 // 9x9 sudoku

  // Grid navigation with arrow keys and WASD (with wrapping)
  useGridNavigationInput(
    {
      onMove: (direction) => {
        const baseRow = selectedCell?.row ?? 0
        const baseCol = selectedCell?.col ?? 0

        let newRow = baseRow
        let newCol = baseCol

        if (direction === 'up') {
          newRow = (baseRow - 1 + gridSize) % gridSize
        } else if (direction === 'down') {
          newRow = (baseRow + 1) % gridSize
        } else if (direction === 'left') {
          newCol = (baseCol - 1 + gridSize) % gridSize
        } else if (direction === 'right') {
          newCol = (baseCol + 1) % gridSize
        }

        onCellSelect(newRow, newCol)
      },
    },
    { enabled: true, includeWasd: true, allowRepeat: true },
  )

  // Digit input (1-9 to apply, 0/Backspace to clear)
  useEffect(() => {
    const handleKeyDown = (event: KeyboardEvent) => {
      const key = event.key.toLowerCase()

      // Handle digit input 1-9
      if (key >= '1' && key <= '9') {
        event.preventDefault()
        onApplyDigit(parseInt(key, 10))
        return
      }

      // Handle clear (0, Backspace, Delete)
      if (key === '0' || key === 'backspace' || key === 'delete') {
        event.preventDefault()
        onApplyDigit(0)
        return
      }
    }

    window.addEventListener('keydown', handleKeyDown)
    return () => {
      window.removeEventListener('keydown', handleKeyDown)
    }
  }, [onApplyDigit])
}

