 * Feed a pet and return updated state
 */
export function feedPetMeal(
  state: PetState,
  minute: number = state.lifecycle.ageMinutes,
): PetState {
  return dispatchPetAction(state, {
    type: 'feedMeal',
    minute,
  })
}

