/**
 * Tango Board Component
 * Visual representation of the Tango slide puzzle board
 */

import React from 'react'
import type { Board, Position } from '../domain'
import styles from './TangoBoard.module.css'

interface TangoBoardProps {
  board: Board
  onTileClick: (position: Position) => void
  highlightedTile?: Position | null
  size: number
}

export const TangoBoard: React.FC<TangoBoardProps> = ({
  board,
  onTileClick,
  highlightedTile,
  size,
}) => {
  const renderTile = (row: number, col: number) => {
    const value = board[row][col]
    const isEmpty = value === 0
    const isHighlighted =
      highlightedTile && highlightedTile.row === row && highlightedTile.col === col

    let className = styles.tile
    if (isEmpty) {className += ` ${styles.empty}`}
    if (isHighlighted) {className += ` ${styles.highlighted}`}

    return (
      <div
        key={`${row}-${col}`}
        className={className}
        onClick={() => !isEmpty && onTileClick({ row, col })}
        role="button"
        tabIndex={isEmpty ? -1 : 0}
        aria-label={isEmpty ? 'Empty space' : `Tile ${value}`}
        onKeyDown={(e) => {
          if (!isEmpty && (e.key === 'Enter' || e.key === ' ')) {
            e.preventDefault()
            onTileClick({ row, col })
          }
        }}
      >
        {!isEmpty && <span className={styles.tileNumber}>{value}</span>}
      </div>
    )
  }

  return (
    <div
      className={styles.board}
      style={{ '--board-size': size } as React.CSSProperties}
      role="grid"
      aria-label={`Tango puzzle board of size ${size}x${size}`}
    >
      {board.map((row, rowIndex) => row.map((_, colIndex) => renderTile(rowIndex, colIndex)))}
    </div>
  )
}

/**
 * Tango Game Component
 * Main Tango slide puzzle interface
 */

import { ActionBar, Button, StatPill, StatsBar } from '@games/assets-shared'
import React, { useState } from 'react'
import { useTangoGame } from '../app'
import type { Difficulty, Position } from '../domain'
import { TangoBoard } from './TangoBoard'
import styles from './TangoGame.module.css'

export const TangoGame: React.FC = () => {
  const [difficulty, setDifficulty] = useState<Difficulty>('medium')
  const [showHint, setShowHint] = useState(false)
  const [hintTile, setHintTile] = useState<Position | null>(null)

  const {
    gameState,
    makeTileMove,
    canMove,
    resetGame,
    newPuzzle,
    getHint,
    solvePuzzle,
    solveCompletely,
    gameTime,
    isSolved,
    moveCount,
  } = useTangoGame(difficulty)

  const handleTileClick = (position: Position) => {
    if (canMove(position)) {
      makeTileMove(position)
      setShowHint(false)
      setHintTile(null)
    }
  }

  const handleHint = () => {
    const hint = getHint()
    if (hint) {
      setHintTile(hint)
      setShowHint(true)
      // Auto-hide hint after 3 seconds
      setTimeout(() => {
        setShowHint(false)
        setHintTile(null)
      }, 3000)
    }
  }

  const handleDifficultyChange = (newDifficulty: Difficulty) => {
    setDifficulty(newDifficulty)
    resetGame()
    setShowHint(false)
    setHintTile(null)
  }

  const formatTime = (seconds: number): string => {
    const mins = Math.floor(seconds / 60)
    const secs = seconds % 60
    return `${mins}:${secs.toString().padStart(2, '0')}`
  }

  return (
    <div className={styles.game}>
      <div className={styles.controls}>
        <div className={styles.controlGroup}>
          <label className={styles.label} htmlFor="difficulty-select">
            Difficulty:
          </label>
          <select
            id="difficulty-select"
            className={styles.select}
            value={difficulty}
            onChange={(e) => handleDifficultyChange(e.target.value as Difficulty)}
          >
            <option value="easy">Easy (3×3)</option>
            <option value="medium">Medium (4×4)</option>
            <option value="hard">Hard (5×5)</option>
            <option value="expert">Expert (6×6)</option>
          </select>
        </div>
      </div>

      <div className={`${styles.status} ${isSolved ? styles.success : styles.info}`}>
        {isSolved ? `🎉 Solved in ${formatTime(gameTime)} with ${moveCount} moves!` : null}
      </div>

      <StatsBar className={styles.stats}>
        <StatPill label="Moves" value={moveCount} />
        <StatPill label="Time" value={formatTime(gameTime)} />
        <StatPill label="Size" value={`${gameState.size}×${gameState.size}`} />
      </StatsBar>

      <TangoBoard
        board={gameState.board}
        onTileClick={handleTileClick}
        highlightedTile={showHint ? hintTile : null}
        size={gameState.size}
      />

