export interface UseGameBoardReturn {
  board: Board
  turn: Token
  focusedIndex: number
  gameState: GameState
  status: string
  gameStartTime: number | null
  moveHistory: Board[]
  currentMoveIndex: number
  canUndo: boolean
  canRedo: boolean
  handleHumanSelect: (index: number) => void
  handleFocusChange: (index: number) => void
  handleReset: () => void
  handleUndo: () => void
  handleRedo: () => void
  setFirstPlayer: (token: Token) => void
  dispatch: React.Dispatch<GameAction>
}

const useGameBoard = (): UseGameBoardReturn => {
  const [state, dispatch] = useReducer(gameReducer, null, createInitialState)

  const gameState = useMemo(() => getGameState(state.board), [state.board])

  useEffect(() => {
    if (state.gameStartTime === null && state.history.length > 1) {
      dispatch({ type: ACTIONS.SET_GAME_START_TIME, payload: Date.now() })
    }
  }, [state.history.length, state.gameStartTime])

  const status = useMemo(() => {
    if (gameState.winner) {
      return `${gameState.winner} wins!`
    }
    if (gameState.isDraw) {
      return 'Draw!'
    }
    return `${state.turn}'s turn`
  }, [gameState, state.turn])

  const handleHumanSelect = useCallback((index: number) => {
    dispatch({ type: ACTIONS.HUMAN_MOVE, payload: { index } })
  }, [])

  const handleFocusChange = useCallback((index: number) => {
    dispatch({ type: ACTIONS.SET_FOCUSED_INDEX, payload: index })
  }, [])

  const handleReset = useCallback(() => {
    dispatch({ type: ACTIONS.RESET })
  }, [])

  const handleUndo = useCallback(() => {
    dispatch({ type: ACTIONS.UNDO })
  }, [])

  const handleRedo = useCallback(() => {
    dispatch({ type: ACTIONS.REDO })
  }, [])

  const setFirstPlayer = useCallback((token: Token) => {
    dispatch({ type: ACTIONS.SET_FIRST_PLAYER, payload: token })
  }, [])

  return {
    board: state.board,
    turn: state.turn,
    focusedIndex: state.focusedIndex,
    gameState,
    status,
    gameStartTime: state.gameStartTime,
    moveHistory: state.history,
    currentMoveIndex: state.historyIndex,
    canUndo: state.historyIndex > 0,
    canRedo: state.historyIndex < state.history.length - 1,
    handleHumanSelect,
    handleFocusChange,
    handleReset,
    handleUndo,
    handleRedo,
    setFirstPlayer,
    dispatch,
  }
}

export default useGameBoard

import { useCallback, useEffect, useMemo, useState } from 'react'

import type { Board, GameState, Notification, Outcome } from '@/domain'
import { TOKENS } from '@/domain'
import usePrevious from './usePrevious.ts'

interface Sounds {
  playMove: () => void
  playWin: () => void
  playLoss: () => void
  playDraw: () => void
}

interface Notifications {
  enqueue: (notification: {
    message: string
    variant: string
    duration: number
    hasAction?: boolean
  }) => void
  clear: () => void
  updateCurrent: (updates: Partial<Notification>) => void
}

interface UseGameOrchestrationConfig {
  board: Board
  gameState: GameState
  secondsLeft: number | null
  notification: Notification | null
  sounds: Sounds
  notifications: Notifications
  outcomeStyles: Record<string, string | undefined>
  rootClass: string | undefined
  cx: (...args: (string | Record<string, unknown> | null | undefined | false)[]) => string
}

interface UseGameOrchestrationReturn {
  outcome: Outcome | null
  showConfetti: boolean
  setShowConfetti: React.Dispatch<React.SetStateAction<boolean>>
  showOutcomeOverlay: boolean
  handleOverlayDone: () => void
  containerClass: string
}

const useGameOrchestration = ({
  board,
  gameState,
  secondsLeft,
  notification,
  sounds,
  notifications,
  outcomeStyles,
  rootClass,
  cx,
}: UseGameOrchestrationConfig): UseGameOrchestrationReturn => {
  const [outcome, setOutcome] = useState<Outcome | null>(null)
  const [showConfetti, setShowConfetti] = useState(false)
  const [showOutcomeOverlay, setShowOutcomeOverlay] = useState(false)

  const prevBoard = usePrevious(board)
  const prevGameOver = usePrevious(gameState.isOver)

  useEffect(() => {
    const boardChanged = prevBoard !== undefined && prevBoard !== board
    const justEnded = gameState.isOver && !prevGameOver

    if (boardChanged && !justEnded) {
      sounds.playMove()
    }

    if (justEnded) {
      let outcomeType: Outcome = 'draw'
      if (gameState.winner === TOKENS.HUMAN) {
        sounds.playWin()
        outcomeType = 'win'
        setShowConfetti(true)
      } else if (gameState.winner === TOKENS.CPU) {
        sounds.playLoss()
        outcomeType = 'loss'
      } else {
        sounds.playDraw()
      }
      setOutcome(outcomeType)
      setShowOutcomeOverlay(true)
    }

    if (!gameState.isOver && prevGameOver) {
      setOutcome(null)
      setShowConfetti(false)
      setShowOutcomeOverlay(false)
      notifications.clear()
    }
  }, [board, gameState.isOver, gameState.winner, sounds, notifications, prevBoard, prevGameOver])

  useEffect(() => {
    if (notification?.variant === 'countdown' && secondsLeft !== null && secondsLeft > 0) {
      notifications.updateCurrent({
        message: `New game in ${secondsLeft} ${secondsLeft === 1 ? 'second' : 'seconds'}`,
      })
    }
  }, [secondsLeft, notification?.variant, notifications])

  const containerClass = useMemo(() => {
    const outcomeClass = outcome ? outcomeStyles[outcome] : null
    return cx(rootClass, outcomeClass)
  }, [outcome, outcomeStyles, rootClass, cx])

  const handleOverlayDone = useCallback(() => {
    setShowOutcomeOverlay(false)
    notifications.enqueue({
      message: 'New game in 15 seconds',
      variant: 'countdown',
      duration: 0,
      hasAction: true,
    })
  }, [notifications])

  return {
    outcome,
    showConfetti,
    setShowConfetti,
    showOutcomeOverlay,
    handleOverlayDone,
    containerClass,
  }
}

export default useGameOrchestration

import { useEffect, useState } from 'react'

import type { GameState, Score } from '@/domain'
import { TOKENS } from '@/domain'
import usePrevious from './usePrevious.ts'

interface UseGameStatsReturn {
  score: Score
  streak: number
  bestTime: number | null
}

const useGameStats = (
  gameState: GameState,
  historyIndex: number,
  gameStartTime: number | null,
): UseGameStatsReturn => {
  const [score, setScore] = useState<Score>({ X: 0, O: 0, draws: 0 })
  const [streak, setStreak] = useState(0)
  const [bestTime, setBestTime] = useState<number | null>(null)

  const prevGameOver = usePrevious(gameState.isOver)
  const prevHistoryIndex = usePrevious(historyIndex)

  useEffect(() => {
    const justEnded = gameState.isOver && !prevGameOver

    if (!justEnded) {
      return
    }

    const undoHappened = prevHistoryIndex !== undefined && historyIndex < prevHistoryIndex

    if (undoHappened && gameState.winner === TOKENS.HUMAN) {
      setStreak(0)
    }

    setScore((prev) => {
      const newScore = { ...prev }
      if (gameState.winner) {
        newScore[gameState.winner] = prev[gameState.winner] + 1

        if (gameState.winner === TOKENS.HUMAN && !undoHappened) {
          setStreak((s) => s + 1)
        } else if (gameState.winner === TOKENS.HUMAN && undoHappened) {
          setStreak(0)
        } else if (gameState.winner === TOKENS.CPU) {
          setStreak(0)
        }

        if (gameState.winner === TOKENS.HUMAN && gameStartTime !== null) {
          const winTime = (Date.now() - gameStartTime) / 1000
          setBestTime((currentBest) =>
            currentBest === null || winTime < currentBest ? winTime : currentBest,
          )
        }
      } else {
        newScore.draws = prev.draws + 1
        setStreak(0)
      }
      return newScore
    })
  }, [
    gameState.isOver,
    gameState.winner,
    historyIndex,
    gameStartTime,
    prevGameOver,
    prevHistoryIndex,
  ])

  return { score, streak, bestTime }
}

export default useGameStats

import { useEffect, useRef } from 'react'

import { BOARD_SIZE } from '@/domain'

const NAV_KEYS = new Set([
  'ArrowUp',
  'ArrowDown',
  'ArrowLeft',
  'ArrowRight',
  'w',
  'a',
  's',
  'd',
  'W',
  'A',
  'S',
  'D',
])

const getNextIndex = (current: number, key: string): number => {
  const row = Math.floor(current / BOARD_SIZE)
  const col = current % BOARD_SIZE
  const k = key.length === 1 ? key.toLowerCase() : key

  switch (k) {
    case 'ArrowUp':
    case 'w':
      return row > 0 ? current - BOARD_SIZE : current
    case 'ArrowDown':
    case 's':
      return row < BOARD_SIZE - 1 ? current + BOARD_SIZE : current
    case 'ArrowLeft':
    case 'a':
      return col > 0 ? current - 1 : current
    case 'ArrowRight':
    case 'd':
      return col < BOARD_SIZE - 1 ? current + 1 : current
    default:
      return current
  }
}

const useGridKeyboard = (
  focusedIndex: number,
  onFocusChange: (index: number) => void,
  onSelect: (index: number) => void,
  onNav?: () => void,
): void => {
  const focusedRef = useRef(focusedIndex)
  const selectRef = useRef(onSelect)
  const focusChangeRef = useRef(onFocusChange)
  const navRef = useRef(onNav)

  focusedRef.current = focusedIndex
  selectRef.current = onSelect
  focusChangeRef.current = onFocusChange
  navRef.current = onNav

  useEffect(() => {
    const handler = (e: KeyboardEvent) => {
      const { key } = e

      if (NAV_KEYS.has(key)) {
        e.preventDefault()
        const next = getNextIndex(focusedRef.current, key)
        if (next !== focusedRef.current) {
          focusChangeRef.current(next)
          if (navRef.current) {
            navRef.current()
          }
        }
        return
      }

      if (key === ' ' || key === 'Enter') {
        e.preventDefault()
        selectRef.current(focusedRef.current)
      }
    }

    document.addEventListener('keydown', handler)
    return () => document.removeEventListener('keydown', handler)
  }, [])
}

export default useGridKeyboard

import { useCallback, useEffect, useState } from 'react'

import type { GameState, SeriesScore, Token } from '@/domain'
import { TOKENS } from '@/domain'
import usePrevious from './usePrevious.ts'

interface UseSeriesReturn {
  seriesLength: number
  seriesScore: SeriesScore
  seriesWinner: Token | null
  gamesPlayed: number
  winsNeeded: number
  isSeriesActive: boolean
  isSeriesOver: boolean
  setSeriesLength: (length: number) => void
  resetSeries: () => void
}

const useSeries = (gameState: GameState): UseSeriesReturn => {
  const [seriesLength, setSeriesLengthRaw] = useState(0)
  const [seriesScore, setSeriesScore] = useState<SeriesScore>({ X: 0, O: 0 })
  const [seriesWinner, setSeriesWinner] = useState<Token | null>(null)
  const [gamesPlayed, setGamesPlayed] = useState(0)

  const prevGameOver = usePrevious(gameState.isOver)

  useEffect(() => {
    if (seriesLength === 0) {
      return
    }
    if (!gameState.isOver || prevGameOver) {
      return
    }
    if (seriesWinner) {
      return
    }

    setGamesPlayed((prev) => prev + 1)

    if (gameState.winner) {
      const { winner } = gameState
      setSeriesScore((prev) => {
        const next = {
          ...prev,
          [winner]: prev[winner] + 1,
        }
        const needed = Math.ceil(seriesLength / 2)
        if (next[TOKENS.HUMAN] >= needed) {
          setSeriesWinner(TOKENS.HUMAN)
        } else if (next[TOKENS.CPU] >= needed) {
          setSeriesWinner(TOKENS.CPU)
        }
        return next
      })
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps -- intentionally tracking only .isOver and .winner, not the full gameState object
  }, [gameState.isOver, gameState.winner, prevGameOver, seriesLength, seriesWinner])

  const setSeriesLength = useCallback((length: number) => {
    setSeriesLengthRaw(length)
    setSeriesScore({ X: 0, O: 0 })
    setSeriesWinner(null)
    setGamesPlayed(0)
  }, [])

  const resetSeries = useCallback(() => {
    setSeriesScore({ X: 0, O: 0 })
    setSeriesWinner(null)
    setGamesPlayed(0)
  }, [])

  return {
    seriesLength,
    seriesScore,
    seriesWinner,
    gamesPlayed,
    winsNeeded: seriesLength > 0 ? Math.ceil(seriesLength / 2) : 0,
    isSeriesActive: seriesLength > 0,
    isSeriesOver: seriesWinner !== null,
    setSeriesLength,
    resetSeries,
  }
}

export default useSeries

import { useWindowSize } from '@games/app-hook-utils'
import { useEffect, useState } from 'react'

type Alignment = 'left' | 'right'

interface UseSmartPositionConfig {
  trigger: React.RefObject<HTMLElement | null>
  panel: React.RefObject<HTMLElement | null>
  minPanelWidth?: number
  viewportPadding?: number
  preferredAlignment?: Alignment
}

const useSmartPosition = ({
  trigger,
  panel,
  minPanelWidth = 240,
  viewportPadding = 16,
  preferredAlignment = 'right',
}: UseSmartPositionConfig): Alignment => {
  const [alignment, setAlignment] = useState<Alignment>(preferredAlignment)
  const { width } = useWindowSize()

  useEffect(() => {
    if (!trigger?.current || !panel?.current) {
      return
    }

    const triggerRect = trigger.current.getBoundingClientRect()

    const rightEdge = triggerRect.right + minPanelWidth
    const wouldOverflowRight = rightEdge + viewportPadding > width

    const leftEdge = triggerRect.left - minPanelWidth
    const wouldOverflowLeft = leftEdge - viewportPadding < 0

    let newAlignment: Alignment = preferredAlignment
    if (preferredAlignment === 'right' && wouldOverflowRight && !wouldOverflowLeft) {
      newAlignment = 'left'
    } else if (preferredAlignment === 'left' && wouldOverflowLeft && !wouldOverflowRight) {
      newAlignment = 'right'
    }

    setAlignment(newAlignment)
  }, [trigger, panel, minPanelWidth, viewportPadding, preferredAlignment, width])

  return alignment
}

export default useSmartPosition

