import React, { useEffect, useRef } from 'react'

import type { Notification } from '@/domain'
import { cx } from '../utils/cssModules.ts'
import styles from './NotificationBanner.module.css'

interface NotificationBannerProps {
  notification: Notification | null
  onDismiss: () => void
  onAction?: () => void
}

const NotificationBanner: React.FC<NotificationBannerProps> = ({
  notification,
  onDismiss,
  onAction,
}) => {
  const timerRef = useRef<ReturnType<typeof setTimeout> | null>(null)

  const nId = notification?.id
  const nDuration = notification?.duration ?? 0

  useEffect(() => {
    if (timerRef.current) {
      clearTimeout(timerRef.current)
      timerRef.current = null
    }

    if (!nId || nDuration <= 0) {
      return
    }

    timerRef.current = setTimeout(onDismiss, nDuration)

    return () => {
      if (timerRef.current) {
        clearTimeout(timerRef.current)
        timerRef.current = null
      }
    }
  }, [nId, nDuration, onDismiss])

  if (!notification) {
    return null
  }

  return (
    <div
      className={cx(
        styles.root,
        notification.variant === 'win' && styles.win,
        notification.variant === 'loss' && styles.loss,
        notification.variant === 'draw' && styles.draw,
        notification.variant === 'countdown' && styles.countdown,
        notification.variant === 'info' && styles.info,
      )}
      role="status"
      aria-live="polite"
      aria-atomic="true"
      key={notification.id}
    >
      <p className={styles.message}>{notification.message}</p>
      {notification.hasAction && onAction && (
        <button type="button" className={styles.action} onClick={onAction}>
          Reset Now
        </button>
      )}
    </div>
  )
}

export default NotificationBanner

import React, { useEffect, useState } from 'react'

import styles from './WinLine.module.css'

interface Coords {
  x1: number
  y1: number
  x2: number
  y2: number
}

interface WinLineProps {
  winLine: number[] | null
  boardRef: React.RefObject<HTMLDivElement | null>
}

const WinLine: React.FC<WinLineProps> = ({ winLine, boardRef }) => {
  const [coords, setCoords] = useState<Coords | null>(null)

  useEffect(() => {
    if (!winLine || winLine.length < 3 || !boardRef?.current) {
      setCoords(null)
      return
    }

    const board = boardRef.current
    const boardRect = board.getBoundingClientRect()
    const cells = board.querySelectorAll('button')
    if (cells.length < 9) {
      return
    }

    const center = (idx: number) => {
      const cell = cells[idx]
      if (!cell) {
        return { x: 0, y: 0 }
      }
      const r = cell.getBoundingClientRect()
      return {
        x: ((r.left + r.width / 2 - boardRect.left) / boardRect.width) * 100,
        y: ((r.top + r.height / 2 - boardRect.top) / boardRect.height) * 100,
      }
    }

    const startIdx = winLine[0]
    const endIdx = winLine[2]
    if (startIdx === undefined || endIdx === undefined) {
      return
    }
    const start = center(startIdx)
    const end = center(endIdx)

    const dx = end.x - start.x
    const dy = end.y - start.y
    const len = Math.sqrt(dx * dx + dy * dy) || 1
    const ext = 5
    const ux = (dx / len) * ext
    const uy = (dy / len) * ext

    setCoords({
      x1: start.x - ux,
      y1: start.y - uy,
      x2: end.x + ux,
      y2: end.y + uy,
    })
  }, [winLine, boardRef])

  if (!coords) {
    return null
  }

  return (
    <svg className={styles.root} viewBox="0 0 100 100" aria-hidden="true">
      <line x1={coords.x1} y1={coords.y1} x2={coords.x2} y2={coords.y2} className={styles.line} />
    </svg>
  )
}

WinLine.displayName = 'WinLine'

export default WinLine

import React, { useCallback, useEffect, useRef, useState } from 'react'

import { tap } from '../../app/haptics.ts'
import useGridKeyboard from '../../app/useGridKeyboard.ts'
import usePrevious from '../../app/usePrevious.ts'
// TODO: Fix useSwipe import - hook not found in app directory
// import { useSwipe } from '../../app/useSwipe.ts'
import type { Board, CellValue, SwipeDirection } from '@/domain'
import { BOARD_SIZE } from '@/domain'
