import styles from './BoardGrid.module.css'

interface BoardGridProps {
  board: Board
  focusedIndex: number
  onFocusChange: (index: number) => void
  onSelect: (index: number) => void
  isGameOver: boolean
  winLine: number[] | null
  onNav?: () => void
  onTap?: () => void
  id?: string
  children?: React.ReactNode
}

const BoardGrid: React.FC<BoardGridProps> = ({
  board,
  focusedIndex,
  onFocusChange,
  onSelect,
  isGameOver,
  winLine,
  onNav,
  onTap,
  id,
  children,
}) => {
  const cellRefs = useRef<(HTMLButtonElement | null)[]>([])
  const gridRef = useRef<HTMLDivElement>(null)
  const [isResetting, setIsResetting] = useState(false)
  const [focusDirection, setFocusDirection] = useState<SwipeDirection | null>(null)
  const prevBoard = usePrevious(board)
  const prevFocused = usePrevious(focusedIndex)

  useGridKeyboard(focusedIndex, onFocusChange, onSelect, onNav)

  useEffect(() => {
    if (prevFocused !== undefined && focusedIndex !== prevFocused) {
      const prevRow = Math.floor(prevFocused / BOARD_SIZE)
      const prevCol = prevFocused % BOARD_SIZE
      const currRow = Math.floor(focusedIndex / BOARD_SIZE)
      const currCol = focusedIndex % BOARD_SIZE

      let direction: SwipeDirection | null = null
      if (currRow < prevRow) {
        direction = 'up'
      } else if (currRow > prevRow) {
        direction = 'down'
      } else if (currCol < prevCol) {
        direction = 'left'
      } else if (currCol > prevCol) {
        direction = 'right'
      }

      setFocusDirection(direction)
    }
  }, [focusedIndex, prevFocused])

  // TODO: Re-enable useSwipe call once hook is properly defined
  // const handleSwipe = useCallback(
  //   (direction: SwipeDirection) => {
  //     ...
  //   },
  //   [focusedIndex, onFocusChange, onNav],
  // )
  // TODO: Re-enable useSwipe call once hook is properly defined
  // useSwipe(gridRef, handleSwipe)

  const handleSelect = useCallback(
    (index: number) => {
      onTap?.()
      tap()
      onSelect(index)
    },
    [onSelect, onTap],
  )

  useEffect(() => {
    if (prevBoard === undefined) {
      return
    }
    const hadMarks = prevBoard.some((cell: CellValue) => cell !== null)
    const nowEmpty = board.every((cell: CellValue) => cell === null)
    if (hadMarks && nowEmpty) {
      setIsResetting(true)
      const timer = setTimeout(() => setIsResetting(false), 300)
      return () => clearTimeout(timer)
    }
  }, [board, prevBoard])

  useEffect(() => {
    const el = cellRefs.current[focusedIndex]
    if (el) {
      el.focus()
    }
  }, [focusedIndex])

  return (
    <div
      ref={gridRef}
      className={cx(styles.root, isResetting && styles.resetting)}
      role="grid"
      aria-label="Tic-Tac-Toe board"
      id={id}
    >
      {board.map((value, index) => {
        const isDisabled = isGameOver || value !== null
        const isWinning = winLine ? winLine.includes(index) : false

        return (
          <CellButton
            ref={(el) => {
              cellRefs.current[index] = el
            }}
            key={index}
            value={value}
            disabled={isDisabled}
            isFocused={focusedIndex === index}
            isWinning={isWinning}
            focusDirection={focusedIndex === index ? focusDirection : null}
            onClick={() => handleSelect(index)}
            ariaLabel={`Row ${Math.floor(index / BOARD_SIZE) + 1}, Column ${(index % BOARD_SIZE) + 1}, ${value ?? 'empty'}`}
            tabIndex={focusedIndex === index ? 0 : -1}
          />
        )
      })}
      {winLine && <WinLine winLine={winLine} boardRef={gridRef} />}
      {children}
    </div>
  )
}

export default BoardGrid

import { useResponsiveState } from '@games/app-hook-utils'
import {
  BoardGrid as SharedBoardGrid,
  Tile,
  type Position,
  type TileContent,
  type TileState,
} from '@games/ui-board-core'
import React from 'react'
import styles from './BoardGrid.module.css'

export interface BoardGridProps {
  board: (string | null)[]
  onCellClick: (position: Position) => void
  selectedPosition?: Position | null
  validMoves?: Position[]
  disableInteraction?: boolean
  winLine?: Position[]
}

export const BoardGrid: React.FC<BoardGridProps> = ({
  board,
  onCellClick,
  selectedPosition,
  validMoves = [],
  disableInteraction = false,
  winLine = [],
}) => {
  const responsive = useResponsiveState()
  const BOARD_SIZE = 3

  // Map TicTacToe cell state to TileContent format
  const getTileContent = (cellIndex: number): TileContent | undefined => {
    const value = board[cellIndex]
    if (!value) {
      return undefined
    }

    return {
      type: 'text',
      value,
    }
  }

  // Map TicTacToe cell state to TileState format
  const getTileState = (position: Position): TileState => {
    const cellIndex = position.row * BOARD_SIZE + position.col
    const isSelected =
      selectedPosition?.row === position.row && selectedPosition?.col === position.col
    const isWinCell = winLine.some((w) => w.row === position.row && w.col === position.col)
    const isValidMove = validMoves.some((m) => m.row === position.row && m.col === position.col)
    const isCellOccupied = board[cellIndex] !== null

    return {
      selected: isSelected,
      highlighted: isValidMove,
      error: isWinCell,
      disabled: disableInteraction || isCellOccupied,
    }
  }

  // Build cell data for SharedBoardGrid
  const cells = board.map((value, index) => ({
    position: {
      row: Math.floor(index / BOARD_SIZE),
      col: index % BOARD_SIZE,
    },
    isDarkSquare: false,
    isPlayable: !disableInteraction && value === null,
  }))

  return (
    <SharedBoardGrid
      rows={BOARD_SIZE}
      cols={BOARD_SIZE}
      cells={cells}
      className={styles.tictactoeBoard}
      responsive={responsive}
      keyboardFocus={selectedPosition || null}
      selectedPosition={selectedPosition || null}
      onCellClick={(position) => {
        const cellIndex = position.row * BOARD_SIZE + position.col
        if (!disableInteraction && board[cellIndex] === null) {
          onCellClick(position)
        }
      }}
      renderCell={(cell) => {
        const content = getTileContent(cell.position.row * BOARD_SIZE + cell.position.col)
        const state = getTileState(cell.position)

        return (
          <Tile
            key={`${cell.position.row}-${cell.position.col}`}
            position={cell.position}
            content={content}
            state={state}
            isDarkSquare={cell.isDarkSquare}
            isPlayable={cell.isPlayable}
          />
        )
      }}
    />
  )
}

export default BoardGrid

