 * TODO: OUTPUTS
 * TODO: Next state with ladder flags and vertical climbing movement.
 *
 * TODO: DEPENDENCIES
 * TODO: Climb speed constant and collision helpers.
 *
 * TODO: EDGE CASES
 * TODO: Broken ladders remain non-interactive; leaving ladder clears climb mode.
 *
 * TODO: PERFORMANCE NOTES
 * TODO: Iterates ladder list once per tick with cheap AABB checks.
 */
import { PLAYER_CLIMB_SPEED } from '../core/constants'
import type { GameState } from '../core/game-state'
import type { InputState } from '../core/types'
import { isIntersecting } from '../utils/collision'

const LADDER_GRAB_MARGIN_PX = 10

export const applyLadderSystem = (state: GameState, input: InputState): GameState => {
  if (state.screen !== 'playing') {
    return state
  }

  const climbIntent = input.climbUp || input.climbDown
  const dismountIntent = input.left || input.right || input.jump

  const playerBox = { position: state.player.position, bounds: state.player.bounds }
  const nearLadderBox = {
    position: {
      x: state.player.position.x - LADDER_GRAB_MARGIN_PX,
      y: state.player.position.y,
    },
    bounds: {
      width: state.player.bounds.width + LADDER_GRAB_MARGIN_PX * 2,
      height: state.player.bounds.height,
    },
  }

  const touchingLadder = state.ladders.find(
    (ladder) =>
      !ladder.broken &&
      isIntersecting(playerBox, { position: ladder.position, bounds: ladder.bounds }),
  )
  const nearbyLadder = state.ladders.find(
    (ladder) =>
      !ladder.broken &&
      isIntersecting(nearLadderBox, { position: ladder.position, bounds: ladder.bounds }),
  )

  if (state.player.onLadder && dismountIntent) {
    return {
      ...state,
      player: { ...state.player, onLadder: false, velocity: { ...state.player.velocity, y: 0 } },
    }
  }

  const activeLadder = touchingLadder ?? (climbIntent ? nearbyLadder : undefined)

  if (!activeLadder) {
    if (!state.player.onLadder) {
      return state
    }
    return {
      ...state,
      player: { ...state.player, onLadder: false },
    }
  }

  if (!state.player.onLadder && !climbIntent) {
    return state
  }

  const verticalIntent = input.climbUp
    ? -PLAYER_CLIMB_SPEED
    : input.climbDown
      ? PLAYER_CLIMB_SPEED
      : 0
  if (verticalIntent === 0) {
    return {
      ...state,
      player: { ...state.player, onLadder: true, velocity: { x: 0, y: 0 } },
    }
  }

  return {
    ...state,
    player: {
      ...state.player,
      onLadder: true,
      onGround: false,
      velocity: { x: 0, y: 0 },
      position: {
        x: activeLadder.position.x + (activeLadder.bounds.width - state.player.bounds.width) / 2,
        y: state.player.position.y + verticalIntent,
      },
    },
  }
}

import type { GameState } from '../core/game-state'

const withSound = (
  state: GameState,
  type: 'jump' | 'death' | 'score' | 'levelComplete',
): GameState => ({
  ...state,
  soundEvents: [...state.soundEvents, { id: state.nextSoundEventId, type }],
  nextSoundEventId: state.nextSoundEventId + 1,
})

export const emitJumpSoundIfNeeded = (previous: GameState, next: GameState): GameState => {
  const wasJumping = previous.player.velocity.y < 0
  const isJumping = next.player.velocity.y < 0
  if (!wasJumping && isJumping) {
    return withSound(next, 'jump')
  }
  return next
}

export const emitDeathSoundIfNeeded = (previous: GameState, next: GameState): GameState => {
  if (previous.player.isAlive && !next.player.isAlive) {
    return withSound(next, 'death')
  }
  return next
}

export const emitLevelCompleteSoundIfNeeded = (previous: GameState, next: GameState): GameState => {
  if (previous.levelIndex !== next.levelIndex && next.levelIndex > previous.levelIndex) {
    return withSound(next, 'levelComplete')
  }
  return next
}

export const emitScoreSoundIfNeeded = (previous: GameState, next: GameState): GameState => {
  if (next.score > previous.score) {
    return withSound(next, 'score')
  }
  return next
}

import type { GameState } from '../core/game-state'

export function applySoundQueueDrainSystem(state: GameState): GameState {
  if (state.soundEvents.length === 0) {
    return state
  }

  return {
    ...state,
    soundEvents: [],
  }
}

import type { AnimationState, EntityAnimation } from '@/domain'
import { Rectangle, Texture } from 'pixi.js'
import { SPRITE_ATLAS } from './sprites'
import { getTexture } from './texture-registry'

interface Props {
  atlasGroup: 'player' | 'barrel' | 'enemy' | 'collectible'
  animationState: AnimationState
  animation: EntityAnimation
  x: number
  y: number
  width: number
  height: number
}

export function AnimatedSpriteRenderer({
  atlasGroup,
  animationState,
  animation,
  x,
  y,
  width,
  height,
}: Props) {
  const group = SPRITE_ATLAS[atlasGroup] as Record<
    string,
    {
      textureId: string
      frames: ReadonlyArray<{ x: number; y: number; width: number; height: number }>
    }
  >
  const config = group[animationState]
  if (!config) {
    return null
  }

  const baseTexture = getTexture(config.textureId)
  if (!baseTexture) {
    return null
  }

  const frameCount = config.frames.length
  const safeFrameIndex = frameCount === 0 ? 0 : animation.frameIndex % frameCount
  const frame = config.frames[safeFrameIndex]
  const texture = new Texture({
    source: baseTexture.source,
    frame: new Rectangle(frame.x, frame.y, frame.width, frame.height),
  })

  return <pixiSprite texture={texture} x={x} y={y} width={width} height={height} />
}

