      const input = {
        ...EMPTY_INPUT,
        right: index % 3 === 0,
        jump: index % 17 === 0,
        climbUp: index % 29 === 0,
      }
      first = tick(first, input)
      second = tick(second, input)
    }

    expect(first).toEqual(second)
  })
})

