class WorkerMock {
  public onmessage: ((event: MessageEvent) => void) | null = null

  public postMessage(message: { id: number; command: string; payload: unknown }): void {
    if (!this.onmessage) {
      return
    }

    if (message.command === 'hint') {
      this.onmessage({
        data: {
          id: message.id,
          ok: true,
          engine: 'wasm',
          data: { row: 0, col: 1 },
        },
      } as MessageEvent)
      return
    }

    if (message.command === 'solve') {
      const solution: Solution = {
        path: [
          { row: 0, col: 0 },
          { row: 0, col: 1 },
          { row: 0, col: 2 },
        ],
        moves: [
          {
            from: { row: 0, col: 0 },
            to: { row: 0, col: 1 },
            direction: 'right',
          },
          {
            from: { row: 0, col: 1 },
            to: { row: 0, col: 2 },
            direction: 'right',
          },
        ],
        collectedItems: [],
        totalCost: 2,
      }

      this.onmessage({
        data: {
          id: message.id,
          ok: true,
          engine: 'wasm',
          data: solution,
        },
      } as MessageEvent)
      return
    }

    this.onmessage({
      data: {
        id: message.id,
        ok: true,
        engine: 'js',
        data: createStateFixture(),
      },
    } as MessageEvent)
  }

  public terminate(): void {}
}

