import type { Difficulty, Position, Solution, ZipState } from '../domain'
import { findOptimalPath, generateSolvableMaze, getHintMove } from '../domain'
import { AI_WASM_BASE64 } from '../wasm/ai-wasm'

type WasmDistanceFn = (fromRow: number, fromCol: number, toRow: number, toCol: number) => number

type EngineKind = 'wasm' | 'js'

type ZipWorkerRequestMap = {
  hint: { state: ZipState }
  solve: { state: ZipState }
  generate: { difficulty: Difficulty }
}

type ZipWorkerResponseMap = {
  hint: Position | null
  solve: Solution | null
  generate: ZipState
}

type WorkerRequest<K extends keyof ZipWorkerRequestMap> = {
  id: number
  command: K
  payload: ZipWorkerRequestMap[K]
}

type WorkerResponse<K extends keyof ZipWorkerResponseMap> = {
  id: number
  ok: boolean
  engine: EngineKind
  data?: ZipWorkerResponseMap[K]
  error?: string
}

export type ZipAiResult<T> = {
  data: T
  engine: EngineKind
}

let wasmDistanceFn: WasmDistanceFn | null = null
let wasmReady = false

const initWasmPromise: Promise<void> = (async () => {
  try {
    if (!AI_WASM_BASE64) {
      return
    }

    const binary = atob(AI_WASM_BASE64)
    const bytes = new Uint8Array(binary.length)
    for (let i = 0; i < binary.length; i++) {
      bytes[i] = binary.charCodeAt(i)
    }

    const imports = { env: { abort: () => {} } }
    const { instance } = await WebAssembly.instantiate(bytes, imports)

    wasmDistanceFn = instance.exports.zipHeuristicDistance as WasmDistanceFn
    wasmReady = typeof wasmDistanceFn === 'function'
  } catch {
    wasmDistanceFn = null
    wasmReady = false
  }
})()

export const ensureWasmReady = (): Promise<void> => initWasmPromise

const getCurrentEngine = (): EngineKind => (wasmReady && wasmDistanceFn ? 'wasm' : 'js')

export const generateSolvableMazeAi = (difficulty: Difficulty): ZipAiResult<ZipState> => {
  return {
    data: generateSolvableMaze(difficulty),
    engine: getCurrentEngine(),
  }
}

export const getHintMoveAi = (state: ZipState): ZipAiResult<Position | null> => {
  return {
    data: getHintMove(state),
    engine: getCurrentEngine(),
  }
}

export const findOptimalPathAi = (state: ZipState): ZipAiResult<Solution | null> => {
  return {
    data: findOptimalPath(state),
    engine: getCurrentEngine(),
  }
}

let worker: Worker | null = null
let requestId = 0
const pending = new Map<number, (value: ZipAiResult<unknown>) => void>()
const pendingErrors = new Map<number, (reason: unknown) => void>()

const getWorker = (): Worker => {
  if (worker) {
    return worker
  }

  worker = new Worker(new URL('../workers/ai.worker.ts', import.meta.url), { type: 'module' })
  worker.onmessage = (event: MessageEvent<WorkerResponse<keyof ZipWorkerResponseMap>>) => {
    const response = event.data
    const resolve = pending.get(response.id)
    const reject = pendingErrors.get(response.id)

    if (!resolve || !reject) {
      return
    }

    pending.delete(response.id)
    pendingErrors.delete(response.id)

    if (!response.ok) {
      reject(new Error(response.error || 'Worker request failed'))
      return
    }

    resolve({
      data: response.data,
      engine: response.engine,
    })
  }

  return worker
}

const runWorkerCommand = <K extends keyof ZipWorkerRequestMap>(
  command: K,
  payload: ZipWorkerRequestMap[K],
): Promise<ZipAiResult<ZipWorkerResponseMap[K]>> => {
  const activeWorker = getWorker()
  const id = ++requestId

  return new Promise<ZipAiResult<ZipWorkerResponseMap[K]>>((resolve, reject) => {
    pending.set(id, resolve as (value: ZipAiResult<unknown>) => void)
    pendingErrors.set(id, reject as (reason: unknown) => void)

    const request: WorkerRequest<K> = { id, command, payload }
    activeWorker.postMessage(request)
  })
}

export const generateSolvableMazeAsync = async (
  difficulty: Difficulty,
): Promise<ZipAiResult<ZipState>> => {
  return runWorkerCommand('generate', { difficulty })
}

export const getHintMoveAsync = async (state: ZipState): Promise<ZipAiResult<Position | null>> => {
  return runWorkerCommand('hint', { state })
}

export const findOptimalPathAsync = async (
  state: ZipState,
): Promise<ZipAiResult<Solution | null>> => {
  return runWorkerCommand('solve', { state })
}

export const terminateAsyncAi = (): void => {
  if (!worker) {
    return
  }

  worker.terminate()
  worker = null
  pending.clear()
  pendingErrors.clear()
}

/**
 * Zip App Layer
 * React hooks and context for Zip maze game
 */

import { useCallback, useEffect, useState } from 'react'

import type { Difficulty, Direction, Move, Position, ZipState } from '@/domain'
import { getDirectionDelta, makeMove, resetGame } from '@/domain'
import {
  ensureWasmReady,
  findOptimalPathAi,
  findOptimalPathAsync,
  generateSolvableMazeAi,
  generateSolvableMazeAsync,
  getHintMoveAi,
  getHintMoveAsync,
} from '../aiEngine'

type AiEngineSource = 'wasm' | 'js' | null

type AiRunSummary = {
  optimalMoves: number
  replayTimeMs: number
  playerMoves: number
  playerTimeSeconds: number
  savedMoves: number
  savedSeconds: number
}

const AI_REPLAY_STEP_MS = 120

const wait = (ms: number): Promise<void> =>
  new Promise((resolve) => {
    setTimeout(resolve, ms)
  })

const isSamePosition = (a: Position, b: Position): boolean => a.row === b.row && a.col === b.col

const resolveReplaySolution = async (
  baselineState: ZipState,
): Promise<{
  engine: AiEngineSource
  moves: Move[] | null
}> => {
  try {
    const solved = await findOptimalPathAsync(baselineState)
    return {
      engine: solved.engine,
      moves: solved.data?.moves ?? null,
    }
  } catch {
    const fallback = findOptimalPathAi(baselineState)
    return {
      engine: fallback.engine,
      moves: fallback.data?.moves ?? null,
    }
  }
}

type ReplayStepHandlers = {
  onRunnerPosition: (position: Position) => void
  onReplayMoves: (moves: Move[]) => void
  onCollectedItems: (items: Position[]) => void
}

const playReplayMoves = async (
  baselineState: ZipState,
  moves: Move[],
  handlers: ReplayStepHandlers,
): Promise<void> => {
  let collected: Position[] = []
  let replayMoves: Move[] = []

  for (const move of moves) {
    await wait(AI_REPLAY_STEP_MS)
    handlers.onRunnerPosition(move.to)
    replayMoves = [...replayMoves, move]
    handlers.onReplayMoves(replayMoves)

    const isItem = baselineState.items.some((item) => isSamePosition(item, move.to))
    if (isItem && !collected.some((item) => isSamePosition(item, move.to))) {
      collected = [...collected, move.to]
      handlers.onCollectedItems(collected)
    }
  }
}

export const useZipGame = (difficulty: Difficulty = 'medium') => {
  const [gameState, setGameState] = useState<ZipState>(
    () => generateSolvableMazeAi(difficulty).data,
  )
  const [gameTime, setGameTime] = useState(0)
  const [isTimerRunning, setIsTimerRunning] = useState(false)
  const [moveCount, setMoveCount] = useState(0)
  const [isAiBusy, setIsAiBusy] = useState(false)
  const [lastAiLatencyMs, setLastAiLatencyMs] = useState<number | null>(null)
  const [lastAiEngine, setLastAiEngine] = useState<AiEngineSource>(null)
  const [isAiReplayRunning, setIsAiReplayRunning] = useState(false)
  const [aiRunnerPosition, setAiRunnerPosition] = useState<Position | null>(null)
  const [aiReplayCollectedItems, setAiReplayCollectedItems] = useState<Position[]>([])
  const [aiReplayMoves, setAiReplayMoves] = useState<Move[]>([])
  const [lastAiRunSummary, setLastAiRunSummary] = useState<AiRunSummary | null>(null)

  useEffect(() => {
    void ensureWasmReady()
  }, [])

  useEffect(() => {
    let interval: ReturnType<typeof setInterval> | null = null

    if (isTimerRunning && !gameState.isComplete) {
      interval = setInterval(() => {
        setGameTime((prev) => prev + 1)
      }, 1000)
    }

    return () => {
      if (interval) {
        clearInterval(interval)
      }
    }
  }, [isTimerRunning, gameState.isComplete])

  useEffect(() => {
    if (moveCount > 0 && !isTimerRunning && !gameState.isComplete) {
      setIsTimerRunning(true)
    }
  }, [moveCount, isTimerRunning, gameState.isComplete])

  const makePlayerMove = useCallback(
    (direction: Direction) => {
      if (gameState.isComplete) {
        return
      }

      setGameState((prevState) => {
        const newState = makeMove(prevState, direction)
        if (newState.moves.length > prevState.moves.length) {
          setMoveCount((prev) => prev + 1)
        }
        return newState
      })
    },
    [gameState.isComplete],
  )

  const canMove = useCallback(
    (direction: Direction): boolean => {
      const currentPos = gameState.playerPosition
      const delta = getDirectionDelta(direction)
      const newPos: Position = {
        row: currentPos.row + delta.row,
        col: currentPos.col + delta.col,
      }

      return (
        newPos.row >= 0 &&
        newPos.row < gameState.maze.length &&
        newPos.col >= 0 &&
        newPos.col < gameState.maze[0].length &&
        gameState.maze[newPos.row][newPos.col].type !== 'wall'
      )
    },
    [gameState],
  )

  const newPuzzle = useCallback(async () => {
    setIsAiBusy(true)
    const startedAt = performance.now()
    try {
      const nextState = await generateSolvableMazeAsync(difficulty)
      setGameState(nextState.data)
      setLastAiEngine(nextState.engine)
      setIsAiReplayRunning(false)
      setAiRunnerPosition(null)
      setAiReplayCollectedItems([])
      setAiReplayMoves([])
      setLastAiRunSummary(null)
    } catch {
      const fallback = generateSolvableMazeAi(difficulty)
      setGameState(fallback.data)
      setLastAiEngine(fallback.engine)
      setIsAiReplayRunning(false)
      setAiRunnerPosition(null)
      setAiReplayCollectedItems([])
      setAiReplayMoves([])
      setLastAiRunSummary(null)
    } finally {
      setGameTime(0)
      setIsTimerRunning(false)
      setMoveCount(0)
      setLastAiLatencyMs(Math.round(performance.now() - startedAt))
      setIsAiBusy(false)
    }
  }, [difficulty])

  const resetCurrentGame = useCallback(() => {
    setGameState((prevState) => resetGame(prevState))
    setGameTime(0)
    setIsTimerRunning(false)
    setMoveCount(0)
    setIsAiReplayRunning(false)
    setAiRunnerPosition(null)
    setAiReplayCollectedItems([])
    setAiReplayMoves([])
    setLastAiRunSummary(null)
  }, [])

  const getHint = useCallback(async (): Promise<Position | null> => {
    setIsAiBusy(true)
    const startedAt = performance.now()
    try {
      const hint = await getHintMoveAsync(gameState)
      setLastAiEngine(hint.engine)
      return hint.data
    } catch {
      const fallback = getHintMoveAi(gameState)
      setLastAiEngine(fallback.engine)
      return fallback.data
    } finally {
      setLastAiLatencyMs(Math.round(performance.now() - startedAt))
      setIsAiBusy(false)
    }
  }, [gameState])

  const solveCompletely = useCallback(async () => {
    setIsAiBusy(true)
    const startedAt = performance.now()
    try {
      const solution = await findOptimalPathAsync(gameState)
      setLastAiEngine(solution.engine)
      const solvedPath = solution.data
      if (!solvedPath) {
        return
      }

      let currentState = { ...gameState }
      for (const move of solvedPath.moves) {
        currentState = makeMove(currentState, move.direction)
      }
      setGameState(currentState)
      setMoveCount((prev) => prev + solvedPath.moves.length)
    } catch {
      const fallback = findOptimalPathAi(gameState)
      const fallbackSolution = fallback.data
      setLastAiEngine(fallback.engine)
      if (!fallbackSolution) {
        return
      }

      let currentState = { ...gameState }
      for (const move of fallbackSolution.moves) {
        currentState = makeMove(currentState, move.direction)
      }
      setGameState(currentState)
      setMoveCount((prev) => prev + fallbackSolution.moves.length)
    } finally {
      setLastAiLatencyMs(Math.round(performance.now() - startedAt))
      setIsAiBusy(false)
    }
  }, [gameState])

  const changeDifficulty = useCallback(
    async (nextDifficulty: Difficulty) => {
      setIsAiBusy(true)
      const startedAt = performance.now()
      try {
        const nextState = await generateSolvableMazeAsync(nextDifficulty)
        setGameState(nextState.data)
        setLastAiEngine(nextState.engine)
      } catch {
        const fallback = generateSolvableMazeAi(nextDifficulty)
        setGameState(fallback.data)
        setLastAiEngine(fallback.engine)
      } finally {
        setGameTime(0)
        setIsTimerRunning(false)
        setMoveCount(0)
        setIsAiReplayRunning(false)
        setAiRunnerPosition(null)
        setAiReplayCollectedItems([])
        setAiReplayMoves([])
        setLastAiRunSummary(null)
        setLastAiLatencyMs(Math.round(performance.now() - startedAt))
        setIsAiBusy(false)
      }
    },
    [],
  )

  const runAiReplay = useCallback(async () => {
    if (isAiBusy || isAiReplayRunning || !gameState.isComplete) {
      return
    }

    const baselineState = resetGame(gameState)
    const replayStartedAt = performance.now()

    setIsAiReplayRunning(true)
    setAiRunnerPosition(baselineState.playerPosition)
    setAiReplayCollectedItems([])
    setAiReplayMoves([])

    try {
      const replaySolution = await resolveReplaySolution(baselineState)
      setLastAiEngine(replaySolution.engine)

      const replayMoves = replaySolution.moves ?? []

      await playReplayMoves(baselineState, replayMoves, {
        onRunnerPosition: setAiRunnerPosition,
        onReplayMoves: setAiReplayMoves,
        onCollectedItems: setAiReplayCollectedItems,
      })

      const replayTimeMs = Math.round(performance.now() - replayStartedAt)
      const replayTimeSeconds = replayTimeMs / 1000
      setLastAiRunSummary({
        optimalMoves: replayMoves.length,
        replayTimeMs,
        playerMoves: moveCount,
        playerTimeSeconds: gameTime,
        savedMoves: Math.max(moveCount - replayMoves.length, 0),
        savedSeconds: Math.max(gameTime - replayTimeSeconds, 0),
      })
    } catch (error) {
      console.error('AI replay failed:', error)
      setAiRunnerPosition(null)
      setAiReplayCollectedItems([])
      setAiReplayMoves([])
      setLastAiRunSummary(null)
    } finally {
      setIsAiReplayRunning(false)
    }
  }, [gameState, gameTime, isAiBusy, isAiReplayRunning, moveCount])

  return {
    aiRunnerPosition,
    aiReplayCollectedItems,
    aiReplayMoves,
    canMove,
    gameState,
    gameTime,
    changeDifficulty,
    getHint,
    isAiBusy,
    isAiReplayRunning,
    lastAiEngine,
    lastAiLatencyMs,
    lastAiRunSummary,
    makePlayerMove,
    moveCount,
    newPuzzle,
    resetCurrentGame,
    runAiReplay,
    solveCompletely,
  }
}

/**
 * Zip Domain AI
 * Pathfinding and solving algorithms for maze navigation
 */

import { MOVEMENT_COSTS } from './constants'
import { createInitialState, getValidMoves } from './rules'
import type {
  CellType,
  Difficulty,
  Direction,
  Maze,
  Move,
  PathNode,
  Position,
  Solution,
  ZipState,
} from './types'

/**
 * Calculate Manhattan distance heuristic
 */
const manhattanDistance = (a: Position, b: Position): number => {
  return Math.abs(a.row - b.row) + Math.abs(a.col - b.col)
}

/**
 * Calculate movement cost between positions
 */
const MOVEMENT_COST_BY_CELL: Record<CellType, number> = {
  empty: MOVEMENT_COSTS.empty,
  wall: Number.MAX_SAFE_INTEGER,
  start: MOVEMENT_COSTS.empty,
  goal: MOVEMENT_COSTS.goal,
  item: MOVEMENT_COSTS.item,
  player: MOVEMENT_COSTS.empty,
}

const getMovementCost = (to: Position, maze: Maze): number => {
  const cell = maze[to.row][to.col]
  return MOVEMENT_COST_BY_CELL[cell.type]
}

/**
 * A* pathfinding algorithm for maze navigation
 */
export const findPathAStar = (
  start: Position,
  goal: Position,
  maze: Maze,
  _collectedItems: Position[] = [],
): Position[] => {
  const openSet: PathNode[] = []
  const closedSet: Set<string> = new Set()

  const startNode: PathNode = {
    position: start,
    g: 0,
    h: manhattanDistance(start, goal),
    f: manhattanDistance(start, goal),
  }

  openSet.push(startNode)

  while (openSet.length > 0) {
    // Find node with lowest f score
    openSet.sort((a, b) => a.f - b.f)
    const current = openSet.shift()!

    const posKey = `${current.position.row},${current.position.col}`
    if (closedSet.has(posKey)) {
      continue
    }
    closedSet.add(posKey)

    // Check if goal reached
    if (current.position.row === goal.row && current.position.col === goal.col) {
      return reconstructPath(current)
    }

    // Explore neighbors
    const validMoves = getValidMoves(current.position, maze)
    for (const move of validMoves) {
      const neighborPos = move.to
      const neighborKey = `${neighborPos.row},${neighborPos.col}`

      if (closedSet.has(neighborKey)) {
        continue
      }

      const gScore = current.g + getMovementCost(neighborPos, maze)
      const hScore = manhattanDistance(neighborPos, goal)
      const fScore = gScore + hScore

      // Check if this path is better
      const existingNode = openSet.find(
        (node) => node.position.row === neighborPos.row && node.position.col === neighborPos.col,
      )

      if (!existingNode || gScore < existingNode.g) {
        const neighborNode: PathNode = {
          position: neighborPos,
          g: gScore,
          h: hScore,
          f: fScore,
          parent: current,
        }

        if (existingNode) {
          // Update existing node
          Object.assign(existingNode, neighborNode)
        } else {
          openSet.push(neighborNode)
        }
      }
    }
  }

  return [] // No path found
}

/**
 * Reconstruct path from A* result
 */
const reconstructPath = (node: PathNode): Position[] => {
  const path: Position[] = []
  let current: PathNode | undefined = node

  while (current) {
    path.unshift(current.position)
    current = current.parent
  }

  return path
}

/**
 * Find optimal path considering item collection
 */
export const findOptimalPath = (state: ZipState): Solution | null => {
  const start = state.playerPosition
  const goal = state.goalPosition
  const remainingItems = state.items.filter(
    (item) =>
      !state.collectedItems.some(
        (collected) => collected.row === item.row && collected.col === item.col,
      ),
  )

  if (remainingItems.length === 0) {
    // No items left, go directly to goal
    const path = findPathAStar(start, goal, state.maze, state.collectedItems)
    if (path.length === 0) {
      return null
    }

    return {
      path,
      moves: convertPathToMoves(path),
      collectedItems: [],
      totalCost: calculatePathCost(path, state.maze),
    }
  }

  // Find best sequence to collect remaining items and reach goal
  // For simplicity, use nearest neighbor approach
  let currentPos = start
  const totalPath: Position[] = [start]
  const collectedSequence: Position[] = []

  while (remainingItems.length > 0) {
    let bestItem: Position | null = null
    let bestPath: Position[] = []
    let bestCost = Infinity

    for (const item of remainingItems) {
      const path = findPathAStar(currentPos, item, state.maze, state.collectedItems)
      if (path.length > 0) {
        const cost = calculatePathCost(path, state.maze)
        if (cost < bestCost) {
          bestCost = cost
          bestPath = path
          bestItem = item
        }
      }
    }

    if (!bestItem || bestPath.length === 0) {
      break
    }

    // Add path to item (excluding starting position to avoid duplication)
    totalPath.push(...bestPath.slice(1))
    collectedSequence.push(bestItem)
    currentPos = bestItem

    // Remove collected item
    const index = remainingItems.findIndex(
      (item) => item.row === bestItem!.row && item.col === bestItem!.col,
    )
    remainingItems.splice(index, 1)
  }

  // Add path to goal
  const goalPath = findPathAStar(currentPos, goal, state.maze, state.collectedItems)
  if (goalPath.length > 0) {
    totalPath.push(...goalPath.slice(1))
  }

  if (totalPath.length <= 1) {
    return null
  }

  return {
    path: totalPath,
    moves: convertPathToMoves(totalPath),
    collectedItems: collectedSequence,
    totalCost: calculatePathCost(totalPath, state.maze),
  }
}

/**
 * Convert path to moves
 */
const convertPathToMoves = (path: Position[]): Move[] => {
  const moves: Move[] = []

  for (let i = 0; i < path.length - 1; i++) {
    const from = path[i]
    const to = path[i + 1]

    const deltaRow = to.row - from.row
    const deltaCol = to.col - from.col

    let direction: Direction
    if (deltaRow === -1) {
      direction = 'up'
    } else if (deltaRow === 1) {
      direction = 'down'
    } else if (deltaCol === -1) {
      direction = 'left'
    } else {
      direction = 'right'
    }

    moves.push({
      from,
      to,
      direction,
    })
  }

  return moves
}

/**
 * Calculate total cost of a path
 */
const calculatePathCost = (path: Position[], maze: Maze): number => {
  let cost = 0
  for (let i = 0; i < path.length - 1; i++) {
    cost += getMovementCost(path[i + 1], maze)
  }
  return cost
}

/**
 * Get next hint move
 */
export const getHintMove = (state: ZipState): Position | null => {
  const solution = findOptimalPath(state)
  if (!solution || solution.path.length < 2) {
    return null
  }

  return solution.path[1] // Next position after current
}

/**
 * Check if maze is solvable
 */
export const isMazeSolvable = (state: ZipState): boolean => {
  const solution = findOptimalPath(state)
  return solution !== null && solution.path.length > 0
}

/**
 * Generate a guaranteed solvable maze
 */
export const generateSolvableMaze = (difficulty: Difficulty): ZipState => {
  let state: ZipState
  let attempts = 0
  const maxAttempts = 50

  do {
    state = createInitialState(difficulty)
    attempts++
  } while (!isMazeSolvable(state) && attempts < maxAttempts)

  // If we couldn't generate a solvable maze, return the last attempt
  return state
}

